# desmontar-proyecto: el vhost de los proyectos (web.local) deja de apuntar al proyecto cargado y
# apunta a una pagina que dice que no hay ninguno. El enlace sigue existiendo: si se borrara, el
# gestor ya no reconoceria el vhost y al cargar otro proyecto intentaria crearlo de nuevo. Los
# dominios falseados de una tienda PrestaShop dejan de estarlo (vuelven a llevar a la web real)
function unload_project() {
    local link sudo="" dir=$HTDOCS_DIR/$EMPTY_PROJECT page rc

    link=$(project_link)
    if [ -z "$link" ]; then
        echo "No hay ningun vhost de proyectos (como $PROJECT_VHOST): no hay nada que desmontar"

        return 1
    fi
    if [ "$(readlink "$HTDOCS_DIR/$link" | sed 's:/*$::')" == "$EMPTY_PROJECT" ]; then
        echo "No hay ningun proyecto cargado en $link"

        return 0
    fi
    # La contraseña antes de cambiar nada: cancelarla deja el proyecto cargado
    sudo_first || return 1
    if [ -L "$dir" ] || { [ -e "$dir" ] && [ ! -d "$dir" ]; }; then
        echo "$dir no es una carpeta: borrala o cambiale el nombre y vuelve a intentarlo"

        return 1
    fi
    [ -w "$HTDOCS_DIR" ] || sudo=$SUDO
    if [ ! -d "$dir" ]; then
        run $sudo mkdir -m 755 "$dir" || return 1
    fi
    empty_page "$dir"
    # Todo o nada (como al cargar): si un paso falla o se cancela la tarea, el enlace vuelve al proyecto
    LOAD_UNDO_LINK=$link LOAD_UNDO_TARGET=$(readlink "$HTDOCS_DIR/$link" 2> /dev/null)
    LOAD_UNDO_ACTIVE=$(active_name)
    [ "$DRY" -eq 0 ] && trap 'load_project_undo; exit 130' TERM INT HUP
    unload_project_steps "$link" "$sudo"
    rc=$?
    if [ $rc -ne 0 ] && [ "$DRY" -eq 0 ]; then
        load_project_undo
    fi
    trap - TERM INT HUP
    LOAD_UNDO_LINK=""
    return $rc
}

function unload_project_steps() {
    local link=$1 sudo=$2
    run $sudo rm "$HTDOCS_DIR/$link" || return 1
    run $sudo ln -s "$EMPTY_PROJECT/" "$HTDOCS_DIR/$link" || return 1
    # (sin dominios falseados: los de una tienda PrestaShop vuelven a llevar a la web real)
    hosts_fake cargar || return 1
    # Cada proceso de PHP recuerda a donde apuntaba el enlace (realpath_cache, 120 s)
    if [ -f "$LINK/xamppfiles/logs/httpd.pid" ]; then
        echo "Recargando Apache para que PHP deje de servir el proyecto..."
        run xampp_ctl reloadapache > /dev/null || { echo "No se ha podido recargar Apache. Reinicia la version activa."; return 1; }
    fi
    media_sync || echo "Aviso: $link sigue pidiendo a produccion las imagenes del proyecto anterior"
    echo "Proyecto desmontado: $link ya no apunta a ningun proyecto"
}

# borrar-proyecto <carpeta> [--bd <base> [--copia]]: borra un proyecto entero. Por orden, y si un paso
# falla no se sigue (la carpeta, lo ultimo): lo desmonta si es el cargado, lo borra de Docker (sus
# contenedores y su copia de la BBDD), borra su BBDD de la version activa si se pide (con --copia,
# antes un volcado en ~/lvm-copias; si la copia falla no se borra nada), quita sus vhosts y las lineas
# de sus dominios de /etc/hosts (un dominio real no se queda falseado), lo que el gestor recordaba de
# el y su carpeta de htdocs. Las BBDD de las otras versiones no se tocan
function delete_project() {
    local folder=${1%/} db="" backup="" dir conf slug vhosts copy domains
    shift 2> /dev/null
    while [ $# -gt 0 ]; do
        case $1 in
            --bd) [ -n "$2" ] || { echo "Falta el nombre de la base de --bd"; return 1; }; db=$2; shift 2 ;;
            --copia) backup=--copia; shift ;;
            *) echo "Opcion desconocida: $1"; return 1 ;;
        esac
    done
    if [ -z "$folder" ]; then
        echo "Uso: lvm-instalador borrar-proyecto <carpeta> [--bd <base> [--copia]]"

        return 1
    fi
    valid_project "$folder" || return 1
    if [ "$folder" == "$EMPTY_PROJECT" ] || [ "$folder" == "$PROJECT_VHOST" ] || [ "$folder" == "$(project_link)" ]; then
        echo "$folder no es un proyecto: es del gestor"

        return 1
    fi
    if [ -n "$db" ]; then
        db_valid_name "$db" || return 1
        db_connect || return $?
        db_exists "$db" || { echo "No hay ninguna base de datos $db en lampp-$DB_FOLDER: no se ha borrado nada"; return 1; }
    fi
    dir=$HTDOCS_DIR/$folder
    echo "Se borra el proyecto $folder ($dir)"
    # La contraseña antes de cambiar nada: cancelarla deja el proyecto como estaba
    sudo_first || return 1

    if [ "$(readlink "$HTDOCS_DIR/$(project_link)" 2> /dev/null | sed 's:/*$::')" == "$folder" ]; then
        echo "Es el proyecto cargado: se desmonta"
        unload_project || return 1
    fi
    for conf in "$DOCKER_DIR"/*/proyecto.conf; do
        [ -f "$conf" ] && grep -qxF "CARPETA=$folder" "$conf" || continue
        slug=$(basename "$(dirname "$conf")")
        echo "En Docker como $slug: se borra"
        if [ "$DRY" -eq 0 ] && ! docker_ready; then
            echo "Docker sin root no esta en marcha: arrancalo para borrar $slug (no se ha borrado nada mas)"

            return 1
        fi
        docker_action borrar "$slug" || return 1
    done
    if [ -n "$db" ]; then
        drop_database "$db" $backup || { echo "No se sigue: la carpeta y los vhosts de $folder no se han tocado"; return 1; }
    fi

    # Vhosts con su DocumentRoot en la carpeta (o dentro de ella) y los dominios que llevaban
    vhosts=$(realpath_f "$ACTIVE_VHOSTS")
    copy=$(mktemp "$LOG_DIR/vhosts-borrar-XXXXXX") || return 1
    domains=$(python3 -I - "$vhosts" "$copy" "$folder" << 'EOF'
import re, sys
src, dst, folder = sys.argv[1:4]
lines = open(src, encoding="utf-8", errors="surrogateescape", newline="").read().split("\n")
root = re.compile(r'^\s*DocumentRoot\s+"?[^"\s]*/htdocs/%s(/[^"\s]*)?"?\s*$' % re.escape(folder), re.I)
out, block, names = [], None, set()
for line in lines:
    if block is None:
        if re.match(r"^\s*<VirtualHost\b", line, re.I):
            block = [line]
        else:
            out.append(line)
        continue
    block.append(line)
    if re.match(r"^\s*</VirtualHost>", line, re.I):
        if any(root.match(l) for l in block):
            for l in block:
                w = l.split("#", 1)[0].split()
                if len(w) >= 2 and w[0].lower() in ("servername", "serveralias"):
                    names |= {n.lower().split(":")[0] for n in w[1:]}
            # (sin la linea en blanco que lo separaba del anterior)
            while out and not out[-1].strip():
                out.pop()
        else:
            out += block
        block = None
if block:
    out += block
with open(dst, "w", encoding="utf-8", errors="surrogateescape", newline="") as f:
    f.write("\n".join(out))
print(" ".join(sorted(names)))
EOF
) || { rm -f "$copy"; return 1; }
    if ! cmp -s "$copy" "$vhosts"; then
        echo "Vhosts de $folder: ${domains:-sin dominio}"
        edit_vhosts --aplicar "$copy" || { rm -f "$copy"; echo "No se sigue: la carpeta de $folder no se ha tocado"; return 1; }
    fi
    rm -f "$copy"
    if [ -n "$domains" ]; then
        # Las lineas de esos dominios (falseadas o comentadas); de una linea con otros, solo los suyos
        copy=$(mktemp "$LOG_DIR/hosts-borrar-XXXXXX") || return 1
        python3 -I - "$HOSTS_FILE" "$copy" "$domains" << 'EOF'
import re, sys
src, dst, names = sys.argv[1], sys.argv[2], set(sys.argv[3].split())
rx = re.compile(r"^(\s*#*\s*)(127\.0\.0\.1|::1)(\s+)(.*?)\s*$")
out = []
for line in open(src).read().splitlines():
    m = rx.match(line)
    if m:
        body, sep, comment = m.group(4).partition("#")
        keep = [n for n in body.split() if n.lower() not in names]
        if len(keep) != len(body.split()):
            if not keep:
                continue
            line = m.group(1) + m.group(2) + m.group(3) + " ".join(keep) + (" " + sep + comment if sep else "")
    out.append(line)
open(dst, "w").write("\n".join(out) + "\n")
EOF
        if ! cmp -s "$copy" "$HOSTS_FILE"; then
            echo "Lineas de $HOSTS_FILE de: $domains"
            edit_hosts --aplicar "$copy" || { rm -f "$copy"; echo "No se sigue: la carpeta de $folder no se ha tocado"; return 1; }
        fi
        rm -f "$copy"
        [ "$DRY" -eq 1 ] || local_off si $domains
    fi

    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] se olvida $folder en $PROJECTS_FILE y $REPO_PROJECTS_FILE y se borra $dir"

        return 0
    fi
    if [ -f "$PROJECTS_FILE" ]; then
        awk -v f="$folder" '{ split($0, a, "="); split(a[2], b, " ") } !(index($0, "=") && b[1] == f)' "$PROJECTS_FILE" > "$PROJECTS_FILE.tmp" \
            && mv -f "$PROJECTS_FILE.tmp" "$PROJECTS_FILE"
    fi
    if [ -f "$REPO_PROJECTS_FILE" ]; then
        grep -vxF -- "$folder" "$REPO_PROJECTS_FILE" > "$REPO_PROJECTS_FILE.tmp"
        mv -f "$REPO_PROJECTS_FILE.tmp" "$REPO_PROJECTS_FILE"
    fi
    echo "Borrando la carpeta $dir..."
    # Con tu usuario; lo que haya dejado Apache con otro (daemon), con sudo y sin salir de la carpeta
    # (rm no sigue enlaces; -x: un disco montado dentro no se toca)
    rm -rfx -- "$dir" 2> /dev/null
    if [ -e "$dir" ]; then
        [ "$(realpath_f "$dir")" == "$(realpath_f "$HTDOCS_DIR")/$folder" ] && [ ! -L "$dir" ] \
            && sudo rm -rfx -- "$dir"
    fi
    if [ -e "$dir" ]; then
        echo "No se ha podido borrar del todo $dir: borra a mano lo que queda"

        return 1
    fi
    echo "Proyecto $folder borrado"
}

# ¿Direccion de un repositorio que se puede clonar? Solo https:// o ssh (git@servidor:ruta o
# ssh://git@servidor/ruta), con servidor y ruta sin caracteres raros ni un - al principio (git los
# tomaria como opciones). Nada de file://, ext:: ni rutas locales
function git_url_ok() {
    local host='[A-Za-z0-9][A-Za-z0-9.-]*' path='[A-Za-z0-9_~][A-Za-z0-9._~/-]*'
    [[ "$1" =~ ^https://$host(:[0-9]{1,5})?/$path$ ]] || [[ "$1" =~ ^git@$host:$path$ ]] \
        || [[ "$1" =~ ^ssh://git@$host(:[0-9]{1,5})?/$path$ ]]
}

# montar-proyecto <url de git> <carpeta> <version> <base> [volcado]: proyecto nuevo desde un
# repositorio (GitHub u otro). Lo clona en htdocs, lo carga en esa version de PHP, crea su BBDD y,
# si se indica, carga en ella el volcado (con la carga protegida de importar-bd). El clon va con tu
# usuario (sin sudo), sin submodulos ni ganchos y solo por https o ssh; sin preguntas: un
# repositorio privado por https falla (se usa la direccion SSH con tu clave)
function mount_project() {
    local url=$1 folder=$2 version=$3 db=$4 file=$5 dest dir owner
    if [ -z "$url" ] || [ -z "$folder" ] || [ -z "$version" ] || [ -z "$db" ]; then
        echo "Uso: lvm-instalador montar-proyecto <url de git> <carpeta> <version> <base de datos> [volcado]"

        return 1
    fi
    if ! git_url_ok "$url"; then
        echo "La direccion del repositorio no es valida: usa https://servidor/usuario/repositorio(.git)"
        echo "o git@servidor:usuario/repositorio.git"

        return 1
    fi
    if ! [[ "$folder" =~ ^[A-Za-z0-9_][A-Za-z0-9._-]{0,99}$ ]] || [ "$folder" == "$EMPTY_PROJECT" ]; then
        echo "El nombre de la carpeta solo puede llevar letras sin acentos, numeros, punto, _ y -"

        return 1
    fi
    dest=$HTDOCS_DIR/$folder
    if [ -e "$dest" ] || [ -L "$dest" ]; then
        echo "Ya existe $dest: elige otro nombre para la carpeta"

        return 1
    fi
    dir="$BASE_DIR/XAMPP-$version"
    if ! valid_version_name "$version" || [ ! -d "$dir" ] || [ -L "$dir" ]; then
        echo "No existe la version $version"

        return 1
    fi
    db_valid_name "$db" || return 1
    owner=$dir
    if db_names "$owner" | grep -qxF "$db"; then
        echo "Ya hay una BBDD $db en esa version: elige otro nombre"

        return 1
    fi
    if [ -n "$file" ] && { [ ! -f "$file" ] || [ -L "$file" ]; }; then
        echo "No existe el fichero $file"

        return 1
    fi
    if ! command -v git > /dev/null; then
        echo "Hace falta git para clonar el repositorio: xcode-select --install"

        return 1
    fi
    if [ ! -w "$HTDOCS_DIR" ]; then
        echo "No puedes escribir en $HTDOCS_DIR: el proyecto se clona con tu usuario, sin sudo"

        return 1
    fi

    echo "1/3 Clonando $url en $dest..."
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] git clone --no-recurse-submodules -- $url $dest"
        echo "2/3 [simulacion] cargar-proyecto $folder $version $db"
        echo "3/3 [simulacion] BBDD $db: $([ -n "$file" ] && echo "importar-bd $file $db --crear" || echo "crear-bd $db")"

        return 0
    fi
    # Por ssh, solo servidores cuya clave ya conoces (~/.ssh/known_hosts) o las publicadas de GitHub,
    # GitLab y Bitbucket: un servidor nuevo no se acepta sin mirar (en una red ajena o con /etc/hosts
    # cambiado te darian otro repositorio, y su PHP corre con tu usuario)
    local known
    # (en /tmp y no en $TMPDIR, que viene de la sesion: va entre comillas en GIT_SSH_COMMAND)
    known=$(mktemp /tmp/lvm-conocidos.XXXXXX) || return 1
    printf '%s\n' "$GIT_KNOWN_HOSTS" > "$known"
    # Sin terminal (git y ssh leen tu configuracion: no pueden usar el permiso de sudo recordado ni
    # quedarse leyendola) y sin git-lfs (su .lfsconfig llevaria las descargas a otro servidor)
    if ! GIT_TERMINAL_PROMPT=0 GIT_ASKPASS=/bin/false SSH_ASKPASS=/bin/false GIT_LFS_SKIP_SMUDGE=1 \
        GIT_SSH_COMMAND="ssh -o BatchMode=yes -o StrictHostKeyChecking=yes -o 'UserKnownHostsFile=~/.ssh/known_hosts $known'" \
        no_tty git -c protocol.allow=never -c protocol.https.allow=always -c protocol.ssh.allow=always \
            -c core.hooksPath=/dev/null -c credential.helper= \
            -c filter.lfs.process= -c filter.lfs.smudge= -c filter.lfs.required=false \
            clone --no-recurse-submodules -- "$url" "$dest"; then
        rm -f "$known"
        echo "No se ha podido clonar el repositorio. Si es privado, usa su direccion SSH"
        echo "(git@github.com:usuario/repositorio.git) con tu clave SSH ya configurada en GitHub."
        echo "Si es por SSH a un servidor que no es GitHub, GitLab ni Bitbucket y dice «Host key"
        echo "verification failed», conectate una vez a mano para comprobar y aceptar su clave"
        echo "(ssh -T git@servidor) y vuelve a intentarlo."

        return 1
    fi
    rm -f "$known"
    htdocs_close_world "$dest"
    # Apuntada como montada desde un repositorio: el dominio de su base no se falsea solo (ver
    # load_project_domain)
    mkdir -p "$HOME/.lvm-instalador" && { grep -qxF -- "$folder" "$REPO_PROJECTS_FILE" 2> /dev/null \
        || printf '%s\n' "$folder" >> "$REPO_PROJECTS_FILE"; }

    echo "2/3 Cargando $folder en XAMPP-$version..."
    load_project "$folder" "$version" "$db" || { echo "El proyecto esta clonado en $dest, pero no se ha podido cargar."; return 1; }

    echo "3/3 BBDD $db..."
    if [ -n "$file" ]; then
        import_database "$file" "$db" --crear || return 1
    else
        create_database "$db" || return 1
    fi
    # Tienda PrestaShop: su dominio esta en la base (shop_url), que al cargarla aun no existia. Ahora
    # que esta, su vhost, su certificado y el dominio falseado
    if [ -n "$file" ] && is_prestashop "$folder"; then
        load_project_domain "$folder" "$db" || return 1
    fi
    echo "Proyecto nuevo montado: $folder en XAMPP-$version con la BBDD $db"
}

# Carga un proyecto: activa la version (si se indica y no es la activa) y apunta el enlace del vhost
# a la carpeta del proyecto (lo mismo que rm web.local; ln -s <carpeta>/ web.local)
# Cargar un proyecto es todo o nada: la contraseña se pide antes de cambiar nada y, si se cancela (la
# ventana manda TERM a la tarea) o falla un paso, el enlace del vhost vuelve al proyecto de antes, la
# version activa a la de antes y Apache se recarga. Lo de antes, en LOAD_UNDO_*
LOAD_UNDO_LINK="" LOAD_UNDO_TARGET="" LOAD_UNDO_ACTIVE=""

function load_project_undo() {
    trap - TERM INT HUP
    [ -n "$LOAD_UNDO_LINK" ] || return 0
    local sudo="" now
    echo "Se deja como estaba: $LOAD_UNDO_LINK -> ${LOAD_UNDO_TARGET:-nada}"
    [ -w "$HTDOCS_DIR" ] || sudo=$SUDO
    now=$(readlink "$HTDOCS_DIR/$LOAD_UNDO_LINK" 2> /dev/null)
    if [ "$now" != "$LOAD_UNDO_TARGET" ]; then
        if [ -n "$LOAD_UNDO_TARGET" ]; then
            run $sudo ln -sfn "$LOAD_UNDO_TARGET" "$HTDOCS_DIR/$LOAD_UNDO_LINK"
        elif [ -L "$HTDOCS_DIR/$LOAD_UNDO_LINK" ]; then
            run $sudo rm "$HTDOCS_DIR/$LOAD_UNDO_LINK"
        fi
    fi
    if [ -n "$LOAD_UNDO_ACTIVE" ] && [ "$(active_name)" != "$LOAD_UNDO_ACTIVE" ]; then
        use_version "$LOAD_UNDO_ACTIVE"
    elif [ -f "$LINK/xamppfiles/logs/httpd.pid" ]; then
        run xampp_ctl reloadapache > /dev/null
    fi
    LOAD_UNDO_LINK=""
}

function load_project() {
    local folder=${1%/} version=$2 link rc

    valid_project "$folder" || return 1
    if [ -n "$version" ] && { ! valid_version_name "$version" || [ ! -d "$BASE_DIR/XAMPP-$version" ]; }; then
        echo "No existe la version $version"

        return 1
    fi
    # La contraseña antes de cambiar nada: cancelarla deja el proyecto de antes cargado
    if [ "$DRY" -eq 0 ] && [ -n "$SUDO" ] && ! sudo -v; then
        echo "Cancelado: no se ha cambiado nada"
        return 1
    fi

    link=$(project_link)
    if [ -z "$link" ]; then
        create_project_vhost || return 1
        link=$PROJECT_VHOST
    fi

    if [ "$folder" == "$link" ]; then
        echo "$folder es el propio enlace del vhost, no un proyecto"

        return 1
    fi
    LOAD_UNDO_LINK=$link LOAD_UNDO_TARGET=$(readlink "$HTDOCS_DIR/$link" 2> /dev/null)
    LOAD_UNDO_ACTIVE=$(active_name)
    [ "$DRY" -eq 0 ] && trap 'load_project_undo; exit 130' TERM INT HUP
    load_project_steps "$folder" "$version" "$link" "$3"
    rc=$?
    if [ $rc -ne 0 ] && [ "$DRY" -eq 0 ]; then
        load_project_undo
    fi
    trap - TERM INT HUP
    LOAD_UNDO_LINK=""
    return $rc
}

# PrestaShop 1.7+ guarda su configuracion (con la BBDD) en var/cache: si es la de otro sitio (la del
# contenedor de Docker, db, o la de produccion), la tienda no conecta con su BBDD en LAMPP (error 500).
# Se aparta (a ~/lvm-copias) la cache cuya BBDD no es la de app/config/parameters.php: se rehace sola
function ps_stale_cache() {
    local root=$HTDOCS_DIR/$1 env
    [ -f "$root/app/config/parameters.php" ] || return 0
    for env in $(/usr/bin/python3 -I - "$root" <<'EOF'
import glob, os, re, sys
root = sys.argv[1]
def db(path):
    try:
        text = open(path, encoding="utf-8", errors="replace").read(200000)
    except OSError:
        return None
    return tuple((re.search(r"""['"]%s['"]\s*=>\s*['"]([^'"]*)['"]""" % k, text) or [None, ""])[1]
                 for k in ("database_host", "database_name", "database_user"))
want = db(os.path.join(root, "app/config/parameters.php"))
for cached in glob.glob(os.path.join(root, "var/cache/*/appParameters.php")):
    env = os.path.basename(os.path.dirname(cached))
    if want and re.fullmatch(r"[A-Za-z0-9_-]+", env) and db(cached) not in (None, want):
        print(env)
EOF
    ); do
        [ -L "$root/var/cache/$env" ] && continue
        if [ "$DRY" -eq 1 ]; then
            echo "  [simulacion] se aparta var/cache/$env de $1 (lleva otra BBDD)"
            continue
        fi
        mkdir -p -m 700 "$HOME/lvm-copias"
        mv "$root/var/cache/$env" "$HOME/lvm-copias/$1-cache-$env-$(date +%Y%m%d-%H%M%S)" \
            && echo "La cache de la tienda (var/cache/$env) era de otra BBDD (de Docker o de produccion): apartada en ~/lvm-copias, se rehace sola"
    done
    return 0
}

# Los cambios de load_project (ver arriba): <carpeta> <version> <enlace> <base>
function load_project_steps() {
    local folder=$1 version=$2 link=$3 sudo="" secured=1
    htdocs_close_world "$HTDOCS_DIR/$folder"
    ps_stale_cache "$folder"

    [ -w "$HTDOCS_DIR" ] || sudo=$SUDO
    if [ -L "$HTDOCS_DIR/$link" ]; then
        run $sudo rm "$HTDOCS_DIR/$link" || return 1
    fi
    run $sudo ln -s "$folder/" "$HTDOCS_DIR/$link" || return 1

    # Solo para este Mac: si cambia algo con la version en marcha, se reinicia para aplicarlo
    local web_dir=$(active_dir)
    [ -n "$version" ] && web_dir=$BASE_DIR/XAMPP-$version
    if [ -n "$web_dir" ]; then
        secure_version "$web_dir"
        case $? in
            0) secured=0 ;;
            2) secure_failed 2 "$web_dir" && return 1 ;;
        esac
        vhosts_root && secured=0
    fi

    if [ -n "$version" ] && [ "$(active_dir)" != "$(realpath_f "$BASE_DIR/XAMPP-$version")" ]; then
        echo "Activando XAMPP-$version..."
        use_version "$version" || return 1
    elif [ -n "$(active_dir)" ] && ! lampp_running; then
        echo "Arrancando $(basename "$(active_dir)")..."
        run xampp_ctl start
    elif [ $secured -eq 0 ]; then
        echo "Reiniciando $(basename "$(active_dir)") para que solo se pueda entrar desde este Mac..."
        run xampp_ctl restart > /dev/null || { echo "No se ha podido reiniciar. Reinicia la version activa."; return 1; }
    elif [ -f "$LINK/xamppfiles/logs/httpd.pid" ]; then
        # Cada proceso de PHP-FPM recuerda a donde apuntaba el enlace (realpath_cache, 120 s) y
        # seguiria sirviendo el proyecto anterior: recarga suave de PHP-FPM y Apache
        echo "Recargando Apache para que PHP no siga sirviendo el proyecto anterior..."
        run xampp_ctl reloadapache > /dev/null || { echo "No se ha podido recargar Apache. Reinicia la version activa."; return 1; }
    fi

    # Tienda PrestaShop: su dominio con vhost, certificado y falseado en /etc/hosts. Otro proyecto:
    # ningun dominio falseado
    # La base con la que se carga queda asociada a la carpeta (wp-config.php la usa la proxima vez)
    [[ "$4" =~ ^[A-Za-z0-9_-]+$ ]] && remember_project "$4" "$folder" "$(active_name)"
    load_project_domain "$folder" "$4" || return 1
    # Correo de pruebas: Mailpit con la version y la BBDD del proyecto al dia (sus plugins de correo, la
    # configuracion de la tienda)
    mailpit_sync
    local mdb
    mdb=$(mail_project_db "$folder" "$4") && db_names "$(active_dir)" | grep -qxF "$mdb" && mail_db "$mdb"
    # Imagenes de produccion (media-proyecto): las de este proyecto en el vhost de los proyectos
    media_sync || echo "Aviso: no se han podido poner en $link las imagenes de produccion de $folder"

    echo "Proyecto cargado: $link -> $folder$([ -n "$(active_dir)" ] && echo " ($(basename "$(active_dir)"))")"
}

# ===========================================================================
# Tiendas PrestaShop: dominio propio, certificado y /etc/hosts falseado
# ===========================================================================
# PrestaShop redirige siempre al dominio guardado en su base (tabla shop_url), asi que no se puede
# ver por web.local. Se monta como en el manual de XAMPP del equipo: un vhost por dominio (http y
# https) con DocumentRoot en la carpeta del proyecto, un certificado autofirmado (en el Mac, en
# XAMPP-compartido/ssl, junto al de web.local) y el dominio falseado en /etc/hosts (127.0.0.1 y ::1).
# Al cargar otro proyecto, el dominio deja de estar falseado y vuelve a llevar a la web real.
# (LVM_SSL_CERTS/LVM_SSL_KEYS solo para pruebas)
SSL_CERTS_DIR=${LVM_SSL_CERTS:-$COMMON/ssl}
SSL_KEYS_DIR=${LVM_SSL_KEYS:-$COMMON/ssl}
OWN_SSL_DIR=$COMMON/ssl

# Base de datos y prefijo de tablas de una tienda PrestaShop: base|prefijo. Nada si no lo es.
function ps_config() {
    python3 -I - "$HTDOCS_DIR/$1" <<'EOF'
import os, re, sys
root = sys.argv[1]
rules = [
    ("app/config/parameters.php",
     r"""['"]database_name['"]\s*=>\s*['"]([^'"]+)""", r"""['"]database_prefix['"]\s*=>\s*['"]([^'"]*)"""),
    ("config/settings.inc.php",
     r"""define\(\s*['"]_DB_NAME_['"]\s*,\s*['"]([^'"]+)""", r"""define\(\s*['"]_DB_PREFIX_['"]\s*,\s*['"]([^'"]*)"""),
]
for rel, rx_db, rx_prefix in rules:
    try:
        if not os.path.isfile(os.path.join(root, rel)) or os.path.getsize(os.path.join(root, rel)) > 2000000:
            raise OSError("no es un fichero normal")
        with open(os.path.join(root, rel), errors="replace") as f:
            text = f.read()
    except OSError:
        continue
    db, prefix = re.search(rx_db, text), re.search(rx_prefix, text)
    if db:
        print("%s|%s" % (db.group(1), prefix.group(1) if prefix else "ps_"))
        break
EOF
}

# Virtual hosts sin comentar de VHOSTS_FILE: puerto|carpeta de htdocs|ServerName|alias|certificado|clave
function vhosts_info() {
    [ -f "$VHOSTS_FILE" ] || return 0
    python3 -I - "$VHOSTS_FILE" <<'EOF'
import re, sys
block = None
for raw in open(sys.argv[1], errors="replace"):
    line = raw.split("#", 1)[0].strip() if raw.lstrip().startswith("#") else raw.strip()
    if not line:
        continue
    m = re.match(r"<VirtualHost\s+[^>]*:(\d+)\s*>", line, re.I)
    if m:
        block = {"port": m.group(1), "folder": "", "name": "", "alias": [], "crt": "", "key": ""}
        continue
    if block is None:
        continue
    if re.match(r"</VirtualHost>", line, re.I):
        if block["name"]:
            print("|".join([block["port"], block["folder"], block["name"].lower(),
                            " ".join(a.lower() for a in block["alias"]), block["crt"], block["key"]]))
        block = None
        continue
    key, value = (re.split(r"\s+", line, maxsplit=1) + [""])[:2]
    value = value.strip().strip('"')
    key = key.lower()
    if key == "documentroot":
        m = re.search(r"/htdocs/([^/\s]+)", value)
        block["folder"] = m.group(1) if m else ""
    elif key == "servername":
        block["name"] = value.split(":")[0]
    elif key == "serveralias":
        block["alias"] += value.split()
    elif key == "sslcertificatefile":
        block["crt"] = value
    elif key == "sslcertificatekeyfile":
        block["key"] = value
EOF
}

function valid_domain() {
    [[ "$1" =~ ^[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?(\.[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?)+$ ]]
}

# Certificado autofirmado (no de CA) de <dominio> y <alias> en <crt> y su clave en <key>:
# make_selfsigned <dominio> <alias> <crt> <key>. openssl corre con tu usuario en una carpeta temporal
# tuya y lo hecho se instala (con sudo si la carpeta es de root) solo si <crt> y <key> estan en las
# carpetas de certificados del gestor: las rutas de un vhost las puede haber escrito cualquier programa
# tuyo (la copia de los vhosts es tuya) y root no debe crear ni machacar ficheros donde digan.
function make_selfsigned() {
    local cn=$1 alt=$2 crt=$3 key=$4 tmp s="" d ok_crt=0 ok_key=0 openssl=/usr/bin/openssl
    # El de Homebrew (si esta) corre con tu usuario: es tuyo, pero ya no como root
    command -v brew > /dev/null && [ -x "$(brew --prefix openssl@3 2> /dev/null)/bin/openssl" ] \
        && openssl="$(brew --prefix openssl@3)/bin/openssl"
    for d in "$SSL_CERTS_DIR" "$OWN_SSL_DIR"; do [ "$(dirname "$crt")" == "$d" ] && ok_crt=1; done
    for d in "$SSL_KEYS_DIR" "$OWN_SSL_DIR"; do [ "$(dirname "$key")" == "$d" ] && ok_key=1; done
    if [ $ok_crt -eq 0 ] || [ $ok_key -eq 0 ] || ! [[ "$(basename "$crt")" =~ ^[A-Za-z0-9][A-Za-z0-9._-]*\.(crt|pem)$ ]] \
            || ! [[ "$(basename "$key")" =~ ^[A-Za-z0-9][A-Za-z0-9._-]*\.(key|pem)$ ]] || ! valid_domain "$cn"; then
        echo "El certificado de $cn ($crt) no esta en la carpeta de certificados del gestor ($OWN_SSL_DIR): no se crea."
        echo "Pulsa Arreglarlos en el aviso de certificados (Versiones) o: lvm-instalador arreglar-certificados"
        return 1
    fi
    { [ -d "$(dirname "$crt")" ] && [ -w "$(dirname "$crt")" ] && [ -w "$(dirname "$key")" ]; } || s=$SUDO
    [ -d "$(dirname "$crt")" ] && [ -d "$(dirname "$key")" ] || run $s mkdir -p "$(dirname "$crt")" "$(dirname "$key")" || return 1
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] certificado autofirmado de $cn en $crt (clave en $key)"
        return 0
    fi
    # Como root, solo en carpetas de root sin enlaces (la carpeta ssl y XAMPP-compartido) y sin un
    # enlace en el destino: si no, root escribiria a traves de el en otro fichero del Mac
    if [ -n "$s" ]; then
        for d in "$(dirname "$crt")" "$(dirname "$key")" "$COMMON"; do
            if [ -L "$d" ] || [ "$(stat -f %u "$d" 2> /dev/null)" != 0 ]; then
                echo "No se crea el certificado de $cn: $d no es una carpeta del administrador (vuelve a protegerla)"
                return 1
            fi
        done
        if [ -L "$crt" ] || [ -L "$key" ]; then
            echo "No se crea el certificado de $cn: $crt o $key es un enlace"
            return 1
        fi
    fi
    tmp=$(mktemp -d "${TMPDIR:-/tmp}/lvm-cert.XXXXXX") || return 1
    # Las extensiones van en un fichero de configuracion (la LibreSSL de macOS 12 no tiene -addext)
    printf '[req]\ndistinguished_name = dn\nx509_extensions = ext\nprompt = no\n[dn]\nCN = %s\n[ext]\nbasicConstraints = critical,CA:FALSE\nsubjectAltName = DNS:%s\n' \
        "$cn" "$cn${alt:+,DNS:$alt}" > "$tmp/cnf"
    if ! (umask 077; "$openssl" req -x509 -nodes -newkey rsa:2048 -days 3650 -config "$tmp/cnf" \
            -keyout "$tmp/key" -out "$tmp/crt") > /dev/null 2>&1; then
        rm -rf "$tmp"
        echo "No se ha podido crear el certificado de $cn"
        return 1
    fi
    if [ -n "$s" ]; then
        # Los abre tu usuario (redireccion) y root solo escribe: si mientras tanto cambiaran el
        # temporal por un enlace a un fichero de root, root no lo copiaria
        $s sh -c 'umask 022; cat > "$1"' sh "$crt" < "$tmp/crt" && $s chown root:wheel "$crt" && $s chmod 644 "$crt" \
            && $s sh -c 'umask 077; cat > "$1"' sh "$key" < "$tmp/key" && $s chown root:wheel "$key" && $s chmod 600 "$key"
    else
        install -m 644 "$tmp/crt" "$crt" && install -m 600 "$tmp/key" "$key"
    fi || { rm -rf "$tmp"; echo "No se ha podido guardar el certificado de $cn"; return 1; }
    rm -rf "$tmp"
    return 0
}

# ===========================================================================
# Certificados de los vhosts en los que confia todo el equipo
# ===========================================================================
# Un certificado de proyecto que el equipo da por bueno para todo (en /etc/ssl/certs, o de CA, o
# firmado por una CA local sin limite de dominios cuya clave esta en tu carpeta) deja que quien
# consiga su clave falsifique cualquier web real (el banco, Google) en este equipo. Ver CERTS_PY.
CERTS_PY='# Revisa los certificados de los vhosts https. Imprime:
#   C|dominio|crt|key|motivo   un vhost cuyo certificado hay que cambiar (motivo: falta = no existe;
#                              sistema = esta en
#                              /etc/ssl/certs, donde el sistema lo toma como de confianza; ca = es de
#                              CA y su clave podria firmar cualquier web; firmado = lo firmo una CA
#                              local sin limite de dominios)
#   A|nombre|sha256|sha1|donde una CA local de confianza, sin limite de dominios, que firma
#                              certificados de los vhosts (donde: file:<ruta>, nss:<carpeta>:<nombre>
#                              o llavero:<ruta>)
#   K|ruta                     la clave privada de esa CA en tu carpeta personal (sin ella no se
#                              avisa de la CA: lo que firme no puede salir de este equipo)
# CERTS_PY <linux|mac> <puerto https>; los vhosts en LVM_INFO (vhosts_info)
import base64, glob, hashlib, os, re, subprocess, sys, tempfile
osname, https = sys.argv[1], sys.argv[2]
HOME = os.path.expanduser("~")
def run(args, data=None):
    # En su sesion, sin terminal: certutil carga los modulos de pkcs11.txt de tu nssdb, y la terminal
    # de la tarea tiene el permiso de sudo recordado
    kw = {"input": data} if data is not None else {"stdin": subprocess.DEVNULL}
    try:
        r = subprocess.run(args, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, timeout=20,
                           start_new_session=True, **kw)
        return r.stdout.decode("utf-8", "replace") if r.returncode == 0 else ""
    except (OSError, subprocess.SubprocessError):
        return ""
def pems(text):
    return re.findall(r"-----BEGIN CERTIFICATE-----[A-Za-z0-9+/=\s]+?-----END CERTIFICATE-----", text)
def info(pem):
    out = run(["openssl", "x509", "-noout", "-subject_hash", "-issuer_hash", "-text"], pem.encode())
    lines = out.splitlines()
    if len(lines) < 3:
        return None
    der = base64.b64decode("".join(l for l in pem.splitlines() if not l.startswith("-----")))
    cn = re.search(r"Subject:.*?CN\s*=\s*([^,/\n]+)", out)
    return {"subj": lines[0].strip(), "iss": lines[1].strip(), "ca": "CA:TRUE" in out,
            "nc": "Name Constraints" in out, "cn": (cn.group(1).strip() if cn else "?"),
            "sha256": hashlib.sha256(der).hexdigest(), "sha1": hashlib.sha1(der).hexdigest(), "pem": pem}
def read(path):
    try:
        if os.path.isfile(path) and os.path.getsize(path) <= 1 << 20:
            return open(path, errors="replace").read()
    except OSError:
        pass
    return ""
store = None
def trust_store():
    # CAs añadidas a mano en este equipo (las del sistema operativo no se miran). LVM_PRUEBA_CAS: una
    # carpeta con mas, solo para las pruebas
    found = []
    for f in sorted(glob.glob(os.path.join(os.environ.get("LVM_PRUEBA_CAS", "/nonexistent"), "*.crt"))):
        for p in pems(read(f)):
            found.append((p, "file:" + f))
    if osname == "linux":
        for f in sorted(glob.glob("/usr/local/share/ca-certificates/**/*.crt", recursive=True)):
            for p in pems(read(f)):
                found.append((p, "file:" + f))
        dbs = [os.path.join(HOME, ".pki/nssdb")]
        dbs += glob.glob(os.path.join(HOME, ".mozilla/firefox/*/"))
        dbs += glob.glob(os.path.join(HOME, "snap/firefox/common/.mozilla/firefox/*/"))
        for d in dbs:
            d = d.rstrip("/")
            if not os.path.isfile(os.path.join(d, "cert9.db")):
                continue
            for line in run(["certutil", "-L", "-d", "sql:" + d]).splitlines()[4:]:
                m = re.match(r"^(.*?)\s+([CcTtPpu]*,[CcTtPpu]*,[CcTtPpu]*)\s*$", line)
                if not m or "|" in m.group(1) or "\n" in m.group(1):
                    continue
                if not re.search(r"[CT]", m.group(2).split(",")[0]):
                    continue
                for p in pems(run(["certutil", "-L", "-d", "sql:" + d, "-n", m.group(1), "-a"])):
                    found.append((p, "nss:%s:%s" % (d, m.group(1))))
    else:
        for kc in ("/Library/Keychains/System.keychain", os.path.join(HOME, "Library/Keychains/login.keychain-db")):
            if os.path.exists(kc):
                for p in pems(run(["security", "find-certificate", "-a", "-p", kc])):
                    found.append((p, "llavero:" + kc))
    out = []
    for p, where in found:
        i = info(p)
        if i and i["ca"]:
            out.append((i, where))
    return out
def signed_by(cert, ca):
    # La firma de verdad (no solo el nombre del emisor, que cualquiera puede copiar en un certificado)
    with tempfile.TemporaryDirectory() as d:
        open(os.path.join(d, "ca"), "w").write(ca["pem"] + "\n")
        open(os.path.join(d, "crt"), "w").write(cert["pem"] + "\n")
        out = run(["openssl", "verify", "-CAfile", os.path.join(d, "ca"), os.path.join(d, "crt")])
    return out.strip().endswith("OK")
cas, rows, keys = {}, [], {}
for row in os.environ.get("LVM_INFO", "").splitlines():
    f = row.split("|")
    if len(f) < 6 or f[0] != https or not f[4] or not re.fullmatch(r"[a-z0-9.-]+", f[2]):
        continue
    dom, crt, key = f[2], f[4], f[5]
    if "|" in crt + key:
        continue
    try:
        os.lstat(crt)
    except FileNotFoundError:
        # Sin certificado Apache no arranca: Arreglarlos le pone uno propio
        rows.append((dom, crt, key, "falta", ""))
        continue
    except OSError:
        continue
    text = read(crt)
    p = pems(text)
    i = info(p[0]) if p else None
    if not i:
        continue
    why, by = "", ""
    if osname == "linux" and os.path.dirname(os.path.realpath(crt)) == "/etc/ssl/certs":
        why = "sistema"
    if i["ca"] or i["subj"] != i["iss"]:
        if store is None:
            store = trust_store()
    # De CA solo importa si el equipo confia en el (si no, nadie acepta lo que firme su clave) y si
    # su clave la puede leer un programa tuyo. Entonces tambien se quita su confianza (fila A)
    if i["ca"] and os.access(key, os.R_OK):
        for ca, where in store or []:
            if ca["sha256"] == i["sha256"]:
                why = why or "ca"
                cas.setdefault(ca["sha256"], (ca, set()))[1].add(where)
                keys.setdefault(ca["sha256"], [])
                if key not in keys[ca["sha256"]]:
                    keys[ca["sha256"]].append(key)
    if i["subj"] != i["iss"]:
        for ca, where in store:
            if ca["subj"] == i["iss"] and not ca["nc"] and signed_by(i, ca):
                by = ca["sha256"]
                cas.setdefault(by, (ca, set()))[1].add(where)
    rows.append((dom, crt, key, why, by))
# Las CAs que firman esos certificados solo son un peligro si su clave esta al alcance de un programa
# tuyo (en tu carpeta personal): entonces se avisa y Arreglarlos las quita. Una CA de empresa cuya
# clave no esta en este equipo no se toca
if cas:
    pubs = {}
    for sha, (ca, _) in cas.items():
        pub = run(["openssl", "x509", "-noout", "-pubkey"], ca["pem"].encode()).strip()
        if pub:
            pubs[pub] = sha
    seen = 0
    for top in [HOME] + [d for d in [os.environ.get("LVM_PRUEBA_CLAVES", "")] if d]:
        for root, dirs, files in os.walk(top):
            dirs[:] = [d for d in dirs if not d.startswith(".") or d in (".ssh", ".local", ".config")]
            if root.count(os.sep) - top.count(os.sep) >= 3:
                dirs[:] = []
            for n in files:
                if not re.search(r"(?i)(\.key|key\.pem)$", n):
                    continue
                path = os.path.join(root, n)
                seen += 1
                if seen > 2000 or os.path.islink(path) or "|" in path:
                    continue
                k = read(path)
                if "PRIVATE KEY" not in k:
                    continue
                pub = run(["openssl", "pkey", "-pubout", "-passin", "pass:"], k.encode()).strip()
                if pub in pubs:
                    keys.setdefault(pubs[pub], []).append(path)
for dom, crt, key, why, by in rows:
    if not why and by in keys:
        why = "firmado"
    if why:
        print("C|%s|%s|%s|%s" % (dom, crt, key, why))
for sha, (ca, wheres) in cas.items():
    if sha not in keys:
        continue
    for where in sorted(wheres):
        print("A|%s|%s|%s|%s" % (ca["cn"].replace("|", "/"), sha, ca["sha1"], where))
    for path in keys[sha]:
        print("K|" + path)
'

# Lineas C|dominio|crt|key|motivo, A|CA|sha256|sha1|donde y (con --clave) K|ruta. Ver CERTS_PY.
# Para la ventana se guarda el resultado mientras no cambien los vhosts ni los almacenes de CAs
function cert_audit() {
    local stamp cache=$LOG_DIR/certificados f
    [ -f "$VHOSTS_FILE" ] || return 0
    stamp=$(for f in "$VHOSTS_FILE" "$OWN_SSL_DIR" "/Library/Keychains/System.keychain" "$HOME/Library/Keychains/login.keychain-db" "$HOSTS_FILE" "$LOG_DIR/confianza"; do
        [ -e "$f" ] && echo "$f $(stat -f %m "$f")"; done; echo "$1 $APP_VERSION")
    if [ "$1" != "--clave" ] && [ -f "$cache" ] && [ "$(head -1 "$cache")" == "#$(echo "$stamp" | md5 -q)" ]; then
        tail -n +2 "$cache"
        return 0
    fi
    local out info
    info=$(vhosts_info)
    # (y, para la ventana, los certificados propios con T|... y U|...: TRUST_PY)
    out=$(LVM_INFO=$info python3 -I -c "$CERTS_PY" mac "$PORT_HTTPS" "$@"
          [ "$1" == "--clave" ] || LVM_INFO=$info LVM_HOSTS_FILE=$HOSTS_FILE LVM_TRUST_DIR=$LOG_DIR/confianza python3 -I -c "$TRUST_PY" mac "$PORT_HTTPS" "$OWN_SSL_DIR" | grep '^[TU]|')
    if [ "$1" != "--clave" ] && [ -d "$LOG_DIR" ]; then
        { echo "#$(echo "$stamp" | md5 -q)"; [ -n "$out" ] && echo "$out"; } > "$cache"
    fi
    [ -n "$out" ] && echo "$out"
    return 0
}

# arreglar-certificados: cada vhost con un certificado de los de arriba pasa a uno autofirmado
# propio en la carpeta de certificados del gestor (no de CA, solo para su dominio), y las CAs locales
# sin limite de dominios que los firmaban dejan de ser de confianza en este Mac. La clave de la CA no
# se borra (puede que la quieras): se dice donde esta
function fix_certs() {
    local audit t dom crt key why copy n=0 cas=0 failed=0 old_files=() keyfile
    audit=$(cert_audit --clave)
    if ! grep -qE '^(C|A)\|' <<< "$audit"; then
        echo "Los certificados de los vhosts ya estan bien: ninguno es de confianza para todo este Mac."
        return 0
    fi
    copy=$(mktemp "${TMPDIR:-/tmp}/lvm-vhosts-cert.XXXXXX") || return 1
    cp "$VHOSTS_FILE" "$copy" || { rm -f "$copy"; return 1; }
    while IFS='|' read -r t dom crt key why; do
        [ "$t" == C ] || continue
        local new_crt="$OWN_SSL_DIR/$dom-selfsigned.crt" new_key="$OWN_SSL_DIR/$dom-selfsigned.key"
        case $why in
            sistema) echo "$dom: su certificado esta en /etc/ssl/certs (el sistema lo da por bueno para todo)" ;;
            ca) echo "$dom: su certificado es de CA (con su clave se firmaria cualquier web)" ;;
            firmado) echo "$dom: su certificado lo firma una CA de confianza sin limite de dominios" ;;
            falta) echo "$dom: su certificado ($crt) no existe" ;;
        esac
        echo "  -> certificado propio en $new_crt"
        make_selfsigned "$dom" "$(domain_alias "$dom")" "$new_crt" "$new_key" || { failed=$((failed + 1)); continue; }
        [ "$DRY" -eq 1 ] && { n=$((n + 1)); continue; }
        if ! LVM_DOM=$dom LVM_CRT=$new_crt LVM_KEY=$new_key python3 -I - "$copy" <<'PY'
import os, re, sys
path = sys.argv[1]
dom, crt, key = os.environ["LVM_DOM"], os.environ["LVM_CRT"], os.environ["LVM_KEY"]
lines = open(path, encoding="utf-8", errors="surrogateescape").read().split("\n")
out, block, start = [], None, 0
for line in lines:
    s = line.strip()
    if re.match(r"(?i)<VirtualHost\b", s):
        block, start = [], len(out)
    out.append(line)
    if block is not None:
        block.append(len(out) - 1)
        if re.match(r"(?i)</VirtualHost>", s):
            names = [re.split(r"\s+", out[i].strip(), maxsplit=1)[1].split(":")[0].lower() for i in block
                     if re.match(r"(?i)\s*ServerName\s+\S", out[i])]
            if dom in names:
                for i in block:
                    m = re.match(r"(?i)(\s*)(SSLCertificateFile|SSLCertificateKeyFile)(\s+)\S.*$", out[i])
                    if m:
                        out[i] = m.group(1) + m.group(2) + m.group(3) + "\"%s\"" % (crt if m.group(2).lower() == "sslcertificatefile" else key)
            block = None
open(path, "w", encoding="utf-8", errors="surrogateescape").write("\n".join(out))
PY
        then
            failed=$((failed + 1))
            continue
        fi
        n=$((n + 1))
        :
    done <<< "$audit"
    if [ $n -gt 0 ]; then
        if [ "$DRY" -eq 1 ]; then
            echo "  [simulacion] los vhosts pasan a usar esos certificados (copia de root, comprobacion y recarga de Apache)"
        else
            edit_vhosts --aplicar "$copy" || { rm -f "$copy"; echo "No se han cambiado los vhosts: los certificados viejos siguen en uso."; return 1; }
            rm -f "$LOG_DIR/certificados"
        fi
    fi
    rm -f "$copy"

    if [ $failed -gt 0 ] && grep -q '^A|' <<< "$audit"; then
        echo "No se quita la confianza a la CA: $failed proyecto(s) no se han podido pasar a su certificado"
        echo "propio y dejarian de funcionar. Revisa sus vhosts y vuelve a pulsar Arreglarlos."
        audit=$(grep -v '^A|' <<< "$audit")
    fi
    while IFS='|' read -r t _ _ sha1 where; do
        [ "$t" == A ] || continue
        cas=1
        case $where in
            llavero:*)
                # Primero sus ajustes de confianza (los que pone mkcert con add-trusted-cert): borrar
                # el certificado no los quita
                local kc=${where#llavero:} pem
                pem=$(mktemp "${TMPDIR:-/tmp}/lvm-ca.XXXXXX") || continue
                security find-certificate -a -p "$kc" 2> /dev/null | python3 -I -c '
import base64, hashlib, re, sys
for p in re.findall(r"-----BEGIN CERTIFICATE-----[A-Za-z0-9+/=\s]+?-----END CERTIFICATE-----", sys.stdin.read()):
    der = base64.b64decode("".join(p.split("\n")[1:-1]))
    if hashlib.sha1(der).hexdigest() == sys.argv[1]:
        print(p)
        break' "$sha1" > "$pem"
                if [ "$kc" == /Library/Keychains/System.keychain ]; then
                    echo "Quitando la CA de confianza del llavero del sistema ($sha1)..."
                    [ -s "$pem" ] && run $SUDO security remove-trusted-cert -d "$pem"
                    run $SUDO security delete-certificate -Z "$sha1" "$kc"
                else
                    echo "Quitando la CA de tu llavero ($sha1)..."
                    [ -s "$pem" ] && run security remove-trusted-cert "$pem"
                    run security delete-certificate -Z "$sha1" "$kc"
                fi
                rm -f "$pem" ;;
        esac
    done <<< "$audit"
    keyfile=$(grep '^K|' <<< "$audit" | cut -d'|' -f2- | head -5)
    if [ -n "$keyfile" ]; then
        echo
        echo "La clave privada de esa CA sigue en tu carpeta:"
        sed 's/^/  /' <<< "$keyfile"
        echo "Ya no vale para falsificar webs en este Mac, pero si la usas en otros equipos, bórrala de aqui"
        echo "o guardala cifrada fuera de tu carpeta personal."
    fi
    rm -f "$LOG_DIR/certificados"
    echo
    echo "Certificados arreglados. Para que el navegador no avise en cada proyecto https, pulsa Confiar"
    echo "en el aviso «El navegador avisa al abrir estos proyectos» de la ventana"
    echo "(o: lvm-instalador confiar-certificados)."
    return 0
}

# ===========================================================================
# Que el navegador acepte el certificado propio de cada proyecto
# ===========================================================================
# Con el aviso de certificado (La conexion no es privada) el navegador no deja entrar a las
# herramientas que lo manejan (Claude in Chrome y parecidas): no pueden aceptar el aviso. Se confia en
# el certificado de cada proyecto, no en una CA, y solo en uno que no le valga a nadie para otra web.
TRUST_PY='# Certificados propios de los proyectos https y si el navegador ya confia en ellos. Imprime:
#   T|dominio|crt|sha1|1 o 0|real   se puede confiar en el (1: el navegador ya confia; real: 1 si
#                                   es el dominio real de una tienda, falseado en hosts)
#   X|dominio|motivo                no se confia en el
#   U|dominio (Linux)               el navegador acepta uno nuestro con ese nombre en el que ya no
#   U|dominio|copia|sha1|1 o 0 (Mac)  se puede confiar: hay que quitarlo (Mac: 0, ya no lo acepta)
# Solo vale uno autofirmado que no es de CA, solo para su dominio y su alias (www), de root en la
# carpeta de certificados del gestor y con la clave solo para root: confiar en el no deja falsificar
# ninguna otra web. El de un dominio real (una tienda), solo mientras el y su alias esten falseados en
# hosts: Apache corre con tu usuario y tiene la clave en memoria, donde la puede leer el PHP de
# cualquier web, y con ella se podria suplantar la web de verdad; mientras esta falseado, el navegador
# no va a la web de verdad, y al dejar de falsearlo sale con U (se quita)
# TRUST_PY <linux|mac> <puerto https> <carpeta de certificados> [dominio]; los vhosts en LVM_INFO,
# hosts en LVM_HOSTS_FILE y (Mac) las copias de los que se han confiado en LVM_TRUST_DIR
import base64, glob, hashlib, os, plistlib, re, stat, subprocess, sys, tempfile
osname, https, ssldir = sys.argv[1], sys.argv[2], os.path.realpath(sys.argv[3])
only = sys.argv[4] if len(sys.argv) > 4 else ""
HOME = os.path.expanduser("~")
# (LVM_PRUEBA_DUENO: el usuario que hace de root, solo para las pruebas)
ROOT = int(os.environ.get("LVM_PRUEBA_DUENO", "") or 0)
def run(args, data=None):
    kw = {"input": data} if data is not None else {"stdin": subprocess.DEVNULL}
    try:
        r = subprocess.run(args, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, timeout=20,
                           start_new_session=True, **kw)
        return r.stdout.decode("utf-8", "replace") if r.returncode == 0 else ""
    except (OSError, subprocess.SubprocessError):
        return ""
def pems(text):
    return re.findall(r"-----BEGIN CERTIFICATE-----[A-Za-z0-9+/=\s]+?-----END CERTIFICATE-----", text)
def sha1(pem):
    der = base64.b64decode("".join(l for l in pem.splitlines() if not l.startswith("-----")))
    return hashlib.sha1(der).hexdigest().upper()
# En los que ya confia el navegador. Linux: los de confianza P (la de un servidor) del almacen de
# Chrome y Chromium. Mac: los de tus ajustes de confianza (los que pone add-trusted-cert)
trusted = set()
if osname == "linux":
    db = os.path.join(HOME, ".pki/nssdb")
    if os.path.isfile(os.path.join(db, "cert9.db")):
        for line in run(["certutil", "-L", "-d", "sql:" + db]).splitlines()[4:]:
            m = re.match(r"^(.*?)\s+([CcTtPpu]*,[CcTtPpu]*,[CcTtPpu]*)\s*$", line)
            if m and "P" in m.group(2).split(",")[0] and "|" not in m.group(1):
                for p in pems(run(["certutil", "-L", "-d", "sql:" + db, "-n", m.group(1), "-a"])):
                    trusted.add(sha1(p))
else:
    with tempfile.TemporaryDirectory() as t:
        run(["security", "trust-settings-export", os.path.join(t, "ajustes.plist")])
        try:
            with open(os.path.join(t, "ajustes.plist"), "rb") as f:
                trusted = {k.upper() for k in plistlib.load(f).get("trustList", {})}
        except Exception:
            pass
def own(path, bad_bits):
    # De root, fichero normal (no enlace) directamente en la carpeta de certificados del gestor
    try:
        st = os.lstat(path)
    except OSError:
        return False
    return stat.S_ISREG(st.st_mode) and st.st_uid == ROOT and not st.st_mode & bad_bits \
        and os.path.dirname(os.path.realpath(path)) == ssldir
try:
    sd = os.stat(ssldir)
    dir_ok = sd.st_uid == ROOT and not sd.st_mode & 0o022
except OSError:
    dir_ok = False
# Falseado: todas las lineas sin comentar de hosts que lo llevan, a este equipo (127.x o ::1)
where = {}
try:
    for line in open(os.environ.get("LVM_HOSTS_FILE") or "/etc/hosts", errors="replace"):
        w = line.split("#")[0].split()
        for n in w[1:]:
            where.setdefault(n.lower(), set()).add(w[0])
except OSError:
    pass
def faked(name):
    ips = where.get(name)
    return bool(ips) and all(ip.startswith("127.") or ip == "::1" for ip in ips)
seen, good = set(), {}
for row in os.environ.get("LVM_INFO", "").splitlines():
    f = row.split("|")
    if len(f) < 6 or f[0] != https or not re.fullmatch(r"[a-z0-9.-]+", f[2]) or not f[4]:
        continue
    dom, crt, key = f[2], f[4], f[5]
    if only and dom != only or dom in seen:
        continue
    seen.add(dom)
    alias = dom[4:] if dom.startswith("www.") else "www." + dom
    real = dom.rsplit(".", 1)[-1] not in ("local", "test", "localhost", "example", "invalid", "internal",
                                          "lan", "localdomain") and not dom.endswith(".home.arpa")
    if real and not (faked(dom) and faked(alias)):
        print("X|%s|es un dominio real y no esta falseado en hosts: con su clave (Apache la tiene en memoria) se podria suplantar la web de verdad; se confia en el solo mientras este falseado (Dominios y hosts)" % dom)
        continue
    if not dir_ok or not own(crt, 0o022) or not own(key, 0o077) or ROOT == 0 and os.access(key, os.R_OK):
        print("X|%s|no usa un certificado propio del gestor (pulsa Arreglarlos en el aviso de certificados)" % dom)
        continue
    try:
        with open(crt, errors="replace") as fh:
            p = pems(fh.read(1 << 16))
    except OSError:
        continue
    out = run(["openssl", "x509", "-noout", "-subject_hash", "-issuer_hash", "-text"], p[0].encode()) \
        if len(p) == 1 else ""
    lines = out.splitlines()
    san = re.search(r"Subject Alternative Name:.*\n\s*(.+)", out)
    names = {n.strip() for n in san.group(1).split(",")} if san else set()
    if len(lines) < 3 or lines[0].strip() != lines[1].strip() or "CA:TRUE" in out \
            or not re.search(r"Basic Constraints:.*\n\s*CA:FALSE", out) \
            or not names or not names <= {"DNS:" + dom, "DNS:" + alias}:
        print("X|%s|su certificado no es uno autofirmado solo para %s (pulsa Arreglarlos en el aviso de certificados)" % (dom, dom))
        continue
    s = sha1(p[0])
    good[dom] = s
    print("T|%s|%s|%s|%d|%d" % (dom, crt, s, s in trusted, real))
# Los nuestros que acepta el navegador y en los que ya no se puede confiar (una tienda que ya no esta
# falseada, un vhost que ya no esta...). Linux: por su nombre (lvm-instalador <dominio>) en cada
# almacen. Mac: por las copias que se guardan al confiar (<dominio>.<sha1>.crt)
if osname == "linux":
    gone = set()
    for db in [os.path.join(HOME, ".pki/nssdb"), os.path.join(HOME, "snap/chromium/current/.pki/nssdb")] \
            + glob.glob(HOME + "/.mozilla/firefox/*/") + glob.glob(HOME + "/snap/firefox/common/.mozilla/firefox/*/"):
        if not os.path.isfile(os.path.join(db, "cert9.db")):
            continue
        for line in run(["certutil", "-L", "-d", "sql:" + db]).splitlines()[4:]:
            m = re.match(r"^lvm-instalador ([a-z0-9.-]+)\s+[CcTtPpu]*,[CcTtPpu]*,[CcTtPpu]*\s*$", line)
            if m and m.group(1) not in good and (not only or m.group(1) == only):
                gone.add(m.group(1))
    for d in sorted(gone):
        print("U|" + d)
else:
    rec = os.environ.get("LVM_TRUST_DIR", "")
    for name in sorted(os.listdir(rec)) if rec and os.path.isdir(rec) else []:
        m = re.fullmatch(r"([a-z0-9.-]+)\.([0-9A-F]{40})\.crt", name)
        if m and (not only or m.group(1) == only) and good.get(m.group(1)) != m.group(2):
            print("U|%s|%s|%s|%d" % (m.group(1), os.path.join(rec, name), m.group(2), m.group(2) in trusted))
'

# confiar-certificados [dominio|--hosts|--quitar]: el navegador (Safari, Chrome) acepta sin aviso el
# certificado propio de cada proyecto https (o solo el de ese dominio). Va a tus ajustes de confianza
# (llavero de inicio de sesion), solo para webs (ssl) y solo ese certificado, no una CA: no vale para
# ninguna otra web. El Mac pide tu contraseña en cada uno. Solo los que da por buenos TRUST_PY (los de
# una tienda con dominio real, mientras este falseada en hosts), y los que ya no (U|) se quitan: para
# eso se guarda una copia de cada uno en ~/.lvm-instalador/confianza.
# --hosts (al cambiar hosts): solo quita los de las tiendas que ya no estan falseadas (y dice cuales
# se pueden confiar). --quitar: solo quita
function browser_trust() {
    local only=$1 mode=todo out t dom crt sha1 ok real n=0 failed=0 rec=$LOG_DIR/confianza
    case "$only" in
        --hosts) mode=hosts only="" ;;
        --quitar) mode=quitar only="" ;;
    esac
    if [ -n "$only" ] && ! valid_domain "$only"; then
        echo "Dominio no valido: $only"
        return 1
    fi
    out=$(LVM_INFO=$(vhosts_info) LVM_HOSTS_FILE=$HOSTS_FILE LVM_TRUST_DIR=$rec python3 -I -c "$TRUST_PY" mac "$PORT_HTTPS" "$OWN_SSL_DIR" "$only")
    [ $mode == todo ] && grep '^X|' <<< "$out" | cut -d'|' -f2- | sed 's/|/: no se confia en el: /'
    # Los que el navegador acepta y ya no se puede confiar en ellos (una tienda que ya no esta
    # falseada: el navegador va a la web de verdad, y con su clave se la podria suplantar)
    while IFS='|' read -r t dom crt sha1 ok; do
        [ "$t" == U ] || continue
        if [ "$ok" == 1 ]; then
            echo "$dom: el Mac te pide la contraseña para que el navegador deje de aceptar su certificado..."
            if ! run security remove-trusted-cert "$crt"; then
                echo "$dom: no se ha cambiado (¿has cancelado la contraseña?): el navegador aun lo acepta."
                echo "Pulsa Quitar en el aviso de la ventana."
                failed=$((failed + 1))
                continue
            fi
            run security delete-certificate -Z "$sha1" "$HOME/Library/Keychains/login.keychain-db" > /dev/null 2>&1
            echo "$dom: el navegador ya no acepta su certificado (ya no esta falseado, o su certificado o su vhost han cambiado)"
            n=$((n + 1))
        fi
        run rm -f "$crt"
    done <<< "$out"
    if [ $mode == hosts ]; then
        # Las tiendas falseadas: se confia en ellas con el boton Confiar (pide la contraseña)
        grep '^T|.*|0|1$' <<< "$out" | cut -d'|' -f2 | while read -r dom; do
            echo "$dom: para que el navegador acepte su certificado mientras este falseado, pulsa Confiar en Versiones"
        done
    elif [ $mode == todo ] && grep -q '^T|' <<< "$out"; then
        while IFS='|' read -r t dom crt sha1 ok real; do
            [ "$t" == T ] || continue
            if [ "$ok" == 1 ]; then
                echo "$dom: el navegador ya lo aceptaba"
            else
                echo "$dom: el Mac te pide la contraseña para confiar en su certificado..."
                if ! run security add-trusted-cert -r trustRoot -p ssl -k "$HOME/Library/Keychains/login.keychain-db" "$crt"; then
                    echo "$dom: no se ha cambiado (¿has cancelado la contraseña?)"
                    failed=$((failed + 1))
                    continue
                fi
                echo "$dom: el navegador ya acepta su certificado$([ "$real" == 1 ] && echo " (mientras este falseado en hosts)")"
                n=$((n + 1))
            fi
            # La copia para poder quitarlo (al dejar de falsear la tienda o si deja de ser un proyecto)
            [ -f "$rec/$dom.$sha1.crt" ] || { run mkdir -p -m 700 "$rec" && run cp "$crt" "$rec/$dom.$sha1.crt"; }
        done <<< "$out"
    elif [ $mode == todo ] && ! grep -q '^U|' <<< "$out"; then
        echo "No hay ningun proyecto https${only:+ $only} con un certificado propio en el que confiar."
        [ -z "$only" ] || return 1
    fi
    rm -f "$LOG_DIR/certificados"
    [ $failed -eq 0 ] || return 1
    [ $n -gt 0 ] || return 0
    echo
    echo "Si Chrome estaba abierto y aun avisa en algun proyecto (o aun acepta uno que ya no esta falseado),"
    echo "cierralo del todo y vuelve a abrirlo."
    return 0
}

# Alias del dominio: www.dominio, o el dominio sin www si ya lo lleva
function domain_alias() {
    if [[ "$1" == www.* ]]; then echo "${1#www.}"; else echo "www.$1"; fi
}

# Dominio de una tienda PrestaShop. Primero el de su base (tabla shop_url, tienda principal), que es
# al que redirige; si la base no se puede leer (MariaDB parado o root con contraseña), el ServerName
# del vhost que ya apunte a la carpeta.
function ps_domain() {
    local folder=$1 config db prefix domain
    config=$(ps_config "$folder")
    db=${config%%|*} prefix=${config#*|}
    if [ -n "$db" ] && [[ "$db$prefix" =~ ^[A-Za-z0-9_-]+$ ]] && [ -x "$DB_CLIENT" ] \
            && db_base_table root "${MYSQL_PWD:-}" "$db" "${prefix}shop_url"; then
        # Si MariaDB se acaba de arrancar (cambio de version), se le dan unos segundos
        local try
        for try in 1 2 3 4 5 6; do
            domain=$("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N -e "SELECT domain FROM \`$db\`.\`${prefix}shop_url\` ORDER BY main DESC, active DESC, id_shop_url LIMIT 1" < /dev/null 2>&1) && break
            [[ "$domain" == *"Can't connect"* ]] && [ "$DRY" -eq 0 ] || break
            sleep 1
        done
        domain=$(tr 'A-Z' 'a-z' <<< "${domain%%:*}")
        valid_domain "$domain" && echo "$domain" && return 0
    fi
    domain=$(vhosts_info | awk -F'|' -v f="$folder" -v l="$(project_link)" '$2 == f && $3 != l { print $3; exit }')
    [ -n "$domain" ] && echo "$domain"
}

# ¿Hay ya un vhost con ese dominio que apunte a la carpeta?
function vhost_points_to() {
    vhosts_info | awk -F'|' -v d="$1" -v f="$2" '$3 == d && $2 == f { found = 1 } END { exit !found }'
}

# ¿Se parece el dominio a la carpeta? Su nombre registrable (lo de antes de la terminacion:
# mitienda en www.mitienda.com, ejemplo en tienda.ejemplo.com, cliente en
# cliente.com.es), de 4 letras o mas, va en el nombre de la carpeta sin sus palabras genericas
# (dob, prestashop, wordpress...): asi prestashop.com no vale para dob-prestashop-x
function domain_fits_folder() {
    local domain=${1#www.} folder label w n parts
    folder=$(tr 'A-Z' 'a-z' <<< "$2")
    for w in dob prestashop wordpress tienda shop html php web wp ps; do folder=${folder//$w/}; done
    folder=$(tr -d '._-' <<< "$folder")
    IFS=. read -r -a parts <<< "$(tr 'A-Z' 'a-z' <<< "$domain")"
    n=${#parts[@]}
    (( n >= 2 )) || return 1
    label=${parts[n-2]}
    if (( n >= 3 )) && [[ "$label" =~ ^(com|co|org|net|gob|edu|ac|nom)$ ]]; then label=${parts[n-3]}; fi
    label=$(tr -d '_-' <<< "$label")
    [ ${#label} -ge 4 ] && [[ "$folder" == *"$label"* ]]
}

# ¿Es <tabla> de <base> una tabla de verdad (no una vista, que podria ejecutar funciones del volcado
# con los permisos de quien la lee)? db_base_table <usuario> <contraseña> <base> <tabla>
function db_base_table() {
    local n
    if [ -n "$2" ]; then
        n=$(MYSQL_PWD=$2 "${DB_SAFE[@]}" "$DB_CLIENT" -u"$1" -N -e "SELECT COUNT(*) FROM information_schema.TABLES
            WHERE TABLE_SCHEMA='$3' AND TABLE_NAME='$4' AND TABLE_TYPE='BASE TABLE'" < /dev/null 2> /dev/null)
    else
        n=$(env -u MYSQL_PWD "${DB_SAFE[@]}" "$DB_CLIENT" -u"$1" -N -e "SELECT COUNT(*) FROM information_schema.TABLES
            WHERE TABLE_SCHEMA='$3' AND TABLE_NAME='$4' AND TABLE_TYPE='BASE TABLE'" < /dev/null 2> /dev/null)
    fi
    [ "$n" == 1 ]
}

# Correo del ServerAdmin de los vhosts que se crean: el de git del usuario que usa la app
# (user.email de su ~/.gitconfig) o usuario@localhost
function server_admin() {
    local user=${SUDO_USER:-$USER} home mail
    home=$(dscl . -read "/Users/$user" NFSHomeDirectory 2> /dev/null | awk '{ print $2 }')
    mail=$(HOME=${home:-$HOME} git config --global user.email 2> /dev/null)
    # (va como root en los vhosts: sin \ al final, que uniria la linea con la siguiente, ni comillas)
    [[ "$user" =~ ^[A-Za-z0-9._-]+$ ]] || user=webmaster
    [[ "$mail" =~ ^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+$ ]] && echo "$mail" || echo "$user@localhost"
}

# Comprueba que el dominio tiene vhost http y https apuntando a la carpeta y certificado. Lo que
# falte se crea como en el manual: certificado <dominio>-selfsigned en XAMPP-compartido/ssl y bloques al final
# de VHOSTS_FILE (se guarda copia en ~/lvm-copias). Deja PS_RELOAD=1 si ha cambiado algo.
function ps_vhost() {
    local folder=$1 domain=$2 alias info http https crt key other s="" block="" openssl=/usr/bin/openssl
    # El dominio va en el vhost, en /etc/hosts y en el nombre del certificado: solo uno valido
    valid_domain "$domain" || { echo "Dominio no valido: $domain"; return 1; }
    alias=$(domain_alias "$domain")
    info=$(vhosts_info)
    http=$(awk -F'|' -v p="$PORT_HTTP" -v d="$domain" '$1 == p && $3 == d' <<< "$info" | head -1)
    https=$(awk -F'|' -v p="$PORT_HTTPS" -v d="$domain" '$1 == p && $3 == d' <<< "$info" | head -1)

    other=$(printf '%s\n%s\n' "$http" "$https" | awk -F'|' -v f="$folder" '$0 != "" && $2 != f { print $2; exit }')
    if [ -n "$other" ]; then
        echo "Aviso: el vhost de $domain apunta a $HTDOCS_DIR/$other, no a $folder. No se cambia:"
        echo "revisalo en Editar vhosts si no es lo que quieres."
    fi

    crt=$(cut -d'|' -f5 <<< "$https") key=$(cut -d'|' -f6 <<< "$https")
    if [ -z "$https" ]; then
        crt="$SSL_CERTS_DIR/$domain-selfsigned.crt" key="$SSL_KEYS_DIR/$domain-selfsigned.key"
    fi
    if [ -n "$crt" ] && [ -n "$key" ] && [ ! -f "$crt" ]; then
        echo "Creando el certificado autofirmado de $domain ($crt)..."
        make_selfsigned "$domain" "$alias" "$crt" "$key" || return 1
        PS_RELOAD=1
    fi

    if [ -z "$http" ]; then
        block+="
<VirtualHost *:$PORT_HTTP>
    ServerAdmin $(server_admin)
    DocumentRoot \"$LINK/xamppfiles/htdocs/$folder\"
    ServerName $domain
    ServerAlias $alias
    ErrorLog \"logs/$domain-error_log\"
</VirtualHost>
"
    fi
    if [ -z "$https" ]; then
        block+="
<VirtualHost *:$PORT_HTTPS>
    ServerAdmin $(server_admin)
    DocumentRoot \"$LINK/xamppfiles/htdocs/$folder\"
    ServerName $domain
    ServerAlias $alias

    SSLEngine on
    SSLCertificateFile $crt
    SSLCertificateKeyFile $key
</VirtualHost>
"
    fi
    [ -z "$block" ] && return 0

    block="

######################### URL $(tr 'a-z' 'A-Z' <<< "$domain") (lvm-instalador) #########################
$block"
    echo "Añadiendo el vhost de $domain ($([ -z "$http" ] && echo -n "http ")$([ -z "$https" ] && echo -n "https")) a $VHOSTS_FILE..."
    s=""
    [ -w "$VHOSTS_FILE" ] || s=$SUDO
    if [ -f "$VHOSTS_FILE" ]; then
        run mkdir -p -m 700 "$HOME/lvm-copias"
        run cp "$VHOSTS_FILE" "$HOME/lvm-copias/httpd-vhosts.conf-$(date +%Y%m%d-%H%M%S)" || return 1
    fi
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] añadir a $VHOSTS_FILE:$block"
    else
        # (como root, solo en el fichero de XAMPP-compartido y sin enlaces: ver vhosts_path_ok)
        if [ -n "$s" ] && ! vhosts_path_ok; then
            echo "No se añade el vhost: $VHOSTS_FILE tiene que ser un fichero normal de $COMMON (sin enlaces)."
            return 1
        fi
        printf '%s' "$block" | $s tee -a "$VHOSTS_FILE" > /dev/null || return 1
    fi
    PS_RELOAD=1
}

# Falsea dominios en /etc/hosts (en el Mac, con una linea 127.0.0.1 y otra ::1: si solo hubiera la
# de IPv4, macOS podria buscar la direccion IPv6 del dominio en internet y abrir la web real). Modo carga: falsea los indicados (puede no haber ninguno) y deja de
# falsear el resto de dominios de los vhosts. Modo si/no: solo falsea o deja de falsear uno.
# Solo toca lineas 127.0.0.1/::1 cuyos nombres sean todos dominios de vhosts de proyectos (nunca
# localhost, web.local ni el nombre del equipo): las comenta o les quita el # (y añade la linea
# si no existia). Se escribe con edit_hosts --aplicar (copia del anterior en ~/lvm-copias).
function hosts_fake() {
    local mode=$1 copy rc
    shift
    copy=$(mktemp "${TMPDIR:-/tmp}/lvm-hosts.XXXXXX") || return 1
    LVM_INFO=$(vhosts_info) LVM_LOCAL_OFF="$(cat "$LOCAL_OFF_FILE" 2> /dev/null) $LOCAL_OFF_DRY" \
        python3 -I - "$HOSTS_FILE" "$copy" "$mode" "$PROJECT_VHOST $(project_link)" "$@" <<'EOF'
import os, re, sys
src, dst, mode, links = sys.argv[1:5]
wanted = [d.lower() for d in sys.argv[5:]]
skip = {"localhost"}
for l in links.lower().split():
    skip |= {l, "www." + l}
managed = set()
for row in os.environ.get("LVM_INFO", "").splitlines():
    f = row.split("|")
    if len(f) >= 4:
        managed |= {n.lower() for n in [f[2]] + f[3].split() if n}
managed -= skip
# Los .local no existen fuera: se quedan siempre en hosts (al cargar otro proyecto no se comentan) y
# se añaden si les falta la linea. Sin ella, el equipo los pregunta a la red (mDNS) y cualquiera de
# la misma wifi podria contestar con su IP y servir su web con ese nombre. Salvo los que se han
# apagado a mano en la pestaña Hosts (LOCAL_OFF_FILE): esos se tratan como un dominio mas
off = {n.lower() for n in os.environ.get("LVM_LOCAL_OFF", "").split()}
always = {n.lower() for n in managed if n.lower().endswith(".local")} - off
managed -= always
target = set()
for d in wanted:
    target |= {d, d[4:] if d.startswith("www.") else "www." + d}
# localhost y el vhost de los proyectos (web.local) no se tocan nunca
wanted = [d for d in wanted if d not in skip]
target -= skip
# (un .local no se apaga: no hay ninguna web «real» a la que devolverlo, y sin su linea se
# preguntaria a la red)
if mode == "no":
    managed |= target - always
lines = open(src).read().splitlines()
rx = re.compile(r"^(\s*)(#+\s*)?(127\.0\.0\.1|::1)(\s+)(.*?)\s*$")
IPS = ["127.0.0.1", "::1"]
dones, changes, out = {ip: set() for ip in IPS}, [], []
for line in lines:
    m = rx.match(line)
    names = m.group(5).split("#")[0].split() if m else []
    lnames = {n.lower() for n in names}
    # (una linea con un .local y un dominio de verdad, de un vhost con los dos, tambien es nuestra)
    ours = bool(names) and lnames <= (managed | always | target) and bool(lnames - always)
    if not ours:
        out.append(line)
        continue
    active = not m.group(2)
    done = dones[m.group(3)]
    if lnames & target:
        # Se falsea (sin quitar el # a una segunda linea repetida) o se deja de falsear
        on = mode != "no" and (active or not lnames <= done)
    else:
        # Al cargar un proyecto, el resto de dominios vuelve a la web real
        on = active and mode != "cargar"
    if on and not active:
        line = m.group(1) + m.group(3) + m.group(4) + m.group(5)
        changes.append("Falseado en %s (%s): %s" % (src, m.group(3), " ".join(names)))
    elif not on and active:
        line = m.group(1) + "#" + m.group(3) + m.group(4) + m.group(5)
        # Los .local de esa linea no se comentan: se quedan activos en otra
        keep = [n for n in names if n.lower() in always]
        if keep:
            line = m.group(1) + "#" + m.group(3) + m.group(4) + " ".join(n for n in names if n.lower() not in always)
            out.append(m.group(1) + m.group(3) + m.group(4) + " ".join(keep))
        if all(n.lower().endswith(".local") for n in names):
            changes.append("Apagado en %s (%s): %s" % (src, m.group(3), " ".join(names)))
        else:
            changes.append("Ya no esta falseado (%s, lleva a la web real): %s" % (m.group(3), " ".join(names)))
    if on:
        done |= lnames
    out.append(line)
active_names = {ip: set() for ip in IPS}
off_names = set()
for l in out:
    mm = rx.match(l)
    if mm and not mm.group(2):
        active_names[mm.group(3)] |= {n.lower() for n in mm.group(5).split("#")[0].split()}
    elif mm:
        off_names |= {n.lower() for n in mm.group(5).split("#")[0].split()}
# (tambien los que esten comentados: se vuelven a añadir)
for ip in IPS:
    for d in sorted(always - active_names[ip]):
        last = max([i for i, l in enumerate(out) if rx.match(l)] or [len(out) - 1])
        out.insert(last + 1, "%s %s" % (ip, d))
        changes.append("En %s (%s), para que no se pregunte a la red: %s" % (src, ip, d))
if mode in ("cargar", "si"):
    for d in wanted:
        for ip in IPS:
            if d in dones[ip]:
                continue
            alias = d[4:] if d.startswith("www.") else "www." + d
            new = "%s %s %s" % (ip, d, alias)
            last = max([i for i, l in enumerate(out) if rx.match(l)] or [len(out) - 1])
            out.insert(last + 1, new)
            dones[ip] |= {d, alias}
            changes.append("Falseado en %s (%s): %s %s" % (src, ip, d, alias))
open(dst, "w").write("\n".join(out) + "\n")
for c in changes:
    print(c)
EOF
    rc=$?
    if [ $rc -ne 0 ]; then
        rm -f "$copy"
        echo "No se ha podido preparar el nuevo $HOSTS_FILE"
        return 1
    fi
    if ! cmp -s "$copy" "$HOSTS_FILE"; then
        edit_hosts --aplicar "$copy" || { rm -f "$copy"; return 1; }
    fi
    rm -f "$copy"
}

# hosts-enlace: el vhost de los proyectos (web.local) pasa a 127.0.0.1 en hosts, que es donde escucha
# Apache. Se quita de las lineas que lo llevaban a otra direccion (la del nombre del equipo se queda
# con sus otros nombres) y se añade su linea. Con copia del anterior en ~/lvm-copias (edit_hosts)
function hosts_fix_link() {
    local link copy
    link=$(project_link)
    link=${link:-$PROJECT_VHOST}
    valid_domain "$link" || { echo "No hay vhost de los proyectos"; return 1; }
    copy=$(mktemp "${TMPDIR:-/tmp}/lvm-hosts.XXXXXX") || return 1
    if ! python3 -I - "$HOSTS_FILE" "$copy" "$link" <<'EOF'
import re, sys
src, dst, name = sys.argv[1], sys.argv[2], sys.argv[3].lower()
out, changes, ok, ok6 = [], [], False, False
for line in open(src, errors="surrogateescape").read().splitlines():
    body, sep, comment = line.partition("#")
    w = body.split()
    if len(w) >= 2 and name in [x.lower() for x in w[1:]]:
        if w[0] == "127.0.0.1":
            ok = True
        elif w[0] == "::1":
            ok6 = True
        else:
            rest = [x for x in w[1:] if x.lower() != name]
            changes.append("%s ya no lleva a %s" % (name, w[0]))
            if rest:
                line = " ".join([w[0]] + rest) + ((" " + sep + comment) if sep else "")
            else:
                line = "# (lvm-instalador: %s pasa a 127.0.0.1) %s" % (name, line)
    out.append(line)
if not ok:
    last = max([i for i, l in enumerate(out) if re.match(r"\s*127\.0\.0\.1\s", l)] or [len(out) - 1])
    out.insert(last + 1, "127.0.0.1 %s" % name)
    changes.append("%s lleva a este Mac (127.0.0.1)" % name)
if not ok6:
    out.append("::1 %s" % name)
    changes.append("%s lleva a este Mac (::1)" % name)
open(dst, "w", errors="surrogateescape").write("\n".join(out) + "\n")
for c in changes:
    print(c)
EOF
    then
        rm -f "$copy"
        return 1
    fi
    if cmp -s "$copy" "$HOSTS_FILE"; then
        echo "$link ya lleva a este Mac (127.0.0.1)"
    else
        edit_hosts --aplicar "$copy" || { rm -f "$copy"; return 1; }
    fi
    rm -f "$copy"
}

# hosts-falsear <dominio> si|no: el interruptor de la pestaña Hosts
function hosts_fake_one() {
    local domain=$(tr 'A-Z' 'a-z' <<< "$1") state=$2
    if ! valid_domain "$domain" || [[ "$state" != si && "$state" != no ]]; then
        echo "Uso: lvm-instalador hosts-falsear <dominio> si|no"

        return 1
    fi
    local link
    for link in localhost "$PROJECT_VHOST" $(project_link); do
        if [ "$domain" == "$link" ] || [ "$domain" == "www.$link" ]; then
            echo "$domain no se falsea ni se deja de falsear desde aqui: es el de los proyectos o el del equipo"

            return 1
        fi
    done
    if ! vhosts_info | awk -F'|' -v d="$domain" '$3 == d || index(" " $4 " ", " " d " ") { f = 1 } END { exit !f }'; then
        echo "$domain no es el dominio de ningun vhost de $VHOSTS_FILE"

        return 1
    fi
    # La contraseña antes de cambiar nada: cancelarla deja el dominio como estaba
    sudo_first || return 1
    # Un .local se queda siempre en hosts (sin su linea, el equipo lo preguntaria a la red y
    # cualquiera de la misma wifi podria contestar), salvo que se apague aqui: se recuerda en
    # LOCAL_OFF_FILE, con su www., y al encenderlo se olvida
    if [[ "$domain" == *.local ]]; then
        local base=${domain#www.}
        local_off "$state" "$base" "www.$base" || return 1
        if ! hosts_fake "$state" "$domain"; then
            local_off "$([ "$state" == no ] && echo si || echo no)" "$base" "www.$base"

            return 1
        fi
        if [ "$state" == si ]; then
            echo "$domain encendido: lleva a este Mac (127.0.0.1 y ::1) y se vuelve a mantener en $HOSTS_FILE"
        else
            echo "$domain apagado: sus lineas de $HOSTS_FILE quedan comentadas y no se vuelven a añadir."
            echo "Mientras este apagado, el Mac lo pregunta a la red (cualquiera de la misma wifi podria contestar)."
        fi

        return 0
    fi
    hosts_fake "$state" "$domain" || return 1
    if [ "$state" == si ]; then
        echo "$domain falseado: lleva a este equipo (127.0.0.1 y ::1)"
    else
        echo "$domain ya no esta falseado: lleva a la web real"
    fi
}

# media-produccion <dominio .local> <dominio de produccion>|quitar: lo que falte en local de
# wp-content/uploads o img (imagenes, videos y pdf; uploads e img no van en git) se pide a la web
# de produccion con una redireccion 302, en los vhosts de ese dominio (http y https). Solo en los
# .local: con el dominio real falseado, la redireccion volveria a este equipo. Y el de produccion no
# puede ser un .local: si se falsea, la peticion cae en su propio vhost, sin la regla (404, sin bucle)
# Solo GET y HEAD, y solo esas extensiones: un .php de uploads no se manda a ningun sitio
MEDIA_EXT="jpe?g|png|gif|webp|avif|svg|ico|bmp|mp4|webm|pdf"
function media_proxy() {
    local domain=$(tr 'A-Z' 'a-z' <<< "$1") prod=$(tr 'A-Z' 'a-z' <<< "$2") copy rc
    if [ -z "$domain" ] || [ -z "$prod" ]; then
        echo "Uso: lvm-instalador media-produccion <dominio .local> <dominio de produccion>|quitar"

        return 1
    fi
    domain=${domain#www.}
    if ! valid_domain "$domain" || [[ "$domain" != *.local ]]; then
        echo "$domain no es un dominio .local: el proxy de imagenes solo va en los vhosts .local"
        echo "(con el dominio real falseado, la redireccion volveria a este equipo)"

        return 1
    fi
    if [ "$prod" != quitar ]; then
        prod=${prod#https://}; prod=${prod#http://}; prod=${prod%/}
        if ! valid_domain "$prod" || [[ "$prod" == *.local || "$prod" == localhost || "$prod" == *.localhost ]]; then
            echo "El dominio de produccion no es valido: $prod (solo el dominio, como ejemplo.com)"

            return 1
        fi
    fi
    if ! vhosts_info | awk -F'|' -v d="$domain" '$3 == d || index(" " $4 " ", " " d " ") { f = 1 } END { exit !f }'; then
        echo "$domain no es el dominio de ningun vhost de $VHOSTS_FILE"

        return 1
    fi
    mkdir -p -m 700 "$LOG_DIR" || return 1
    copy=$(mktemp "$LOG_DIR/vhosts-media-XXXXXX") || return 1
    python3 -I - "$(realpath_f "$ACTIVE_VHOSTS")" "$copy" "$domain" "$prod" "$MEDIA_EXT" << 'EOF'
import re, sys
src, dst, domain, prod, ext = sys.argv[1:6]
lines = open(src, encoding="utf-8", errors="surrogateescape", newline="").read().split("\n")
rule = ["    # nexum-media %s: lo que falte aqui de wp-content/uploads o img se pide a produccion (no se edita a mano: lvm-instalador media-produccion)" % prod,
        "    <IfModule rewrite_module>",
        "        RewriteEngine On",
        "        RewriteCond %{REQUEST_METHOD} ^(GET|HEAD)$",
        "        RewriteCond %{DOCUMENT_ROOT}%{REQUEST_URI} !-f",
        "        RewriteRule ^/((wp-content/uploads|img)/.+\\.(%s))$ https://%s/$1 [NC,R=302,L]" % (ext, prod),
        "    </IfModule>",
        "    # /nexum-media"]
found = 0
def fix(block):
    global found
    names = set()
    for l in block:
        w = l.split("#", 1)[0].split()
        if len(w) >= 2 and w[0].lower() in ("servername", "serveralias"):
            names |= {n.lower().split(":")[0] for n in w[1:]}
    if domain not in names and "www." + domain not in names:
        return block
    found += 1
    # (la regla anterior, si la habia, se quita: se pone la nueva o ninguna)
    out, skip = [], False
    for l in block:
        s = l.strip()
        if s.startswith("# nexum-media "):
            skip = True
        elif skip and s == "# /nexum-media":
            skip = False
        elif not skip:
            out.append(l)
    if prod != "quitar":
        out[-1:-1] = rule
    return out
out, block = [], None
for line in lines:
    if block is None:
        if re.match(r"^\s*<VirtualHost\b", line, re.I):
            block = [line]
        else:
            out.append(line)
        continue
    block.append(line)
    if re.match(r"^\s*</VirtualHost>", line, re.I):
        out += fix(block)
        block = None
if block:
    out += block
if not found:
    sys.exit(2)
with open(dst, "w", encoding="utf-8", errors="surrogateescape", newline="") as f:
    f.write("\n".join(out))
sys.exit(0 if out != lines else 3)
EOF
    rc=$?
    if [ $rc -eq 3 ]; then
        rm -f "$copy"
        [ "$prod" == quitar ] && echo "$domain no pedia nada a produccion" || echo "$domain ya pide a $prod lo que falte"

        return 0
    fi
    if [ $rc -ne 0 ]; then
        rm -f "$copy"
        echo "No se encuentra el vhost de $domain en $(realpath_f "$ACTIVE_VHOSTS")"

        return 1
    fi
    if [ "$prod" == quitar ]; then
        echo "$domain: lo que falte de uploads e img ya no se pide a produccion"
    else
        echo "$domain: lo que falte de wp-content/uploads o img se pide a https://$prod"
    fi
    edit_vhosts --aplicar "$copy" || { rm -f "$copy"; return 1; }
    rm -f "$copy"
}

# Dominio de produccion de cada WordPress para sus imagenes (media-proyecto): carpeta|dominio. Se
# aplica al vhost de los proyectos (web.local) mientras ese proyecto este cargado (media_sync)
MEDIA_PROJECTS_FILE="$HOME/.lvm-instalador/media-produccion"
function media_saved() {
    awk -F'|' -v f="$1" '$1 == f { d = $2 } END { if (d != "") print d }' "$MEDIA_PROJECTS_FILE" 2> /dev/null
}

# media-proyecto <carpeta> <dominio de produccion>|quitar: lo que le falte a un WordPress de
# wp-content/uploads se pide a su web real mientras este cargado (por web.local, que es un .local:
# sin bucles). Las tiendas PrestaShop se ven con su dominio real falseado: para ellas, ps-imagenes
function media_project() {
    local folder=${1%/} prod=$(tr 'A-Z' 'a-z' <<< "$2") rest
    if [ -z "$folder" ] || [ -z "$prod" ]; then
        echo "Uso: lvm-instalador media-proyecto <carpeta> <dominio de produccion>|quitar"

        return 1
    fi
    valid_project "$folder" || return 1
    if is_prestashop "$folder"; then
        echo "$folder es una tienda PrestaShop: se ve con su dominio real falseado y una redireccion volveria"
        echo "a este equipo. Descarga las imagenes que faltan: lvm-instalador ps-imagenes $folder"

        return 1
    fi
    if [ "$prod" != quitar ]; then
        prod=${prod#https://}; prod=${prod#http://}; prod=${prod%/}
        if ! valid_domain "$prod" || [[ "$prod" == *.local || "$prod" == localhost || "$prod" == *.localhost ]]; then
            echo "El dominio de produccion no es valido: $prod (solo el dominio, como ejemplo.com)"

            return 1
        fi
    fi
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] $folder: $([ "$prod" == quitar ] && echo "se olvida su dominio de produccion" || echo "imagenes de $prod") en $MEDIA_PROJECTS_FILE"
    else
        mkdir -p -m 700 "$(dirname "$MEDIA_PROJECTS_FILE")" || return 1
        rest=$(awk -F'|' -v f="$folder" '$1 != f' "$MEDIA_PROJECTS_FILE" 2> /dev/null)
        [ "$prod" != quitar ] && rest+=$'\n'"$folder|$prod"
        ( umask 077; sed '/^$/d' <<< "$rest" > "$MEDIA_PROJECTS_FILE" ) || return 1
    fi
    if [ "$prod" == quitar ]; then
        echo "$folder ya no pide a produccion las imagenes que le faltan"
    else
        echo "$folder pide a https://$prod las imagenes que le falten en wp-content/uploads (mientras este cargado)"
    fi
    media_sync
}

# Regla de imagenes del vhost de los proyectos (web.local) segun el proyecto cargado: la de su
# dominio de produccion (media-proyecto) si es un WordPress que lo tiene, si no ninguna. Solo cambia
# los vhosts si hace falta
function media_sync() {
    local link folder name want="" now
    link=$(project_link) || return 0
    folder=$(readlink "$HTDOCS_DIR/$link" 2> /dev/null | sed 's:/*$::')
    name=$(vhosts_info | awk -F'|' -v l="$link" '$2 == l { print $3; exit }')
    [[ "$name" == *.local ]] || return 0
    if [ -n "$folder" ] && [ "$folder" != "$EMPTY_PROJECT" ] && [ -d "$HTDOCS_DIR/$folder" ] && ! is_prestashop "$folder"; then
        want=$(media_saved "$folder")
    fi
    now=$(awk -v n="$name" '
        /^[ \t]*<VirtualHost/ { hit = 0 }
        tolower($1) == "servername" || tolower($1) == "serveralias" { for (i = 2; i <= NF; i++) if (tolower($i) == n) hit = 1 }
        hit && $1 == "#" && $2 == "nexum-media" { sub(/:$/, "", $3); print $3; exit }' "$(realpath_f "$ACTIVE_VHOSTS")" 2> /dev/null)
    [ "$want" == "$now" ] && return 0
    media_proxy "$name" "${want:-quitar}"
}

# Para la ventana: G|dominio guardado de un WordPress (media-proyecto) y D|el de su base (home o
# siteurl de la tabla options, que el gestor no cambia: el local va en WP_HOME de wp-config.php)
function gui_wp_prod() {
    local folder=$1 cfg db prefix url
    valid_project "$folder" > /dev/null || return 1
    echo "G|$(media_saved "$folder")"
    cfg=$(wp_config_read "$HTDOCS_DIR/$folder/wp-config.php") || return 0
    db=$(sed -n 1p <<< "$cfg") prefix=$(sed -n 4p <<< "$cfg")
    [[ "$db" =~ ^[A-Za-z0-9_-]+$ ]] && [[ "$prefix" =~ ^[A-Za-z0-9_]*$ ]] && [ -x "$DB_CLIENT" ] || return 0
    db_base_table root "${MYSQL_PWD:-}" "$db" "${prefix}options" || return 0
    url=$("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N -e "SELECT option_value FROM \`$db\`.\`${prefix}options\`
        WHERE option_name IN ('home', 'siteurl') ORDER BY option_name = 'home' DESC LIMIT 1" < /dev/null 2> /dev/null)
    url=$(tr 'A-Z' 'a-z' <<< "$url" | sed -E 's|^https?://||; s|[/:?#].*$||')
    valid_domain "$url" && [[ "$url" != *.local && "$url" != localhost && "$url" != *.localhost ]] && echo "D|$url"
    return 0
}

# ps-imagenes <carpeta>: descarga de la web real las imagenes de una tienda PrestaShop que faltan en
# img (productos, categorias y marcas, con sus miniaturas; la lista sale de su base). La tienda se ve
# con su dominio real falseado, asi que una redireccion no sirve: se descargan por https resolviendo
# el dominio con DNS cifrado (PS_IMAGES_DOH, sin /etc/hosts) y comprobando su certificado de
# verdad. Cada fichero va a una carpeta temporal y solo pasa a img si ha llegado entero (200); sin
# seguir redirecciones y como mucho 30 MB por fichero. Lo que ya esta en local no se toca
PS_IMAGES_DOH="https://cloudflare-dns.com/dns-query"
function ps_images() {
    local folder=${1%/} config db prefix domain t list total
    if [ -z "$folder" ]; then
        echo "Uso: lvm-instalador ps-imagenes <carpeta>"

        return 1
    fi
    valid_project "$folder" || return 1
    is_prestashop "$folder" || { echo "$folder no es una tienda PrestaShop"; return 1; }
    command -v curl > /dev/null || { echo "Hace falta curl: sudo apt install curl"; return 1; }
    config=$(ps_config "$folder")
    db=${config%%|*} prefix=${config#*|}
    [ -n "$db" ] && [[ "$db$prefix" =~ ^[A-Za-z0-9_-]+$ ]] || { echo "No se puede leer la BBDD de $folder (su parameters.php o settings.inc.php)"; return 1; }
    db_connect || return $?
    if ! db_exists "$db"; then
        echo "La BBDD de $folder ($db) no esta en lampp-$DB_FOLDER, la version activa: carga el proyecto"
        echo "en su version (o importa su BBDD en esta) y vuelve a intentarlo"

        return 1
    fi
    domain=$(ps_domain "$folder")
    if ! valid_domain "$domain" || [[ "$domain" == *.local || "$domain" == localhost || "$domain" == *.localhost ]]; then
        echo "No se sabe el dominio de produccion de $folder (el de su tabla ${prefix}shop_url): ${domain:-ninguno}"

        return 1
    fi
    # (solo tablas de verdad: una vista del volcado ejecutaria sus funciones como root)
    for t in image image_type; do
        db_base_table root "${MYSQL_PWD:-}" "$db" "$prefix$t" || { echo "La BBDD $db no tiene la tabla $prefix$t"; return 1; }
    done
    local sql=(db_root_sql -N -B)
    list=$( {
        "${sql[@]}" -e "SELECT 'I', id_image FROM \`$db\`.\`${prefix}image\`" < /dev/null
        "${sql[@]}" -e "SELECT 'T', name, products, categories, manufacturers FROM \`$db\`.\`${prefix}image_type\`" < /dev/null
        db_base_table root "${MYSQL_PWD:-}" "$db" "${prefix}category" \
            && "${sql[@]}" -e "SELECT 'C', id_category FROM \`$db\`.\`${prefix}category\` WHERE id_category > 2" < /dev/null
        db_base_table root "${MYSQL_PWD:-}" "$db" "${prefix}manufacturer" \
            && "${sql[@]}" -e "SELECT 'M', id_manufacturer FROM \`$db\`.\`${prefix}manufacturer\`" < /dev/null
    } 2> /dev/null | python3 -I -c '
import os, re, sys
root = sys.argv[1]
ids, types = {"I": [], "C": [], "M": []}, {"I": [], "C": [], "M": []}
for line in sys.stdin:
    f = line.rstrip("\n").split("\t")
    if f[0] in ids and len(f) == 2 and f[1].isdigit():
        ids[f[0]].append(int(f[1]))
    elif f[0] == "T" and len(f) == 5 and re.match(r"^[A-Za-z0-9_-]{1,64}$", f[1]):
        for k, col in (("I", 2), ("C", 3), ("M", 4)):
            if f[col] == "1":
                types[k].append(f[1])
for k, base in (("I", "img/p"), ("C", "img/c"), ("M", "img/m")):
    for i in sorted(set(ids[k])):
        d = base + "/" + "/".join(str(i)) if k == "I" else base
        for t in [""] + types[k]:
            rel = "%s/%d%s.jpg" % (d, i, "-" + t if t else "")
            if not os.path.isfile(os.path.join(root, rel)):
                print(rel)
' "$HTDOCS_DIR/$folder")
    total=$(grep -c . <<< "$list")
    if [ "$total" -eq 0 ]; then
        echo "A $folder no le falta ninguna imagen de productos, categorias ni marcas"

        return 0
    fi
    echo "A $folder le faltan $total imagenes: se descargan de https://$domain"
    echo "($domain se resuelve con DNS cifrado, sin /etc/hosts, y se comprueba su certificado)"
    if [ "$DRY" -eq 1 ]; then
        head -3 <<< "$list" | sed 's/^/  [simulacion] /'

        return 0
    fi
    mkdir -p -m 700 "$LOG_DIR" || return 1
    local file rc
    file=$(mktemp "$LOG_DIR/ps-imagenes-lista-XXXXXX") || return 1
    printf '%s\n' "$list" > "$file"
    python3 -I - "$HTDOCS_DIR/$folder" "$domain" "$PS_IMAGES_DOH" "$LOG_DIR" "$file" "$APP_NAME/$APP_VERSION" << 'EOF'
import os, shutil, signal, subprocess, sys, tempfile
root, domain, doh, logdir, listfile, agent = sys.argv[1:7]
rels = [l for l in open(listfile).read().split("\n") if l]
# (al cancelar la tarea se borra la carpeta temporal)
signal.signal(signal.SIGTERM, lambda *_: sys.exit(130))
img = os.path.realpath(os.path.join(root, "img"))
got = gone = moved = blocked = 0
# El programa dice quien es (sin hacerse pasar por un navegador): si la web lo bloquea, se le da
# permiso en su servidor
agent = "%s (imagenes que faltan en una copia local)" % agent.replace(" ", "-")
with tempfile.TemporaryDirectory(dir=logdir, prefix="ps-imagenes-") as tmp:
    for start in range(0, len(rels), 300):
        batch = rels[start:start + 300]
        cfg = os.path.join(tmp, "curl.conf")
        with open(cfg, "w") as f:
            for n, rel in enumerate(batch):
                f.write('url = "https://%s/%s"\noutput = "%s/%d"\n' % (domain, rel, tmp, n))
        cmd = ["curl", "-s", "--parallel", "--parallel-max", "8", "-A", agent,
               "--proto", "=https", "--fail", "--max-redirs", "0", "--max-filesize", "30000000",
               "--connect-timeout", "15", "--max-time", "120", "-K", cfg,
               "-w", "%{exitcode} %{http_code} %{filename_effective}\n"]
        if doh:
            cmd[2:2] = ["--doh-url", doh]
        out = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True).stdout
        for line in out.splitlines():
            code, http, name = (line.split(" ", 2) + ["", ""])[:3]
            n = os.path.basename(name)
            if not n.isdigit() or int(n) >= len(batch):
                continue
            src = os.path.join(tmp, n)
            dest = os.path.join(root, batch[int(n)])
            # (sin salir de img: una carpeta de la ruta podria ser un enlace a otro sitio. Se mira
            # antes de crear nada)
            real = os.path.realpath(os.path.dirname(dest))
            if code == "0" and http == "200" and os.path.isfile(src) and os.path.getsize(src) > 0 \
                    and real.startswith(img + os.sep) and not os.path.lexists(dest):
                os.makedirs(os.path.dirname(dest), mode=0o755, exist_ok=True)
                shutil.move(src, dest)
                got += 1
            elif http in ("301", "302", "307", "308"):
                moved += 1
            elif http in ("000", "401", "403", "429", "503"):
                blocked += 1
            else:
                gone += 1
            if os.path.lexists(src):
                os.remove(src)
        notes = [t % c for t, c in (("%d no estan en produccion", gone), ("%d bloqueadas por la web", blocked),
                                     ("%d con redireccion", moved)) if c]
        print("Descargadas %d de %d%s" % (got, len(rels), " (" + ", ".join(notes) + ")" if notes else ""), flush=True)
        # Lo primero, todo bloqueado: no se sigue llamando a la web
        if not got and blocked == len(batch):
            break
if blocked:
    print("La web de %s no deja descargar (cortafuegos o proteccion contra robots del servidor). Este" % domain)
    print("programa se presenta como «%s»: dale permiso en el servidor (Plesk: ModSecurity" % agent)
    print("o Imunify) o copia la carpeta img de produccion a mano")
if moved:
    print("Aviso: %d piden una redireccion (a www o a otro dominio): mira el dominio de la tienda" % moved)
print("Listo: %d imagenes nuevas en %s/img" % (got, root))
sys.exit(0 if got or not rels else 1)
EOF
    rc=$?
    rm -f "$file"
    return $rc
}

# Dominios .local apagados a mano en la pestaña Hosts: ya no se mantienen en /etc/hosts.
# local_off si|no <dominio...>: no = apagado (se recuerda), si = encendido (se olvida)
LOCAL_OFF_FILE="$HOME/.lvm-instalador/locales-apagados"
# (en simulacion no se guarda: los apagados van aqui, para que hosts_fake enseñe lo que haria)
LOCAL_OFF_DRY=""
function local_off() {
    local state=$1 d rest
    shift
    if [ "$DRY" -eq 1 ]; then
        [ "$state" == no ] && LOCAL_OFF_DRY+=" $*"
        echo "  [simulacion] $* $([ "$state" == no ] && echo "se recuerda apagado" || echo "se olvida como apagado") en $LOCAL_OFF_FILE"

        return 0
    fi
    mkdir -p -m 700 "$(dirname "$LOCAL_OFF_FILE")" || return 1
    rest=$(cat "$LOCAL_OFF_FILE" 2> /dev/null)
    for d in "$@"; do
        rest=$(grep -vxF -- "$d" <<< "$rest")
        [ "$state" == no ] && rest+=$'\n'"$d"
    done
    ( umask 077; sed '/^$/d' <<< "$rest" > "$LOCAL_OFF_FILE" )
}

# Para la pestaña Hosts: F|dominio|alias|carpeta|falseado (1/0)|https (1/0)|certificado (1/0)|PrestaShop (1/0)|personalizado (1/0)
function gui_hosts() {
    local info=$(vhosts_info) link=$(project_link)
    LVM_INFO=$info python3 -I - "$HOSTS_FILE" "$HTDOCS_DIR" "$PROJECT_VHOST $link" "$PORT_HTTPS" "$CUSTOM_DOMAINS_FILE" "$VHOSTS_FILE" <<'EOF'
import os, re, sys
hosts, htdocs, links, https_port, custom_file, vhosts = sys.argv[1:7]
# Dominio de produccion al que se piden las imagenes que faltan (media-produccion), por dominio
media, names = {}, []
try:
    for line in open(vhosts, errors="replace"):
        s = line.strip()
        if re.match(r"(?i)<VirtualHost\b", s):
            names = []
        w = s.split()
        if len(w) >= 2 and w[0].lower() in ("servername", "serveralias"):
            names += [n.lower().split(":")[0] for n in w[1:]]
        m = re.match(r"# nexum-media (\S+):", s)
        if m:
            for n in names:
                media[n] = m.group(1)
except OSError:
    pass
custom = set()
try:
    custom = {l.split("=", 1)[0] for l in open(custom_file) if "=" in l}
except OSError:
    pass
skip = set()
for l in links.split():
    skip |= {l, "www." + l}
active = set()
try:
    for line in open(hosts, errors="replace"):
        m = re.match(r"^\s*127\.0\.0\.1\s+(.*)", line)
        if m:
            active |= set(m.group(1).split("#")[0].lower().split())
except OSError:
    pass
rows = {}
for row in os.environ.get("LVM_INFO", "").splitlines():
    f = row.split("|")
    if len(f) < 6 or f[2] in skip:
        continue
    r = rows.setdefault(f[2], {"alias": "", "folder": "", "https": 0, "crt": 0})
    aliases = f[3].split()
    # El alias www.<dominio> si lo hay (algun vhost http tiene un alias copiado de otro)
    r["alias"] = ("www." + f[2]) if "www." + f[2] in aliases else (r["alias"] or (aliases or [""])[0])
    r["folder"] = r["folder"] or f[1]
    if f[0] == https_port:
        r["https"] = 1
        r["crt"] = int(bool(f[4]) and os.path.isfile(f[4]))
for name in sorted(rows):
    r = rows[name]
    ps = any(os.path.isfile(os.path.join(htdocs, r["folder"], p))
             for p in ("app/config/parameters.php", "config/settings.inc.php")) if r["folder"] else False
    print("F|%s|%s|%s|%d|%d|%d|%d|%d|%s" % (name, r["alias"], r["folder"], name in active,
                                            r["https"], r["crt"], ps, name in custom, media.get(name, "")))
# El vhost de los proyectos (web.local) tiene que llevar a 127.0.0.1, donde escucha Apache: si en
# hosts apunta a otra direccion (otra direccion de 127.x o de la red) o no esta, el
# navegador da ERR_CONNECTION_REFUSED. L|nombre|direccion a la que apunta ahora (vacio si no esta)
vhost_names = {row.split("|")[2].lower() for row in os.environ.get("LVM_INFO", "").splitlines()
               if len(row.split("|")) >= 3}
for name in dict.fromkeys(links.lower().split()):
    if not name or name not in vhost_names or name in active:
        continue
    now = ""
    try:
        for line in open(hosts, errors="replace"):
            w = line.split("#")[0].split()
            if len(w) >= 2 and name in [x.lower() for x in w[1:]]:
                now = w[0]
                break
    except OSError:
        pass
    print("L|%s|%s" % (name, re.sub(r"[^0-9A-Fa-f.:]", "", now)))
EOF
}

# Ficheros y carpetas de htdocs que puede cambiar cualquier usuario del Mac (plugins y caches que
# los dejan en 777 o 666): otro usuario podria dejar un PHP y ejecutarlo con el tuyo pidiendolo a
# localhost. Se les quita la escritura para los demas (Apache, que corre con tu usuario, sigue
# pudiendo escribir). Solo lo tuyo y con tu usuario (sin sudo: root no cambia permisos dentro de
# htdocs, que es tuyo); de lo de otros solo se avisa. htdocs_close_world <carpeta>
function htdocs_close_world() {
    local dir=$1 me n others
    [ -d "$dir" ] && [ ! -L "$dir" ] || return 0
    me=$(id -un)
    # Una sola pasada (al cargar un proyecto con vendor o node_modules, cuenta): lo tuyo se cambia
    # y se cuenta a la vez. Lo de otros usuarios solo se mira con --otros (Protegerlas)
    if [ "$DRY" -eq 1 ]; then
        n=$(find "$dir" -xdev \( -type f -o -type d \) -perm -0002 -user "$me" -print 2> /dev/null | wc -l | tr -d ' ')
        [ "$n" -gt 0 ] && echo "  [simulacion] $n ficheros y carpetas de $dir dejarian de poder cambiarlos los demas usuarios"
    elif [ "$2" == "--otros" ]; then
        # Una sola pasada tambien aqui: lo tuyo se cambia y se cuenta, y lo de otros solo se cuenta
        local list
        list=$(find "$dir" -xdev \( -type f -o -type d \) -perm -0002 \
            \( -user "$me" -exec chmod o-w {} + -exec echo m \; -o -exec echo o \; \) 2> /dev/null)
        n=$(grep -c '^m$' <<< "$list") others=$(grep -c '^o$' <<< "$list")
        [ "$n" -gt 0 ] && echo "$n ficheros y carpetas de $dir ya no los puede cambiar cualquier usuario"
        [ "$others" -gt 0 ] && echo "Aviso: $others de $dir son de otro usuario y los puede cambiar cualquiera: revisalos (sudo chmod o-w)"
        return 0
    else
        n=$(find "$dir" -xdev \( -type f -o -type d \) -perm -0002 -user "$me" -exec chmod o-w {} + -print 2> /dev/null | wc -l | tr -d ' ')
        [ "$n" -gt 0 ] && echo "$n ficheros y carpetas de $dir ya no los puede cambiar cualquier usuario del Mac"
    fi
    return 0
}

# Tu usuario (el de SUDO_USER si esto corre con sudo), para Apache, PHP-FPM y los permisos: solo un
# nombre valido de un usuario que existe (va a la configuracion que lee root). Si no, el que corre
function web_user_name() {
    local u=${SUDO_USER:-$USER}
    if [[ "$u" =~ ^[A-Za-z0-9_][A-Za-z0-9_.-]{0,31}$ ]] && id "$u" > /dev/null 2>&1; then
        echo "$u"
    else
        id -un
    fi
}

# Proyectos nuevos con dominio falseado (pestaña Hosts): dominio=carpeta, uno por linea
CUSTOM_DOMAINS_FILE="$HOME/.lvm-instalador/dominios"

# Dominio personalizado de una carpeta (vacio si no tiene)
function custom_domain() {
    local d
    [ -f "$CUSTOM_DOMAINS_FILE" ] || return 0
    d=$(awk -F= -v f="$1" '$2 == f { d = $1 } END { if (d != "") print d }' "$CUSTOM_DOMAINS_FILE")
    # El fichero es tuyo: solo un dominio valido (sin /, .., espacios ni saltos de linea)
    [ -n "$d" ] && valid_domain "$d" && echo "$d"
    return 0
}

# nuevo-dominio <dominio> <carpeta> [base]: proyecto nuevo con el dominio de produccion falseado.
# Crea la carpeta en htdocs, su vhost http y https con certificado (lo mismo que una tienda
# PrestaShop), la base vacia con el nombre de produccion en la version activa (si se indica y no
# existe) y falsea el dominio (los demas dejan de estarlo, como al cargar un proyecto). El dominio
# queda asociado a la carpeta: Cargar proyecto lo vuelve a falsear.
function new_custom_domain() {
    local domain=$(tr 'A-Z' 'a-z' <<< "$1") folder=${2%/} db=$3 link owner s=""

    if ! valid_domain "$domain"; then
        echo "Dominio no valido: $1 (por ejemplo: mitienda.com)"

        return 1
    fi
    for link in localhost "$PROJECT_VHOST" $(project_link); do
        if [ "$domain" == "$link" ] || [ "$domain" == "www.$link" ] || [ "$folder" == "$link" ]; then
            echo "$link es el de los proyectos o el del equipo: elige otro dominio y otra carpeta"

            return 1
        fi
    done
    if ! [[ "$folder" =~ ^[A-Za-z0-9_][A-Za-z0-9._-]*$ ]]; then
        echo "Carpeta no valida: $folder (solo letras sin acentos, numeros, punto, _ y -)"

        return 1
    fi
    if [ -L "$HTDOCS_DIR/$folder" ]; then
        echo "$HTDOCS_DIR/$folder es un enlace, no una carpeta de proyecto"

        return 1
    fi
    owner=$(vhosts_info | awk -F'|' -v d="$domain" '$3 == d || index(" " $4 " ", " " d " ") { print $2; exit }')
    if [ -n "$owner" ]; then
        echo "Ya hay un vhost para $domain (carpeta ${owner:-desconocida}). Para falsearlo usa su"
        echo "interruptor en Dominios y hosts (o: lvm-instalador hosts-falsear $domain si)."

        return 1
    fi
    if [ -n "$db" ]; then
        db_valid_name "$db" || return 1
    fi

    if [ -d "$HTDOCS_DIR/$folder" ]; then
        echo "Se usa la carpeta que ya existe: $HTDOCS_DIR/$folder"
    else
        echo "Creando la carpeta $HTDOCS_DIR/$folder..."
        [ -w "$HTDOCS_DIR" ] || s=$SUDO
        run $s mkdir -p "$HTDOCS_DIR/$folder" || return 1
        [ -n "$s" ] && run $SUDO chown "${SUDO_USER:-$USER}:$(id -gn "${SUDO_USER:-$USER}")" "$HTDOCS_DIR/$folder"
    fi

    PS_RELOAD=0
    ps_vhost "$folder" "$domain" || return 1

    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] $domain=$folder en $CUSTOM_DOMAINS_FILE"
    else
        mkdir -p "$(dirname "$CUSTOM_DOMAINS_FILE")"
        { [ -f "$CUSTOM_DOMAINS_FILE" ] && grep -v "^$domain=" "$CUSTOM_DOMAINS_FILE"; echo "$domain=$folder"; } > "$CUSTOM_DOMAINS_FILE.nuevo"
        mv "$CUSTOM_DOMAINS_FILE.nuevo" "$CUSTOM_DOMAINS_FILE"
    fi

    if [ -n "$db" ]; then
        if db_connect > /dev/null 2>&1 && db_exists "$db"; then
            echo "La base de datos $db ya existe en XAMPP-$DB_FOLDER: se deja como esta"
        else
            create_database "$db" || echo "Aviso: no se ha creado la base $db. Creala despues en la pestaña Bases de datos."
        fi
        # Cargar proyecto desde el buscador de bases encuentra la carpeta aunque aun no haya configuracion
        if [ "$DRY" -eq 0 ]; then
            remember_project "$db" "$folder"
        fi
    fi

    hosts_fake cargar "$domain" || return 1
    if [ "$PS_RELOAD" -eq 1 ] && [ -f "$LINK/xamppfiles/logs/httpd.pid" ]; then
        echo "Recargando Apache para aplicar el vhost y el certificado..."
        run xampp_ctl reloadapache > /dev/null || { echo "No se ha podido recargar Apache. Reinicia la version activa."; return 1; }
    fi
    echo "Proyecto nuevo listo: https://$domain -> $HTDOCS_DIR/$folder$([ -n "$db" ] && echo " (base $db)")"
}

# ===========================================================================
# Seguridad: los servicios, solo para este Mac
# ===========================================================================
# Las versiones instaladas antes de la 1.16.0 escuchan en todas las interfaces: cualquier equipo de
# la red (la de la oficina o una wifi publica) veria los proyectos de los clientes, llegaria a
# MariaDB (root sin contraseña) y entraria por FTP en htdocs con la contraseña del Mac, que viaja
# sin cifrar. Se dejan solo para este Mac (127.0.0.1 y ::1), el FTP deja de arrancar con la version
# (se activa en la pestaña Servicios cuando haga falta) y los vhosts vuelven a ser de root. Solo
# se cambia lo que falta; lo anterior queda en ~/lvm-copias.
SECURE_MARK=xamppfiles/etc/lvm-seguridad

# Primer vhost del puerto 80: Apache le pasa las peticiones cuyo dominio no tiene ningun vhost. Una web
# cualquiera puede hacer que su dominio apunte a 127.0.0.1 (DNS rebinding) y entonces su JavaScript
# leeria phpMyAdmin (root sin contraseña) y los proyectos desde el navegador. Solo deja pasar
# localhost, 127.0.0.1 y [::1] (la carpeta htdocs y phpMyAdmin); el resto recibe un 403. Los vhosts
# por nombre (web.local, los dominios falseados) no pasan por aqui. HTTPS no lo necesita: el
# certificado no vale para el dominio de fuera y el navegador corta la conexion.
UNKNOWN_HOST_CONF=etc/extra/lvm-dominio-desconocido.conf
UNKNOWN_HOST_VHOST='# lvm-instalador: dominios que no tienen ningun vhost (va antes de httpd-vhosts.conf)
# Solo deja pasar localhost, 127.0.0.1 y [::1]. Cualquier otro dominio que apunte a este Mac
# (una web que intenta leer phpMyAdmin o los proyectos desde el navegador) recibe un 403.
# Para usar otro dominio, crea su vhost (pestaña Hosts o httpd-vhosts.conf).
<VirtualHost *:80>
    ServerName localhost
    ServerAlias 127.0.0.1 [::1]
    <If "%{HTTP_HOST} !~ /^(localhost|127\.0\.0\.1|\[::1\])(:[0-9]+)?$/">
        Require all denied
        ErrorDocument 403 "Este dominio no tiene vhost en este Mac (lvm-instalador): crea su vhost o entra con localhost."
    </If>
    # En 127.0.0.1 y [::1] solo phpMyAdmin: los proyectos van en localhost
    <If "%{HTTP_HOST} =~ /^(127\.0\.0\.1|\[::1\])(:[0-9]+)?$/ && %{REQUEST_URI} !~ m#^/phpmyadmin(/|$)#">
        Require all denied
        ErrorDocument 403 "En 127.0.0.1 solo esta phpMyAdmin: los proyectos van en http://localhost/ (lvm-instalador)"
    </If>
</VirtualHost>

# phpMyAdmin tiene su propio origen: solo en http://127.0.0.1/phpmyadmin/ (o [::1]), donde no hay
# nada mas. Los proyectos van en localhost/<carpeta>, web.local o sus dominios: un fallo XSS en uno
# de ellos no puede leer phpMyAdmin (es otro origen para el navegador)
<Location "/phpmyadmin">
    # Por localhost (un marcador antiguo, la costumbre de XAMPP), a su portada en 127.0.0.1: siempre
    # la misma direccion, sin lo que llevara detras. Por cualquier otro dominio, un 403 con el aviso
    <If "%{HTTP_HOST} =~ /^localhost(:[0-9]+)?$/i">
        # (el ? del final: Redirect añadiria la consulta de antes)
        Redirect 302 "http://127.0.0.1/phpmyadmin/?"
    </If>
    <ElseIf "%{HTTP_HOST} !~ /^(127\.0\.0\.1|\[::1\])(:[0-9]+)?$/">
        Require all denied
        ErrorDocument 403 "phpMyAdmin esta en http://127.0.0.1/phpmyadmin/ (lvm-instalador)"
    </ElseIf>
    # Lo que manda otra web (un formulario o un fetch a 127.0.0.1): el navegador pone ese dominio y
    # phpMyAdmin, que entra como root sin contraseña, lo ejecutaria aunque la web no pueda leer la
    # respuesta. Desde otra web solo se puede abrir la portada con un enlace; escribiendo la
    # direccion, desde lvm-instalador o dentro de phpMyAdmin, todo funciona igual
    <If "(%{HTTP:Sec-Fetch-Site} =~ /^(cross-site|same-site)$/i && !(%{REQUEST_METHOD} =~ /^(GET|HEAD)$/ && -z %{QUERY_STRING} && %{REQUEST_URI} =~ m#^/phpmyadmin/?(index\.php)?$#)) || (%{REQUEST_METHOD} !~ /^(GET|HEAD)$/ && -n %{HTTP:Origin} && %{HTTP:Origin} != '"'"'http://'"'"' . %{HTTP_HOST} && %{HTTP:Origin} != '"'"'https://'"'"' . %{HTTP_HOST})">
        Require all denied
        ErrorDocument 403 "Otra web ha intentado usar phpMyAdmin: no se ha hecho nada. Abrelo escribiendo http://127.0.0.1/phpmyadmin/ o desde lvm-instalador."
    </If>
</Location>
# Su asistente setup y su configuracion, cerrados (sin distinguir mayusculas: en el Mac el disco
# no las distingue y /phpmyadmin/Setup/ abriria setup/)
<LocationMatch "(?i)^/phpmyadmin/setup(/|$)">
    Require all denied
</LocationMatch>
<Files "config.inc.php">
    Require all denied
</Files>

# Configuracion, repositorios, copias de bases y registros de los proyectos (.env, .git, .sql,
# .dump, .old, copias~, debug.log, error_log, auth.json de composer...): no se sirven. Sin distinguir mayusculas (.ENV o .GIT en el Mac)
# Tampoco los registros (.log), los .yml (docker-compose lleva las claves de la BBDD), las copias
# de wp-config.php ni las copias de seguridad de las webs (Duplicator, UpdraftPlus, All-in-One...),
# ni claves y certificados con su clave (.pem, .key, .p12), .ini, .conf o las exportaciones de clientes
# del modulo de boletin de PrestaShop (customers_export_*.csv) y de WP All Import/Export (su carpeta
# wpallimport, con los .zip y .xml de clientes). Tampoco claves de otros programas (.my.cnf, .netrc,
# .pgpass, credentials*.json, .aws, .docker)
<DirectoryMatch "(?i)/\.(git|svn|hg|vscode|idea|ssh|aws|docker)(/|$)">
    Require all denied
</DirectoryMatch>
<DirectoryMatch "(?i)/wp-content/uploads/(sites/[0-9]+/)?wpall(import|export)(/|$)">
    Require all denied
</DirectoryMatch>
<FilesMatch "(?i)(^\.(env.*|git.*|ht.*|envrc|ds_store|npmrc|my\.cnf|netrc|pgpass|s3cfg|mysql_history|bash_history)$|^(credentials|service-account|gcloud-credentials)[^/]*\.json$|\.(sql|sql\.(gz|zip|bz2|xz)|dump|bak|old|orig|save|swp|log|ya?ml|wpress)$|~$|^(debug\.log|error_log|auth\.json)$|^wp-config(?!(\.php|-sample\.php)$)|^(backup|copia|respaldo|bkp)([-_.][^/]*)?\.(zip|tar|tgz|gz|bz2|xz|7z|rar)$|_archive\.(zip|daf)$|wpvivid[^/]*\.(zip|tar|gz)$|\.(pem|key|p12|pfx|jks|ini|conf|sqlite|sqlite3|db)$|^id_(rsa|dsa|ecdsa|ed25519)(\.pub)?$|^customers_export_[^/]*\.(csv|zip|xml|xlsx?)$)">
    Require all denied
</FilesMatch>

# Una web de fuera no puede leer las respuestas de tus proyectos: WordPress responde a cualquier
# origen en su API (Access-Control-Allow-Origin), y se quita si el origen no es la propia web
<IfModule headers_module>
    <If "-n %{HTTP:Origin} && %{HTTP:Origin} != '"'"'http://'"'"' . %{HTTP_HOST} && %{HTTP:Origin} != '"'"'https://'"'"' . %{HTTP_HOST}">
        Header unset Access-Control-Allow-Origin
        Header always unset Access-Control-Allow-Origin
        Header unset Access-Control-Allow-Credentials
        Header always unset Access-Control-Allow-Credentials
    </If>
</IfModule>
TraceEnable Off
# Peticiones de como mucho 64 MB (PHP2Shell, CVE-2026-109618/109619: cuerpos enormes para PHP).
# Un vhost puede subirlo con su propio LimitRequestBody
LimitRequestBody 67108864
# lvm-barrera-web: lo que manda otra web a cualquier proyecto (se apaga en Configuración o con
# lvm-instalador barrera-web no). Desde otra web solo se puede abrir una pagina (un enlace: GET o
# HEAD de la pagina entera); un formulario, un fetch, un iframe o una imagen de otra web no llega.
# Y un POST (o PUT, DELETE...) con el Origin de otra web, tampoco. Ojo: la vuelta de una pasarela de
# pago que hace un POST desde su web se corta mientras este puesta
<If "(%{HTTP:Sec-Fetch-Site} =~ /^cross-site$/i && !(%{REQUEST_METHOD} =~ /^(GET|HEAD)$/ && %{HTTP:Sec-Fetch-Mode} =~ /^(navigate)?$/i && %{HTTP:Sec-Fetch-Dest} =~ /^(document)?$/i)) || (%{REQUEST_METHOD} !~ /^(GET|HEAD)$/ && -n %{HTTP:Origin} && %{HTTP:Origin} != '"'"'http://'"'"' . %{HTTP_HOST} && %{HTTP:Origin} != '"'"'https://'"'"' . %{HTTP_HOST})">
    Require all denied
    ErrorDocument 403 "Otra web ha intentado mandar algo a este proyecto: no se ha hecho nada (barrera entre webs de lvm-instalador; se apaga en Configuracion)."
</If>
# /lvm-barrera-web
'
UNKNOWN_HOST_SSL='
# Lo mismo en HTTPS, con el certificado de localhost de la version
<IfModule ssl_module>
<VirtualHost *:443>
    ServerName localhost
    ServerAlias 127.0.0.1 [::1]
    SSLEngine on
    SSLCertificateFile "etc/ssl.crt/server.crt"
    SSLCertificateKeyFile "etc/ssl.key/server.key"
    <If "%{HTTP_HOST} !~ /^(localhost|127\.0\.0\.1|\[::1\])(:[0-9]+)?$/">
        Require all denied
        ErrorDocument 403 "Este dominio no tiene vhost en este Mac (lvm-instalador): crea su vhost o entra con localhost."
    </If>
    # En 127.0.0.1 y [::1] solo phpMyAdmin: los proyectos van en localhost
    <If "%{HTTP_HOST} =~ /^(127\.0\.0\.1|\[::1\])(:[0-9]+)?$/ && %{REQUEST_URI} !~ m#^/phpmyadmin(/|$)#">
        Require all denied
        ErrorDocument 403 "En 127.0.0.1 solo esta phpMyAdmin: los proyectos van en http://localhost/ (lvm-instalador)"
    </If>
</VirtualHost>
</IfModule>
'

# Barrera entre webs (el bloque lvm-barrera-web de UNKNOWN_HOST_VHOST): puesta salvo que se haya
# apagado. Lo apagado es un fichero de root en XAMPP-compartido: lo que lleva el Apache de todas las
# versiones (que arranca como root) no lo puede cambiar un programa tuyo
WEB_BARRIER_OFF=$COMMON/lvm-sin-barrera-web
function web_barrier_on() {
    [ -f "$WEB_BARRIER_OFF" ] && [ ! -L "$WEB_BARRIER_OFF" ] || return 0
    # (en las pruebas sin sudo vale cualquier fichero)
    [ -n "$TEST_DIR" ] && return 1
    [ "$(stat -f %u "$WEB_BARRIER_OFF" 2> /dev/null)" == 0 ] && return 1
    return 0
}

# UNKNOWN_HOST_VHOST tal cual o, con la barrera apagada, sin su bloque (siempre acaba en salto de linea)
function unknown_host_vhost() {
    if web_barrier_on; then
        printf '%s' "$UNKNOWN_HOST_VHOST"
    else
        awk '/^# lvm-barrera-web:/ { skip = 1 } !skip { print } /^# \/lvm-barrera-web$/ { skip = 0 }' <<< "${UNKNOWN_HOST_VHOST%$'\n'}"
    fi
}

# barrera-web si|no: pone o quita la barrera entre webs en todas las versiones (y reinicia Apache
# de la activa si esta en marcha). Sin argumento, dice como esta
function web_barrier_command() {
    # (si hay que cambiarla: la contraseña antes de nada; cancelarla la deja como estaba)
    if { [ "$1" == si ] && ! web_barrier_on; } || { [ "$1" == no ] && web_barrier_on; }; then
        sudo_first || return 1
    fi
    case "$1" in
        "")
            web_barrier_on && echo "Barrera entre webs: puesta" || echo "Barrera entre webs: apagada"
            return 0 ;;
        si|no) ;;
        *) echo "Uso: lvm-instalador barrera-web [si|no]"; return 1 ;;
    esac
    if [ "$1" == si ]; then
        web_barrier_on && { echo "La barrera entre webs ya esta puesta"; return 0; }
        echo "Barrera entre webs: se pone en todas las versiones"
        run $SUDO rm -f "$WEB_BARRIER_OFF" || return 1
    else
        web_barrier_on || { echo "La barrera entre webs ya esta apagada"; return 0; }
        echo "Barrera entre webs: se apaga en todas las versiones (otras webs podran volver a mandar"
        echo "formularios a tus proyectos, como la vuelta de una pasarela de pago)"
        if [ "$DRY" -eq 0 ]; then
            [ -d "$COMMON" ] || { echo "No existe $COMMON (se crea al instalar la primera version)"; return 1; }
            echo "Apagada con lvm-instalador barrera-web no" | $SUDO tee "$WEB_BARRIER_OFF" > /dev/null || return 1
            [ -z "$SUDO" ] || $SUDO chmod 644 "$WEB_BARRIER_OFF" || return 1
        fi
    fi
    [ "$DRY" -eq 1 ] && return 0
    secure_all
    if [ $? -eq 2 ]; then
        # (no se ha podido aplicar: el interruptor vuelve a como estaba)
        if [ "$1" == si ]; then
            echo "Apagada con lvm-instalador barrera-web no" | $SUDO tee "$WEB_BARRIER_OFF" > /dev/null
            [ -z "$SUDO" ] || $SUDO chmod 644 "$WEB_BARRIER_OFF"
        else
            $SUDO rm -f "$WEB_BARRIER_OFF"
        fi
        secure_all > /dev/null 2>&1
        echo "No se ha podido cambiar en todas las versiones: se deja como estaba"
        return 1
    fi
    if [ -n "$(active_dir)" ] && [ -f "$LINK/xamppfiles/logs/httpd.pid" ]; then
        echo "Recargando Apache de la version activa..."
        xampp_ctl reloadapache > /dev/null || { echo "No se ha podido recargar Apache: reinicia la version activa."; return 1; }
    fi
    echo "Listo"
}

# PHP de las pilas propias contra PHP2Shell (CVE-2026-109618 y CVE-2026-109619): la subida de
# ficheros con el progreso de la sesion, los arrays muy anidados y los cuerpos enormes, sin decir la
# version de PHP. Lo escriben install_stack y SECURE_PY (las versiones ya instaladas)
PHP_SECURITY_INI='; lvm-instalador: PHP2Shell (CVE-2026-109618 y CVE-2026-109619)
; Va despues de 99-xampp.ini: estos valores mandan. Lo rehace lvm-instalador asegurar
session.upload_progress.enabled = Off
max_input_nesting_level = 6
post_max_size = 64M
upload_max_filesize = 64M
expose_php = Off
'
# (desde PHP 8.5: sin la traza de los errores fatales, que llevaria los argumentos)
PHP_SECURITY_INI_85='fatal_error_backtraces = 0
'

# ===========================================================================
# Correo de pruebas: Mailpit
# ===========================================================================
# Lo que mandan las webs locales (formularios, pedidos, contraseñas) no puede llegar a nadie: con las
# BBDD copiadas de los clientes, un pedido de prueba avisaria al cliente real. Con el correo de pruebas
# encendido (por defecto), todo va a Mailpit (https://github.com/axllent/mailpit, MIT), que lo guarda
# y lo enseña en http://127.0.0.1:8025/:
#   - mail() de PHP en todas las versiones (sendmail_path al sendmail de Mailpit; SECURE_PY)
#   - WordPress con plugins de SMTP o Brevo, segun MAIL_WP_FILE: mailpit (los de SMTP siguen, pero
#     con su correo a Mailpit: etc/lvm-correo-wordpress.php en auto_prepend_file; los que mandan por
#     una API se desactivan en la copia local), desactivar (todos fuera de la copia local, con lo que
#     WordPress usa mail()) o nada (no se tocan: el correo puede salir de verdad)
#   - PrestaShop: su configuracion de correo, por SMTP a Mailpit (en la copia local)
# Los cambios en las BBDD se apuntan (con lo que habia) en la tabla MAIL_TABLE de la propia base: se
# deshacen al apagarlo y no salen en las copias (exportar-bd, copiar-bd, Docker). Mailpit va con la
# version activa: arranca y para con ella, con tu usuario y solo en 127.0.0.1. (Los proyectos de
# Docker Desktop aun no: podrian mandar a host.docker.internal:1025, pero Mailpit solo escucha en
# 127.0.0.1; sus BBDD, como las copias, llevan el correo de produccion)
# Version fijada y sha256 de cada .tar.gz de macOS (de los digest de la publicacion en GitHub,
# comprobados al descargarlos el 25/10/2026). La 1.32.0 arregla fallos de seguridad (GHSA-379p-g4f4-hq5h)
MAILPIT_VERSION="1.32.0"
MAILPIT_SHA_ARM64="23709bd727f20da2290de6a2a40c4685c48a3127586d77370efd1a3a595f9ef6"
MAILPIT_SHA_AMD64="d7f3d0964cd2ea4c2a7d10660a12e02876718e67d88ced390d9cd90350a453da"
# El programa, de root en /Library/Nexum/mailpit (junto al gestor y XAMPP-compartido, cada carpeta
# hasta / de root y sin escritura para el grupo admin): ni tu usuario ni una web pueden cambiar lo que
# ejecuta PHP al mandar un correo. Sus datos, solo tuyos
MAILPIT_DIR=$BASE_DIR/mailpit
MAILPIT_BIN=$MAILPIT_DIR/mailpit
MAILPIT_DATA=$LOG_DIR/mailpit
MAILPIT_MAX=500
MAIL_SMTP_PORT=1025
MAIL_UI_PORT=8025
MAIL_UI_URL="http://127.0.0.1:$MAIL_UI_PORT/"
# Encendido salvo que exista MAIL_OFF_FILE; el modo de WordPress, en MAIL_WP_FILE (mailpit si no hay)
MAIL_OFF_FILE=$LOG_DIR/correo-apagado
MAIL_WP_FILE=$LOG_DIR/correo-wordpress
MAIL_TABLE=lvm_correo_original

# etc/lvm-correo-wordpress.php de cada version (lo escribe SECURE_PY como root; @PUERTO@, el SMTP de
# Mailpit). El mismo que en Linux: vale desde PHP 7.1
MAIL_WP_PHP=$(cat <<'PHP'
<?php
// lvm-instalador (Nexum Dev Stack): correo de pruebas de WordPress. Lo pone root y PHP lo carga antes
// de cada script de esta version (auto_prepend_file) mientras el correo de pruebas esta encendido y
// los plugins de SMTP de WordPress van a Mailpit. Fuera de WordPress no hace nada: solo deja dos
// ganchos en la lista que WordPress lee al arrancar (desde la 4.7 la pasa a WP_Hook con
// WP_Hook::build_preinitialized_hooks; las anteriores la usan tal cual).
//  - phpmailer_init, el ultimo: lo que sale por PHPMailer (wp_mail y los plugins de SMTP que lo usan:
//    WP Mail SMTP, Easy WP SMTP, SMTP Mailer, WP SMTP...) va al SMTP de Mailpit, sin usuario ni cifrado
//  - pre_http_request: no se llama a las API de envio de correo (Brevo, SendGrid, Mailgun...)
if (!isset($GLOBALS['wp_filter']) || is_array($GLOBALS['wp_filter'])) {
    $GLOBALS['wp_filter']['phpmailer_init'][PHP_INT_MAX][] = array(
        'function' => function ($mailer) {
            if (!is_object($mailer) || !method_exists($mailer, 'isSMTP')) {
                return;
            }
            $mailer->isSMTP();
            $mailer->Host = '127.0.0.1';
            $mailer->Port = @PUERTO@;
            $mailer->SMTPAuth = false;
            $mailer->Username = '';
            $mailer->Password = '';
            $mailer->SMTPSecure = '';
            $mailer->SMTPAutoTLS = false;
        },
        'accepted_args' => 1,
    );
    $GLOBALS['wp_filter']['pre_http_request'][PHP_INT_MAX][] = array(
        'function' => function ($pre, $args = array(), $url = '') {
            $host = strtolower((string) parse_url((string) $url, PHP_URL_HOST));
            $path = strtolower((string) parse_url((string) $url, PHP_URL_PATH));
            // dominio => parte de la ruta ('' = cualquiera)
            $apis = array(
                'brevo.com' => '', 'sendinblue.com' => '', 'sendgrid.com' => '', 'sendgrid.net' => '',
                'mailgun.net' => '', 'postmarkapp.com' => '', 'sparkpost.com' => '', 'mailjet.com' => '',
                'smtp2go.com' => '', 'resend.com' => '', 'mailersend.com' => '', 'elasticemail.com' => '',
                'sendlayer.com' => '', 'smtp.com' => '', 'mandrillapp.com' => '', 'zeptomail.com' => '',
                'zeptomail.eu' => '', 'sendpulse.com' => '', 'pepipost.com' => '', 'netcorecloud.net' => '',
                'socketlabs.com' => '', 'gmail.googleapis.com' => '/send', 'graph.microsoft.com' => '/sendmail',
                'mail.zoho.com' => '/messages', 'mail.zoho.eu' => '/messages',
            );
            $hit = (bool) preg_match('/^email(-smtp)?\.[a-z0-9-]+\.amazonaws\.com$/', $host);
            foreach ($apis as $api => $part) {
                if (($host === $api || substr($host, -strlen($api) - 1) === '.' . $api)
                        && ($part === '' || strpos($path, $part) !== false)) {
                    $hit = true;
                }
            }
            if ($hit && class_exists('WP_Error')) {
                return new WP_Error('lvm_correo', 'Correo de pruebas (lvm-instalador): en este equipo no se llama a '
                    . 'las API de envio de correo; lo que se mande va a Mailpit.');
            }
            return $pre;
        },
        'accepted_args' => 3,
    );
}
PHP
)

function mail_on() {
    [ ! -e "$MAIL_OFF_FILE" ]
}

# Modo de los plugins de correo de WordPress: mailpit, desactivar o nada
function mail_wp_mode() {
    local m=""
    [ -f "$MAIL_WP_FILE" ] && m=$(head -c 20 "$MAIL_WP_FILE" | tr -d ' \n')
    case $m in
        desactivar|nada) echo "$m" ;;
        *) echo mailpit ;;
    esac
}

function mailpit_installed() {
    [ -f "$MAILPIT_BIN" ] && [ -x "$MAILPIT_BIN" ] && [ ! -L "$MAILPIT_BIN" ]
}

function mailpit_installed_version() {
    head -c 20 "$MAILPIT_DIR/version" 2> /dev/null | head -1 | grep -E '^[0-9]+\.[0-9]+\.[0-9]+$'
}

# Lo que SECURE_PY pone en el PHP de cada version (LVM_CORREO): binario|puerto|WordPress a Mailpit
# (1/0). Nada con el correo apagado. Sin Mailpit instalado tambien: mail() falla en lugar de salir
function mail_secure_spec() {
    mail_on || return 0
    echo "$MAILPIT_BIN|$MAIL_SMTP_PORT|$([ "$(mail_wp_mode)" == mailpit ] && echo 1 || echo 0)"
}

# ¿Es <pid> un Mailpit del gestor tuyo? Sin /proc: su usuario y su orden, de ps, que empieza por el
# binario y --smtp (el Python que lo arranca, antes de pasar a ser Mailpit, no vale)
function mailpit_is() {
    local uid cmd
    [[ "$1" =~ ^[0-9]+$ ]] && [ "$1" -gt 1 ] || return 1
    read -r uid cmd < <(ps -o uid=,command= -p "$1" 2> /dev/null)
    [ "$uid" == "$(id -u)" ] && [[ "$cmd" == "$MAILPIT_BIN --smtp "* ]]
}

# Mailpit del gestor en marcha con tu usuario (pgrep, por el principio de su orden)
function mailpit_find() {
    pgrep -u "$(id -u)" -f -- "^$MAILPIT_BIN --smtp " 2> /dev/null | head -1
}

# Numero del proceso de Mailpit: el de su .pid si es tuyo y es el del gestor o, si se ha perdido, el
# que este en marcha con su binario
function mailpit_pid() {
    local p
    p=$(head -c 20 "$MAILPIT_DATA/mailpit.pid" 2> /dev/null | tr -d ' \n')
    if mailpit_is "$p"; then
        echo "$p"
        return 0
    fi
    p=$(mailpit_find)
    [ -n "$p" ] && echo "$p"
}

# Arranca Mailpit con tu usuario (nunca como root): SMTP y web solo en 127.0.0.1, la web solo con su
# direccion (Mailpit rechaza otro Host: una web cuyo dominio apunte a 127.0.0.1, DNS rebinding, no
# puede leer los correos; y las peticiones de otras webs que cambian algo, por su Origin), sin buscar
# versiones nuevas, sin CSS ni fuentes de fuera en los correos y como mucho MAILPIT_MAX. Con el entorno
# limpio: Mailpit lee su configuracion de las variables MP_* (una MP_SMTP_RELAY_ALL de tu sesion
# mandaria los correos de verdad).
# En el Mac no hay setsid: lo hace el Python del sistema (os.setsid y exec), para que no siga en la
# sesion de la terminal de la tarea. Y sin quedarse con ella: la entrada de /dev/null y la salida a un
# fichero (con la terminal abierta, la ventana se quedaria esperando el final de la tarea)
MAILPIT_SETSID_PY='
import os, sys
# (si ya fuera el primero de su grupo, setsid no se puede: antes, un proceso hijo)
try:
    os.setsid()
except OSError:
    if os.fork():
        os._exit(0)
    os.setsid()
os.execv(sys.argv[1], sys.argv[1:])
'
function mailpit_start() {
    local p="" i
    [ -n "$(mailpit_pid)" ] && return 0
    mailpit_installed || return 1
    [ "$(id -u)" -eq 0 ] && { echo "Mailpit no se arranca como root"; return 1; }
    # (--suave, desde la ventana cada 20 s: si no pudo arrancar hace menos de 5 minutos, no se espera otra vez)
    [ "$1" == --suave ] && [ -n "$(find "$MAILPIT_DATA/no-arranca" -mmin -5 2> /dev/null)" ] && return 1
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] Mailpit en 127.0.0.1:$MAIL_SMTP_PORT (SMTP) y $MAIL_UI_URL, con datos en $MAILPIT_DATA"
        return 0
    fi
    if [ -L "$MAILPIT_DATA" ] || { [ -e "$MAILPIT_DATA" ] && [ ! -O "$MAILPIT_DATA" ]; }; then
        echo "$MAILPIT_DATA no es una carpeta tuya: no se arranca Mailpit"
        return 1
    fi
    mkdir -p -m 700 "$MAILPIT_DATA" && chmod 700 "$MAILPIT_DATA" || return 1
    [ -L "$MAILPIT_DATA/salida.log" ] && rm -f "$MAILPIT_DATA/salida.log"
    ( cd / && exec env -i HOME="$HOME" USER="$USER" PATH=/usr/bin:/bin /usr/bin/python3 -I -c "$MAILPIT_SETSID_PY" \
        "$MAILPIT_BIN" \
        --smtp "127.0.0.1:$MAIL_SMTP_PORT" --listen "127.0.0.1:$MAIL_UI_PORT" \
        --allowed-hosts "127.0.0.1:$MAIL_UI_PORT,localhost:$MAIL_UI_PORT" \
        --database "$MAILPIT_DATA/mailpit.db" --max "$MAILPIT_MAX" --label "Nexum Dev Stack" \
        --disable-version-check --block-remote-css-and-fonts --smtp-disable-rdns --quiet \
        --log-file "$MAILPIT_DATA/mailpit.log" ) < /dev/null > "$MAILPIT_DATA/salida.log" 2>&1 &
    # (lista en un par de segundos; si no aparece o se cierra enseguida, el puerto lo usa otro programa.
    # Su numero se busca: el python3 de /usr/bin podria arrancarlo en un proceso aparte)
    for i in $(seq 30); do
        sleep 0.1
        p=$(mailpit_find)
        [ -n "$p" ] && curl -q -s --noproxy '*' --max-time 1 -o /dev/null "${MAIL_UI_URL}readyz" 2> /dev/null && break
    done
    p=$(mailpit_find)
    if [ -z "$p" ]; then
        rm -f "$MAILPIT_DATA/mailpit.pid"
        : > "$MAILPIT_DATA/no-arranca"
        echo "Mailpit no ha arrancado (¿otro programa en el puerto $MAIL_SMTP_PORT o $MAIL_UI_PORT?): mira $MAILPIT_DATA/mailpit.log"
        return 1
    fi
    echo "$p" > "$MAILPIT_DATA/mailpit.pid"
    rm -f "$MAILPIT_DATA/no-arranca"
    echo "Mailpit en marcha: el correo de las webs se ve en $MAIL_UI_URL"
}

function mailpit_stop() {
    local p i
    p=$(mailpit_pid)
    if [ -z "$p" ]; then
        rm -f "$MAILPIT_DATA/mailpit.pid"
        return 0
    fi
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] se para Mailpit ($p)"
        return 0
    fi
    kill "$p" 2> /dev/null
    for i in $(seq 50); do
        kill -0 "$p" 2> /dev/null || break
        sleep 0.1
    done
    kill -0 "$p" 2> /dev/null && kill -9 "$p" 2> /dev/null
    rm -f "$MAILPIT_DATA/mailpit.pid"
    echo "Mailpit parado"
}

# Mailpit en marcha solo con el correo de pruebas encendido, instalado y la version activa en marcha
# (--suave: lo pasa a mailpit_start)
function mailpit_sync() {
    if mail_on && mailpit_installed && lampp_running; then
        mailpit_start "$1"
    else
        mailpit_stop
    fi
}

# Instala (o pone al dia) Mailpit en MAILPIT_DIR: el .tar.gz oficial de GitHub para este Mac,
# comprobado con su sha256 y abierto como root en una carpeta de root (asi ningun programa tuyo puede
# cambiarlo entre la comprobacion y la copia). Solo el programa y su licencia, de root. curl no le pone
# la cuarentena (Gatekeeper no lo mira); por si acaso, se le quitan los atributos extendidos, y su
# firma (la de Go, sin ella un Mac con Apple Silicon no lo ejecuta) se comprueba con codesign
function mailpit_install() {
    local arch sha url tmp rtmp got own=(-o 0 -g 0) tls=(--proto '=https' --proto-redir '=https' --tlsv1.2)
    case $(uname -m) in
        arm64|aarch64) arch=arm64 sha=$MAILPIT_SHA_ARM64 ;;
        x86_64|amd64) arch=amd64 sha=$MAILPIT_SHA_AMD64 ;;
        *) echo "Mailpit no publica version para este Mac ($(uname -m))"; return 1 ;;
    esac
    url=https://github.com/axllent/mailpit/releases/download/v$MAILPIT_VERSION/mailpit-darwin-$arch.tar.gz
    # (las pruebas, sin root ni red: otro fichero y su suma)
    if [ -n "$TEST_DIR" ]; then
        url=${LVM_MAILPIT_URL:-$url} sha=${LVM_MAILPIT_SHA:-$sha} own=() tls=()
    fi
    if mailpit_installed && [ "$(mailpit_installed_version)" == "$MAILPIT_VERSION" ]; then
        echo "Mailpit $MAILPIT_VERSION ya esta instalado en $MAILPIT_DIR"
        return 0
    fi
    echo "Instalando Mailpit $MAILPIT_VERSION (correo de pruebas) en $MAILPIT_DIR"
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] descarga de $url, comprobacion de su sha256 y copia de root en $MAILPIT_BIN"
        return 0
    fi
    # Su carpeta y la de encima (/Library/Nexum) tienen que ser de root
    if [ -L "$MAILPIT_DIR" ] || { [ -z "$TEST_DIR" ] && { [ "$(stat -f %u "$BASE_DIR" 2> /dev/null)" != 0 ] \
            || { [ -e "$MAILPIT_DIR" ] && [ "$(stat -f %u "$MAILPIT_DIR")" != 0 ]; }; }; }; then
        echo "$MAILPIT_DIR no es una carpeta de root: no se instala Mailpit"
        return 1
    fi
    mkdir -p -m 700 "$LOG_DIR" || return 1
    tmp=$(mktemp -d "$LOG_DIR/mailpit-descarga.XXXXXX") || return 1
    echo "Descargando $(basename "$url")..."
    if ! curl -q -fsSL "${tls[@]}" --retry 2 --max-time 600 -o "$tmp/mailpit.tar.gz" "$url"; then
        rm -rf "$tmp"
        echo "No se ha podido descargar Mailpit ($url)"
        echo "Se puede descargar a mano de https://github.com/axllent/mailpit/releases/tag/v$MAILPIT_VERSION"
        return 1
    fi
    rtmp=$($SUDO mktemp -d "${TEST_DIR:-/tmp}/lvm-mailpit.XXXXXX") && $SUDO chmod 700 "$rtmp" || { rm -rf "$tmp"; return 1; }
    $SUDO cp "$tmp/mailpit.tar.gz" "$rtmp/mailpit.tar.gz"
    rm -rf "$tmp"
    got=$($SUDO shasum -a 256 "$rtmp/mailpit.tar.gz" 2> /dev/null | cut -d' ' -f1)
    if [ "$got" != "$sha" ]; then
        $SUDO rm -rf "$rtmp"
        echo "La descarga de Mailpit no coincide con su suma sha256 (${got:-ninguna}): no se instala."
        return 1
    fi
    # Se abre entero en su carpeta (ya comprobado con su sha256) y se busca el programa; si falla, con
    # el error de tar y la pagina de descarga
    local x=$rtmp/x bin lic err
    if ! err=$({ $SUDO /bin/mkdir "$x" && $SUDO /usr/bin/tar -xzf "$rtmp/mailpit.tar.gz" -C "$x" --no-same-owner; } 2>&1); then
        $SUDO rm -rf "$rtmp"
        echo "No se ha podido abrir el paquete de Mailpit: no se instala."
        [ -n "$err" ] && sed 's/^/  /' <<< "$err" | head -5
        echo "Se puede descargar a mano de https://github.com/axllent/mailpit/releases/tag/v$MAILPIT_VERSION ($(basename "$url"))"
        return 1
    fi
    bin=$($SUDO /usr/bin/find "$x" -maxdepth 2 -type f -name mailpit 2> /dev/null | head -1)
    lic=$($SUDO /usr/bin/find "$x" -maxdepth 2 -type f -name LICENSE 2> /dev/null | head -1)
    if [ -z "$bin" ]; then
        $SUDO rm -rf "$rtmp"
        echo "El paquete de Mailpit no trae su programa: no se instala."
        return 1
    fi
    # La firma se comprueba como root: la carpeta temporal es de root y solo suya (con tu usuario,
    # codesign no podia leerlo y decia siempre que no tenia firma). Si viniera sin ninguna (los de Apple
    # Silicon traen la local de Go), se le pone una local: su contenido ya esta comprobado con la
    # sha256 de la descarga. Una firma que no cuadra (programa cambiado), no se instala
    if [ -z "$TEST_DIR" ]; then
        $SUDO /usr/bin/xattr -c "$bin" 2> /dev/null
        if ! err=$($SUDO /usr/bin/codesign --verify "$bin" 2>&1); then
            if [[ "$err" == *"not signed at all"* ]] && $SUDO /usr/bin/codesign --force --sign - "$bin" > /dev/null 2>&1 \
                    && $SUDO /usr/bin/codesign --verify "$bin" 2> /dev/null; then
                echo "Mailpit viene sin firmar: se le pone una firma local (comprobado antes con su sha256)"
            else
                $SUDO rm -rf "$rtmp"
                echo "El programa de Mailpit no lleva una firma valida (macOS no lo ejecutaria): no se instala."
                [ -n "$err" ] && sed 's/^/  /' <<< "$err" | head -3
                return 1
            fi
        fi
    fi
    if ! { $SUDO install -d "${own[@]}" -m 755 "$MAILPIT_DIR" \
            && $SUDO install "${own[@]}" -m 755 "$bin" "$MAILPIT_DIR/mailpit.nuevo" \
            && $SUDO mv -f "$MAILPIT_DIR/mailpit.nuevo" "$MAILPIT_BIN" \
            && { [ -z "$lic" ] || $SUDO install "${own[@]}" -m 644 "$lic" "$MAILPIT_DIR/LICENSE"; } \
            && echo "$MAILPIT_VERSION" | $SUDO tee "$MAILPIT_DIR/version" > /dev/null; }; then
        $SUDO rm -rf "$rtmp"
        echo "No se ha podido copiar Mailpit a $MAILPIT_DIR"
        return 1
    fi
    $SUDO rm -rf "$rtmp"
    echo "Mailpit $MAILPIT_VERSION instalado: $MAILPIT_BIN (sus correos, en $MAILPIT_DATA)"
    # (el de antes, si estaba en marcha, se para: mailpit_sync arranca el nuevo)
    [ -n "$(mailpit_pid)" ] && mailpit_stop > /dev/null
    return 0
}

# Despues de cambiar el correo de pruebas: el PHP de todas las versiones (como asegurar --todas, pide
# la contraseña), Apache y PHP-FPM de la activa recargados, Mailpit en marcha o parado y la BBDD del
# proyecto cargado al dia
function mail_apply() {
    local rc
    secure_all
    rc=$?
    if [ $rc -eq 2 ]; then
        echo "No se ha podido cambiar en todas las versiones: prueba con lvm-instalador asegurar --todas"
        return 1
    fi
    if [ $rc -eq 0 ] && lampp_running; then
        run xampp_ctl reloadapache > /dev/null || { echo "No se ha podido recargar Apache"; return 1; }
    fi
    mailpit_sync
    mail_loaded_project
    return 0
}

# Texto del modo de WordPress
function mail_wp_text() {
    case $1 in
        mailpit) echo "los plugins de SMTP de WordPress siguen, con su correo a Mailpit (los que mandan por una API, como Brevo, se desactivan en la copia local)" ;;
        desactivar) echo "los plugins de SMTP y de envio de correo de WordPress se desactivan en la copia local (WordPress usa mail(), que va a Mailpit)" ;;
        nada) echo "los plugins de correo de WordPress no se tocan: lo que manden por SMTP o por su API puede llegar de verdad" ;;
    esac
}

# correo [estado] | si | no | wordpress mailpit|desactivar|nada | instalar | vaciar | bd <base>
# Un ajuste que se aplica como root (interruptores de la ventana): la contraseña antes de cambiar
# nada. Cancelarla deja el ajuste como estaba
function sudo_first() {
    { [ "$DRY" -eq 1 ] || [ -z "$SUDO" ]; } && return 0
    sudo -v && return 0
    echo "Cancelado: no se ha cambiado nada"
    return 1
}

function mail_command() {
    local mode old
    case $1 in
        ""|estado)
            if mail_on; then
                echo "Correo de pruebas encendido: lo que mandan las webs va a Mailpit"
            else
                echo "Correo de pruebas apagado: lo que mandan las webs sale como sin el gestor (puede llegar de verdad)"
            fi
            echo "  WordPress: $(mail_wp_text "$(mail_wp_mode)")"
            if mailpit_installed; then
                echo "  Mailpit $(mailpit_installed_version) en $MAILPIT_BIN$([ -n "$(mailpit_pid)" ] && echo ", en marcha: $MAIL_UI_URL" || echo ", parado (va con la version activa)")"
            else
                echo "  Mailpit no esta instalado (lvm-instalador correo instalar): sin el, mail() falla y no sale nada"
            fi
            return 0 ;;
        si|on|no|off)
            mkdir -p -m 700 "$LOG_DIR" || return 1
            if [ "$1" == si ] || [ "$1" == on ]; then
                mail_on && { echo "El correo de pruebas ya estaba encendido"; return 0; }
                sudo_first || return 1
                # (--instalar: y Mailpit, si no lo esta; lo ofrece la ventana la primera vez)
                if [ "$2" == --instalar ] && ! mailpit_installed; then
                    mailpit_install || return 1
                fi
                [ "$DRY" -eq 0 ] && rm -f "$MAIL_OFF_FILE"
                mailpit_installed || echo "Aviso: Mailpit no esta instalado (lvm-instalador correo instalar): hasta entonces mail() falla"
            else
                mail_on || { echo "El correo de pruebas ya estaba apagado"; return 0; }
                sudo_first || return 1
                [ "$DRY" -eq 0 ] && { : > "$MAIL_OFF_FILE" || return 1; }
            fi
            if [ "$DRY" -eq 1 ]; then
                echo "  [simulacion] correo de pruebas $([[ "$1" =~ ^(si|on)$ ]] && echo encendido || echo apagado) en todas las versiones"
                return 0
            fi
            if ! mail_apply; then
                # (no se ha podido aplicar: el interruptor vuelve a como estaba)
                if [ "$1" == si ] || [ "$1" == on ]; then : > "$MAIL_OFF_FILE"; else rm -f "$MAIL_OFF_FILE"; fi
                mail_apply > /dev/null 2>&1
                echo "No se ha cambiado el correo de pruebas"
                return 1
            fi
            mail_on && echo "Correo de pruebas encendido: lo que manden las webs va a Mailpit" \
                || echo "Correo de pruebas apagado: lo que manden las webs puede llegar de verdad"
            return 0 ;;
        wordpress)
            mode=$2
            case $mode in
                mailpit|desactivar|nada) ;;
                *) echo "Uso: lvm-instalador correo wordpress mailpit|desactivar|nada"; return 1 ;;
            esac
            if [ "$DRY" -eq 1 ]; then
                echo "  [simulacion] WordPress: $(mail_wp_text "$mode")"
                return 0
            fi
            sudo_first || return 1
            old=$(mail_wp_mode)
            mkdir -p -m 700 "$LOG_DIR" && echo "$mode" > "$MAIL_WP_FILE" || return 1
            if ! mail_apply; then
                echo "$old" > "$MAIL_WP_FILE"
                mail_apply > /dev/null 2>&1
                echo "No se ha cambiado el modo de WordPress"
                return 1
            fi
            echo "WordPress: $(mail_wp_text "$mode")"
            return 0 ;;
        instalar)
            mailpit_install || return 1
            [ "$DRY" -eq 1 ] && return 0
            if mail_on; then
                mail_apply
            else
                echo "El correo de pruebas esta apagado: enciendelo con lvm-instalador correo si"
            fi
            return 0 ;;
        vaciar)
            [ -n "$(mailpit_pid)" ] || { echo "Mailpit no esta en marcha"; return 1; }
            run curl -q -fs --noproxy '*' --max-time 10 -X DELETE -o /dev/null "${MAIL_UI_URL}api/v1/messages" \
                || { echo "No se ha podido vaciar la bandeja de Mailpit"; return 1; }
            echo "Bandeja de Mailpit vacia"
            return 0 ;;
        bd)
            mail_db "$2" ;;
        *)
            echo "Uso: lvm-instalador correo [estado] | si [--instalar] | no | wordpress mailpit|desactivar|nada | instalar | vaciar | bd <base>"
            return 1 ;;
    esac
}

# Ficheros de configuracion de una version que hay que cambiar: <ruta>|<fichero nuevo>|<que cambia>
SECURE_PY='
import glob, os, re, sys
base, out, v6 = sys.argv[1], sys.argv[2], sys.argv[3] == "1"
UNKNOWN_HOST_CONF, UNKNOWN_HOST_VHOST, UNKNOWN_HOST_SSL = sys.argv[4], sys.argv[5], sys.argv[6]
# (lo de PHP de las pilas propias: el .ini y lo que se añade en la 8.5; sin ellos no se mira)
PHP_INI, PHP_INI_85 = (sys.argv[7], sys.argv[8]) if len(sys.argv) > 8 else ("", "")
changes = []
# Un fichero con varios cambios (Listen y el Include de httpd.conf) se escribe una sola vez con
# todos: read() devuelve lo ya cambiado y save() lo pone al dia
pending = {}
def read(path):
    if path in pending:
        return pending[path]
    with open(path, encoding="utf-8", errors="surrogateescape", newline="") as f:
        return f.read()
def save(path, text, what):
    rel = os.path.relpath(path, base)
    for i, (r, dst, w) in enumerate(changes):
        if r == rel:
            changes[i] = (r, dst, w + "; " + what)
            break
    else:
        dst = os.path.join(out, str(len(changes)))
        changes.append((rel, dst, what))
    with open(dst, "w", encoding="utf-8", errors="surrogateescape", newline="") as f:
        f.write(text)
    pending[path] = text
def own(path):
    return os.path.isfile(path) and not os.path.islink(path)

# Apache: Listen 80 (o con la IP de la red, 0.0.0.0, * o [::]) -> Listen 127.0.0.1:80 y
# Listen [::1]:80 (los vhosts *:80 siguen igual). Los de 127.x, [::1] y localhost se quedan
listen = re.compile(r"^([ \t]*)Listen[ \t]+\"?(?:(\[[0-9A-Fa-f:.]*\]|[^\s:\[\]\"]+):)?(\d+)\"?([ \t]+[A-Za-z]+)?[ \t]*(\r?)$", re.M | re.I)
LOOP = re.compile(r"^(127\.\d+\.\d+\.\d+|\[::1\]|localhost)$", re.I)
confs = [os.path.join(base, "etc/httpd.conf"), os.path.join(base, "apache2/conf/httpd.conf")]
confs += sorted(glob.glob(os.path.join(base, "etc/extra/**/*.conf"), recursive=True))
http_ports = set()
# Direcciones y puertos ya escritos (en todos los ficheros): dos Listen iguales no dejan arrancar
# Apache («Cannot define multiple Listeners on the same IP:port»); el repetido se comenta
# Solo entre los ficheros que Apache carga de verdad (etc/httpd.conf y sus Include): otro httpd.conf
# suelto (el de fabrica de apache2/conf en las pilas propias) tiene sus propios Listen
def loaded():
    seen, todo = set(), [os.path.join(base, "etc/httpd.conf")]
    while todo:
        f = todo.pop()
        if f in seen or not own(f):
            continue
        seen.add(f)
        for inc in re.findall(r"(?mi)^[ \t]*Include(?:Optional)?[ \t]+\"?([^\"\s]+)", read(f)):
            if not inc.startswith("/"):
                inc = os.path.join(base, inc)
            else:
                for mark in ("/lampp/", "/xamppfiles/"):
                    if mark in inc and not inc.startswith(base + "/"):
                        inc = os.path.join(base, inc.split(mark, 1)[1])
                        break
            todo += glob.glob(inc)
    return seen
LOADED = loaded()
bound, bound_other = set(), {}
def addrs(addr, port):
    a = (addr or "").lower()
    if a == "localhost":
        return {("127.0.0.1", port), ("[::1]", port)}
    return {(a, port)}
for path in confs:
    if os.path.basename(path) == "httpd-vhosts.conf" or not own(path):
        continue
    text = read(path)
    ports = []
    bset = bound if path in LOADED else bound_other.setdefault(path, set())
    for m in listen.finditer(text):
        # Los de SSL no (httpd-ssl.conf, «https» o el 443): un vhost sin SSL delante romperia su https
        if (m.group(4) or "").strip().lower() != "https" and m.group(3) != "443" \
                and "ssl" not in os.path.basename(path).lower():
            http_ports.add(m.group(3))
    def fix(m):
        sp, port, proto, cr = m.group(1), m.group(3), m.group(4) or "", m.group(5)
        if m.group(2) and LOOP.match(m.group(2)):
            mine = addrs(m.group(2), port)
            if mine & bset:
                ports.append(port)
                return "%s# (lvm-instalador: repetido) %s" % (sp, m.group(0).lstrip())
            bset.update(mine)
            return m.group(0)
        ports.append(port)
        want = [a for a in (["127.0.0.1", "[::1]"] if v6 else ["127.0.0.1"]) if (a, port) not in bset]
        bset.update((a, port) for a in want)
        if not want:
            return "%s# (lvm-instalador: abierto a la red) %s" % (sp, m.group(0).lstrip())
        return "\n".join("%sListen %s:%s%s%s" % (sp, a, port, proto, cr) for a in want)
    new = listen.sub(fix, text)
    if new != text:
        save(path, new, "Apache, solo desde este Mac (puerto %s)" % ", ".join(ports))

# Apache: primer vhost del puerto 80 (etc/extra/lvm-dominio-desconocido.conf), incluido antes de los
# vhosts. Recibe los dominios que no tiene ningun vhost y solo deja pasar localhost
path = os.path.join(base, "etc/httpd.conf")
if own(path):
    text = read(path)
    vhosts = re.search(r"(?m)^([ \t]*)Include[ \t]+\"?etc/extra/httpd-vhosts\.conf\"?[ \t]*(\r?)$", text)
    if vhosts and UNKNOWN_HOST_CONF not in text:
        sp, cr = vhosts.group(1), vhosts.group(2)
        new = text[:vhosts.start()] + "%sInclude %s%s\n" % (sp, UNKNOWN_HOST_CONF, cr) + text[vhosts.start():]
        save(path, new, "Apache, rechaza los dominios sin vhost")
    elif UNKNOWN_HOST_CONF not in text:
        # Sin vhosts (Include comentado): al final, para que las reglas valgan igual
        nl = "\r\n" if "\r\n" in text else "\n"
        new = text + ("" if text.endswith("\n") else nl) + "# lvm-instalador" + nl + "Include " + UNKNOWN_HOST_CONF + nl
        save(path, new, "Apache, rechaza los dominios sin vhost")
    # El fichero es de lvm-instalador: si es de una version anterior (o le falta el 443), se rehace
    conf = os.path.join(base, UNKNOWN_HOST_CONF)
    want = UNKNOWN_HOST_VHOST
    # Otros puertos http (un Listen 8080 puesto a mano): tambien los recibe, si no evil.com:8080
    # resuelto a 127.0.0.1 llegaria a htdocs (DNS rebinding)
    # (y los que los vhosts usan con SSLEngine on)
    try:
        vtext = open(os.path.join(base, "etc/extra/httpd-vhosts.conf"), errors="replace").read()
    except OSError:
        vtext = ""
    for blk in re.findall(r"(?is)<VirtualHost\s+([^>]*)>(.*?)</VirtualHost>", vtext):
        if re.search(r"(?im)^\s*SSLEngine\s+on\b", blk[1]):
            http_ports -= set(re.findall(r":(\d+)", blk[0]))
    extra = sorted(http_ports - {"80"}, key=int)
    if extra and "<VirtualHost *:80>" in want:
        want = want.replace("<VirtualHost *:80>", "<VirtualHost %s>" % " ".join("*:" + x for x in ["80"] + extra), 1)
    if os.path.isfile(os.path.join(base, "etc/ssl.crt/server.crt")) \
            and os.path.isfile(os.path.join(base, "etc/ssl.key/server.key")):
        want += UNKNOWN_HOST_SSL
    if not os.path.lexists(conf):
        save(conf, want, "Apache, vhost para los dominios sin vhost")
    elif own(conf) and read(conf).startswith("# lvm-instalador:") and read(conf) != want:
        save(conf, want, "Apache, reglas de seguridad al dia (phpMyAdmin, barrera entre webs, peticiones de 64 MB)")

# OpenSSL de Homebrew (copiado en la version) leeria su configuracion de /opt/homebrew, que es de tu
# usuario, al arrancar como root: la version usa la suya (etc/openssl.cnf, de root)
xampp = os.path.join(base, "xampp")
if own(xampp) and own(os.path.join(base, "etc/pvm-stack")):
    text = read(xampp)
    if "OPENSSL_CONF" not in text:
        new = re.sub(r"(?m)^(ROOT=.*)$", "\\1\n# OpenSSL: solo su configuracion (no la de Homebrew, que es de tu usuario)\n"
                     "export OPENSSL_CONF=$ROOT/etc/openssl.cnf\nexport OPENSSL_MODULES=$ROOT/lib/ossl-modules", text, count=1)
        if new != text:
            save(xampp, new, "OpenSSL con su propia configuracion")
    fpm = os.path.join(base, "bin/pvm-php-fpm")
    if own(fpm):
        text = read(fpm)
        if "OPENSSL_CONF" not in text:
            new = text.replace("env -i PATH=/usr/sbin:/usr/bin:/sbin:/bin \"$FPM\"",
                               "env -i PATH=/usr/sbin:/usr/bin:/sbin:/bin OPENSSL_CONF=\"${FPM%/php/sbin/php-fpm}/etc/openssl.cnf\" \"$FPM\"")
            if new != text:
                save(fpm, new, "PHP-FPM con la configuracion de OpenSSL de la version")
    cnf = os.path.join(base, "etc/openssl.cnf")
    if not os.path.lexists(cnf):
        save(cnf, "# OpenSSL de esta version (lvm-instalador): sin configuracion ni modulos de fuera\n",
             "Configuracion de OpenSSL de la version")

# PHP2Shell (CVE-2026-109618 y CVE-2026-109619), en las pilas propias: PHP con los limites que lo
# frenan (php/etc/conf.d/zz-lvm-seguridad.ini, que va despues de 99-xampp.ini), PHP-FPM que rehace
# sus procesos cada 50 peticiones y htdocs sin CGI ni SSI (ExecCGI, Includes y el AddHandler de
# .cgi y .pl: ahi solo hay proyectos PHP)
if PHP_INI and own(os.path.join(base, "etc/pvm-stack")):
    conf_d = os.path.join(base, "php/etc/conf.d")
    php = read(os.path.join(base, "etc/pvm-php")).strip() if own(os.path.join(base, "etc/pvm-php")) else ""
    nums = [int(x) for x in re.findall(r"\d+", php)[:2]]
    want = PHP_INI + (PHP_INI_85 if len(nums) == 2 and nums >= [8, 5] else "")
    ini = os.path.join(conf_d, "zz-lvm-seguridad.ini")
    if os.path.isdir(conf_d) and not os.path.islink(conf_d):
        if not os.path.lexists(ini):
            save(ini, want, "PHP, limites contra PHP2Shell (CVE-2026-109618/109619)")
        elif own(ini) and read(ini).startswith("; lvm-instalador:") and read(ini) != want:
            save(ini, want, "PHP, limites contra PHP2Shell al dia")
    path = os.path.join(base, "php/etc/php-fpm.conf")
    if own(path):
        text = read(path)
        if not re.search(r"(?m)^[ \t]*pm\.max_requests[ \t]*=", text):
            new = re.sub(r"(?m)^([ \t]*pm[ \t]*=.*?)(\r?)$", lambda m: m.group(0) + "\npm.max_requests = 50" + m.group(2), text, count=1)
            if new != text:
                save(path, new, "PHP-FPM, procesos nuevos cada 50 peticiones (PHP2Shell)")
    path = os.path.join(base, "etc/httpd.conf")
    if own(path):
        text = read(path)
        new = re.sub(r"(?m)^([ \t]*Options[ \t]+Indexes[ \t]+FollowSymLinks)[ \t]+ExecCGI[ \t]+Includes[ \t]*(\r?)$", r"\1\2", text)
        new = re.sub(r"(?m)^([ \t]*)(AddHandler[ \t]+cgi-script[ \t]+\.cgi[ \t]+\.pl[ \t]*\r?)$",
                     r"\1# (lvm-instalador: sin CGI en htdocs) \2", new)
        if new != text:
            save(path, new, "Apache, htdocs sin CGI ni SSI (ExecCGI, Includes, .cgi y .pl)")

# MariaDB: bind-address = 127.0.0.1 en [mysqld] si no tiene un bind-address de este equipo ni
# skip-networking. Un bind-address abierto (0.0.0.0, ::, *, la IP de la red) o skip-networking=0 se
# comentan: estaban ahi, pero dejaban entrar desde la red
path = os.path.join(base, "etc/my.cnf")
if own(path):
    text = read(path)
    nl = "\r\n" if "\r\n" in text else "\n"
    section, has, out_lines = None, False, []
    for line in text.splitlines(True):
        s = line.strip()
        m = re.match(r"\[([^\]]+)\]", s)
        if m:
            section = m.group(1).strip().lower()
        elif section in ("mysqld", "mariadb", "mariadbd", "server"):
            b = re.match(r"(?i)bind[-_]address\s*=\s*[\"\x27]?([^\s\"\x27#;]*)", s)
            k = re.match(r"(?i)skip[-_]networking\b\s*(?:=\s*[\"\x27]?([^\s\"\x27#;]*))?", s)
            if b:
                if b.group(1).lower() in ("127.0.0.1", "::1", "localhost"):
                    has = True
                else:
                    line = "# (lvm-instalador: abierto a la red) " + line
            elif k:
                if (k.group(1) or "1").lower() in ("1", "on", "true", "yes", ""):
                    has = True
                else:
                    line = "# (lvm-instalador: abierto a la red) " + line
        out_lines.append(line)
    if "".join(out_lines) != text:
        text = "".join(out_lines)
        save(path, text, "MariaDB, sin el bind-address abierto a la red")
    if not has:
        add = "# Solo desde este Mac (lvm-instalador)" + nl + "bind-address = 127.0.0.1" + nl
        m = re.search(r"(?m)^[ \t]*\[mysqld\][ \t]*\r?(\n|$)", text)
        if m:
            head = text[:m.end()]
            new = head + ("" if head.endswith("\n") else nl) + add + text[m.end():]
        else:
            new = text + ("" if text.endswith("\n") or not text else nl) + nl + "[mysqld]" + nl + add
        save(path, new, "MariaDB, solo desde este Mac (bind-address)")

# MariaDB: sin leer ni escribir ficheros del Mac desde SQL. Con secure_file_priv vacio (el de
# XAMPP), root (phpMyAdmin entra como root sin contraseña) lee cualquier fichero con LOAD_FILE y
# escribe un PHP en htdocs con INTO OUTFILE. Se limita a una carpeta vacia de root, que tiene que
# existir (si falta, MariaDB no arranca), y sin LOAD DATA LOCAL. Una carpeta puesta a mano se respeta
NOFILES = os.path.join(base, "etc/lvm-sin-ficheros")
if own(path):
    text = read(path)
    nl = "\r\n" if "\r\n" in text else "\n"
    section, priv, infile, out_lines = None, None, False, []
    for line in text.splitlines(True):
        s = line.strip()
        m = re.match(r"\[([^\]]+)\]", s)
        if m:
            section = m.group(1).strip().lower()
        elif section in ("mysqld", "mariadb", "mariadbd", "server"):
            p = re.match(r"(?i)(?:loose[-_])?secure[-_]file[-_]priv\s*=\s*[\"\x27]?([^\"\x27#;]*?)[\"\x27]?\s*(?:[#;].*)?$", s)
            k = re.match(r"(?i)(?:loose[-_])?local[-_]infile\b\s*(?:=\s*[\"\x27]?([^\s\"\x27#;]*))?", s)
            if p:
                if p.group(1).strip():
                    priv = p.group(1).strip()
                else:
                    line = "# (lvm-instalador: dejaba leer y escribir ficheros) " + line
            elif k:
                if (k.group(1) or "1").lower() in ("0", "off", "false", "no"):
                    infile = True
                else:
                    line = "# (lvm-instalador: dejaba leer y escribir ficheros) " + line
        out_lines.append(line)
    new = "".join(out_lines)
    add = ""
    if priv is None:
        add += "secure-file-priv = \"%s\"%s" % (NOFILES, nl)
        priv = NOFILES
    if not infile:
        add += "local-infile = 0" + nl
    if add:
        add = "# Sin leer ni escribir ficheros del Mac desde SQL (lvm-instalador)" + nl + add
        m = re.search(r"(?m)^[ \t]*\[mysqld\][ \t]*\r?(\n|$)", new)
        if m:
            head = new[:m.end()]
            new = head + ("" if head.endswith("\n") else nl) + add + new[m.end():]
        else:
            new = new + ("" if new.endswith("\n") or not new else nl) + nl + "[mysqld]" + nl + add
    if new != text:
        save(path, new, "MariaDB, sin leer ni escribir ficheros desde SQL (secure_file_priv)")
    if os.path.normpath(priv) == NOFILES and not os.path.isdir(NOFILES):
        # (una carpeta, no un fichero: secure_lampp la crea de root)
        changes.append(("etc/lvm-sin-ficheros/", "", "MariaDB, carpeta vacia de secure_file_priv"))

# ProFTPD: DefaultAddress 127.0.0.1 y SocketBindTight on, detras de Port
path = os.path.join(base, "etc/proftpd.conf")
if own(path):
    text = read(path)
    # Un DefaultAddress de la red o SocketBindTight off: abiertos, se cambian
    new = re.sub(r"(?mi)^([ \t]*DefaultAddress[ \t]+)(?!127\.0\.0\.1[ \t]*\r?$)(\S.*?)([ \t]*\r?)$",
                 r"\g<1>127.0.0.1\3", text)
    new = re.sub(r"(?mi)^([ \t]*SocketBindTight[ \t]+)off\b", r"\g<1>on", new)
    if new != text:
        save(path, new, "FTP, solo desde este equipo (DefaultAddress)")
        text = new
    if not re.search(r"(?mi)^[ \t]*DefaultAddress\b", text):
        nl = "\r\n" if "\r\n" in text else "\n"
        add = "# Solo desde este Mac (lvm-instalador)" + nl + "DefaultAddress 127.0.0.1" + nl
        if not re.search(r"(?mi)^[ \t]*SocketBindTight\b", text):
            add += "SocketBindTight on" + nl
        m = re.search(r"(?mi)^[ \t]*Port\b[^\n]*\n", text)
        new = text[:m.end()] + add + text[m.end():] if m else add + text
        save(path, new, "FTP, solo desde este Mac (DefaultAddress)")

# El FTP arrancaba siempre con la version. Ahora solo si se ha activado (etc/lvm-startftp)
path = os.path.join(base, "xampp")
if own(path):
    text = read(path)
    if "lvm-startftp" not in text:
        new = re.sub(r"(?m)^(\s*start\) .*; start_apache); start_ftp ;;$",
                     r"""\1; if [ -f "$ROOT/etc/lvm-startftp" ]; then start_ftp; fi ;;""", text)
        new = re.sub(r"(?m)^(\s*)startftp\) start_ftp ;;$",
                     r"""\1startftp) touch "$ROOT/etc/lvm-startftp"; start_ftp ;;""", new)
        new = re.sub(r"(?m)^(\s*)stopftp\) stop_ftp ;;$",
                     r"""\1stopftp) rm -f "$ROOT/etc/lvm-startftp"; stop_ftp ;;""", new)
        if new != text:
            save(path, new, "El FTP solo arranca si se activa en Servicios")

# Certificado de fabrica de XAMPP (Apache Friends, de 2004, RSA de 1024 bits): su clave es la misma
# en todos los XAMPP y se puede descargar. Se cambia por uno propio de este equipo (localhost). La
# clave nueva solo se crea al aplicar (LVM_SECURE_APPLY): al comprobar basta con saber que falta
crt = os.path.join(base, "etc/ssl.crt/server.crt")
key = os.path.join(base, "etc/ssl.key/server.key")
def factory_cert(path):
    import base64, binascii
    pem = "".join(l.strip() for l in read(path).splitlines() if l.strip() and not l.startswith("-----"))
    try:
        return b"Apache Friends" in base64.b64decode(pem)
    except (binascii.Error, ValueError):
        return False
if own(crt) and own(key) and factory_cert(crt):
    import subprocess, tempfile
    if os.environ.get("LVM_SECURE_APPLY") == "1":
        d = tempfile.mkdtemp(dir=out)
        # Las extensiones van en un fichero de configuracion y no con -addext: la LibreSSL de macOS 12
        # (la que usa root, con el PATH del sistema) no tiene -addext
        with open(os.path.join(d, "cnf"), "w") as f:
            f.write("[req]\ndistinguished_name = dn\nx509_extensions = ext\nprompt = no\n[dn]\nCN = localhost\n"
                    "[ext]\nbasicConstraints = critical,CA:FALSE\n"
                    "subjectAltName = DNS:localhost,IP:127.0.0.1,IP:0:0:0:0:0:0:0:1\n")
        r = subprocess.run(["openssl", "req", "-x509", "-nodes", "-newkey", "rsa:2048", "-days", "3650",
                            "-config", os.path.join(d, "cnf"),
                            "-keyout", os.path.join(d, "key"), "-out", os.path.join(d, "crt")],
                           stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        if r.returncode == 0:
            # (el certificado primero: se escriben en este orden)
            save(crt, read(os.path.join(d, "crt")), "Apache, certificado SSL propio")
            save(key, read(os.path.join(d, "key")), "Apache, clave SSL propia (la de XAMPP es la misma en todos)")
    else:
        save(crt, "", "Apache, clave SSL propia (la de XAMPP es la misma en todos)")

# Pilas propias de la 1.27 y anteriores: MariaDB arrancaba como root (mariadbd-safe) y se paraba con
# kill como root, con var/mysql de tu usuario. Ahora con tu usuario (el de user= en my.cnf)
path = os.path.join(base, "xampp")
if own(path):
    text = read(path)
    if "pila propia creada por lvm-instalador" in text and "as_web" not in text:
        user = ""
        mycnf = os.path.join(base, "etc/my.cnf")
        if own(mycnf):
            m = re.search(r"(?m)^[ \t]*user[ \t]*=[ \t]*([A-Za-z_][A-Za-z0-9_.-]*)[ \t]*\r?$", read(mycnf))
            user = m.group(1) if m else ""
        start_old = "(cd \"$ROOT/mysql\" && nohup ./bin/mariadbd-safe"
        stop_old = "    kill \"$(cat \"$MYSQL_PID\")\""
        anchor = "FTP_PID=$ROOT/var/proftpd/proftpd.pid\n"
        if user and user != "root" and start_old in text and stop_old in text and anchor in text:
            helper = ("WEB_USER=" + user + "\nas_web() {\n"
                      "    if [ \"$(id -u)\" -eq 0 ] && [ -n \"$WEB_USER\" ] && [ \"$WEB_USER\" != root ]; then\n"
                      "        /usr/bin/sudo -u \"$WEB_USER\" \"$@\"\n    else\n        \"$@\"\n    fi\n}\n")
            new = text.replace(anchor, anchor + "# MariaDB con tu usuario, no como root (lvm-instalador)\n" + helper, 1)
            new = new.replace(start_old, "(cd \"$ROOT/mysql\" && as_web /usr/bin/nohup ./bin/mariadbd-safe", 1)
            new = new.replace(stop_old, "    as_web kill \"$(cat \"$MYSQL_PID\")\"", 1)
            save(path, new, "MariaDB arranca con tu usuario, no como root")
    # Hasta la 1.39.7, MariaDB, PHP-FPM, Apache y ProFTPD arrancaban con la terminal de la tarea como
    # entrada: seguian con ella abierta y la ventana se quedaba esperando el final (en el 98 %)
    # (las de la 1.27 y anteriores, despues del cambio de arriba: no dos cambios del mismo fichero a la vez)
    text = read(path)
    if "pila propia creada por lvm-instalador" in text and "as_web" in text:
        new = text
        for old, fixed in (
                ("--defaults-file=\"$ROOT/etc/my.cnf\" > /dev/null 2>&1 &)",
                 "--defaults-file=\"$ROOT/etc/my.cnf\" < /dev/null > /dev/null 2>&1 &)"),
                ("    \"$ROOT/bin/pvm-php-fpm\" start\n", "    \"$ROOT/bin/pvm-php-fpm\" start < /dev/null\n"),
                ("-k start >> \"$ROOT/logs/error_log\" 2>&1", "-k start < /dev/null >> \"$ROOT/logs/error_log\" 2>&1"),
                ("-c \"$ROOT/etc/proftpd.conf\" 2> /dev/null &&", "-c \"$ROOT/etc/proftpd.conf\" < /dev/null 2> /dev/null &&")):
            new = new.replace(old, fixed, 1)
        if new != text:
            save(path, new, "Los servicios arrancan sin quedarse con la terminal de la tarea")
# PHP: correo de pruebas (LVM_CORREO = binario de Mailpit|puerto|WordPress a Mailpit 1/0; vacio, apagado).
# mail() va a Mailpit (sendmail_path) y, si los plugins de SMTP de WordPress van a Mailpit, PHP carga
# antes de cada script etc/lvm-correo-wordpress.php (auto_prepend_file; su texto llega en
# LVM_CORREO_PHP). Las dos rutas solo si son de root, sin enlaces ni escritura para otros, hasta /
# (/Library/Nexum/mailpit y la version): nadie mas puede cambiar lo que ejecuta o carga PHP. En
# php/etc/conf.d/99-lvm-correo.ini de cada pila; apagado, ese fichero se queda sin directivas
def root_path_ok(path):
    import stat
    p = os.path.abspath(path)
    while not os.path.lexists(p):
        p = os.path.dirname(p)
    while True:
        st = os.lstat(p)
        if stat.S_ISLNK(st.st_mode) or st.st_uid != 0 or st.st_mode & 0o022:
            return False
        if p == "/":
            return True
        p = os.path.dirname(p)
mail_lines = []
confd = os.path.join(base, "php/etc/conf.d")
mail_stack = own(os.path.join(base, "etc/pvm-stack")) and os.path.isdir(confd) and not os.path.islink(confd)
m = re.fullmatch(r"(/[A-Za-z0-9._/-]+)\|([0-9]{1,5})\|([01])", os.environ.get("LVM_CORREO", ""))
if mail_stack and m and "/../" not in m.group(1) + "/":
    binp, port, wp = m.group(1), m.group(2), m.group(3) == "1"
    prep = os.path.join(base, "etc/lvm-correo-wordpress.php")
    php = os.environ.get("LVM_CORREO_PHP", "")
    # (solo las pruebas, sin root, se saltan la comprobacion; nunca al aplicar)
    test = os.environ.get("LVM_CORREO_PRUEBA") == "1" and os.environ.get("LVM_SECURE_APPLY") != "1"
    if test or root_path_ok(binp):
        mail_lines.append("sendmail_path = \"%s sendmail -S 127.0.0.1:%s\"" % (binp, port))
        if wp and php.startswith("<?php") and (not os.path.lexists(prep) or own(prep)) and (test or root_path_ok(prep)):
            want = php.replace("@PUERTO@", port).rstrip("\n") + "\n"
            if not os.path.lexists(prep) or read(prep) != want:
                save(prep, want, "PHP, plugins de SMTP de WordPress a Mailpit (lvm-correo-wordpress.php)")
            mail_lines.append("auto_prepend_file = \"%s\"" % prep)
if mail_stack:
    path = os.path.join(confd, "99-lvm-correo.ini")
    want = "; lvm-instalador: correo de pruebas (Mailpit). Se cambia en Configuracion o con lvm-instalador correo\n" \
        + ("".join(l + "\n" for l in mail_lines) if mail_lines else "; (apagado: el correo de PHP sale como sin el gestor)\n")
    if (mail_lines and not os.path.lexists(path)) or (own(path) and read(path) != want):
        save(path, want, "PHP, el correo de las webs va a Mailpit" if mail_lines else "PHP, correo de pruebas apagado")
# (las carpetas primero: si no se pudiera crear la de secure_file_priv, no se cambia el my.cnf)
for c in sorted(changes, key=lambda c: not c[0].endswith("/")):
    print("|".join(c))
'

# Antes de arrancar una version: si no se ha podido dejar solo para este Mac (secure_version
# devolvio 2), no se arranca, porque quedaria abierta a la red. secure_failed <codigo> <carpeta>
function secure_failed() {
    [ "$1" -eq 2 ] && [ "$DRY" -eq 0 ] || return 1
    echo "No se arranca $(basename "$2"): no se ha podido dejar solo para este Mac."
    echo "Prueba con: lvm-instalador asegurar --todas"
    return 0
}

# Lineas Listen de los vhosts compartidos que abren Apache a la red (sin 127.x, [::1] ni localhost).
# Apache las lee, pero SECURE_PY no cambia los vhosts (son de todas las versiones y de root): solo se
# pueden poner a mano (sudo -e), por ejemplo siguiendo una guia de vhosts por puerto
function vhosts_open_listen() {
    local real
    real=$(realpath_f "$VHOSTS_FILE" 2> /dev/null) && [ -f "$real" ] || return 0
    python3 -I - "$real" <<'EOF'
import re, sys
# Como Apache: lineas solo por \n, las acabadas en \ unidas a la siguiente y los campos separados
# por cualquier espacio ASCII (\v, \f, \r tambien). Un Include no se sigue: tambien se avisa
lines = open(sys.argv[1], encoding="utf-8", errors="replace", newline="\n").read().split("\n")
i = 0
while i < len(lines):
    n, line = i + 1, lines[i].rstrip("\r")
    while line.endswith("\\") and i + 1 < len(lines):
        i += 1
        line = line[:-1] + lines[i].rstrip("\r")
    i += 1
    w = re.split(r"[ \t\v\f\r]+", line.strip(" \t\v\f\r"), maxsplit=1)
    if w[0].lower() == "include" and len(w) > 1 and re.match(r"^\"?/Library/Nexum/XAMPP-compartido/docker-claves/[a-z0-9]([a-z0-9-]{0,38}[a-z0-9])?\.conf\"?$", w[1].strip(" \t\v\f\r")):
        # (la clave de un proyecto en Docker: un RequestHeader, de root)
        continue
    if w[0].lower() in ("include", "includeoptional"):
        print("Linea %d: %s (no se puede comprobar lo que trae)" % (n, re.sub(r"[\x00-\x1f\x7f]", " ", line.strip())[:120]))
        continue
    if w[0].lower() != "listen" or len(w) < 2:
        continue
    m = re.match(r"^[\"\x27]?(?:(\[[0-9A-Fa-f:.]*\]|[^\s:\[\]\"\x27]+):)?(\d+)", w[1])
    if m and not (m.group(1) and re.match(r"^(127\.\d+\.\d+\.\d+|\[::1\]|localhost)$", m.group(1), re.I)):
        print("Linea %d: %s" % (n, re.sub(r"[\x00-\x1f\x7f]", " ", line.strip())[:120]))
EOF
}

# Deja una version solo para este Mac (lo que falte). Devuelve 0 si ha cambiado algo (si esta en
# marcha, hay que reiniciarla para aplicarlo), 1 si no hacia falta y 2 si no se ha podido: entonces
# no se arranca.
function secure_version() {
    local dir=$1 tmp list rel src what changed=1 name base
    base=$dir/xamppfiles
    [ -n "$dir" ] && [ -d "$base" ] && [ ! -L "$dir" ] && [ -f "$base/etc/httpd.conf" ] || return 1
    # Las pruebas sin sudo (LVM_PRUEBA) ya se instalan asi
    [ -n "$TEST_DIR" ] && return 1
    name=$(basename "$dir")
    # Una version que no es de root no se hace de root: en /Applications puede escribir cualquier
    # administrador, y un programa con tu usuario podria haber puesto ahi una version falsa (con su
    # script xampp) para que, al protegerla, root la diera por buena y la arrancara. Se reinstala
    if [ "$(stat -f %u "$dir")" != 0 ] || [ "$(stat -f %u "$base")" != 0 ]; then
        echo "$name no es del administrador: no se protege ni se arranca como root. Si la instalaste"
        echo "tu, vuelve a instalarla desde la terminal: lvm-instalador actualizar $(version_name "$dir")"
        return 2
    fi
    # Un Listen abierto en los vhosts compartidos dejaria Apache abierto a la red aunque la version
    # este cerrada: no se arranca hasta quitarlo (se avisa una vez aunque se miren varias versiones)
    local open
    open=$(vhosts_open_listen)
    if [ -n "$open" ]; then
        if [ -z "$LISTEN_WARNED" ]; then
            echo "Los vhosts ($VHOSTS_FILE) abren Apache a la red (o traen otros ficheros):"
            sed 's/^/  /' <<< "$open"
            echo "Quita esas lineas con Editar vhosts (menú de la ventana) y vuelve a arrancarla."
            LISTEN_WARNED=1
        fi
        return 2
    fi
    # Los ficheros nuevos se preparan como root en una carpeta de root: en una tuya, cualquier
    # programa tuyo podria cambiarlos (un ErrorLog "|orden" en httpd.conf) antes de que root los
    # copie a la version. Primero se mira sin sudo si hay algo que cambiar (casi siempre no)
    local rooted=0 mail
    # (el correo de pruebas: binario|puerto|WordPress, o nada si esta apagado)
    mail=$(mail_secure_spec)
    tmp=$(mktemp -d "${TMPDIR:-/tmp}/lvm-seguridad.XXXXXX") || return 2
    # macOS siempre tiene ::1 (lo0)
    list=$(LVM_CORREO=$mail LVM_CORREO_PHP=$MAIL_WP_PHP LVM_CORREO_PRUEBA= /usr/bin/python3 -I -c "$SECURE_PY" \
        "$base" "$tmp" 1 "$UNKNOWN_HOST_CONF" "$(unknown_host_vhost)" \
        "$UNKNOWN_HOST_SSL" "$PHP_SECURITY_INI" "$PHP_SECURITY_INI_85") || { rm -rf "$tmp"; return 2; }
    rm -rf "$tmp"
    local sudo=$SUDO
    if [ -n "$list" ]; then
        if [ "$DRY" -eq 1 ]; then
            sudo=""
            tmp=$(mktemp -d "${TMPDIR:-/tmp}/lvm-seguridad.XXXXXX") || return 2
        else
            tmp=$($SUDO mktemp -d /tmp/lvm-seguridad.XXXXXX) && $SUDO chmod 700 "$tmp" || return 2
        fi
        list=$($sudo env LVM_SECURE_APPLY=1 LVM_CORREO="$mail" LVM_CORREO_PHP="$MAIL_WP_PHP" \
            /usr/bin/python3 -I -c "$SECURE_PY" "$base" \
            "$tmp" 1 "$UNKNOWN_HOST_CONF" "$(unknown_host_vhost)" "$UNKNOWN_HOST_SSL" \
            "$PHP_SECURITY_INI" "$PHP_SECURITY_INI_85") || { $sudo rm -rf "$tmp"; return 2; }
        rooted=1
    fi
    while IFS='|' read -r rel src what; do
        [ -n "$rel" ] || continue
        [ $changed -eq 1 ] && echo "Seguridad de $name: solo se podra entrar desde este Mac"
        changed=0
        echo "  $what ($rel)"
        [ "$DRY" -eq 1 ] && continue
        # Una carpeta (la vacia de secure_file_priv): de root y sin nada dentro
        if [[ "$rel" == */ ]]; then
            if [ -L "$base/${rel%/}" ] || ! $SUDO install -d -o 0 -g 0 -m 755 "$base/${rel%/}"; then
                echo "  No se ha podido crear $base/${rel%/}"
                $SUDO rm -rf "$tmp"
                return 2
            fi
            continue
        fi
        # (los ficheros nuevos, como lvm-dominio-desconocido.conf, no tienen copia)
        [ -f "$base/$rel" ] && mkdir -p -m 700 "$HOME/lvm-copias" \
            && cp "$base/$rel" "$HOME/lvm-copias/$name-$(basename "$rel")-$(date +%Y%m%d-%H%M%S)" 2> /dev/null
        $SUDO sh -c 'cat "$1" > "$2"' sh "$src" "$base/$rel" || { $SUDO rm -rf "$tmp"; return 2; }
        [[ "$rel" == *.key ]] && $SUDO chmod 600 "$base/$rel"
    done <<< "$list"
    [ $rooted -eq 1 ] && $sudo rm -rf "$tmp"

    # La carpeta de la version y su script xampp, sin escritura para el grupo (admin, que es tu
    # usuario): xampp_ctl no arranca una version que no lo cumpla. Solo se quita la escritura: lo
    # que no es de root no se hace de root (ver arriba)
    local f
    for f in "$dir" "$base" "$base/xampp" "$base/bin/pvm-php-fpm"; do
        [ -e "$f" ] && [ ! -L "$f" ] || continue
        if [ "$(stat -f %u "$f")" != 0 ]; then
            echo "  $f no es del administrador: vuelve a instalarla (lvm-instalador actualizar $(version_name "$dir"))"
            return 2
        fi
        if [ $(( 8#$(stat -f %Lp "$f") & 8#022 )) -ne 0 ]; then
            [ $changed -eq 1 ] && echo "Seguridad de $name:"
            changed=0
            echo "  $f: sin escritura para el grupo ni los demas"
            run $SUDO chmod go-w "$f" || return 2
        fi
    done

    # Lo de dentro que root ejecuta o carga: si no es de root o el grupo admin (tu usuario) lo puede
    # cambiar, ya no se sabe si lo han cambiado (un httpd.conf o una biblioteca): no se da por buena
    # quitandole la escritura, se reinstala (install_stack lo deja todo de root y sin escritura)
    # mariadb-install-db le da al usuario del servidor (tu usuario) la carpeta del ayudante de PAM y
    # deja dentro un programa setuid de root. Aqui no se usa PAM: se quita (como root; la carpeta de
    # encima es de root) en vez de dar la version por insegura y no arrancarla
    local pam=$base/mysql/lib/plugin/auth_pam_tool_dir
    if [ -e "$pam" ] || [ -L "$pam" ]; then
        [ $changed -eq 1 ] && echo "Seguridad de $name:"
        changed=0
        echo "  Se quita $pam (el ayudante de PAM de MariaDB, que aqui no se usa)"
        run $SUDO rm -rf "$pam" || return 2
    fi

    local unsafe
    unsafe=$(version_unsafe_files "$dir" | head -1)
    if [ -n "$unsafe" ]; then
        echo "  $unsafe no es del administrador o lo puede cambiar el grupo admin: vuelve a instalar la"
        echo "  version (lvm-instalador actualizar $(version_name "$dir")). Hasta entonces no se arranca como root."
        return 2
    fi

    # Una sola vez por version: el FTP deja de arrancar con ella (se activa en Servicios)
    if [ ! -f "$dir/$SECURE_MARK" ]; then
        if [ "$(active_dir)" == "$(realpath_f "$dir")" ] && service_running ftp; then
            [ $changed -eq 1 ] && echo "Seguridad de $name:"
            echo "  El FTP ya no arranca con la version: activalo en los servicios de la ventana (la flecha del visor de arriba) cuando lo necesites"
            changed=0
            run xampp_ctl stopftp
        fi
        run $SUDO rm -f "$base/etc/lvm-startftp"
        if [ "$DRY" -eq 0 ]; then
            echo "1" | $SUDO tee "$dir/$SECURE_MARK" > /dev/null
        fi
    fi
    return $changed
}

# Todas las versiones, solo para este Mac. Devuelve como secure_version: 0 si ha cambiado algo, 1
# si no hacia falta y 2 si alguna no se ha podido.
function secure_all() {
    local d rc=1 r
    for d in $(version_dirs); do
        [ -f "$d/xamppfiles/etc/pvm-stack" ] || continue
        secure_version "$d"
        r=$?
        [ $r -eq 2 ] && { echo "No se ha podido dejar $(basename "$d") solo para este Mac"; rc=2; }
        [ $r -eq 0 ] && [ $rc -eq 1 ] && rc=0
    done
    return $rc
}

# Versiones a las que les falta algo de lo que pondria secure_version, separadas por espacios
function unsecured_versions() {
    local d tmp list out="" mail
    [ -n "$TEST_DIR" ] && return 0
    mail=$(mail_secure_spec)
    # (las de /Applications de antes de la 1.39.3: protegerlas es pasarlas a /Library/Nexum)
    for d in $(legacy_dirs); do
        out+="${out:+ }${d##*/XAMPP-}"
    done
    tmp=$(mktemp -d "${TMPDIR:-/tmp}/lvm-seguridad.XXXXXX") || return 0
    for d in $(version_dirs); do
        [ -f "$d/xamppfiles/etc/pvm-stack" ] || continue
        list=$(LVM_CORREO=$mail LVM_CORREO_PHP=$MAIL_WP_PHP LVM_CORREO_PRUEBA= python3 -I -c "$SECURE_PY" \
            "$d/xamppfiles" "$tmp" 1 "$UNKNOWN_HOST_CONF" \
            "$(unknown_host_vhost)" "$UNKNOWN_HOST_SSL" "$PHP_SECURITY_INI" "$PHP_SECURITY_INI_85" 2> /dev/null)
        [ -n "$list" ] || ! trusted_version_dir "$d" && out+="${out:+ }$(version_name "$d")"
        rm -f "$tmp"/*
    done
    rm -rf "$tmp"
    echo "$out"
}

# ¿Se puede arrancar como root esta carpeta? Solo una carpeta XAMPP-<version> de /Library/Nexum (de
# root: en /Applications puede escribir cualquier administrador, tu usuario, y un programa tuyo
# podria cambiar una version o XAMPP-compartido por algo suyo entre la comprobacion y el arranque),
# de root con su script xampp de root y los vhosts compartidos de root, todo sin enlaces ni escritura
# para el grupo o los demas, y cada carpeta de encima igual (boot_root_owned). Las de /Applications
# de antes de la 1.39.3, no: primero lvm-instalador migrar
function trusted_version_dir() {
    local d=$1 f vhosts
    [[ "$d" =~ ^/Library/Nexum/XAMPP-[0-9]+\.[0-9]+(\.[0-9]+)?$ ]] || return 1
    boot_root_owned "$d/xamppfiles/xampp" || return 1
    vhosts=$(realpath_f "$VHOSTS_FILE" 2> /dev/null)
    # (si existen y no se sabe adonde llevan, no vale: no se comprobarian)
    [ -e "$VHOSTS_FILE" ] && [ -z "$vhosts" ] && return 1
    # (los vhosts, en XAMPP-compartido de /Library/Nexum)
    [ -n "$vhosts" ] && { [ "$vhosts" == "$COMMON/httpd-vhosts.conf" ] && boot_root_owned "$vhosts" || return 1; }
    for f in "$d" "$d/xamppfiles" "$d/xamppfiles/xampp" "$COMMON" ${vhosts:+"$vhosts"}; do
        [ -e "$f" ] || { [ "$f" == "$COMMON" ] && continue; return 1; }
        [ ! -L "$f" ] || return 1
        [ "$(stat -f %u "$f")" == 0 ] || return 1
        [ $(( 8#$(stat -f %Lp "$f") & 8#022 )) -eq 0 ] || return 1
    done
    # Y, por dentro, lo que root ejecuta o carga al arrancar (programas, bibliotecas, configuracion):
    # de root y sin escritura para el grupo ni los demas, como lo deja install_stack
    [ -z "$(version_unsafe_files "$d" | head -1)" ]
}

# Lo de dentro de una version que root ejecuta o carga y no es de root o pueden cambiar el grupo o
# los demas (las bases, tmp y los registros quedan fuera)
function version_unsafe_files() {
    local deep=() sub
    for sub in apache2 php proftpd bin sbin lib libexec mysql etc; do
        [ -e "$1/xamppfiles/$sub" ] && deep+=("$1/xamppfiles/$sub")
    done
    [ ${#deep[@]} -gt 0 ] || return 0
    find "${deep[@]}" ! -type l \( ! -user root -o -perm -020 -o -perm -002 \) -print 2> /dev/null
}

# ===========================================================================
# Paso a /Library/Nexum (1.39.3)
# ===========================================================================
# Hasta la 1.39.2 las versiones y XAMPP-compartido estaban en /Applications, donde puede escribir el
# grupo admin (tu usuario): un programa tuyo podia cambiar una carpeta por otra entre la comprobacion
# y el uso como root. "lvm-instalador migrar" las pasa a /Library/Nexum, de root.

# Pasa, como root, las versiones de antes de la 1.39.3 de <antes> (/Applications) a <ahora>
# (/Library/Nexum): mueve XAMPP-X.Y[.Z] (solo las de root, con pvm-stack) y XAMPP-compartido, deja en
# <antes> un enlace a cada una (para lo tuyo que use las rutas viejas: root no pasa por ellos), cambia
# las rutas de su configuracion, sus scripts y sus enlaces, y las de las librerias de sus programas
# (install_name_tool y la firma local otra vez), repunta <enlace> (/Applications/XAMPP) y fija el
# php.ini, conf.d y extension_dir de PHP-FPM (las rutas que trae compiladas son las de antes). Lo que
# cambia queda en un diario, con el original enlazado, para deshacerlo. Las BBDD (var), los registros
# y los proyectos de htdocs no se tocan.
# Uso: migrar|deshacer|terminar <antes> <ahora> <diario> [<enlace> <plantilla de pvm-php-fpm>]
# Escribe M|version (o XAMPP-compartido) movida, S|carpeta|por que no, E|error, I|aviso
MIGRATE_PY='
import json, os, re, shutil, stat, subprocess, sys
mode, old, new, jdir = sys.argv[1:5]
link = sys.argv[5] if len(sys.argv) > 5 else ""
tmpl = sys.argv[6] if len(sys.argv) > 6 else ""
J = os.path.join(jdir, "diario.json")
VER = re.compile(r"^XAMPP-[0-9]+\.[0-9]+(\.[0-9]+)?$")
MACHO = (b"\xcf\xfa\xed\xfe", b"\xca\xfe\xba\xbe")
# Dentro de xamppfiles no se tocan los datos, los registros ni lo temporal
SKIP = ("var", "logs", "tmp", "phpmyadmin/tmp")
TOOLS = {"otool": "/usr/bin/otool", "install_name_tool": "/usr/bin/install_name_tool", "codesign": "/usr/bin/codesign"}
ROOT = 0
# (en las pruebas, sin root: otras herramientas, y tu usuario hace de root)
if os.getuid() != 0 and os.environ.get("LVM_PRUEBA_HERRAMIENTAS"):
    TOOLS = {k: os.path.join(os.environ["LVM_PRUEBA_HERRAMIENTAS"], k) for k in TOOLS}
    ROOT = os.getuid()
state = {}

def say(*f):
    print("|".join(str(x).replace("|", "/").replace("\n", " ") for x in f))
    sys.stdout.flush()

def save():
    tmp = J + ".nuevo"
    with open(tmp, "w") as f:
        json.dump(state, f)
    os.replace(tmp, J)

# Deshace lo del diario, en orden inverso (cada paso aunque falle otro: lo que no se pueda, se dice)
def undo(st):
    def each(items, fn):
        for item in reversed(items):
            try:
                fn(*item) if isinstance(item, list) else fn(item)
            except OSError as e:
                say("E", "no se ha podido deshacer %s: %s" % (item, e))
    def back_file(path, b):
        if os.path.lexists(b):
            os.replace(b, path)
    def drop(path):
        if os.path.lexists(path) and not os.path.isdir(path):
            os.unlink(path)
    def attrs(path, uid, gid, mode_):
        if os.path.lexists(path):
            os.lchown(path, uid, gid)
            os.chmod(path, mode_)
    def back_link(path, target):
        if os.path.islink(path):
            tmp = path + ".lvm-migracion"
            if os.path.lexists(tmp):
                os.unlink(tmp)
            os.symlink(target, tmp)
            os.rename(tmp, path)
    def unlink(path):
        if os.path.islink(path):
            os.unlink(path)
    def back_move(src, dst):
        if os.path.lexists(dst) and not os.path.lexists(src):
            os.rename(dst, src)
    each(st.get("files", []), back_file)
    each(st.get("created", []), drop)
    each(st.get("attrs", []), attrs)
    each(st.get("relinks", []), back_link)
    each(st.get("links", []), unlink)
    each(st.get("moves", []), back_move)

def backup(path):
    b = os.path.join(jdir, "b", str(len(state["files"])))
    os.link(path, b)
    state["files"].append([path, b])
    save()

def put(path, st, data):
    tmp = path + ".lvm-migracion"
    if os.path.lexists(tmp):
        os.unlink(tmp)
    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
    with os.fdopen(fd, "wb") as f:
        f.write(data)
    os.chown(tmp, st.st_uid, st.st_gid)
    os.chmod(tmp, stat.S_IMODE(st.st_mode))
    backup(path)
    os.rename(tmp, path)

def swap(subs, text):
    for rx, rep in subs:
        text = rx.sub(lambda m: rep, text)
    return text

def run(*args):
    r = subprocess.run(list(args), stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if r.returncode != 0:
        raise RuntimeError("%s: %s" % (os.path.basename(args[0]), r.stderr.decode("utf-8", "replace").strip()[:300]))
    return r.stdout.decode("utf-8", "replace")

LOADS = {"LC_LOAD_DYLIB", "LC_LOAD_WEAK_DYLIB", "LC_REEXPORT_DYLIB", "LC_LAZY_LOAD_DYLIB", "LC_LOAD_UPWARD_DYLIB"}
def load_commands(path):
    cmd, found = "", []
    for line in run(TOOLS["otool"], "-l", path).splitlines():
        w = line.split()
        if len(w) >= 2 and w[0] == "cmd":
            cmd = w[1]
        elif len(w) >= 2 and w[0] == "name" and (cmd in LOADS or cmd == "LC_ID_DYLIB"):
            found.append(("id" if cmd == "LC_ID_DYLIB" else "dep", line.strip()[5:].rsplit(" (offset", 1)[0]))
        elif len(w) >= 2 and w[0] == "path" and cmd == "LC_RPATH":
            found.append(("rpath", line.strip()[5:].rsplit(" (offset", 1)[0]))
    return found

# Un programa o una libreria: las rutas de sus librerias (install_name_tool) y la firma local de
# nuevo. Las cadenas que lleva compiladas no se cambian (lvm-instalador actualizar las rehace)
def macho(path, st, subs):
    args, seen = [], set()
    for kind, value in load_commands(path):
        nv = swap(subs, value.encode()).decode()
        if nv == value or (kind, value) in seen:
            continue
        seen.add((kind, value))
        if kind == "id":
            args += ["-id", nv]
        elif kind == "rpath":
            args += ["-rpath", value, nv]
        else:
            args += ["-change", value, nv]
    if not args:
        return
    tmp = path + ".lvm-migracion"
    if os.path.lexists(tmp):
        os.unlink(tmp)
    shutil.copyfile(path, tmp)
    os.chown(tmp, st.st_uid, st.st_gid)
    os.chmod(tmp, stat.S_IMODE(st.st_mode))
    try:
        run(TOOLS["install_name_tool"], *(args + [tmp]))
        run(TOOLS["codesign"], "--force", "--sign", "-", "--identifier", os.path.basename(path), tmp)
    except Exception:
        os.unlink(tmp)
        raise
    backup(path)
    os.rename(tmp, path)

# (sin leerlo entero: los programas pueden ser grandes)
def contains(path, needle):
    tail = b""
    with open(path, "rb") as f:
        while True:
            chunk = f.read(1 << 20)
            if not chunk:
                return False
            if needle in tail + chunk:
                return True
            tail = chunk[-len(needle):]

def rewrite(path, subs, extra=None):
    st = os.lstat(path)
    if not stat.S_ISREG(st.st_mode) or st.st_size < 4:
        return
    with open(path, "rb") as f:
        head = f.read(4)
    if not contains(path, (old + "/").encode()):
        return
    if head in MACHO:
        macho(path, st, subs)
        return
    # Otros binarios (.a, .mo...), no: cambiar la longitud de una ruta los romperia. Y nada enorme
    if st.st_size > 64 * 1024 * 1024:
        return
    with open(path, "rb") as f:
        data = f.read()
    if b"\0" in data:
        return
    text = swap(subs, data)
    if extra:
        text = text.replace(extra[0], extra[1])
    if text != data:
        put(path, st, text)

def relink(path, subs):
    target = os.readlink(path)
    nt = swap(subs, target.encode()).decode()
    if nt == target:
        return
    st = os.lstat(path)
    tmp = path + ".lvm-migracion"
    if os.path.lexists(tmp):
        os.unlink(tmp)
    os.symlink(nt, tmp)
    os.lchown(tmp, st.st_uid, st.st_gid)
    state["relinks"].append([path, target])
    save()
    os.rename(tmp, path)

def skipped(top, path):
    rel = os.path.relpath(path, top)
    return any(rel == s or rel.startswith(s + "/") for s in SKIP)

def stack(dst, subs):
    top = os.path.join(dst, "xamppfiles")
    ftp = os.path.join(top, "etc/proftpd.conf")
    for d, dirs, files in os.walk(dst):
        for name in list(dirs):
            p = os.path.join(d, name)
            if os.path.islink(p):
                relink(p, subs)
                dirs.remove(name)
            elif skipped(top, p):
                dirs.remove(name)
        for name in files:
            p = os.path.join(d, name)
            if os.path.islink(p):
                relink(p, subs)
            elif p == ftp:
                # El FTP entra (chroot, como root) en su htdocs por su ruta, no por /Applications/XAMPP
                rewrite(p, subs, ((old + "/XAMPP/xamppfiles").encode(), top.encode()))
            elif not p.endswith(".lvm-migracion"):
                rewrite(p, subs)
    # PHP-FPM con el php.ini y conf.d de su carpeta nueva (las rutas compiladas son las de antes)
    fpm = os.path.join(top, "bin/pvm-php-fpm")
    php = ""
    try:
        php = open(os.path.join(top, "etc/pvm-php")).read().strip()
    except OSError:
        pass
    if tmpl and re.match(r"^[0-9]+\.[0-9]+\.[0-9]+$", php) and os.path.isfile(fpm) and not os.path.islink(fpm):
        want = tmpl.replace("@ROOT@", top).replace("@VERSION@", php).encode()
        cur = open(fpm, "rb").read()
        if cur != want and b"--fpm-config" in cur:
            put(fpm, os.lstat(fpm), want)
    # extension_dir: el que trae compilado PHP es el de antes
    ini = os.path.join(top, "php/etc/php.ini")
    conf_d = os.path.join(top, "php/etc/conf.d")
    exts = [e for e in sorted(os.listdir(os.path.join(top, "php/lib/php/extensions")))
            if os.path.isdir(os.path.join(top, "php/lib/php/extensions", e))] \
        if os.path.isdir(os.path.join(top, "php/lib/php/extensions")) else []
    has = os.path.isfile(ini) and re.search(r"(?m)^[ \t]*extension_dir[ \t]*=", open(ini, encoding="utf-8", errors="replace").read())
    pin = os.path.join(conf_d, "00-lvm-rutas.ini")
    if not has and len(exts) == 1 and os.path.isdir(conf_d) and not os.path.islink(conf_d) and not os.path.lexists(pin):
        cst = os.lstat(conf_d)
        fd = os.open(pin, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o644)
        state["created"].append(pin)
        save()
        with os.fdopen(fd, "w") as f:
            f.write("; lvm-instalador (1.39.3): las extensiones, por su carpeta de %s (la ruta que trae\n"
                    "; compilada PHP es la de %s, y root no pasa por alli)\nextension_dir = \"%s\"\n"
                    % (new, old, os.path.join(top, "php/lib/php/extensions", exts[0])))
        os.chown(pin, cst.st_uid, cst.st_gid)

def migrate():
    global state
    if os.path.exists(J):
        st = json.load(open(J))
        if not st.get("done"):
            say("I", "Se deshace lo que quedo a medias la otra vez")
            undo(st)
        shutil.rmtree(jdir)
    elif os.path.lexists(jdir):
        shutil.rmtree(jdir)
    nst = os.lstat(new)
    if not stat.S_ISDIR(nst.st_mode) or nst.st_uid != ROOT or nst.st_mode & 0o022:
        say("E", "%s no es una carpeta de root" % new)
        sys.exit(1)
    moves = []
    for name in sorted(os.listdir(old)):
        src, dst = os.path.join(old, name), os.path.join(new, name)
        if not (VER.match(name) or name == "XAMPP-compartido") or os.path.islink(src) or not os.path.isdir(src):
            continue
        if name != "XAMPP-compartido":
            if not os.path.isfile(os.path.join(src, "xamppfiles/etc/pvm-stack")):
                say("S", src, "no es una version del gestor")
                continue
            if os.lstat(src).st_uid != ROOT or os.lstat(os.path.join(src, "xamppfiles")).st_uid != ROOT:
                say("S", src, "no es de root: no se pasa (vuelve a instalarla con lvm-instalador actualizar)")
                continue
        if os.path.lexists(dst):
            say("E", "ya existe %s: no se mueve nada" % dst)
            sys.exit(1)
        moves.append((src, dst))
    if not moves:
        return
    os.mkdir(jdir, 0o700)
    os.mkdir(os.path.join(jdir, "b"), 0o700)
    state = {"moves": [], "links": [], "files": [], "created": [], "attrs": [], "relinks": [], "done": False}
    save()
    try:
        for src, dst in moves:
            os.rename(src, dst)
            state["moves"].append([src, dst])
            save()
            os.symlink(dst, src)
            state["links"].append(src)
            save()
        subs = [(re.compile(re.escape((old + "/" + os.path.basename(d)).encode()) + rb"(?![A-Za-z0-9._-])"),
                 (new + "/" + os.path.basename(d)).encode()) for s, d in moves]
        for src, dst in moves:
            if os.path.basename(dst) == "XAMPP-compartido":
                # Solo su configuracion (los proyectos de htdocs no se tocan) y la carpeta, de root
                for f in [os.path.join(dst, "httpd-vhosts.conf")] + [
                        os.path.join(dst, "docker-claves", n) for n in
                        (sorted(os.listdir(os.path.join(dst, "docker-claves")))
                         if os.path.isdir(os.path.join(dst, "docker-claves")) and not os.path.islink(os.path.join(dst, "docker-claves")) else [])
                        if n.endswith(".conf")]:
                    if os.path.isfile(f) and not os.path.islink(f):
                        rewrite(f, subs)
                st = os.lstat(dst)
                if st.st_uid != ROOT or stat.S_IMODE(st.st_mode) != 0o755 or (ROOT == 0 and st.st_gid != 0):
                    state["attrs"].append([dst, st.st_uid, st.st_gid, stat.S_IMODE(st.st_mode)])
                    save()
                    os.lchown(dst, ROOT, 0 if ROOT == 0 else st.st_gid)
                    os.chmod(dst, 0o755)
                say("M", "XAMPP-compartido")
                continue
            stack(dst, subs)
            say("M", os.path.basename(dst)[len("XAMPP-"):])
        # El enlace a la version activa, a su carpeta nueva
        if link and os.path.islink(link):
            target = os.readlink(link)
            for src, dst in moves:
                if target.rstrip("/") == src:
                    tmp = link + ".lvm-migracion"
                    if os.path.lexists(tmp):
                        os.unlink(tmp)
                    os.symlink(dst, tmp)
                    state["relinks"].append([link, target])
                    save()
                    os.rename(tmp, link)
    except Exception as e:
        say("E", "%s: %s" % (type(e).__name__, e))
        undo(state)
        shutil.rmtree(jdir, ignore_errors=True)
        say("I", "Se ha dejado todo como estaba")
        sys.exit(1)

if mode == "migrar":
    migrate()
elif mode == "deshacer":
    if os.path.exists(J):
        undo(json.load(open(J)))
        shutil.rmtree(jdir)
        say("I", "Se ha dejado todo como estaba")
elif mode == "terminar":
    if os.path.exists(J):
        state = json.load(open(J))
        state["done"] = True
        save()
        shutil.rmtree(jdir)
else:
    sys.exit(2)
'

# Librerias que cargan los programas de una version (como root, en su carpeta de root): solo de ella
# misma o del sistema. Una de /opt/homebrew o de otra carpeta tuya la cargaria Apache como root. Los
# LC_RPATH, si algo se carga con @rpath. Uso: <carpeta XAMPP-X>. Escribe lo que no vale
MACHO_AUDIT_PY='
import os, stat, subprocess, sys
top = os.path.realpath(sys.argv[1])
OTOOL = "/usr/bin/otool"
if os.getuid() != 0 and os.environ.get("LVM_PRUEBA_HERRAMIENTAS"):
    OTOOL = os.path.join(os.environ["LVM_PRUEBA_HERRAMIENTAS"], "otool")
MACHO = (b"\xcf\xfa\xed\xfe", b"\xca\xfe\xba\xbe")
SYSTEM = ("/usr/lib/", "/System/Library/")
LOADS = {"LC_LOAD_DYLIB", "LC_LOAD_WEAK_DYLIB", "LC_REEXPORT_DYLIB", "LC_LAZY_LOAD_DYLIB", "LC_LOAD_UPWARD_DYLIB"}
bad = []
def inside(p):
    p = os.path.realpath(p)
    return p == top or p.startswith(top + "/")
def ok_path(p):
    return p.startswith(SYSTEM) and ".." not in p or inside(p)
def commands(path):
    r = subprocess.run([OTOOL, "-l", path], stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
    if r.returncode != 0:
        return None
    cmd, found = "", []
    for line in r.stdout.decode("utf-8", "replace").splitlines():
        w = line.split()
        if len(w) >= 2 and w[0] == "cmd":
            cmd = w[1]
        elif len(w) >= 2 and w[0] == "name" and cmd in LOADS:
            found.append(("dep", line.strip()[5:].rsplit(" (offset", 1)[0]))
        elif len(w) >= 2 and w[0] == "path" and cmd == "LC_RPATH":
            found.append(("rpath", line.strip()[5:].rsplit(" (offset", 1)[0]))
    return found
def resolve(value, base):
    for k in ("@loader_path", "@executable_path"):
        if value == k or value.startswith(k + "/"):
            return base + value[len(k):]
    return value
uses_rpath, rpaths = False, []
for d, dirs, files in os.walk(os.path.join(top, "xamppfiles")):
    rel = os.path.relpath(d, os.path.join(top, "xamppfiles"))
    if rel == "var" or rel.startswith("var/"):
        dirs[:] = []
        continue
    for name in files:
        p = os.path.join(d, name)
        try:
            st = os.lstat(p)
            if not stat.S_ISREG(st.st_mode) or st.st_size < 4:
                continue
            with open(p, "rb") as f:
                if f.read(4) not in MACHO:
                    continue
        except OSError:
            continue
        found = commands(p)
        if found is None:
            bad.append("%s (no se puede leer)" % os.path.relpath(p, top))
            continue
        for kind, value in found:
            if kind == "rpath":
                rpaths.append((p, value, resolve(value, d)))
            elif value.startswith("@rpath/"):
                uses_rpath = True
            elif not ok_path(resolve(value, d)):
                bad.append("%s -> %s" % (os.path.relpath(p, top), value))
# Las rutas de busqueda (LC_RPATH) solo cuentan si algo se carga con @rpath: entonces, dentro de la version
if uses_rpath:
    for p, value, real in rpaths:
        if not ok_path(real):
            bad.append("%s -> LC_RPATH %s" % (os.path.relpath(p, top), value))
for b in bad[:50]:
    print(b)
sys.exit(1 if bad else 0)
'

# Versiones de antes de la 1.39.3 que siguen en /Applications (carpetas, no enlaces, con pvm-stack) y
# XAMPP-compartido si sigue alli: lo que pasa a /Library/Nexum con lvm-instalador migrar
function legacy_dirs() {
    local d name
    [ -n "$TEST_DIR" ] && return 0
    for d in "$LEGACY_DIR"/XAMPP-*; do
        name=${d##*/}
        [ -d "$d" ] && [ ! -L "$d" ] || continue
        if [[ "$name" =~ ^XAMPP-[0-9]+\.[0-9]+(\.[0-9]+)?$ ]] && [ -f "$d/xamppfiles/etc/pvm-stack" ]; then
            echo "$d"
        elif [ "$name" == XAMPP-compartido ]; then
            echo "$d"
        fi
    done
}

# Lo que se comprueba de una version recien movida: que sus programas solo cargan librerias suyas o
# del sistema (como root), que arrancan (con tu usuario: librerias, rutas y firmas) y que su
# configuracion ya no lleva a /Applications. Escribe los problemas
function stack_check() {
    local dir=$1 top=$1/xamppfiles name out p
    name=$(basename "$1")
    if ! out=$($SUDO /usr/bin/python3 -I -c "$MACHO_AUDIT_PY" "$dir" 2>&1); then
        echo "  $name carga librerias de fuera de su carpeta:"
        head -5 <<< "$out" | sed 's/^/    /'
    fi
    for p in "apache2/bin/httpd -v" "php/bin/php -n -v" "php/sbin/php-fpm -n -v" "mysql/bin/mariadbd --no-defaults --version" \
            "proftpd/sbin/proftpd -v"; do
        [ -x "$top/${p%% *}" ] || continue
        "$top/${p%% *}" ${p#* } > /dev/null 2>&1 < /dev/null || echo "  $name: ${p%% *} no arranca desde $BASE_DIR"
    done
    out=$(grep -rlsE "$LEGACY_DIR/XAMPP-(compartido|[0-9])" "$top/etc" "$top/xampp" "$top/bin/pvm-php-fpm" \
        "$top/php/etc" "$top/apache2/conf" 2> /dev/null | head -3)
    [ -n "$out" ] && echo "  $name: estos ficheros siguen llevando a $LEGACY_DIR: $(tr '\n' ' ' <<< "$out")"
    return 0
}

# compose.yaml de los proyectos en Docker: su carpeta de htdocs, la de /Library/Nexum
function docker_refresh_compose() {
    local f
    for f in "$DOCKER_DIR"/*/compose.yaml; do
        [ -f "$f" ] && [ ! -L "$f" ] && [ -O "$f" ] && grep -qF "$LEGACY_DIR/XAMPP-compartido/" "$f" || continue
        python3 -I - "$f" "$LEGACY_DIR/XAMPP-compartido/" "$COMMON/" <<'EOF' || continue
import os, sys
path, old, new = sys.argv[1:4]
text = open(path, encoding="utf-8").read()
tmp = path + ".nuevo"
with open(tmp, "w", encoding="utf-8") as f:
    f.write(text.replace(old, new))
os.chmod(tmp, os.stat(path).st_mode & 0o777)
os.replace(tmp, path)
EOF
        echo "  Docker: $(basename "$(dirname "$f")") usa ya $HTDOCS_DIR (se nota al arrancarlo otra vez)"
    done
}

# ¿Hay algo en marcha de las versiones del gestor (las de /Applications de antes o las de BASE_DIR)?
# Como lampp_running, pero sin el XAMPP oficial
function stacks_running() {
    pgrep -f "^($LEGACY_DIR|$BASE_DIR)/XAMPP-[0-9][0-9.]*/xamppfiles/(apache2/bin/httpd|mysql/bin/mariadbd|proftpd/sbin/proftpd)( |$)" > /dev/null
}

# lvm-instalador migrar: las versiones de antes de la 1.39.3 pasan de /Applications a /Library/Nexum
# (MIGRATE_PY). Antes se para todo, con kill (como root no se ejecuta nada de /Applications); despues
# se comprueba cada una en su sitio nuevo y, si algo falla, se deja todo como estaba. Las BBDD, los
# proyectos, los vhosts, los certificados y /etc/hosts se conservan. Se puede repetir (si no queda
# nada en /Applications, no hace nada). Devuelve 0 si ya no queda nada por pasar
function stacks_migrate() {
    local list was="" out rc kind a b v problems="" moved=() jdir=$BASE_DIR/.migracion
    list=$(legacy_dirs)
    [ -n "$list" ] || return 0
    echo "Las versiones pasan de $LEGACY_DIR a $BASE_DIR (una carpeta de root, que no puede cambiar tu usuario):"
    sed 's/^/  /' <<< "$list"
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] se pararia lo que este en marcha y se moverian con sus BBDD; en $LEGACY_DIR quedaria un enlace a cada una"
        echo "  [simulacion] se cambiarian sus rutas, se comprobarian y, si algo fallara, se dejaria todo como estaba"
        return 0
    fi
    [ -n "$SUDO" ] && [ -z "$TEST_DIR" ] || return 1
    sudo -v || return 1
    boot_root_owned "$BASE_DIR" || { echo "$BASE_DIR no es una carpeta de root: no se mueve nada."; return 1; }
    # (solo si hay algo de las versiones del gestor en marcha: el XAMPP oficial, si lo hay, sigue)
    if stacks_running; then
        was=$(active_dir)
        echo "Parando lo que esta en marcha..."
        close_processes --todos
    fi
    if stacks_running; then
        echo "Sigue algo de XAMPP en marcha: no se mueve nada. Cierralo (lvm-instalador cerrar-procesos --todos) y vuelve a probar."
        return 1
    fi
    echo "Moviendolas y cambiando sus rutas (sus programas se vuelven a firmar: puede tardar unos minutos)..."
    out=$($SUDO /usr/bin/python3 -I -c "$MIGRATE_PY" migrar "$LEGACY_DIR" "$BASE_DIR" "$jdir" "$LINK" "$(fpm_script_template)")
    rc=$?
    while IFS='|' read -r kind a b; do
        case $kind in
            M) if [ "$a" == XAMPP-compartido ]; then
                   echo "  XAMPP-compartido -> $COMMON"
               else
                   echo "  XAMPP-$a -> $BASE_DIR/XAMPP-$a"
                   moved+=("$a")
               fi ;;
            S) echo "  No se pasa $a: $b" ;;
            E) echo "  Error: $a${b:+ ($b)}" ;;
            I) echo "  $a" ;;
        esac
    done <<< "$out"
    if [ $rc -ne 0 ]; then
        echo "No se ha movido nada. Si no se ve por que, pasa este registro."
        return 1
    fi
    echo "Comprobandolas en su sitio nuevo..."
    for v in "${moved[@]}"; do
        out=$(stack_check "$BASE_DIR/XAMPP-$v")
        [ -n "$out" ] && problems+="$out"$'\n'
    done
    if [ -n "$problems" ]; then
        printf '%s' "$problems"
        echo "Se deja todo como estaba (en $LEGACY_DIR)..."
        $SUDO /usr/bin/python3 -I -c "$MIGRATE_PY" deshacer "$LEGACY_DIR" "$BASE_DIR" "$jdir" | sed 's/^I|/  /; s/^E|/  Error: /'
        return 1
    fi
    $SUDO /usr/bin/python3 -I -c "$MIGRATE_PY" terminar "$LEGACY_DIR" "$BASE_DIR" "$jdir" || return 1
    # Los vhosts y su carpeta, de root (si alguna version anterior los hizo tuyos), y los Docker
    vhosts_root
    docker_refresh_compose
    echo "Hecho: las versiones estan en $BASE_DIR. Docker Desktop: añade $HTDOCS_DIR en Settings > Resources > File sharing."
    [ ${#moved[@]} -gt 0 ] && [ -n "$was" ] && [ -d "$BASE_DIR/$(basename "$was")" ] && use_version "$(version_name "$was")"
    return 0
}

# Comandos lvm-instalador y lvm de /opt/homebrew/bin: a este gestor (se crean si no estan, como hacia
# el instalador del .dmg; los que llevan a otro programa no se tocan)
function point_commands() {
    local link
    [ "$DRY" -eq 1 ] && return 0
    [ -d "$CMD_DIR" ] && [ -w "$CMD_DIR" ] || return 0
    for link in "$CMD_DIR/lvm-instalador" "$CMD_DIR/lvm"; do
        if [ -L "$link" ]; then
            [[ "$(readlink "$link")" == */[lp]vm-instalador.sh ]] && [ "$(readlink "$link")" != "$SELF" ] \
                && ln -sfh "$SELF" "$link"
        elif [ ! -e "$link" ]; then
            [ "$link" == "$CMD_DIR/lvm" ] && command -v lvm > /dev/null && continue
            ln -s "$SELF" "$link"
        fi
    done
}

# La copia de antes de la 1.39.3 (~/lvm-instalador/lvm-instalador.sh, o a la que apuntaban los
# comandos o la aplicacion) se queda en un aviso que abre el gestor de root: asi no la usa nadie para
# nada de root aunque un programa tuyo la cambie. Nunca una version mas nueva que esta
function retire_old_copies() {
    local f link plist app list=("$HOME/lvm-instalador/lvm-instalador.sh")
    for link in "$CMD_DIR/lvm-instalador" "$CMD_DIR/lvm"; do
        [ -L "$link" ] && list+=("$(readlink "$link")")
    done
    for app in "$APP_BUNDLE" "${OLD_APP_BUNDLES[@]}"; do
        plist=$(/usr/libexec/PlistBuddy -c "Print :LVMScript" "$app/Contents/Info.plist" 2> /dev/null) && list+=("$plist")
    done
    for f in "${list[@]}"; do
        [ -n "$f" ] && [ "$f" != "$TRUSTED_SCRIPT" ] && [[ "$f" == "$HOME"/* ]] && [ -f "$f" ] && [ ! -L "$f" ] \
            && [ -O "$f" ] && grep -q '^APP_VERSION=' "$f" && ! script_is_newer "$f" || continue
        printf '#!/bin/bash\n# Nexum Dev Stack ya no esta aqui: desde la 1.39.3 el gestor esta en %s,\n# de root. Este fichero solo lo abre.\nexec /bin/bash %s "$@"\n' \
            "$TRUSTED_DIR" "$TRUSTED_SCRIPT" > "$f.nuevo" && chmod 755 "$f.nuevo" && mv -f "$f.nuevo" "$f" \
            && echo "  $f ahora solo abre $TRUSTED_SCRIPT"
    done
}

# lvm-instalador migrar [--ventana] (lo lanza tambien instalar-gestor): lo que queda de antes de la
# 1.39.3. Las versiones pasan a /Library/Nexum, la copia de antes se queda en un aviso, y los comandos
# y la aplicacion apuntan a este gestor. Con --ventana, al final abre la ventana. Se puede repetir
function gestor_migrate() {
    local rc=0
    if [ -z "$TEST_DIR" ] && [ "$SELF" != "$TRUSTED_SCRIPT" ]; then
        echo "migrar lo hace el gestor de root ($TRUSTED_SCRIPT): bash $SELF instalar-gestor"
        return 1
    fi
    stacks_migrate || rc=1
    if [ "$DRY" -eq 0 ]; then
        retire_old_copies
        point_commands
        migrate_old_app
    fi
    if [ "$1" == --ventana ]; then
        open_window || rc=1
    elif [ -d "$APP_BUNDLE" ]; then
        update_app
    fi
    [ $rc -eq 0 ] && [ -n "$(legacy_dirs)" ] && rc=1
    return $rc
}

# Ejecuta el script xampp de la version montada como root, por su ruta real y solo si
# trusted_version_dir la da por buena. El XAMPP oficial (una carpeta, no un enlace) va como antes.
function xampp_ctl() {
    local real
    if [ -z "$SUDO" ]; then
        "$LINK/xamppfiles/xampp" "$@"
        return
    fi
    if [ ! -L "$LINK" ]; then
        # El XAMPP oficial (una carpeta, no el enlace): su script no se ejecuta nunca como root. Lleva
        # programas y librerias que el gestor no revisa, y /Applications la puede cambiar el grupo
        # admin (tu usuario). Se arranca desde su panel (manager-osx); para pararlo, official_stop
        echo "El XAMPP oficial de $LINK no se arranca ni se para desde aqui: usa su panel (manager-osx),"
        echo "o apartalo (lvm-instalador apartar) para usar las versiones del gestor."
        return 1
    fi
    real=$(readlink "$LINK")
    if ! trusted_version_dir "$real"; then
        if [[ "$real" == "$LEGACY_DIR"/XAMPP-* ]]; then
            echo "No se arranca ni se para $real como administrador: esta en $LEGACY_DIR (lo puede cambiar"
            echo "el grupo admin). Pasala a $BASE_DIR con: lvm-instalador migrar"
        else
            echo "No se arranca ni se para $real como administrador: no es de root, tiene enlaces o el"
            echo "grupo puede cambiarlo. Dejalo bien con: lvm-instalador asegurar --todas"
        fi
        return 1
    fi
    # (root vuelve a comprobar la ruta antes de ejecutarlo: ROOT_EXEC_PY)
    $SUDO "$real/xamppfiles/xampp" "$@"
}

# ¿Esta en marcha un servicio (apache, mariadb o ftp) de la version montada? Por su .pid: sin sudo,
# macOS no enseña la orden de los procesos de root
function service_running() {
    local dir pidf pid
    dir=$(active_dir)
    [ -n "$dir" ] || return 1
    case $1 in
        apache) pidf=logs/httpd.pid ;;
        mariadb) pidf=var/mysql/mysqld.pid ;;
        ftp) pidf=var/proftpd/proftpd.pid ;;
        *) return 1 ;;
    esac
    [ -r "$dir/xamppfiles/$pidf" ] || return 1
    pid=$(head -1 "$dir/xamppfiles/$pidf" 2> /dev/null | tr -dc '0-9')
    [ -n "$pid" ] && ps -p "$pid" > /dev/null 2>&1
}

# Puertos de XAMPP que escuchan en toda la red y no solo en este Mac, uno por linea
function exposed_ports() {
    netstat -an -p tcp 2> /dev/null | awk -v ports=" $PORT_HTTP $PORT_HTTPS $PORT_MYSQL $PORT_FTP " '$NF == "LISTEN" {
        a = $4; p = a; sub(/.*\./, "", p); h = substr(a, 1, length(a) - length(p) - 1)
        if (index(ports, " " p " ") && h !~ /^(127\.|::1$|fe80::1%lo0$)/) print p
    }' | sort -un
}

# Servicios abiertos a la red, para avisar: «Apache (80, 443), MariaDB (3306)»
function exposed_summary() {
    local ports p apache="" out=""
    lampp_running || return 0
    ports=$(exposed_ports)
    [ -z "$ports" ] && return 0
    for p in $ports; do
        case $p in
            "$PORT_HTTP"|"$PORT_HTTPS") apache+="${apache:+, }$p" ;;
        esac
    done
    [ -n "$apache" ] && out="Apache ($apache)"
    grep -qx "$PORT_MYSQL" <<< "$ports" && out+="${out:+, }MariaDB ($PORT_MYSQL)"
    grep -qx "$PORT_FTP" <<< "$ports" && out+="${out:+, }FTP ($PORT_FTP)"
    echo "$out"
}

# asegurar [version]: lo que falte para que solo se pueda entrar desde este Mac. Si es la version en
# marcha y algo sigue abierto a la red, se reinicia para aplicarlo.
function secure_command() {
    local version=$1 dir changed=1 rc moved=0
    if [ "$version" == "--todas" ]; then
        # Las de antes de la 1.39.3, primero a /Library/Nexum (si no, no se pueden arrancar como root)
        stacks_migrate || moved=1
        secure_all
        rc=$?
        [ $moved -eq 1 ] && rc=2
        htdocs_close_world "$HTDOCS_DIR" --otros
        hosts_fake locales
        vhosts_root
        [ $rc -eq 2 ] && return 1
        dir=$(active_dir)
        if [ -n "$dir" ] && lampp_running && { [ $rc -eq 0 ] || [ -n "$(exposed_ports)" ]; }; then
            echo "Reiniciando $(basename "$dir") para aplicarlo..."
            run xampp_ctl restart > /dev/null || { echo "No se ha podido reiniciar"; return 1; }
        fi
        lampp_running && wait_mariadb && secure_mariadb
        echo "Todas las versiones son solo para este Mac"
        return 0
    fi
    if [ -n "$version" ]; then
        if valid_version_name "$version" && [ ! -d "$BASE_DIR/XAMPP-$version" ] && [ -d "$LEGACY_DIR/XAMPP-$version" ] \
                && [ ! -L "$LEGACY_DIR/XAMPP-$version" ] && [ -z "$TEST_DIR" ]; then
            echo "XAMPP-$version sigue en $LEGACY_DIR (de antes de la 1.39.3): pasala a $BASE_DIR con: lvm-instalador migrar"
            return 1
        fi
        valid_version_name "$version" && [ -d "$BASE_DIR/XAMPP-$version" ] \
            || { echo "No existe la version $version"; return 1; }
        dir=$BASE_DIR/XAMPP-$version
    else
        dir=$(active_dir)
        [ -n "$dir" ] || { echo "No hay ninguna version activa (indica cual: lvm-instalador asegurar <version>)"; return 1; }
    fi
    secure_version "$dir"
    rc=$?
    [ $rc -eq 2 ] && { echo "No se ha podido dejar $(basename "$dir") solo para este Mac"; return 1; }
    [ $rc -eq 0 ] && changed=0
    vhosts_root && changed=0
    if [ "$(realpath_f "$dir")" == "$(active_dir)" ] && lampp_running \
        && { [ $changed -eq 0 ] || [ -n "$(exposed_ports)" ]; }; then
        echo "Reiniciando $(basename "$dir") para aplicarlo..."
        run xampp_ctl restart > /dev/null || { echo "No se ha podido reiniciar"; return 1; }
        [ "$DRY" -eq 1 ] && return 0
        sleep 1
        local left=$(exposed_summary)
        if [ -n "$left" ]; then
            echo "Sigue abierto a la red: $left"
            echo "Puede que no sea de XAMPP (otro programa en el mismo puerto): lvm-instalador procesos"
            return 1
        fi
    fi
    [ "$(realpath_f "$dir")" == "$(active_dir)" ] && lampp_running && wait_mariadb && secure_mariadb
    [ $changed -eq 1 ] && echo "$(basename "$dir") ya era solo para este Mac: no hay nada que cambiar"
    echo "Solo se puede entrar desde este Mac"
}

# servicio apache|mariadb|ftp arrancar|parar|reiniciar: un servicio de la version montada (lo que
# hace el panel de XAMPP). El FTP arrancado asi sigue arrancando con la version hasta que se pare.
function service_control() {
    local name=$1 action=$2 dir cmds=() c
    dir=$(active_dir)
    if [ -z "$dir" ]; then
        echo "No hay ninguna version activa"

        return 1
    fi
    case "$name" in
        apache) c=apache ;;
        mariadb|mysql) c=mysql ;;
        ftp) c=ftp ;;
        *) echo "Uso: lvm-instalador servicio apache|mariadb|ftp arrancar|parar|reiniciar"; return 1 ;;
    esac
    case "$action" in
        arrancar|start) cmds=("start$c") ;;
        parar|stop) cmds=("stop$c") ;;
        reiniciar|restart) cmds=("stop$c" "start$c") ;;
        *) echo "Uso: lvm-instalador servicio apache|mariadb|ftp arrancar|parar|reiniciar"; return 1 ;;
    esac
    # Antes de arrancar: solo para este Mac y nada de otras versiones ocupando el puerto
    if [ "${cmds[-1]}" == "start$c" ]; then
        secure_version "$dir"
        secure_failed $? "$dir" && return 1
        vhosts_root
        close_processes
    fi
    for c in "${cmds[@]}"; do
        run xampp_ctl "$c" || return 1
    done
    mailpit_sync
}

# Para la ventana (menu Gestor > Buscar actualizaciones), solo cuando se pide:
#   U|version|fecha|sha256|ruta del .zip   version nueva de GitHub, descargada y con la firma comprobada
#   I|texto                                avisos (sin conexion, sin firma...)
#   O|origen y N|version|fecha|sha256|ruta del .dmg mas nuevo que esta version que haya en Descargas,
#   si en GitHub no hay ninguna (sin conexion, por ejemplo). Ese no va firmado: se dice de donde se
#   descargo y su huella, y se abre para ejecutar su instalador
UPDATES_DIR="$LOG_DIR/actualizaciones"
# Publicaciones de GitHub (JSON de la API en la entrada, la lista de las ultimas): la version de Mac
# mas nueva que traen, version|fecha|url del .zip|url del .sig. Sin borradores ni versiones de
# prueba, y las descargas solo de la publicacion que las trae
MAC_RELEASE_PY='
import json, re, sys
repo = sys.argv[1]
try:
    rels = json.load(sys.stdin)
except ValueError:
    sys.exit(1)
if not isinstance(rels, list):
    sys.exit(1)
best = None
for r in rels:
    if not isinstance(r, dict) or not isinstance(r.get("assets"), list) or r.get("draft") or r.get("prerelease"):
        continue
    tag, when = r.get("tag_name") or "", r.get("published_at") or ""
    if not re.fullmatch(r"v[0-9]{1,4}(\.[0-9]{1,4}){1,3}", tag) \
            or not re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z", when):
        continue
    base = "https://github.com/%s/releases/download/%s/" % (repo, tag)
    urls = {a.get("name"): a.get("browser_download_url") for a in r["assets"] if isinstance(a, dict)}
    for name in urls:
        m = re.fullmatch(r"lvm-instalador-mac-([0-9]{1,4}(\.[0-9]{1,4}){1,3})\.zip", name or "")
        if not m or urls.get(name) != base + name or urls.get(name + ".sig") != base + name + ".sig":
            continue
        v = tuple(int(x) for x in m.group(1).split("."))
        if best is None or v > best[0]:
            best = (v, m.group(1), when, base + name, base + name + ".sig")
if not best:
    sys.exit(1)
print("%s|%s|%s|%s" % best[1:])
'

# ¿Es la version <a> mas nueva que <b>? (numeros separados por puntos)
function mac_version_gt() {
    [[ "$1" =~ ^[0-9]+(\.[0-9]+)*$ ]] && [[ "$2" =~ ^[0-9]+(\.[0-9]+)*$ ]] || return 1
    python3 -I -c 'import sys; a, b = (tuple(int(x) for x in v.split(".")) for v in sys.argv[1:3]); sys.exit(0 if a > b else 1)' "$1" "$2"
}

# Comprueba una firma OpenPGP suelta (.sig, binaria) de la clave de las actualizaciones (EdDSA con
# Ed25519, v4), solo con Python del sistema: sin gpgv de Homebrew, que es de tu usuario y podria dar
# por buena cualquier cosa que despues instalaria root. La huella de la clave tiene que ser la
# esperada y la firma, de esa clave principal. Uso: <fichero> <firma> <clave en base64> <huella>.
# Solo es buena si escribe FIRMA-BUENA (no basta con que termine bien)
UPDATE_VERIFY_PY='
import base64, hashlib, sys, time
path, sig_path, key_b64, want = sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4].upper()
def no(why):
    sys.stderr.write("Firma: %s\n" % why)
    sys.exit(1)
def packets(data):
    i, out = 0, []
    while i < len(data):
        b = data[i]
        if not b & 0x80:
            no("paquete OpenPGP no valido")
        if b & 0x40:
            tag, o = b & 0x3F, data[i + 1]
            if o < 192:
                n, h = o, 2
            elif o < 224:
                n, h = ((o - 192) << 8) + data[i + 2] + 192, 3
            elif o == 255:
                n, h = int.from_bytes(data[i + 2:i + 6], "big"), 6
            else:
                no("longitud parcial no admitida")
        else:
            tag, lt = (b >> 2) & 0x0F, b & 3
            if lt == 3:
                no("longitud indeterminada no admitida")
            size = (1, 2, 4)[lt]
            n, h = int.from_bytes(data[i + 1:i + 1 + size], "big"), 1 + size
        body = data[i + h:i + h + n]
        if len(body) != n:
            no("paquete cortado")
        out.append((tag, body, data[i:i + h + n]))
        i += h + n
    return out
def mpi(b, i):
    bits = int.from_bytes(b[i:i + 2], "big")
    n = (bits + 7) // 8
    return b[i + 2:i + 2 + n], i + 2 + n
# Ed25519 (RFC 8032), solo para comprobar
P = 2 ** 255 - 19
Q = 2 ** 252 + 27742317777372353535851937790883648493
D = -121665 * pow(121666, P - 2, P) % P
SQRT_M1 = pow(2, (P - 1) // 4, P)
def recover_x(y, sign):
    xx = (y * y - 1) * pow(D * y * y + 1, P - 2, P) % P
    x = pow(xx, (P + 3) // 8, P)
    if (x * x - xx) % P:
        x = x * SQRT_M1 % P
    if (x * x - xx) % P:
        return None
    if x == 0 and sign:
        return None
    if x & 1 != sign:
        x = P - x
    return x
def add(a, b):
    x1, y1, z1, t1 = a
    x2, y2, z2, t2 = b
    A = (y1 - x1) * (y2 - x2) % P
    B = (y1 + x1) * (y2 + x2) % P
    C = 2 * t1 * t2 * D % P
    E = 2 * z1 * z2 % P
    e, f, g, h = B - A, E - C, E + C, B + A
    return (e * f % P, g * h % P, f * g % P, e * h % P)
def mul(s, a):
    r = (0, 1, 1, 0)
    while s:
        if s & 1:
            r = add(r, a)
        a = add(a, a)
        s >>= 1
    return r
def encode(a):
    zi = pow(a[2], P - 2, P)
    x, y = a[0] * zi % P, a[1] * zi % P
    return (y | ((x & 1) << 255)).to_bytes(32, "little")
def decode(s):
    if len(s) != 32:
        return None
    y = int.from_bytes(s, "little")
    sign, y = y >> 255, y & ((1 << 255) - 1)
    if y >= P:
        return None
    x = recover_x(y, sign)
    return None if x is None else (x, y, 1, x * y % P)
BY = 4 * pow(5, P - 2, P) % P
BASE = (recover_x(BY, 0), BY, 1, recover_x(BY, 0) * BY % P)
def ed25519_ok(pub, msg, sig):
    a, r = decode(pub), decode(sig[:32])
    s = int.from_bytes(sig[32:], "little")
    if a is None or r is None or s >= Q:
        return False
    h = int.from_bytes(hashlib.sha512(sig[:32] + pub + msg).digest(), "little") % Q
    return encode(mul(s, BASE)) == encode(add(r, mul(h, a)))
# La clave: la principal (EdDSA con Ed25519) y su huella v4, que tiene que ser la esperada
try:
    key = base64.b64decode("".join(key_b64.split()), validate=True)
except ValueError:
    no("clave no valida")
kp = [p for p in packets(key) if p[0] == 6]
if not kp:
    no("no hay clave")
kb = kp[0][1]
fpr = hashlib.sha1(b"\x99" + len(kb).to_bytes(2, "big") + kb).hexdigest().upper()
OID = bytes.fromhex("2B06010401DA470F01")
if fpr != want or kb[0] != 4 or kb[5] != 22 or kb[6] != len(OID) or kb[7:7 + len(OID)] != OID:
    no("la clave no es la esperada")
q, _ = mpi(kb, 7 + len(OID))
if len(q) != 33 or q[0] != 0x40:
    no("clave Ed25519 no valida")
pub = q[1:]
# La firma: una sola, v4, de un fichero (tipo 0), EdDSA y SHA-2, de esa clave
with open(sig_path, "rb") as f:
    raw = f.read(65536)
sp = packets(raw)
if len(sp) != 1 or sp[0][0] != 2:
    no("no es una firma suelta")
sb = sp[0][1]
if len(sb) < 10 or sb[0] != 4 or sb[1] != 0 or sb[2] != 22 or sb[3] not in (8, 9, 10):
    no("tipo de firma no admitido")
HASH = {8: hashlib.sha256, 9: hashlib.sha384, 10: hashlib.sha512}[sb[3]]
hl = int.from_bytes(sb[4:6], "big")
hashed = sb[6:6 + hl]
ul = int.from_bytes(sb[6 + hl:8 + hl], "big")
unhashed = sb[8 + hl:8 + hl + ul]
rest = sb[8 + hl + ul:]
def subpackets(b, hashed_area):
    i, out = 0, []
    while i < len(b):
        o = b[i]
        if o < 192:
            n, h = o, 1
        elif o < 255:
            n, h = ((o - 192) << 8) + b[i + 1] + 192, 2
        else:
            n, h = int.from_bytes(b[i + 1:i + 5], "big"), 5
        if n < 1 or i + h + n > len(b):
            no("subpaquete no valido")
        t, v = b[i + h] & 0x7F, b[i + h + 1:i + h + n]
        # Uno critico que no se conoce: no se puede dar por buena (como gpgv)
        if hashed_area and b[i + h] & 0x80 and t not in (2, 16, 33, 27, 3):
            no("subpaquete critico desconocido (%d)" % t)
        out.append((t, v))
        i += h + n
    return out
subs = subpackets(hashed, True) + subpackets(unhashed, False)
issuers = [v[1:].hex().upper() for t, v in subs if t == 33 and len(v) == 21 and v[0] == 4]
ids = [v.hex().upper() for t, v in subs if t == 16 and len(v) == 8]
if not (fpr in issuers or (not issuers and fpr[-16:] in ids)):
    no("la firma no es de esa clave")
# (si caduca, que no haya caducado)
made = [int.from_bytes(v, "big") for t, v in subpackets(hashed, True) if t == 2 and len(v) == 4]
life = [int.from_bytes(v, "big") for t, v in subpackets(hashed, True) if t == 3 and len(v) == 4]
if life and life[0] and (not made or time.time() > made[0] + life[0]):
    no("la firma ha caducado")
h = HASH()
with open(path, "rb") as f:
    for chunk in iter(lambda: f.read(1 << 20), b""):
        h.update(chunk)
h.update(sb[:6 + hl])
h.update(b"\x04\xff" + (6 + hl).to_bytes(4, "big"))
digest = h.digest()
if len(rest) < 2 or rest[:2] != digest[:2]:
    no("el fichero no es el firmado")
r, i = mpi(rest, 2)
s, i = mpi(rest, i)
if len(r) > 32 or len(s) > 32 or i != len(rest):
    no("firma EdDSA no valida")
if not ed25519_ok(pub, digest, r.rjust(32, b"\0") + s.rjust(32, b"\0")):
    no("la firma no es buena")
print("FIRMA-BUENA")
'

# ¿Esta <fichero> firmado con la clave de las actualizaciones? (la firma, en <fichero>.sig)
function update_signed() {
    [ -f "$1" ] && [ -f "$1.sig" ] && [ ! -L "$1.sig" ] && [ -n "$UPDATE_VERIFY_PY" ] || return 1
    [ "$(/usr/bin/python3 -I -c "$UPDATE_VERIFY_PY" "$1" "$1.sig" "$UPDATE_KEY_B64" "$UPDATE_KEY_FPR" 2> /dev/null)" == FIRMA-BUENA ]
}

# Si en GitHub hay una version de Mac mas nueva que esta, descarga su .zip y su firma a UPDATES_DIR
# (solo tuya; el .zip con la fecha de la publicacion) y la ofrece (U|) si la firma es buena. Si no se
# puede, lo dice (I|...). Devuelve 1 si no hay nada que ofrecer de GitHub
function github_update() {
    local json code rel v when zip_url sig_url f
    local get=(curl -q --proto =https --proto-redir =https -fsSL --max-time 60)

    # (sin -f: un 404 es que el repositorio aun no tiene publicaciones, no un fallo de la conexion)
    json=$(curl -q --proto =https --proto-redir =https -sSL --max-time 30 --max-filesize 4194304 \
        -H "Accept: application/vnd.github+json" -w '\n%{http_code}' \
        "https://api.github.com/repos/$UPDATE_REPO/releases?per_page=30" 2> /dev/null)
    code=${json##*$'\n'} json=${json%$'\n'*}
    case "$code" in
        200) ;;
        404) echo "I|Todavía no hay ninguna versión publicada en GitHub"; return 1 ;;
        *) echo "I|No se ha podido consultar GitHub (¿sin conexión?): solo se ha buscado en Descargas"; return 1 ;;
    esac
    rel=$(python3 -I -c "$MAC_RELEASE_PY" "$UPDATE_REPO" <<< "$json") \
        || { echo "I|En GitHub todavía no hay ninguna versión para Mac con su firma"; return 1; }
    IFS='|' read -r v when zip_url sig_url <<< "$rel"
    mac_version_gt "$v" "$APP_VERSION" || return 1

    [ -L "$UPDATES_DIR" ] && { echo "I|$UPDATES_DIR es un enlace: no se descarga nada ahí"; return 1; }
    mkdir -p -m 700 "$UPDATES_DIR" && chmod 700 "$UPDATES_DIR" || return 1
    f=$UPDATES_DIR/lvm-instalador-mac-$v.zip
    # Ya descargada y bien firmada: no se vuelve a bajar
    if ! { [ -f "$f" ] && [ ! -L "$f" ] && update_signed "$f"; }; then
        rm -f -- "$UPDATES_DIR"/lvm-instalador-mac-*
        if ! "${get[@]}" --max-filesize 52428800 -o "$f.part" "$zip_url" 2> /dev/null \
                || ! "${get[@]}" --max-filesize 65536 -o "$f.sig" "$sig_url" 2> /dev/null; then
            rm -f -- "$f.part" "$f.sig"
            echo "I|No se ha podido descargar la $v de GitHub"
            return 1
        fi
        mv -f -- "$f.part" "$f"
        touch -d "$when" "$f" 2> /dev/null
        if ! update_signed "$f"; then
            rm -f -- "$f" "$f.sig"
            echo "I|La $v de GitHub no está firmada por quien hace el programa: no se ofrece"
            return 1
        fi
    fi
    echo "U|$v|$(date -r "$(stat -f %m "$f")" '+%d/%m/%Y %H:%M')|$(shasum -a 256 "$f" | cut -d' ' -f1)|$f"
}

function gui_package() {
    github_update && return 0
    local f v best="" best_v=$APP_VERSION
    for f in "$HOME"/Downloads/lvm-instalador-mac-*.dmg; do
        [ -f "$f" ] && [ ! -L "$f" ] && [ -O "$f" ] || continue
        v=${f##*/lvm-instalador-mac-}
        v=${v%.dmg}
        mac_version_gt "$v" "$best_v" && best=$f best_v=$v
    done
    [ -n "$best" ] || return 0
    # Se abre una copia en una carpeta privada, con la huella calculada sobre esa copia: si despues
    # cambiaran el de Descargas, no se abriria otro distinto del que se te ha mostrado. Tambien se
    # dice de donde se descargo (lo guarda macOS): un .dmg que deja una web lo delata
    local dir copy from old
    # (las copias de otras veces se borran)
    for old in "${TMPDIR:-/tmp}"/lvm-actualizar.*; do
        [ -d "$old" ] && [ ! -L "$old" ] && [ -O "$old" ] && rm -rf "$old"
    done
    dir=$(mktemp -d "${TMPDIR:-/tmp}/lvm-actualizar.XXXXXX") || return 0
    copy=$dir/$(basename "$best")
    # Con sus atributos: com.apple.quarantine hace que Gatekeeper revise lo que traiga el .dmg
    cp "$best" "$copy" || { rm -rf "$dir"; return 0; }
    from=$(mdls -raw -name kMDItemWhereFroms "$best" 2> /dev/null | tr -d '\n"()' | sed 's/^ *//; s/ *, */ y /g' | tr -c '[:print:]' ' ')
    [ "$from" == "(null)" ] || [ "$from" == "null" ] && from=""
    echo "O|${from:-desconocido (no viene de una descarga del navegador)}"
    echo "N|$best_v|$(date -r "$(stat -f %m "$best")" '+%d/%m/%Y %H:%M')|$(shasum -a 256 "$copy" | cut -d' ' -f1)|$copy"
}

# Saca lvm-instalador.sh de un .zip de actualizacion: uno solo, normal (no un enlace) y de un tamaño
# razonable. Uso: <zip> <destino>
UPDATE_EXTRACT_PY='
import stat, sys, zipfile
src, dst = sys.argv[1:3]
try:
    with zipfile.ZipFile(src) as z:
        infos = [i for i in z.infolist() if i.filename == "lvm-instalador.sh"]
        if len(infos) != 1 or stat.S_ISLNK(infos[0].external_attr >> 16) or infos[0].file_size > 16 * 1024 * 1024:
            sys.exit(1)
        data = z.read(infos[0])
except (OSError, zipfile.BadZipFile, RuntimeError):
    sys.exit(1)
with open(dst, "wb") as f:
    f.write(data)
'

# actualizar-gestor <lvm-instalador-mac-X.zip>: instala la version de un .zip firmado (el que ha
# descargado Buscar actualizaciones) en el gestor de root (/Library/Nexum/gestor), al que apuntan los
# comandos y la aplicacion. Root copia el .zip y su firma a una carpeta suya y lo comprueba todo
# alli (la firma, con UPDATE_VERIFY_PY; que solo traiga un lvm-instalador.sh normal; que sea la
# version del nombre del .zip, mas nueva que esta, y que bash la entienda entera): lo que instala es
# justo lo comprobado, aunque un programa tuyo cambiara el .zip de tu carpeta entre medias
function install_update() {
    local zip=$1 v work new_v dest=$TRUSTED_SCRIPT owner=(-o root -g wheel)

    v=${zip##*/lvm-instalador-mac-}
    v=${v%.zip}
    if [ ! -f "$zip" ] || [ -L "$zip" ] || [ ! -O "$zip" ] || [[ "$zip" != */lvm-instalador-mac-*.zip ]] \
            || ! [[ "$v" =~ ^[0-9]+(\.[0-9]+)*$ ]]; then
        echo "Uso: lvm-instalador actualizar-gestor <ruta de lvm-instalador-mac-X.Y.Z.zip>"
        return 1
    fi
    if ! mac_version_gt "$v" "$APP_VERSION"; then
        echo "La $v no es mas nueva que la que tienes ($APP_VERSION): no se instala."
        return 1
    fi
    if ! update_signed "$zip"; then
        echo "$zip no lleva la firma de quien publica el programa: no se instala."
        return 1
    fi
    # (en las pruebas, LVM_PRUEBA: sin sudo y en el sitio de este script)
    if [ -n "$TEST_DIR" ]; then
        dest=$SELF owner=()
    elif [ "$SELF" != "$TRUSTED_SCRIPT" ]; then
        echo "Las actualizaciones las instala el gestor de root ($TRUSTED_SCRIPT): bash $SELF instalar-gestor"
        return 1
    fi
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] root copiaria el .zip a una carpeta suya, volveria a comprobar la firma y $dest pasaria a ser la $v"
        return 0
    fi
    if [ -n "$TEST_DIR" ]; then
        work=$(mktemp -d "${TMPDIR:-/tmp}/lvm-actualizar.XXXXXX") || return 1
    else
        work=$($SUDO mktemp -d /private/tmp/lvm-actualizar.XXXXXX) && $SUDO chmod 755 "$work" || return 1
    fi
    if ! { $SUDO install -m 644 "$zip" "$work/nuevo.zip" && $SUDO install -m 644 "$zip.sig" "$work/nuevo.zip.sig"; }; then
        $SUDO rm -rf "$work"
        echo "No se ha podido copiar $zip"
        return 1
    fi
    if [ "$($SUDO /usr/bin/python3 -I -c "$UPDATE_VERIFY_PY" "$work/nuevo.zip" "$work/nuevo.zip.sig" "$UPDATE_KEY_B64" "$UPDATE_KEY_FPR")" != FIRMA-BUENA ]; then
        $SUDO rm -rf "$work"
        echo "$zip no lleva la firma de quien publica el programa: no se instala."
        return 1
    fi
    if ! { $SUDO /usr/bin/python3 -I -c "$UPDATE_EXTRACT_PY" "$work/nuevo.zip" "$work/lvm-instalador.sh" \
            && $SUDO chmod 644 "$work/lvm-instalador.sh"; }; then
        $SUDO rm -rf "$work"
        echo "$zip no trae un lvm-instalador.sh valido: no se instala."
        return 1
    fi
    # (la copia es de root: se puede mirar sin sudo, no cambiar)
    new_v=$(grep -m1 '^APP_VERSION=' "$work/lvm-instalador.sh" | cut -d'"' -f2)
    if [ "$new_v" != "$v" ] || ! "$BASH" -n "$work/lvm-instalador.sh" 2> /dev/null; then
        $SUDO rm -rf "$work"
        echo "El lvm-instalador.sh de $zip no es la $v o esta dañado: no se instala."
        return 1
    fi
    echo "Instalando la $v en $dest..."
    # Al lado del instalado y despues con mv: si algo falla, el de antes sigue entero
    if ! { $SUDO install "${owner[@]}" -m 755 "$work/lvm-instalador.sh" "$dest.nuevo" && $SUDO mv -f "$dest.nuevo" "$dest"; }; then
        $SUDO rm -f "$dest.nuevo"
        $SUDO rm -rf "$work"
        echo "No se ha podido escribir $dest"
        return 1
    fi
    $SUDO rm -rf "$work"
    echo "Instalada la $v. La ventana se vuelve a abrir con ella."
}

# Para la pestaña Servicios: S|servicio|en marcha (1/0)|puertos|abierto a la red (1/0)|arranca con
# la version (1/0)|usuario (FTP), de la version montada
function gui_services() {
    local dir ports p name running port open auto user
    dir=$(active_dir)
    [ -n "$dir" ] || return 0
    ports=$(exposed_ports)
    for name in apache mariadb ftp; do
        running=0
        service_running "$name" && running=1
        case $name in
            apache) port="$PORT_HTTP, $PORT_HTTPS" ;;
            mariadb) port=$PORT_MYSQL ;;
            ftp) port=$PORT_FTP ;;
        esac
        open=0
        if [ $running -eq 1 ]; then
            for p in ${port//,/}; do grep -qx "$p" <<< "$ports" && open=1; done
        fi
        auto=1 user=""
        if [ $name == ftp ]; then
            [ -f "$dir/xamppfiles/etc/lvm-startftp" ] || auto=0
            # Las versiones anteriores a la 1.16.0, sin asegurar, arrancan el FTP siempre
            [ -f "$dir/$SECURE_MARK" ] || auto=1
            user=$(awk '/<Limit LOGIN>/ { f = 1 } f && $1 == "AllowUser" { print $2; exit }' "$dir/xamppfiles/etc/proftpd.conf" 2> /dev/null)
        fi
        echo "S|$name|$running|$port|$open|$auto|$user"
    done
}

# Lo que falta en la carga de un proyecto: si es PrestaShop, su dominio con vhost, certificado y
# falseado en /etc/hosts; si no, ningun dominio falseado. Recarga Apache si ha cambiado algo.
function load_project_domain() {
    local folder=$1 domain=""
    PS_RELOAD=0
    # Tienda recien clonada: parameters.php con la base cargada y, la primera vez, cache vacia
    if is_prestashop "$folder"; then
        PS_NEW_PARAMS=0
        ps_parameters "$folder" "$2" || return 1
        # Codigo de produccion volcado encima: la configuracion vuelve a la base de la carpeta
        ps_set_db "$folder" "${2:-$(saved_project_db "$folder")}" || return 1
        ps_first_load "$folder"
    fi
    # WordPress con el codigo de produccion pegado encima: wp-config.php con la base de la carpeta
    if ! is_prestashop "$folder" && is_wordpress "$folder"; then
        wp_config "$folder" "$2" || return 1
    fi
    if [ -n "$(ps_config "$folder")" ]; then
        domain=$(ps_domain "$folder")
        if [ -z "$domain" ]; then
            echo "Aviso: $folder es una tienda PrestaShop, pero no se ha podido saber su dominio: su"
            echo "base no se puede leer (¿MariaDB parado o root con contraseña?) y ningun vhost apunta"
            echo "a la carpeta. Crea su vhost (Editar vhosts) y vuelve a cargar el proyecto."
        elif ! vhost_points_to "$domain" "$folder" && grep -qxF -- "$folder" "$REPO_PROJECTS_FILE" 2> /dev/null; then
            # Montada con Montar nuevo proyecto: la base (su volcado) y el nombre de la carpeta (el del
            # repositorio) los elige quien publica el repositorio, asi que el parecido no basta
            echo "La tienda usa el dominio $domain (de su base). No se falsea solo, porque la base y el"
            echo "nombre de la carpeta vienen con el repositorio: si es el suyo, crealo en Dominios y"
            echo "hosts (Nuevo proyecto con dominio falseado, con la carpeta $folder y ese dominio)."
            domain=""
        elif ! vhost_points_to "$domain" "$folder" && ! domain_fits_folder "$domain" "$folder"; then
            # El dominio viene de la base (shop_url): un volcado manipulado podria llevar uno real
            # (de un banco, de github...) para que este Mac lo mande aqui. Sin vhost suyo, solo se
            # falsea si se parece al nombre de la carpeta
            echo "Aviso: el dominio de la base ($domain) no se parece al nombre de la carpeta $folder:"
            echo "no se le crea vhost ni se falsea. Si es el correcto, crealo en Dominios y hosts"
            echo "(Nuevo proyecto con dominio falseado) o en los vhosts."
            domain=""
        else
            echo "Tienda PrestaShop: dominio $domain"
            ps_vhost "$folder" "$domain" || return 1
        fi
    elif domain=$(custom_domain "$folder") && [ -n "$domain" ]; then
        # Proyecto nuevo creado con su dominio desde la pestaña Hosts (al crearlo ya se le hace su
        # vhost). El fichero de dominios es tuyo y otro programa podria añadir uno real (github.com):
        # sin vhost suyo, solo si se parece al nombre de la carpeta, como con PrestaShop
        if ! vhost_points_to "$domain" "$folder" && ! domain_fits_folder "$domain" "$folder"; then
            echo "Aviso: el dominio guardado para $folder ($domain) no tiene vhost ni se parece al nombre"
            echo "de la carpeta: no se crea ni se falsea. Si es el correcto, crealo en Dominios y hosts."
            domain=""
        else
            echo "Proyecto con dominio propio: $domain"
            ps_vhost "$folder" "$domain" || return 1
        fi
    fi
    hosts_fake cargar $domain || return 1
    if [ "$PS_RELOAD" -eq 1 ] && [ -f "$LINK/xamppfiles/logs/httpd.pid" ]; then
        echo "Recargando Apache para aplicar el vhost y el certificado..."
        run xampp_ctl reloadapache > /dev/null || { echo "No se ha podido recargar Apache. Reinicia la version activa."; return 1; }
    fi
    return 0
}

# ===========================================================================
# Tiendas PrestaShop: parameters.php y cache
# ===========================================================================
# El repositorio de una tienda 1.7 no lleva app/config/parameters.php (esta en su .gitignore): al
# clonarla queda vacio ('parameters' => NULL) y PrestaShop dice "install" directory is missing. Se
# crea con la base cargada en local y claves nuevas, y se guarda una copia en PS_PARAMS_DIR para
# volver a ponerla (con las mismas claves) si se pierde. La primera vez que se carga una tienda se
# vacia su var/cache (la de produccion da error 500 en local); se apunta en PS_LOADED_FILE.
PS_PARAMS_DIR="$HOME/.lvm-instalador/prestashop"
PS_LOADED_FILE="$HOME/.lvm-instalador/prestashop-cargados"
# Carpetas clonadas con montar-proyecto (el dominio de su base no se falsea solo)
REPO_PROJECTS_FILE="$HOME/.lvm-instalador/montados-de-repositorio"

# ¿Es una tienda PrestaShop? Por su configuracion, sus carpetas o "prestashop" en el nombre
function is_prestashop() {
    local dir=$HTDOCS_DIR/$1
    [[ "${1,,}" == *prestashop* ]] || [ -d "$dir/src/PrestaShopBundle" ] \
        || [ -f "$dir/classes/PrestaShopAutoload.php" ] || [ -n "$(ps_config "$1")" ]
}

# Base de una tienda cuya configuracion no la dice: la indicada, la recordada para la carpeta
# (~/.lvm-instalador/proyectos) o, en la version activa, la unica ps_<final de la carpeta>
# (dob-prestashop-mitienda -> ps_mitienda)
function ps_guess_db() {
    local folder=$1 db=$2 tail
    if [ -z "$db" ] && [ -f "$PROJECTS_FILE" ]; then
        db=$(saved_project_db "$folder")
    fi
    if [ -z "$db" ]; then
        tail=$(tr 'A-Z' 'a-z' <<< "${folder##*[-.]}")
        # Va dentro de la consulta: solo letras, numeros y _
        if [[ "$tail" =~ ^[a-z0-9_]+$ ]]; then
            db=$("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N -e "SELECT SCHEMA_NAME FROM information_schema.SCHEMATA WHERE LOWER(SCHEMA_NAME) IN ('ps_$tail', '$tail')" < /dev/null 2> /dev/null)
        fi
        [ "$(grep -c . <<< "$db")" == 1 ] || db=""
    fi
    [[ "$db" =~ ^[A-Za-z0-9_-]+$ ]] && echo "$db"
}

# Prefijo de las tablas de una tienda: el de su tabla <prefijo>shop_url (solo letras, numeros y _:
# los nombres de las tablas los trae la base, y el prefijo se usa despues en otras consultas). Si la
# base tiene varias tiendas, el indicado (el que ya usaba su configuracion) si lo tiene; si no, el
# mas corto. ps_table_prefix <base> [prefijo preferido]
function ps_table_prefix() {
    local pref=$2
    [[ "$1" =~ ^[A-Za-z0-9_-]+$ ]] || return 0
    [[ "$pref" =~ ^[A-Za-z0-9_]+$ ]] || pref=""
    db_root_sql -N -e "SELECT LEFT(TABLE_NAME, LENGTH(TABLE_NAME) - 8) FROM information_schema.TABLES WHERE TABLE_SCHEMA='$1' AND TABLE_TYPE='BASE TABLE' AND TABLE_NAME LIKE '%shop\\_url' ORDER BY TABLE_NAME = '${pref}shop_url' DESC, LENGTH(TABLE_NAME) LIMIT 1" < /dev/null 2> /dev/null \
        | grep -E '^[A-Za-z0-9_]+$'
}

# Tienda 1.7 o posterior sin base en app/config/parameters.php: lo crea con la base cargada en local
# (la copia guardada si es de la misma base). Lo que ya tiene base no se toca.
function ps_parameters() {
    local folder=$1 db dir=$HTDOCS_DIR/$1 prefix saved try out
    local file=$dir/app/config/parameters.php
    [ -f "$dir/app/config/set_parameters.php" ] || [ -d "$dir/src/PrestaShopBundle" ] || return 0
    [ -f "$file" ] && grep -qE "['\"]database_name['\"][[:space:]]*=>[[:space:]]*['\"][^'\"]" "$file" && return 0

    # Si MariaDB se acaba de arrancar (cambio de version), se le dan unos segundos
    for try in 1 2 3 4 5 6; do
        out=$("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N -e 'SELECT 1' < /dev/null 2>&1) && break
        [[ "$out" == *"Can't connect"* ]] && [ "$DRY" -eq 0 ] || break
        sleep 1
    done
    db=$(ps_guess_db "$folder" "$2")
    if [ -z "$db" ] || ! db_exists "$db" 2> /dev/null; then
        echo "Aviso: $folder no tiene la base de datos en app/config/parameters.php y no se sabe"
        echo "cual es${db:+ ($db no esta en la version activa)}. Cargala desde el buscador de Bases de"
        echo "datos (Cargar proyecto) o pon database_name a mano en ese fichero."

        return 0
    fi
    prefix=$(ps_table_prefix "$db")
    if [ -z "$prefix" ]; then
        echo "Aviso: la base $db no tiene la tabla shop_url de PrestaShop: no se crea parameters.php"

        return 0
    fi

    if ! project_path_ok "$dir" "$file"; then
        echo "Aviso: app/config/parameters.php de $folder es un enlace o esta fuera de la carpeta: no se toca"

        return 0
    fi
    saved=$PS_PARAMS_DIR/$folder.parameters.php
    if [ -f "$saved" ] && grep -qF "'database_name' => '$db'" "$saved"; then
        echo "app/config/parameters.php no tiene la base: se pone la copia guardada ($db)"
        project_write "$saved" "$file" || return 1
    else
        echo "Creando app/config/parameters.php con la base $db (prefijo $prefix) y claves nuevas..."
        if [ "$DRY" -eq 1 ]; then
            echo "  [simulacion] $file con la base $db y copia en $saved"
            return 0
        fi
        [ -f "$file" ] && mkdir -p -m 700 "$HOME/lvm-copias" \
            && cp "$file" "$HOME/lvm-copias/parameters.php-$folder-$(date +%Y%m%d-%H%M%S)"
        mkdir -p -m 700 "$PS_PARAMS_DIR" || return 1
        python3 -I - "$PS_PARAMS_DIR/.nuevo" "$db" "$prefix" <<'EOF' || { echo "No se ha podido preparar $file"; return 1; }
import datetime, hashlib, os, secrets, string, sys
path, db, prefix = sys.argv[1:4]
alnum = string.ascii_letters + string.digits
def gen(n):
    return "".join(secrets.choice(alnum) for _ in range(n))
# Clave de defuse/php-encryption (new_cookie_key): cabecera, 32 bytes y su sha256, en hexadecimal
head = b"\xde\xf0\x00\x00"
key = os.urandom(32)
defuse = (head + key + hashlib.sha256(head + key).digest()).hex()
params = [
    ("database_host", "localhost"), ("database_port", ""), ("database_name", db),
    ("database_user", "root"), ("database_password", ""), ("database_prefix", prefix),
    ("database_engine", "InnoDB"), ("mailer_transport", "smtp"), ("mailer_host", "127.0.0.1"),
    ("mailer_user", None), ("mailer_password", None), ("secret", gen(64)),
    ("ps_caching", "CacheMemcache"), ("ps_cache_enable", False),
    ("ps_creation_date", datetime.date.today().isoformat()), ("locale", "es-ES"),
    ("use_debug_toolbar", True), ("cookie_key", gen(64)), ("cookie_iv", gen(32)),
    ("new_cookie_key", defuse),
]
def php(v):
    if v is None:
        return "NULL"
    if isinstance(v, bool):
        return "true" if v else "false"
    return "'%s'" % v.replace("\\", "\\\\").replace("'", "\\'")
text = "<?php return array (\n  'parameters' => \n  array (\n%s  ),\n);\n" % "".join(
    "    '%s' => %s,\n" % (k, php(v)) for k, v in params)
with open(path, "w") as f:
    f.write(text)
EOF
        project_write "$PS_PARAMS_DIR/.nuevo" "$file" || { rm -f "$PS_PARAMS_DIR/.nuevo"; echo "No se ha podido escribir $file"; return 1; }
        mv "$PS_PARAMS_DIR/.nuevo" "$saved"
    fi
    # La cache guarda la configuracion anterior (var/cache/*/appParameters.php): se vacia al cargar
    PS_NEW_PARAMS=1
    return 0
}

# Vacia una carpeta (var/cache de una tienda) como root sin seguir enlaces en ningun momento: la ruta
# se recorre desde / con O_NOFOLLOW y tiene que estar dentro de htdocs; dentro, los enlaces se
# borran (no se sigue a donde apuntan). CACHE_CLEAR_PY <carpeta> <htdocs>
CACHE_CLEAR_PY='
import os, stat, sys
target, top = sys.argv[1], os.path.realpath(sys.argv[2])
real = os.path.realpath(target)
if not real.startswith(top + "/") or not real.endswith("/var/cache"):
    sys.exit("%s no esta dentro de %s: no se vacia" % (target, top))
fd = os.open("/", os.O_RDONLY | os.O_DIRECTORY)
for p in [p for p in real.split("/") if p]:
    nfd = os.open(p, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=fd)
    os.close(fd)
    fd = nfd
dev = os.fstat(fd).st_dev
def empty(dfd):
    for e in os.scandir(dfd):
        st = os.stat(e.name, dir_fd=dfd, follow_symlinks=False)
        if stat.S_ISDIR(st.st_mode) and st.st_dev == dev:
            sub = os.open(e.name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=dfd)
            try:
                empty(sub)
            finally:
                os.close(sub)
            os.rmdir(e.name, dir_fd=dfd)
        elif not stat.S_ISDIR(st.st_mode):
            os.unlink(e.name, dir_fd=dfd)
empty(fd)
'

# vaciar-cache <carpeta>: borra el contenido de var/cache de una tienda (PrestaShop 1.7 la usa para
# Symfony y da error 500 con la de otro equipo). Si no tiene var/cache no hace nada.
function ps_clear_cache() {
    local folder=${1%/} cache s=""
    valid_project "$folder" || return 1
    cache=$HTDOCS_DIR/$folder/var/cache
    if [ ! -d "$cache" ]; then
        echo "$folder no tiene la carpeta var/cache: no hay cache que vaciar"

        return 0
    fi
    # var y var/cache tienen que estar dentro de la tienda: si fueran enlaces a otra carpeta (por
    # ejemplo a /Library, donde cache coincide con Caches), con sudo se vaciaria la del sistema
    if [ -L "$HTDOCS_DIR/$folder/var" ] || [ -L "$cache" ] \
        || [ "$(realpath_f "$cache")" != "$(realpath_f "$HTDOCS_DIR/$folder")/var/cache" ]; then
        echo "var/cache de $folder es un enlace a otra carpeta: no se vacia"

        return 1
    fi
    # Los ficheros que creo Apache como daemon (antes de User/Group) solo se borran con sudo
    find "$cache" -mindepth 1 ! -user "$(id -un)" -print -quit 2> /dev/null | grep -q . && s=$SUDO
    echo "Vaciando la cache de $folder (var/cache)..."
    # Con sudo, root abre var/cache carpeta a carpeta sin seguir enlaces y borra desde ahi: si entre
    # la comprobacion y el borrado cambian var por un enlace (a /var), falla en lugar de vaciar otra
    if [ -n "$s" ]; then
        run $s python3 -I -c "$CACHE_CLEAR_PY" "$cache" "$HTDOCS_DIR"
    else
        run find "$cache" -mindepth 1 -delete
    fi || { echo "No se ha podido vaciar $cache"; return 1; }
    echo "Cache de $folder vaciada"
}

# Para el boton de la pestaña Bases de datos: la carpeta de la tienda de una base (la recordada, o
# la unica cuya configuracion la usa, o la unica cuyo nombre acaba como la base sin ps_)
function ps_clear_cache_db() {
    local db=$1 folder="" tail
    [[ "$db" =~ ^[A-Za-z0-9_-]+$ ]] || { echo "Base de datos no valida: $db"; return 1; }
    folder=$(linked_folder "$db")
    if [ -z "$folder" ] || [ ! -d "$HTDOCS_DIR/$folder" ]; then
        folder=$(gui_projects | awk -F'|' -v d="$db" '$1 == "P" && $3 == d { print $2 }')
        if [ "$(grep -c . <<< "$folder")" != 1 ]; then
            tail=$(tr 'A-Z' 'a-z' <<< "${db#ps_}")
            folder=$(gui_projects | awk -F'|' -v t="$tail" '$1 == "P" { n = tolower($2); if (n == t || substr(n, length(n) - length(t)) ~ ("[-.]" t "$")) print $2 }')
        fi
    fi
    if [ -z "$folder" ] || [ "$(grep -c . <<< "$folder")" != 1 ]; then
        echo "No se sabe cual es la carpeta de la tienda de $db. Cargala una vez con Cargar proyecto"
        echo "(se recuerda) o usa: lvm-instalador vaciar-cache <carpeta>"

        return 1
    fi
    ps_clear_cache "$folder"
}

# Primera carga de una tienda en este equipo (o parameters.php nuevo): vacia su cache y la apunta
function ps_first_load() {
    local folder=$1
    if [ "$PS_NEW_PARAMS" != 1 ] && [ -f "$PS_LOADED_FILE" ] && grep -qxF "$folder" "$PS_LOADED_FILE"; then
        return 0
    fi
    grep -qxF "$folder" "$PS_LOADED_FILE" 2> /dev/null || echo "Primera carga de la tienda $folder en este equipo"
    ps_clear_cache "$folder" || return 0
    [ "$DRY" -eq 1 ] && return 0
    grep -qxF "$folder" "$PS_LOADED_FILE" 2> /dev/null && return 0
    mkdir -p "$(dirname "$PS_LOADED_FILE")" && echo "$folder" >> "$PS_LOADED_FILE"
}

# ===========================================================================
# WordPress: wp-config.php con la base cargada en local
# ===========================================================================
# Al pegar el codigo de produccion encima del proyecto local, su wp-config.php trae la base, el
# usuario, la contraseña y el servidor de produccion. Al cargar el proyecto (y al subir una base
# nueva para el) se comprueba que use la base asociada a la carpeta y que sus datos entren en el
# MariaDB local. Si no, se rehace con la plantilla: la copia del ultimo wp-config.php que funciono
# en este equipo (WP_CONFIG_DIR/<carpeta>.wp-config.php) o, si no la hay, el propio fichero (o
# wp-config-sample.php) con root y localhost. De la plantilla solo cambian la base y el prefijo.
WP_CONFIG_DIR="$HOME/.lvm-instalador/wordpress"

function is_wordpress() {
    [ -f "$HTDOCS_DIR/$1/wp-config.php" ] || [ -d "$HTDOCS_DIR/$1/wp-includes" ]
}

# Vinculos entre las BBDD y las carpetas de los proyectos (~/.lvm-instalador/proyectos), uno por
# linea: base@version=carpeta (en esa version, la de XAMPP-<version>; sin carpeta, la base no es de
# ningun proyecto en esa version) o base=carpeta (en todas las versiones, como se guardaban hasta la
# 1.36). El de la version manda: asi la copia de una base en otra version puede ir con otra carpeta

# Nombre de la version activa (8.4.27, de XAMPP-8.4.27), o nada
function active_name() {
    local a=$(active_dir)
    [ -n "$a" ] && version_name "$a"
}

# Carpeta vinculada a <base> en <version> (sin version, la activa). Nada si no tiene
function linked_folder() {
    local db=$1 ver=${2:-$(active_name)}
    [ -f "$PROJECTS_FILE" ] || return 0
    awk -F= -v d="$db" -v k="$db@$ver" '$1 == k { v = $2; hv = 1 } $1 == d { g = $2 } END { print (hv ? v : g) }' "$PROJECTS_FILE"
}

# Base vinculada a una carpeta en <version> (sin version, la activa): la ultima que se vinculo
function saved_project_db() {
    local ver=${2:-$(active_name)}
    [ -f "$PROJECTS_FILE" ] || return 0
    awk -F= -v f="$1" -v ver="$ver" '{
        n = index($1, "@")
        if (n) { d = substr($1, 1, n - 1); if (substr($1, n + 1) != ver) next; per[d] = $2; has[d] = 1 }
        else { d = $1; all[d] = $2 }
        last[d] = NR
    } END {
        for (d in last) { v = (d in has) ? per[d] : all[d]; if (v == f && last[d] > best) { best = last[d]; db = d } }
        if (db != "") print db
    }' "$PROJECTS_FILE"
}

# remember_project <base> <carpeta> [version] [--unica]: vincula la base a la carpeta en esa version
# (sin version, la activa; sin carpeta, la desvincula). Con --unica, en esa version la carpeta deja
# de estar vinculada a otras bases (la base nueva sustituye a la anterior)
function remember_project() {
    local db=$1 folder=$2 ver=${3:-$(active_name)} key
    [ "$DRY" -eq 1 ] && return 0
    key=$db${ver:+@$ver}
    mkdir -p "$(dirname "$PROJECTS_FILE")"
    { [ -f "$PROJECTS_FILE" ] && awk -F= -v k="$key" -v d="$db" -v f="$folder" -v ver="$ver" -v u="$4" '
        $1 == k { next }
        u == "--unica" && f != "" && $2 == f && $1 != d {
            # (la de todas las versiones se queda para las demas y en esta se desvincula)
            if (index($1, "@") == 0) { print; if (ver != "") print $1 "@" ver "="; next }
            if (substr($1, index($1, "@") + 1) == ver) next
        }
        { print }' "$PROJECTS_FILE"; echo "$key=$folder"; } > "$PROJECTS_FILE.nuevo"
    mv "$PROJECTS_FILE.nuevo" "$PROJECTS_FILE"
}

# vincular-bd <base> <version> <carpeta|->: la carpeta del proyecto de la base en esa version (- =
# ninguna). Cargar proyecto la carga con ella
function link_database() {
    local db=$1 ver=$2 folder=$3
    if [ -z "$db" ] || [ -z "$ver" ] || [ -z "$folder" ]; then
        echo "Uso: lvm-instalador vincular-bd <base de datos> <version> <carpeta de htdocs|->"
        return 1
    fi
    db_valid_name "$db" || return 1
    if ! valid_version_name "$ver" || [ ! -d "$BASE_DIR/XAMPP-$ver" ]; then
        echo "No existe la version XAMPP-$ver"
        return 1
    fi
    if [ "$folder" == "-" ]; then
        remember_project "$db" "" "$ver"
        echo "$db ya no esta vinculada a ningun proyecto en XAMPP-$ver"
    else
        folder=${folder%/}
        valid_project "$folder" || return 1
        remember_project "$db" "$folder" "$ver"
        echo "$db queda vinculada a $folder en XAMPP-$ver"
    fi
}

# Datos de un wp-config.php, uno por linea: base, usuario, servidor, prefijo y contraseña
function wp_config_read() {
    python3 -I - "$1" <<'EOF'
import os, re, sys
try:
    if not os.path.isfile(sys.argv[1]) or os.path.getsize(sys.argv[1]) > 2000000:
        raise OSError("no es un fichero normal")
    with open(sys.argv[1], encoding="utf-8", errors="replace") as f:
        text = f.read()
except OSError:
    sys.exit(1)
def const(name):
    # Solo las que no estan comentadas (// define( 'DB_USER', 'development' );)
    m = re.search(r"""(?m)^[ \t]*define\(\s*['"]%s['"]\s*,\s*(?:'((?:[^'\\]|\\.)*)'|"((?:[^"\\]|\\.)*)")""" % name, text)
    if not m:
        return ""
    return re.sub(r"\\(.)", r"\1", m.group(1) if m.group(1) is not None else m.group(2))
m = re.search(r"""(?m)^[ \t]*\$table_prefix\s*=\s*['"]([^'"]*)['"]""", text)
# Sin caracteres de control (salen en la terminal: un ESC cambiaria lo que se ve), salvo en la
# contraseña, que no se muestra
for i, v in enumerate((const("DB_NAME"), const("DB_USER"), const("DB_HOST"), m.group(1) if m else "", const("DB_PASSWORD"))):
    print(v.replace("\n", " ") if i == 4 else re.sub(r"[\x00-\x1f\x7f-\x9f]", "?", v))
EOF
}

# ===========================================================================
# Administrador de pruebas de los paneles (WordPress y PrestaShop)
# ===========================================================================
# Al cargar una BBDD (y al pulsar el boton del panel en Cargar proyecto) se le añade un administrador
# de pruebas, el mismo en todos los equipos: el boton abre la pantalla de acceso con el usuario y la
# contraseña ya escritos. Solo en las BBDD de este equipo (que nunca van a produccion)
TEST_ADMIN_USER="local@local.test"
TEST_ADMIN_PASS="local"
# (huella bcrypt de «local», para PrestaShop 1.7 o posterior; la 1.6 usa md5 de su _COOKIE_KEY_ y
# la contraseña, y WordPress acepta md5 y la cambia por la suya al entrar)
TEST_ADMIN_BCRYPT='$2y$12$IqVkFsJq4UhjbzLfagfW9eU5V6iIauQCbfMJDY26MoM8ETz6ZKgxG'

# Cliente de MariaDB como root para el administrador de pruebas (test_admin, wp_table_prefixes y
# ps_table_prefix): el de XAMPP-X (DB_CLIENT) o, si DB_ROOT_CLIENT (un array) tiene algo, ese. Asi
# test_admin sirve tambien para la BBDD de un contenedor de Docker (docker_test_admin)
DB_ROOT_CLIENT=()
function db_root_sql() {
    if [ ${#DB_ROOT_CLIENT[@]} -gt 0 ]; then
        "${DB_ROOT_CLIENT[@]}" "$@"
    else
        "${DB_SAFE[@]}" "$DB_CLIENT" -uroot "$@"
    fi
}

# usuario-pruebas <base> [carpeta]: crea o deja al dia el administrador de pruebas en los WordPress y
# la tienda PrestaShop de la base. Dice A|wp|usuario|contraseña y/o A|ps|... por cada uno (para la
# ventana); sale con 1 si no hay ninguno. La carpeta (o la recordada para la base) solo hace falta en
# PrestaShop 1.6, por su _COOKIE_KEY_
function test_admin() {
    local db=$1 folder=$2 p sql cols col exprs hash src key done_any=1
    if ! [[ "$db" =~ ^[A-Za-z0-9_][A-Za-z0-9_-]{0,63}$ ]]; then
        echo "Base no valida: $db"
        return 1
    fi
    [ -z "$folder" ] && folder=$(linked_folder "$db" "${DB_TARGET_FOLDER:-}")
    [[ "$folder" =~ ^[A-Za-z0-9_][A-Za-z0-9\ ._-]*$ ]] && [ -d "$HTDOCS_DIR/$folder" ] || folder=""
    # (el cliente de root de XAMPP-X o, con DB_ROOT_CLIENT, otro: el de la MariaDB de un contenedor)
    local mysql=(db_root_sql -N --default-character-set=utf8mb4)
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] administrador de pruebas $TEST_ADMIN_USER / $TEST_ADMIN_PASS en $db"
        return 0
    fi
    # (solo tablas de verdad: una vista del volcado ejecutaria sus funciones como root)
    function has_table() {
        [ "$("${mysql[@]}" -e "SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA='$db' AND TABLE_NAME='$1' AND TABLE_TYPE='BASE TABLE'" < /dev/null 2> /dev/null)" == 1 ]
    }

    # WordPress (todos los de la base): usuario con rol de administrador
    for p in $(wp_table_prefixes "$db"); do
        has_table "${p}usermeta" || continue
        sql=$(sed "s/@P@/$p/g" <<'SQL'
SET @id := (SELECT ID FROM `@P@users` WHERE user_login = 'local@local.test' ORDER BY ID LIMIT 1);
INSERT INTO `@P@users` (user_login, user_pass, user_nicename, user_email, user_url, user_registered, user_activation_key, user_status, display_name)
    SELECT 'local@local.test', MD5('local'), 'local-pruebas', 'local@local.test', '', NOW(), '', 0, 'Local (pruebas)' FROM DUAL WHERE @id IS NULL;
SET @id := IFNULL(@id, LAST_INSERT_ID());
UPDATE `@P@users` SET user_pass = MD5('local'), user_activation_key = '' WHERE ID = @id;
DELETE FROM `@P@usermeta` WHERE user_id = @id AND meta_key IN ('@P@capabilities', '@P@user_level');
INSERT INTO `@P@usermeta` (user_id, meta_key, meta_value) SELECT @id, '@P@capabilities', 'a:1:{s:13:"administrator";b:1;}' FROM DUAL WHERE @id > 0;
INSERT INTO `@P@usermeta` (user_id, meta_key, meta_value) SELECT @id, '@P@user_level', '10' FROM DUAL WHERE @id > 0;
SELECT CAST(IFNULL(@id, 0) AS UNSIGNED);
SQL
)
        if [ "$("${mysql[@]}" "$db" -e "$sql" < /dev/null 2> /dev/null | tail -1)" -gt 0 ] 2> /dev/null; then
            echo "A|wp|$TEST_ADMIN_USER|$TEST_ADMIN_PASS"
            done_any=0
        fi
    done

    # PrestaShop: una copia del primer SuperAdmin (mismas columnas, sea cual sea la version) con el
    # correo y la contraseña de pruebas, en todas las tiendas
    p=$(ps_table_prefix "$db")
    # (ps_table_prefix no da nada si la tienda no lleva prefijo)
    if has_table "${p}employee" && has_table "${p}employee_shop" && has_table "${p}shop" && has_table "${p}shop_url"; then
        src=$("${mysql[@]}" "$db" -e "SELECT passwd FROM \`${p}employee\` WHERE id_profile = 1 ORDER BY active DESC, id_employee LIMIT 1" < /dev/null 2> /dev/null)
        if [[ "$src" == '$'* ]]; then
            hash=$TEST_ADMIN_BCRYPT
        elif [ -n "$src" ]; then
            # PrestaShop 1.6: md5(_COOKIE_KEY_ + contraseña), con la clave de su settings.inc.php
            key=""
            [ -n "$folder" ] && key=$(python3 -I - "$HTDOCS_DIR/$folder/config/settings.inc.php" <<'EOF'
import re, sys
try:
    text = open(sys.argv[1], errors="replace").read(1000000)
except OSError:
    sys.exit(0)
m = re.search(r"""define\(\s*['"]_COOKIE_KEY_['"]\s*,\s*['"]([A-Za-z0-9]+)['"]""", text)
print(m.group(1) if m else "")
EOF
)
            [ -n "$key" ] && hash=$(python3 -I -c 'import hashlib, sys; print(hashlib.md5(sys.argv[1].encode()).hexdigest())' "$key$TEST_ADMIN_PASS")
        fi
        cols=$("${mysql[@]}" -e "SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='$db' AND TABLE_NAME='${p}employee' ORDER BY ORDINAL_POSITION" < /dev/null 2> /dev/null)
        if [ -z "$hash" ]; then
            [ -n "$src" ] && echo "Aviso: no se sabe la _COOKIE_KEY_ de la tienda (PrestaShop 1.6): sin administrador de pruebas. Cargala con su carpeta (Cargar proyecto)."
        elif [ -n "$cols" ] && ! grep -qvE '^[A-Za-z0-9_]+$' <<< "$cols"; then
            local list="" sel=""
            for col in $cols; do
                case $col in
                    id_employee) continue ;;
                    email) exprs="'local@local.test'" ;;
                    passwd) exprs="'$hash'" ;;
                    firstname) exprs="'Pruebas'" ;;
                    lastname) exprs="'Local'" ;;
                    active|id_profile) exprs=1 ;;
                    last_passwd_gen) exprs="NOW()" ;;
                    reset_password_token|reset_password_validity) exprs=NULL ;;
                    *) exprs="\`$col\`" ;;
                esac
                list+="${list:+, }\`$col\`" sel+="${sel:+, }$exprs"
            done
            sql="SET @src := (SELECT id_employee FROM \`${p}employee\` WHERE id_profile = 1 ORDER BY active DESC, id_employee LIMIT 1);
SET @id := (SELECT id_employee FROM \`${p}employee\` WHERE email = 'local@local.test' ORDER BY id_employee LIMIT 1);
INSERT INTO \`${p}employee\` ($list) SELECT $sel FROM \`${p}employee\` WHERE id_employee = @src AND @id IS NULL;
SET @id := IFNULL(@id, LAST_INSERT_ID());
UPDATE \`${p}employee\` SET passwd = '$hash', active = 1, id_profile = 1 WHERE id_employee = @id AND @src IS NOT NULL;
INSERT IGNORE INTO \`${p}employee_shop\` (id_employee, id_shop) SELECT @id, id_shop FROM \`${p}shop\` WHERE @id > 0 AND @src IS NOT NULL;
SELECT CAST(IF(@src IS NULL, 0, @id) AS UNSIGNED);"
            if [ "$("${mysql[@]}" "$db" -e "$sql" < /dev/null 2> /dev/null | tail -1)" -gt 0 ] 2> /dev/null; then
                echo "A|ps|$TEST_ADMIN_USER|$TEST_ADMIN_PASS"
                done_any=0
            fi
        fi
    fi
    unset -f has_table
    return $done_any
}

# Prefijos de los WordPress de una base: los de sus tablas <prefijo>options con <prefijo>users
function wp_table_prefixes() {
    [[ "$1" =~ ^[A-Za-z0-9_-]+$ ]] || return 0
    # Solo prefijos de letras, numeros y _ (los nombres de las tablas los trae la base)
    db_root_sql -N -e "SELECT LEFT(TABLE_NAME, LENGTH(TABLE_NAME) - 7) AS p FROM information_schema.TABLES
        WHERE TABLE_SCHEMA='$1' AND TABLE_TYPE='BASE TABLE' AND TABLE_NAME LIKE '%options' AND CONCAT(LEFT(TABLE_NAME, LENGTH(TABLE_NAME) - 7), 'users')
        IN (SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA='$1' AND TABLE_TYPE='BASE TABLE') ORDER BY LENGTH(p)" < /dev/null 2> /dev/null \
        | grep -E '^[A-Za-z0-9_]*$'
}

# ¿Entra la web en la base con estos datos? usuario contraseña servidor base tabla. Solo se prueba
# si el servidor es este equipo (nunca se conecta a uno de produccion). La base y la tabla van en
# la consulta: solo nombres validos (el prefijo de la tabla puede venir del wp-config.php)
function db_login_ok() {
    local user=$1 pass=$2 host=$3 db=$4 table=$5
    [ -n "$user" ] && [[ "$host" =~ ^(localhost|127\.0\.0\.1)(:.*)?$ ]] || return 1
    [[ "$db" =~ ^[A-Za-z0-9_-]+$ ]] && [[ "$table" =~ ^[A-Za-z0-9_]+$ ]] || return 1
    # Sin leer la tabla: podria ser una vista del volcado que ejecuta funciones con los permisos de
    # este usuario (root muchas veces). Basta con que la vea como tabla de verdad
    db_base_table "$user" "$pass" "$db" "$table"
}

# URL con la que se ve un proyecto en este equipo: su dominio propio (pestaña Hosts) o el vhost de
# los proyectos (el ServerName que tenga: web.local, localhost...), con https si tiene certificado
function wp_local_url() {
    local domain link
    domain=$(custom_domain "$1")
    if [ -n "$domain" ]; then
        echo "https://$domain"

        return 0
    fi
    link=$(project_link)
    vhosts_info | awk -F'|' -v l="${link:-$PROJECT_VHOST}" '
        $2 == l && $5 != "" && https == "" { https = "https://" $3 ($1 == 443 ? "" : ":" $1) }
        $2 == l && $5 == "" && http == "" { http = "http://" $3 ($1 == 80 ? "" : ":" $1) }
        END { print (https != "" ? https : http != "" ? http : "https://" l) }'
}

# wp-config <carpeta> [base]: comprueba el wp-config.php de un WordPress y, si no usa la base
# asociada (la indicada, la recordada para la carpeta o la suya si esta en local) o no entra en el
# MariaDB local, lo rehace con la plantilla
function wp_config() {
    local folder=${1%/} db=$2 dir file sample saved src name user host prefix pass new_prefix prefixes
    local s_name s_user s_host s_prefix s_pass local_db=0 try out url
    valid_project "$folder" || return 1
    dir=$HTDOCS_DIR/$folder file=$HTDOCS_DIR/$folder/wp-config.php sample=$HTDOCS_DIR/$folder/wp-config-sample.php
    if ! project_path_ok "$dir" "$file" || { [ -e "$sample" ] && ! project_path_ok "$dir" "$sample"; }; then
        echo "Aviso: wp-config.php de $folder es un enlace o esta fuera de la carpeta: no se toca"

        return 0
    fi
    saved=$WP_CONFIG_DIR/$folder.wp-config.php
    { IFS= read -r name; IFS= read -r user; IFS= read -r host; IFS= read -r prefix; IFS= read -r pass; } \
        < <(wp_config_read "$file")

    # Si MariaDB se acaba de arrancar (cambio de version), se le dan unos segundos
    for try in 1 2 3 4 5 6; do
        out=$("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N -e 'SELECT 1' < /dev/null 2>&1) && break
        [[ "$out" == *"Can't connect"* ]] && [ "$DRY" -eq 0 ] || break
        sleep 1
    done
    [ -z "$db" ] && db=$(saved_project_db "$folder")
    if [ -z "$db" ]; then
        # El nombre lo trae el wp-config.php: solo si es un nombre de base valido
        [[ "$name" =~ ^[A-Za-z0-9_][A-Za-z0-9_-]*$ ]] && db_exists "$name" 2> /dev/null && db=$name
    fi
    if [ -z "$db" ]; then
        echo "Aviso: el wp-config.php de $folder usa la base ${name:-(ninguna)}, que no esta en la"
        echo "version activa, y la carpeta no tiene una base asociada. Cargala desde el buscador de"
        echo "Bases de datos (Cargar proyecto) o al subirla elige el proyecto, y se corrige sola."

        return 0
    fi
    if ! [[ "$db" =~ ^[A-Za-z0-9_-]+$ ]] || ! db_exists "$db" 2> /dev/null; then
        echo "Aviso: la base $db de $folder no esta en la version activa: no se toca su wp-config.php"

        return 0
    fi
    prefixes=$(wp_table_prefixes "$db")
    if [ -z "$prefixes" ]; then
        echo "Aviso: la base $db no tiene las tablas de WordPress: no se toca el wp-config.php de $folder"

        return 0
    fi

    # Funciona en este equipo con la base asociada: es la plantilla para la proxima vez
    if [ "$name" == "$db" ] && grep -qxF -- "$prefix" <<< "$prefixes" && db_login_ok "$user" "$pass" "$host" "$db" "${prefix}options"; then
        if [ "$DRY" -eq 0 ] && ! cmp -s "$file" "$saved"; then
            mkdir -p "$WP_CONFIG_DIR" && cp "$file" "$saved"
        fi
        echo "WordPress: wp-config.php usa la base $db"

        return 0
    fi

    # Plantilla: la copia de este equipo, el propio fichero o wp-config-sample.php
    if [ -f "$saved" ]; then
        src=$saved
    elif [ -f "$file" ]; then
        src=$file
    elif [ -f "$sample" ]; then
        src=$sample
    else
        echo "Aviso: $folder no tiene wp-config.php ni wp-config-sample.php: no se puede crear"

        return 0
    fi
    { IFS= read -r s_name; IFS= read -r s_user; IFS= read -r s_host; IFS= read -r s_prefix; IFS= read -r s_pass; } \
        < <(wp_config_read "$src")
    # Prefijo: siempre uno que traen las tablas de la base (nunca se cambian las tablas). Con varios
    # WordPress en la base, el del wp-config.php del proyecto o el de la plantilla si la base lo
    # tiene; si no se sabe cual es, no se toca (un prefijo sin tablas abriria la instalacion)
    if grep -qxF -- "$prefix" <<< "$prefixes" && [ -f "$file" ]; then
        new_prefix=$prefix
    elif grep -qxF -- "$s_prefix" <<< "$prefixes"; then
        new_prefix=$s_prefix
    elif [ "$(wc -l <<< "$prefixes")" == 1 ]; then
        new_prefix=$prefixes
    else
        echo "Aviso: $db tiene tablas de varios WordPress (prefijos $(tr '\n' ' ' <<< "$prefixes"| sed 's/ $//'))"
        echo "y el wp-config.php de $folder no usa ninguno: no se toca. Pon en \$table_prefix el"
        echo "de su web y vuelve a cargar el proyecto."

        return 0
    fi
    # Usuario, contraseña y servidor de la plantilla si entran en local; si no, root y localhost
    db_login_ok "$s_user" "$s_pass" "$s_host" "$db" "${new_prefix}options" || local_db=1

    if [ "$name" != "$db" ]; then
        echo "WordPress: el wp-config.php de $folder usa la base ${name:-(ninguna)}${host:+ en $host}; la de la carpeta es $db"
    else
        echo "WordPress: el wp-config.php de $folder no entra en el MariaDB local${host:+ (servidor $host, usuario $user)}"
    fi
    case "$src" in
        "$saved") echo "Se rehace con la plantilla de este equipo, con la base $db" ;;
        "$sample") echo "Se crea a partir de wp-config-sample.php, con la base $db y claves nuevas" ;;
        *) echo "Se cambia a la base $db" ;;
    esac
    [ $local_db -eq 1 ] && echo "  Usuario root y servidor localhost (los de MariaDB local)"
    [ "$new_prefix" != "$s_prefix" ] && echo "  Prefijo de las tablas: $new_prefix (era ${s_prefix:-ninguno})"
    url=$(wp_local_url "$folder")
    echo "  WP_SITEURL y WP_HOME: $url"
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] $file con la base $db y copia en $saved"

        return 0
    fi

    mkdir -p -m 700 "$WP_CONFIG_DIR" || return 1
    if [ -f "$file" ] && ! cmp -s "$file" "$saved"; then
        mkdir -p -m 700 "$HOME/lvm-copias" && cp "$file" "$HOME/lvm-copias/wp-config.php-$folder-$(date +%Y%m%d-%H%M%S)" \
            && echo "  El anterior queda en ~/lvm-copias"
    fi
    LVM_WP_CLAVE=${MYSQL_PWD:-} python3 -I - "$src" "$WP_CONFIG_DIR/.nuevo" "$db" "$new_prefix" "$local_db" "$url" <<'EOF' || { echo "No se ha podido preparar el wp-config.php"; return 1; }
import os, re, secrets, string, sys
src, dst, db, prefix, local_db, url = sys.argv[1:7]
# newline="": se conservan los finales de linea (CRLF en muchos wp-config.php)
with open(src, encoding="utf-8", errors="surrogateescape", newline="") as f:
    text = f.read()
def php(v):
    return "'%s'" % v.replace("\\", "\\\\").replace("'", "\\'")
def put(text, name, value):
    rx = re.compile(r"""(?m)^([ \t]*define\(\s*['"]%s['"]\s*,\s*)(?:'(?:[^'\\]|\\.)*'|"(?:[^"\\]|\\.)*")""" % name)
    return rx.sub(lambda m: m.group(1) + php(value), text, count=1)
text = put(text, "DB_NAME", db)
if local_db == "1":
    text = put(text, "DB_USER", "root")
    text = put(text, "DB_PASSWORD", os.environ.get("LVM_WP_CLAVE", ""))
    text = put(text, "DB_HOST", "localhost")
text = re.sub(r"""(?m)^([ \t]*\$table_prefix\s*=\s*)(['"])[^'"]*\2""", lambda m: m.group(1) + php(prefix), text, count=1)
# La web en este equipo (si no, WordPress redirige al dominio de produccion guardado en la base)
nl = "\r\n" if "\r\n" in text else "\n"
missing = []
for name in ("WP_SITEURL", "WP_HOME"):
    rx = re.compile(r"""(?m)^([ \t]*define\(\s*['"]%s['"]\s*,\s*)(?:'(?:[^'\\]|\\.)*'|"(?:[^"\\]|\\.)*")""" % name)
    if rx.search(text):
        text = rx.sub(lambda m: m.group(1) + php(url), text, count=1)
    else:
        missing.append(name)
if missing:
    lines = "".join("define('%s', %s);%s" % (name, php(url), nl) for name in missing) + nl
    # Delante de los datos de la base, como en la plantilla del equipo; si no, detras de <?php
    m = re.search(r"""(?m)^[ \t]*(?://[^\r\n]*Database settings|define\(\s*['"]DB_NAME['"])""", text)
    if m:
        text = text[:m.start()] + lines + text[m.start():]
    else:
        m = re.search(r"<\?php[^\n]*\n", text)
        at = m.end() if m else 0
        text = text[:at] + nl + lines + text[at:]
# Sin editor de plugins y temas en el escritorio de WordPress: todos los proyectos van en el mismo
# origen (localhost), y un fallo XSS en uno podria usar ese editor en otro para ejecutar PHP
if not re.search(r"""(?m)^[ \t]*define\(\s*['"]DISALLOW_FILE_EDIT['"]""", text):
    line = "define('DISALLOW_FILE_EDIT', true); // lvm-instalador: sin editor de plugins en local" + nl
    m = re.search(r"""(?m)^[ \t]*(?:/\*[^\n]*stop editing|\$table_prefix\b)""", text)
    if m:
        text = text[:m.start()] + line + nl + text[m.start():]
    else:
        m = re.search(r"<\?php[^\n]*\n", text)
        at = m.end() if m else 0
        text = text[:at] + line + text[at:]
# wp-config-sample.php: claves nuevas
chars = string.ascii_letters + string.digits + "!#$%&()*+,-./:;<=>?@[]^_{|}~"
for key in ("AUTH_KEY", "SECURE_AUTH_KEY", "LOGGED_IN_KEY", "NONCE_KEY",
            "AUTH_SALT", "SECURE_AUTH_SALT", "LOGGED_IN_SALT", "NONCE_SALT"):
    rx = re.compile(r"""(?m)^([ \t]*define\(\s*['"]%s['"]\s*,\s*)['"]put your unique phrase here['"]""" % key)
    text = rx.sub(lambda m: m.group(1) + php("".join(secrets.choice(chars) for _ in range(64))), text, count=1)
with open(dst, "w", encoding="utf-8", errors="surrogateescape", newline="") as f:
    f.write(text)
EOF
    project_write "$WP_CONFIG_DIR/.nuevo" "$file" || { rm -f "$WP_CONFIG_DIR/.nuevo"; echo "No se ha podido escribir $file"; return 1; }
    mv "$WP_CONFIG_DIR/.nuevo" "$saved"
    echo "wp-config.php de $folder listo: base $db (plantilla guardada en $saved)"
}

# Datos de la base en la configuracion de una tienda (app/config/parameters.php o, en 1.6,
# config/settings.inc.php), uno por linea: fichero, base, usuario, servidor, prefijo y contraseña.
# Nada si no tiene configuracion con base (la crea ps_parameters).
function ps_db_read() {
    python3 -I - "$HTDOCS_DIR/$1" <<'EOF'
import os, re, sys
root = sys.argv[1]
quoted = r"""(?:'((?:[^'\\]|\\.)*)'|"((?:[^"\\]|\\.)*)")"""
rules = [
    ("app/config/parameters.php", r"""['"]%s['"]\s*=>\s*""" + quoted,
     ("database_name", "database_user", "database_host", "database_prefix", "database_password")),
    ("config/settings.inc.php", r"""(?m)^[ \t]*define\(\s*['"]%s['"]\s*,\s*""" + quoted,
     ("_DB_NAME_", "_DB_USER_", "_DB_SERVER_", "_DB_PREFIX_", "_DB_PASSWD_")),
]
for rel, rx, keys in rules:
    try:
        if not os.path.isfile(os.path.join(root, rel)) or os.path.getsize(os.path.join(root, rel)) > 2000000:
            raise OSError("no es un fichero normal")
        with open(os.path.join(root, rel), encoding="utf-8", errors="replace") as f:
            text = f.read()
    except OSError:
        continue
    values = []
    for i, key in enumerate(keys):
        m = re.search(rx % key, text)
        v = (m.group(1) if m.group(1) is not None else m.group(2)) if m else ""
        v = re.sub(r"\\(.)", r"\1", v)
        # Sin caracteres de control (salen en la terminal), salvo en la contraseña
        values.append(v.replace("\n", " ") if i == 4 else re.sub(r"[\x00-\x1f\x7f-\x9f]", "?", v))
    if values[0]:
        print(rel)
        for v in values:
            print(v)
        break
EOF
}

# Tienda cuya configuracion no usa la base asociada a la carpeta (base nueva subida para ella o
# codigo de produccion pegado encima): cambia la base y el prefijo de las tablas y, si sus datos no
# entran en el MariaDB local, pone root y localhost. Deja PS_NEW_PARAMS=1 para vaciar la cache.
function ps_set_db() {
    local folder=$1 db=$2 rel name user host prefix pass new_prefix local_db=0 file
    [[ "$db" =~ ^[A-Za-z0-9_-]+$ ]] || return 0
    { IFS= read -r rel; IFS= read -r name; IFS= read -r user; IFS= read -r host; IFS= read -r prefix; IFS= read -r pass; } \
        < <(ps_db_read "$folder")
    [ -n "$rel" ] || return 0
    file=$HTDOCS_DIR/$folder/$rel
    if ! project_path_ok "$HTDOCS_DIR/$folder" "$file"; then
        echo "Aviso: $rel de $folder es un enlace o esta fuera de la carpeta: no se toca"

        return 0
    fi
    if ! db_exists "$db" 2> /dev/null; then
        echo "Aviso: la base $db de $folder no esta en la version activa: no se toca $rel"

        return 0
    fi
    new_prefix=$(ps_table_prefix "$db" "$prefix")
    if [ -z "$new_prefix" ]; then
        echo "Aviso: la base $db no tiene la tabla shop_url de PrestaShop: no se toca $rel"

        return 0
    fi
    if [ "$name" == "$db" ] && [ "$prefix" == "$new_prefix" ] \
        && db_login_ok "$user" "$pass" "$host" "$db" "${new_prefix}shop_url"; then
        return 0
    fi
    db_login_ok "$user" "$pass" "$host" "$db" "${new_prefix}shop_url" || local_db=1

    if [ "$name" != "$db" ]; then
        echo "PrestaShop: $rel de $folder usa la base $name${host:+ en $host}; la de la carpeta es $db"
    else
        echo "PrestaShop: $rel de $folder no entra en el MariaDB local${host:+ (servidor $host, usuario $user)}"
    fi
    echo "Se cambia a la base $db"
    [ $local_db -eq 1 ] && echo "  Usuario root y servidor localhost (los de MariaDB local)"
    [ "$new_prefix" != "$prefix" ] && echo "  Prefijo de las tablas: $new_prefix (era ${prefix:-ninguno})"
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] $file con la base $db"

        return 0
    fi

    mkdir -p -m 700 "$PS_PARAMS_DIR" "$HOME/lvm-copias" || return 1
    cp "$file" "$HOME/lvm-copias/$(basename "$rel")-$folder-$(date +%Y%m%d-%H%M%S)" && echo "  El anterior queda en ~/lvm-copias"
    LVM_PS_CLAVE=${MYSQL_PWD:-} python3 -I - "$file" "$PS_PARAMS_DIR/.nuevo" "$db" "$new_prefix" "$local_db" <<'EOF' || { echo "No se ha podido preparar $rel"; return 1; }
import os, re, sys
src, dst, db, prefix, local_db = sys.argv[1:6]
# newline="": se conservan los finales de linea
with open(src, encoding="utf-8", errors="surrogateescape", newline="") as f:
    text = f.read()
def php(v):
    return "'%s'" % v.replace("\\", "\\\\").replace("'", "\\'")
value = r"""(?:'(?:[^'\\]|\\.)*'|"(?:[^"\\]|\\.)*"|NULL|null)"""
if src.endswith("parameters.php"):
    rx = r"""(['"]%s['"]\s*=>\s*)""" + value
    keys = dict(name="database_name", prefix="database_prefix", user="database_user",
                password="database_password", host="database_host", port="database_port")
else:
    rx = r"""(?m)^([ \t]*define\(\s*['"]%s['"]\s*,\s*)""" + value
    keys = dict(name="_DB_NAME_", prefix="_DB_PREFIX_", user="_DB_USER_", password="_DB_PASSWD_",
                host="_DB_SERVER_")
def put(text, key, v):
    return re.sub(rx % keys[key], lambda m: m.group(1) + php(v), text, count=1)
text = put(text, "name", db)
text = put(text, "prefix", prefix)
if local_db == "1":
    text = put(text, "user", "root")
    text = put(text, "password", os.environ.get("LVM_PS_CLAVE", ""))
    text = put(text, "host", "localhost")
    if "port" in keys:
        text = put(text, "port", "")
with open(dst, "w", encoding="utf-8", errors="surrogateescape", newline="") as f:
    f.write(text)
EOF
    project_write "$PS_PARAMS_DIR/.nuevo" "$file" || { rm -f "$PS_PARAMS_DIR/.nuevo"; echo "No se ha podido escribir $file"; return 1; }
    # La copia que se repone si se pierde parameters.php pasa a ser esta
    if [[ "$rel" == */parameters.php ]]; then
        mv "$PS_PARAMS_DIR/.nuevo" "$PS_PARAMS_DIR/$folder.parameters.php"
    else
        rm -f "$PS_PARAMS_DIR/.nuevo"
    fi
    echo "$rel de $folder listo: base $db"
    PS_NEW_PARAMS=1
}

function databases_text() {
    local version=$1 width=${2:-72}
    local names=$(db_names "$BASE_DIR/XAMPP-$version")
    local count=$(grep -c . <<< "$names")

    local text="XAMPP-$version: bases de datos propias\n"
    text+="\nBases de datos: $count (sin contar las del sistema)\n\n"
    text+="$(columns "$width" <<< "$names")\n"

    echo "$text"
}

function list_databases() {
    local dir

    for dir in $(version_dirs); do
        echo -e "$(databases_text "$(version_name "$dir")" "$(tput cols 2> /dev/null || echo 80)")"
        echo ""
    done
}

function disable_version() {
    if official_xampp; then
        echo "$LINK es un XAMPP oficial y no un enlace. No se puede ejecutar esta accion."

        return 1
    fi

    if [ -L "$LINK" ]; then
        run xampp_ctl stop
        run $SUDO rm "$LINK"
    fi
    # Sin version montada no queda ningun proceso de XAMPP en memoria (ni Mailpit)
    close_processes --todos
    mailpit_sync
}

# Lo que trae de serie el htdocs de un XAMPP oficial: no se copia a la carpeta compartida
OFFICIAL_DEFAULTS="applications.html|bitnami.css|dashboard|favicon.ico|img|index.php|webalizer|xampp|.DS_Store"

# ¿Sigue en marcha algun programa del XAMPP oficial? (con sudo: sin el, macOS no deja ver la orden
# completa de los procesos de otros usuarios, como MariaDB)
function official_running() {
    $SUDO pgrep -f "$LINK/xamppfiles/" > /dev/null 2>&1
}

# Para el XAMPP oficial y espera a que no quede nada en marcha (hasta 30 s)
function official_stop() {
    if [ -x "$LINK/xamppfiles/xampp" ]; then
        echo "Parando el XAMPP oficial..."
        if [ -z "$SUDO" ]; then
            xampp_ctl stop 2>&1 | sed 's/^/  /'
        else
            # Su script no se ejecuta como root (ver xampp_ctl): se cierran sus programas, que con
            # TERM terminan bien (tambien MariaDB). Solo los servidores de XAMPP, no cualquier proceso
            # que lleve la ruta en su orden (un editor, un tail)
            local p
            for p in $(kill_pids $($SUDO pgrep -f "$LINK/xamppfiles/" 2> /dev/null)); do
                case "$(basename "$($SUDO ps -o comm= -p "$p" 2> /dev/null)")" in
                    httpd|mysqld|mariadbd|proftpd|php-fpm) $SUDO kill -TERM "$p" 2> /dev/null ;;
                esac
            done
        fi
    fi
    local i
    for i in $(seq 30); do
        official_running || return 0
        sleep 1
    done
    echo "El XAMPP oficial sigue en marcha despues de pararlo:"
    $SUDO pgrep -lf "$LINK/xamppfiles/" 2> /dev/null | sed 's/^/  /'
    echo "No se mueve nada. Cierra su panel (manager-osx), paralo desde ahi y vuelve a intentarlo."

    return 1
}

# Descarga todas las bases del XAMPP oficial (ya parado) en <carpeta>/<base>.zip con un MariaDB
# temporal suyo: sin red, con un socket propio y sin comprobar usuarios (asi da igual que root
# tenga contraseña). Si alguna falla, devuelve error y no se aparta nada
function official_dump_all() {
    local dest=$1 root=$LINK/xamppfiles data=$LINK/xamppfiles/var/mysql server="" client="" dumper="" user b
    if [ ! -d "$data" ]; then
        echo "El XAMPP oficial no tiene bases de datos ($data no existe)."

        return 0
    fi
    for b in sbin/mariadbd sbin/mysqld bin/mariadbd bin/mysqld; do [ -x "$root/$b" ] && { server=$root/$b; break; }; done
    for b in bin/mariadb bin/mysql; do [ -x "$root/$b" ] && { client=$root/$b; break; }; done
    for b in bin/mariadb-dump bin/mysqldump; do [ -x "$root/$b" ] && { dumper=$root/$b; break; }; done
    if [ -z "$server" ] || [ -z "$client" ] || [ -z "$dumper" ]; then
        echo "No se encuentran el servidor o los clientes de MariaDB del XAMPP oficial en $root."

        return 1
    fi
    # El servidor, el cliente y mysqldump son del XAMPP oficial, que no ha comprobado nadie (en
    # /Applications escribe el grupo admin): nunca como root, sino con el dueño de sus datos (-L: el
    # de verdad si var/mysql es un enlace). Si son de root, no se copian
    user=$($SUDO stat -L -f %Su "$data") || return 1
    [ -n "$TEST_DIR" ] && user=$(id -un)
    if [ "$user" == "root" ] || ! [[ "$user" =~ ^[A-Za-z_][A-Za-z0-9_.-]*$ ]]; then
        echo "Las bases del XAMPP oficial son de $user: no se arranca su MariaDB con ese usuario."
        echo "Copialas desde su phpMyAdmin (Exportar), o dale los datos a su usuario de MariaDB"
        echo "(sudo chown -R _mysql \"$data\") y vuelve a intentarlo."

        return 1
    fi
    local as_owner=(${SUDO:+$SUDO -u "$user"})
    local defaults=(--no-defaults --basedir="$root")
    [ -f "$root/etc/my.cnf" ] && defaults=(--defaults-file="$root/etc/my.cnf")

    # La carpeta la crea root y solo es del usuario del servidor: no pide contraseña mientras dura
    # la copia (otros usuarios del Mac no pueden llegar a su socket)
    DB_TMP=$($SUDO mktemp -d /tmp/lvm-mysql-XXXX) || { DB_TMP=""; return 1; }
    DB_TMP_SOCK=$DB_TMP/mysql.sock
    $SUDO chown "$user" "$DB_TMP" && $SUDO chmod 700 "$DB_TMP" || return 1
    echo "Arrancando el MariaDB del XAMPP oficial solo para copiar sus bases (sin red)..."
    "${as_owner[@]}" "$server" "${defaults[@]}" --datadir="$data" --skip-networking --skip-grant-tables \
        --socket="$DB_TMP_SOCK" --pid-file="$DB_TMP/mysql.pid" --log-error="$DB_TMP/mysql.log" \
        < /dev/null > /dev/null 2>&1 &
    local server_pid=$! i
    DB_TMP_PID=$server_pid DB_TMP_USER=$user
    for i in $(seq 300); do
        $SUDO test -S "$DB_TMP_SOCK" && break
        kill -0 $server_pid 2> /dev/null || break
        sleep 0.2
    done
    if ! $SUDO test -S "$DB_TMP_SOCK"; then
        echo "No ha arrancado. Ultimas lineas de su registro:"
        # (lo lee el dueño de los datos, no root)
        $SUDO ${SUDO:+-u "$user"} /usr/bin/tail -15 "$DB_TMP/mysql.log" 2> /dev/null | sed 's/^/  /'
        db_temp_stop

        return 1
    fi

    local dbs db n=0 errors=$(mktemp) routines odd
    dbs=$("${as_owner[@]}" "$client" --no-defaults -S "$DB_TMP_SOCK" -uroot -N -e 'SHOW DATABASES' < /dev/null) || { db_temp_stop; return 1; }
    dbs=$(grep -vxE "$DB_SYSTEM" <<< "$dbs")
    # Solo nombres que se pueden usar como fichero y en las ordenes (sin /, espacios ni - delante)
    odd=$(grep -vE '^[A-Za-z0-9_][A-Za-z0-9_-]{0,63}$' <<< "$dbs" | grep .)
    dbs=$(grep -E '^[A-Za-z0-9_][A-Za-z0-9_-]{0,63}$' <<< "$dbs")
    echo "Bases de datos: $(grep -c . <<< "$dbs")"
    if [ -n "$odd" ]; then
        echo "Estas tienen un nombre que no se puede copiar asi (copialas desde su phpMyAdmin):"
        sed 's/^/  /' <<< "$odd"
    fi
    for db in $dbs; do
        routines=--routines
        while :; do
            if ( set -o pipefail; "${as_owner[@]}" "$dumper" --no-defaults -S "$DB_TMP_SOCK" -uroot --default-character-set=utf8mb4 \
                --single-transaction --quick $routines --triggers --max-allowed-packet=1G "$db" < /dev/null 2> "$errors" \
                | python3 -I -c "$ZIP_WRITE_PY" "$db.sql" > "$dest/$db.zip" ); then
                echo "  $db ($(du -h "$dest/$db.zip" | cut -f1))"
                n=$((n + 1))
                break
            fi
            rm -f "$dest/$db.zip"
            # Datos de un MariaDB anterior sin actualizar (mysql.proc con columnas de menos): sin rutinas
            if [ -n "$routines" ] && grep -q "mysql.proc" "$errors"; then
                routines=""
                echo "  $db: sin funciones ni procedimientos (mysql.proc es de un MariaDB anterior)"
                continue
            fi
            echo "  $db: no se ha podido copiar:"
            sed 's/^/    /' "$errors"
            rm -f "$errors"
            db_temp_stop

            return 1
        done
    done
    rm -f "$errors"
    db_temp_stop
    echo "$n bases copiadas en $dest"
}

# Copia los proyectos del htdocs del XAMPP oficial a la carpeta compartida (sin borrar los
# originales; en APFS, con cp -c, la copia es instantanea y no ocupa espacio hasta que cambian).
# Si ya hay algo con ese nombre en la carpeta compartida, no se toca y se avisa
function official_copy_projects() {
    local src=$LINK/xamppfiles/htdocs dst=$COMMON/htdocs entry name copied=0 skipped=()
    local user=${SUDO_USER:-$USER}
    local group=$(id -gn "$user")
    [ -d "$src" ] || { echo "El XAMPP oficial no tiene carpeta htdocs."; return 0; }
    if [ ! -d "$dst" ]; then
        $SUDO mkdir -p "$dst" && $SUDO chown "$user:$group" "$dst" || return 1
    fi
    echo "Copiando los proyectos de $src a $dst..."
    # Root copia en una carpeta suya de /tmp (el mismo volumen de datos que /Applications: mover es
    # al momento) y no dentro de htdocs, que es tuya: alli, un programa con tu usuario podria cambiar
    # el destino por un enlace a una carpeta del sistema justo antes de la copia. Lo copiado se pasa a
    # tu usuario ahi dentro y lo mueve a htdocs tu usuario (sin permisos de root)
    local stage as_user=() left=0
    [ "$(id -u)" == 0 ] && as_user=(sudo -u "$user")
    # (con rutas: el sudo de macOS no trae secure_path)
    stage=$($SUDO mktemp -d /tmp/lvm-copia.XXXXXX) && $SUDO chmod 700 "$stage" || return 1
    for entry in "$src"/* "$src"/.[!.]*; do
        [ -e "$entry" ] || [ -L "$entry" ] || continue
        name=$(basename "$entry")
        [[ "$name" =~ ^($OFFICIAL_DEFAULTS)$ ]] && continue
        if [ -e "$dst/$name" ] || [ -L "$dst/$name" ]; then
            skipped+=("$name")
            continue
        fi
        $SUDO cp -Rpc "$entry" "$stage/" 2> /dev/null || $SUDO cp -Rp "$entry" "$stage/" || {
            echo "No se ha podido copiar $name."
            $SUDO rm -rf "$stage"

            return 1
        }
        # macOS no protege los enlaces duros: uno de htdocs a un fichero de root que tu no puedes
        # leer quedaria copiado y tuyo. Se mira en la copia (cp -p deja su dueño y sus permisos): lo
        # que no es tuyo ni lo puede leer cualquiera no se pasa a tu usuario, se quita
        local rel
        while IFS= read -r -d '' rel; do
            $SUDO rm -f "$rel"
            echo "  No se copia ${rel#"$stage"/}: no es tuyo ni lo puede leer cualquiera"
        done < <($SUDO find "$stage/$name" ! -type d ! -type l ! -user "$user" ! -perm -004 -print0 2> /dev/null)
        $SUDO chown -Rh "$user:$group" "$stage/$name"
        copied=$((copied + 1))
    done
    # La carpeta pasa a tu usuario (ya no queda nada que hacer como root) y tu usuario lo mueve
    $SUDO chown "$user:$group" "$stage" || { $SUDO rm -rf "$stage"; return 1; }
    for entry in "$stage"/* "$stage"/.[!.]*; do
        [ -e "$entry" ] || [ -L "$entry" ] || continue
        name=$(basename "$entry")
        if [ -e "$dst/$name" ] || [ -L "$dst/$name" ] || ! "${as_user[@]}" /bin/mv "$entry" "$dst/$name"; then
            echo "  No se ha podido mover $name a $dst (queda en $stage)"
            left=1
        fi
    done
    [ $left -eq 0 ] && "${as_user[@]}" /bin/rmdir "$stage" 2> /dev/null
    echo "  $copied copiados"
    if [ ${#skipped[@]} -gt 0 ]; then
        echo "  Ya existian en la carpeta compartida y no se han tocado: ${skipped[*]}"
        echo "  (los originales siguen en el XAMPP oficial apartado, en xamppfiles/htdocs)"
    fi
}

# Añade los vhosts del XAMPP oficial al fichero compartido y comprueba la configuracion de Apache
# con una version instalada. Si no es valida, deja el fichero como estaba y avisa (no impide apartar)
function official_copy_vhosts() {
    local backup=$1 src=$LINK/xamppfiles/etc/extra/httpd-vhosts.conf s="" dir check=""
    [ -f "$src" ] || return 0
    cp "$src" "$backup/httpd-vhosts-del-xampp-oficial.conf"
    if ! grep -qvE '^[[:space:]]*(#|$)' "$src"; then
        echo "Sus vhosts estan todos comentados: no hay nada que copiar."

        return 0
    fi
    if [ ! -f "$VHOSTS_FILE" ]; then
        echo "No existe $VHOSTS_FILE: sus vhosts no se copian (estan en $backup)."

        return 0
    fi
    # Se lee una sola vez: lo que se comprueba es lo que se escribe (y lo de antes, para dejarlo como
    # estaba, tambien de aqui y no de la copia de tu carpeta, que podria cambiar otro programa)
    local content before
    content=$(sed -E "$OLD_LOGS_SED" "$src") && before=$(cat "$VHOSTS_FILE") || return 1
    # Solo directivas de vhosts (Apache arranca como root: nada de ordenes, modulos ni Include)
    if ! python3 -I -c "$VHOSTS_CHECK_PY" /dev/stdin "$VHOSTS_FILE" <<< "$content" > /dev/null; then
        echo "Sus vhosts llevan directivas que cambiarian todo Apache: no se copian. Estan en"
        echo "$backup/httpd-vhosts-del-xampp-oficial.conf: copia a mano los que necesites con Editar vhosts."

        return 0
    fi
    [ -w "$VHOSTS_FILE" ] || s=$SUDO
    if [ -n "$s" ] && ! vhosts_path_ok; then
        echo "No se copian sus vhosts: $VHOSTS_FILE tiene que ser un fichero normal de $COMMON (sin enlaces)."
        echo "Estan en $backup/httpd-vhosts-del-xampp-oficial.conf."
        return 0
    fi
    printf '%s\n' "$before" > "$backup/httpd-vhosts-compartido-antes.conf"
    echo "Añadiendo sus vhosts a $VHOSTS_FILE..."
    { printf '\n# ---- Copiado del XAMPP oficial el %s ----\n' "$(date '+%d/%m/%Y %H:%M')"
      printf '%s\n' "$content"
      printf '\n# ---- Fin de lo copiado del XAMPP oficial ----\n'; } | $s tee -a "$VHOSTS_FILE" > /dev/null || return 1
    # (con el httpd de una version de root: lo ejecuta root)
    for dir in $(version_dirs); do
        [ -x "$dir/xamppfiles/apache2/bin/httpd" ] || continue
        [ -z "$SUDO" ] || [ -n "$TEST_DIR" ] || trusted_version_dir "$dir" || continue
        check=$($SUDO "$dir/xamppfiles/apache2/bin/httpd" -t -f "$dir/xamppfiles/etc/httpd.conf" 2>&1) && return 0
        break
    done
    [ -z "$check" ] && return 0
    printf '%s\n' "$before" | $s tee "$VHOSTS_FILE" > /dev/null
    echo "Aviso: con sus vhosts, Apache no arrancaria:"
    sed 's/^/  /' <<< "$check" | head -8
    echo "Se ha dejado $VHOSTS_FILE como estaba. Sus vhosts estan en"
    echo "$backup/httpd-vhosts-del-xampp-oficial.conf: copialos a mano con Editar vhosts."
}

# Aparta un XAMPP oficial de /Applications/XAMPP para poder usar el enlace, sin borrar nada:
#   1. lo para y comprueba que no queda nada en marcha (si no, no se mueve nada)
#   2. copia todas sus bases (.zip) en ~/lvm-copias/XAMPP-oficial-<fecha>
#   3. copia sus proyectos a XAMPP-compartido/htdocs y sus vhosts al fichero compartido
#   4. mueve la carpeta a /Applications/XAMPP-oficial-<fecha> (volver-oficial la devuelve)
function set_aside_official() {
    official_xampp || { echo "No hay ningun XAMPP oficial en $LINK."; return 0; }
    local stamp=$(date +%Y%m%d-%H%M%S)
    local aside="$APPS_DIR/XAMPP-oficial-$stamp" user=${SUDO_USER:-$USER} home=$HOME
    [ -n "$SUDO_USER" ] && home=$(dscl . -read "/Users/$SUDO_USER" NFSHomeDirectory 2> /dev/null | awk '{ print $2 }')
    local backup="$home/lvm-copias/XAMPP-oficial-$stamp"

    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] parar el XAMPP oficial y comprobar que no queda nada en marcha"
        echo "  [simulacion] copiar sus bases de datos (.zip) en $backup"
        echo "  [simulacion] copiar sus proyectos a $COMMON/htdocs y sus vhosts a $VHOSTS_FILE"
        echo "  [simulacion] mover $LINK a $aside"

        return 0
    fi

    trap db_cleanup EXIT
    trap 'exit 130' INT TERM HUP
    official_stop || return 1
    mkdir -p -m 700 "$home/lvm-copias" && mkdir -p "$backup" || return 1
    # Si algo falla, la carpeta de copias queda como incompleta-… (la ventana no la ofrece para cargar)
    local failed="No se ha apartado nada: el XAMPP oficial sigue en $LINK."
    official_dump_all "$backup" || { mv "$backup" "$home/lvm-copias/incompleta-XAMPP-oficial-$stamp"; echo "$failed"; return 1; }
    if official_running; then
        mv "$backup" "$home/lvm-copias/incompleta-XAMPP-oficial-$stamp"
        echo "El XAMPP oficial se ha vuelto a arrancar: no se mueve nada."

        return 1
    fi
    official_copy_projects || { mv "$backup" "$home/lvm-copias/incompleta-XAMPP-oficial-$stamp"; echo "$failed"; return 1; }
    official_copy_vhosts "$backup"
    printf 'carpeta=%s\nfecha=%s\n' "$aside" "$stamp" > "$backup/xampp-oficial.txt"
    # Solo si esto corre como root (con tu usuario, todo lo de la carpeta ya es tuyo), y solo lo que
    # ha creado root: un enlace duro que pusiera ahi otro programa (macOS no los protege) a un
    # fichero del sistema no pasa a tu usuario
    [ "$(id -u)" == 0 ] && find "$backup" -user 0 \( -type d -o -type f -links 1 \) -exec chown -h "$user" {} + 2> /dev/null

    $SUDO mv "$LINK" "$aside" || return 1
    echo ""
    echo "Hecho. No se ha borrado nada:"
    echo "  - El XAMPP oficial esta ahora en $aside (con todo lo suyo)."
    echo "  - Copia de sus bases de datos: $backup"
    echo "  - Sus proyectos estan tambien en $COMMON/htdocs."
    echo "Ahora activa una version y, en Configuración de la ventana, carga las bases del XAMPP oficial."
    echo "Para deshacerlo: lvm-instalador volver-oficial."
}

# importar-copias <carpeta>: carga en la version activa las bases .zip de una carpeta (las del XAMPP
# oficial apartado). Las que ya existen en la version activa no se tocan
function import_backups() {
    local folder=$1 f db rc loaded=0 skipped=() failed=()
    if [ -z "$folder" ] || [ ! -d "$folder" ]; then
        echo "Uso: lvm-instalador importar-copias <carpeta con copias .zip>"

        return 1
    fi
    db_connect
    rc=$?
    [ $rc -ne 0 ] && return $rc
    for f in "$folder"/*.zip; do
        [ -f "$f" ] || continue
        db=$(basename "$f" .zip)
        if ! db_valid_name "$db" > /dev/null; then
            failed+=("$db (nombre no valido: cargala a mano con otro nombre)")
            continue
        fi
        if db_exists "$db"; then
            skipped+=("$db")
            continue
        fi
        echo ""
        echo "== $db"
        if ( import_database "$f" "$db" --crear ); then
            loaded=$((loaded + 1))
        else
            failed+=("$db")
        fi
    done
    echo ""
    echo "Cargadas en XAMPP-$DB_FOLDER: $loaded"
    [ ${#skipped[@]} -gt 0 ] && echo "Ya existian y no se han tocado: ${skipped[*]}"
    if [ ${#failed[@]} -gt 0 ]; then
        echo "No se han podido cargar: ${failed[*]}"

        return 1
    fi
    return 0
}

# volver-oficial [carpeta]: deshace el apartado. Para y desactiva la version activa del gestor, y
# devuelve el XAMPP oficial apartado (el mas reciente si no se indica) a /Applications/XAMPP y lo
# arranca. Las versiones del gestor, sus bases y las copias no se tocan
function restore_official() {
    local aside=$1
    [ -z "$aside" ] && aside=$(ls -d "$APPS_DIR"/XAMPP-oficial-* 2> /dev/null | sort | tail -1)
    if [ -z "$aside" ] || [ ! -d "$aside" ] || [[ "$(basename "$aside")" != XAMPP-oficial-* ]]; then
        echo "No hay ningun XAMPP oficial apartado en $APPS_DIR."

        return 1
    fi
    if official_xampp; then
        echo "Ya hay un XAMPP oficial en $LINK: no se puede devolver $aside."

        return 1
    fi
    if [ -L "$LINK" ]; then
        echo "Parando y desactivando $(basename "$(readlink "$LINK")")..."
        run xampp_ctl stop
        run $SUDO rm "$LINK" || return 1
    fi
    run $SUDO mv "$aside" "$LINK" || return 1
    echo "El XAMPP oficial vuelve a estar en $LINK. Arrancalo desde su panel (manager-osx): el gestor"
    echo "no ejecuta su script como administrador."
}

# Motivo por el que no se puede desinstalar una version (vacio si se puede)
function remove_blocker() {
    local version=$1
    local dir=$BASE_DIR/XAMPP-$version

    if [ -z "$version" ] || [[ "$version" == */* ]] || [ ! -d "$dir" ] || [ -L "$dir" ] || [ ! -f "$dir/xamppfiles/etc/pvm-stack" ]; then
        echo "No existe la version $version."
    elif [ "$(active_dir)" == "$dir" ]; then
        echo "XAMPP-$version es la version activa. Cambia antes a otra version (o desactivala) y vuelve a intentarlo."
    elif [ -e "$dir/xamppfiles/htdocs" ] && [ ! -L "$dir/xamppfiles/htdocs" ]; then
        # htdocs deberia ser un enlace a la carpeta compartida; si es real puede tener proyectos
        echo "XAMPP-$version tiene una carpeta htdocs propia (no es un enlace a $COMMON/htdocs) y podria contener proyectos.\nRevisala y muevela a mano antes de desinstalar."
    fi
}

# Copia comprimida de las bases de datos de una version (sin la version en marcha)
function backup_databases() {
    local version=$1 dir=${2:-$BASE_DIR/XAMPP-$1}
    local user=${SUDO_USER:-$USER}
    local dest_dir=$(dscl . -read "/Users/$user" NFSHomeDirectory 2> /dev/null | awk '{ print $2 }')/lvm-copias
    local dest="$dest_dir/XAMPP-$version-bases-$(date +%Y%m%d-%H%M%S).tar.gz"

    echo "Guardando copia de las bases de datos en $dest..."
    run mkdir -p -m 700 "$dest_dir" || return 1
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] tar -czf $dest -C $dir/xamppfiles/var mysql"

        return 0
    fi

    # Las bases las lee su dueño (en el Mac, tu usuario, con el que corre MariaDB), no root: macOS no
    # protege los enlaces duros, y uno de var/mysql a un fichero de root (una clave) acabaria dentro
    # de la copia. Solo si son de root las lee root. El fichero lo crea tu usuario (solo para ti)
    local owner reader=($SUDO tar)
    owner=$(stat -f %Su "$dir/xamppfiles/var/mysql" 2> /dev/null)
    if [ -n "$owner" ] && [ "$owner" != root ]; then
        reader=(tar)
        [ "$owner" != "$(id -un)" ] && reader=(sudo -u "$owner" /usr/bin/tar)
    fi
    if [ "$(id -u)" -eq 0 ] && [ "$user" != root ]; then
        "${reader[@]}" -czf - -C "$dir/xamppfiles/var" mysql | sudo -u "$user" /bin/sh -c 'umask 077; cat > "$1"' sh "$dest.parte" \
            || { rm -f "$dest.parte"; return 1; }
    else
        ( umask 077; "${reader[@]}" -czf - -C "$dir/xamppfiles/var" mysql > "$dest.parte" ) || { rm -f "$dest.parte"; return 1; }
    fi
    mv -f "$dest.parte" "$dest" || return 1
    echo "Copia guardada: $dest ($(du -h "$dest" | cut -f1))"
}

function remove_version() {
    local version=$1
    local blocker=$(remove_blocker "$version")

    if [ -n "$blocker" ]; then
        echo -e "$blocker"

        return 1
    fi

    # htdocs y vhosts son enlaces: rm no los sigue
    run $SUDO rm -R "$BASE_DIR/XAMPP-$version" || return 1
    # (y el enlace que dejo migrar en /Applications, si llevaba a ella)
    if [ -z "$TEST_DIR" ] && [ -L "$LEGACY_DIR/XAMPP-$version" ] \
            && [ "$(readlink "$LEGACY_DIR/XAMPP-$version")" == "$BASE_DIR/XAMPP-$version" ]; then
        run $SUDO rm "$LEGACY_DIR/XAMPP-$version"
    fi

    if [ "$DRY" -eq 1 ]; then
        echo "SIMULACION: no se ha borrado nada"
    else
        echo "XAMPP-$version desinstalada"
    fi
}

# ===========================================================================
# Pila propia de una version de PHP
# ===========================================================================

# Progreso de la instalacion, para la barra del panel. Las funciones de instalacion escriben en el
# archivo $PROGRESS (si esta definido) lineas como estas:
#   C|componente 1;componente 2;...               componentes de la version que se instala
#   S|n|desde|hasta|texto|modo|archivo|total|hora  empieza un paso del componente n
# <desde>-<hasta> es el tramo de la barra (en % de la version). Dentro del tramo se avanza segun
# <modo>: lines (lineas de un log), bytes (tamaño de un archivo que se descarga), time (segundos)
# o percent (ultimo "[ NN%]" del log, como el que escribe CMake).
function progress_parts() {
    [ -n "$PROGRESS" ] && echo "C|$(IFS=';'; echo "$*")" >> "$PROGRESS"
    return 0
}

function progress() {
    [ -n "$PROGRESS" ] && echo "S|$1|$2|$3|$4|$5|$6|$7|$(date +%s)" >> "$PROGRESS"
    return 0
}

# Tamaño de un archivo remoto en bytes (siguiendo redirecciones)
function remote_size() {
    curl -q --proto =https --proto-redir =https -fsSLI --max-time 15 "$1" 2> /dev/null | tr -d '\r' | awk 'tolower($1) == "content-length:" {n = $2} END {print n + 0}'
}

# Descarga una URL a la salida estandar. Se guarda una hora en cache, porque las pantallas
# del panel consultan las mismas paginas varias veces.
# (Todas las descargas van con curl -q: sin ~/.curlrc, que cualquier programa tuyo podria preparar
# con --insecure o un proxy suyo)
function fetch() {
    local cache=$LOG_DIR/cache
    local file=$cache/$(md5 -q -s "$1")

    # Al instalar (FETCH_FRESH=1) no se pasa por la cache: es tuya (cualquier programa tuyo la puede
    # cambiar) y de ahi salen las direcciones y las huellas de lo que se instala como root
    if [ "${FETCH_FRESH:-0}" == 1 ]; then
        curl -q --proto =https --proto-redir =https -fsSL --max-time 30 "$1" 2> /dev/null
        return
    fi
    if [ ! -s "$file" ] || [ -n "$(find "$file" -mmin +60 2> /dev/null)" ]; then
        mkdir -p "$cache"
        if ! curl -q --proto =https --proto-redir =https -fsSL --max-time 30 "$1" > "$file.$$" 2> /dev/null; then
            rm -f "$file.$$"

            return 1
        fi
        mv "$file.$$" "$file"
    fi

    cat "$file"
}

# Ultima version de cada rama de STACK_MATRIX publicada en php.net, aunque ya no tenga soporte
# (de la mas nueva a la mas antigua):
# "8.4 8.4.26 <sha256 del .tar.xz>"
function php_releases() {
    local i branch

    # De la rama mas nueva a la mas antigua, como se muestran en el panel y en la ventana
    for (( i = ${#STACK_MATRIX[@]} - 1; i >= 0; i-- )); do
        branch=${STACK_MATRIX[i]%%|*}
        fetch "https://www.php.net/releases/index.php?json&version=$branch" | python3 -I -c 'import json, re, sys
data = json.load(sys.stdin)
import datetime
sha = [s["sha256"] for s in data.get("source", []) if s["filename"].endswith(".tar.xz")]
try:
    date = datetime.datetime.strptime(data.get("date", ""), "%d %b %Y").strftime("%Y-%m-%d")
except ValueError:
    date = "-"
# (rama, ultimo parche, su sha256, su fecha y si php.net lo marca como parche de seguridad)
# (solo X.Y.Z y una suma de verdad: con un | o un salto de linea descolocaria las lineas de la ventana)
if re.match(r"^\d+\.\d+\.\d+$", str(data.get("version", ""))) and sha and re.match(r"^[0-9a-f]{64}$", sha[0]):
    print(sys.argv[1], data["version"], sha[0], date,
          "seguridad" if "security" in (data.get("tags") or []) else "-")' "$branch" 2> /dev/null
    done
}

# Todas las versiones publicadas de PHP 7, 8 y 9: "8.4.26 2026-09-24 seguridad|-", de la mas nueva
# a la mas antigua (fecha de cada una para las versiones instaladas)
function php_all_releases() {
    local major

    for major in 7 8 9; do
        # Una rama mayor que aun no existe (9) devuelve {"error": ...} y no cuenta como fallo
        fetch "https://www.php.net/releases/index.php?json&version=$major&max=1000" | python3 -I -c 'import json, re, sys, datetime
data = json.load(sys.stdin)
for version, info in (data.items() if "error" not in data else []):
    # (solo X.Y.Z: con un | o un salto de linea descolocaria las lineas de la ventana)
    if re.match(r"^\d+\.\d+\.\d+$", version):
        try:
            date = datetime.datetime.strptime(info.get("date", ""), "%d %b %Y").strftime("%Y-%m-%d")
        except ValueError:
            date = "-"
        print(version, date, "seguridad" if "security" in (info.get("tags") or []) else "-")' 2> /dev/null || true
    done | python3 -I -c 'import sys
rows = [l.split() for l in sys.stdin if l.strip()]
rows.sort(key=lambda r: [int(x) for x in r[0].split(".")], reverse=True)
for r in rows: print(" ".join(r))'
}

# Ramas de PHP con soporte oficial (las demas se marcan como "sin soporte" en el panel)
function php_supported() {
    fetch "https://www.php.net/releases/active.php" \
        | python3 -I -c 'import json, re, sys
for branches in json.load(sys.stdin).values():
    for branch in branches:
        if re.match(r"^\d+\.\d+$", str(branch)):
            print(branch)' 2> /dev/null
}

# Estado de cada rama en php.net: rama|estado|fin del soporte activo|fin de los parches de seguridad
#   estado: stable (correcciones de errores y de seguridad), security (solo de seguridad) o eol
function php_branch_states() {
    fetch "https://www.php.net/releases/branches.php" | python3 -I -c 'import json, re, sys
for b in json.load(sys.stdin):
    if not re.match(r"^\d+\.\d+$", str(b.get("branch", ""))) or b.get("state") not in ("stable", "security", "eol"):
        continue
    print("%s|%s|%s|%s" % (b.get("branch", ""), b.get("state", ""),
                           (b.get("active_support_end") or "")[:10], (b.get("security_support_end") or "")[:10]))' 2> /dev/null
}

# Texto del estado de una rama para el panel: estable, solo seguridad o sin soporte
function branch_state_text() {
    local st=$(grep "^$1|" <<< "$2" | cut -d'|' -f2)
    case "$st" in
        stable) echo "estable" ;;
        security) echo "solo seguridad" ;;
        eol) echo "sin soporte" ;;
        *) grep -qxF "$1" <<< "$3" && echo "con soporte" || echo "sin soporte" ;;
    esac
}

# Ramas de los componentes que lleva una rama de PHP: "apache mariadb proftpd perl".
function stack_branches() {
    local row

    # Solo las ramas de la tabla: antes una desconocida recibia sin avisar la de la ultima fila
    for row in "${STACK_MATRIX[@]}"; do
        if [ "${row%%|*}" == "$1" ]; then
            echo "$row" | cut -d'|' -f2- | tr '|' ' '

            return 0
        fi
    done

    return 1
}

# Ultimo parche publicado de cada componente
function latest_apache() {
    fetch https://dlcdn.apache.org/httpd/ | grep -oE "href=\"httpd-$1\.[0-9]+\.tar\.bz2\"" \
        | grep -oE '[0-9]+\.[0-9]+\.[0-9]+' | vsort | tail -1
}

# latest_apr apr|apr-util
function latest_apr() {
    fetch https://dlcdn.apache.org/apr/ | grep -oE "href=\"$1-1\.[0-9]+\.[0-9]+\.tar\.bz2\"" \
        | grep -oE '[0-9]+\.[0-9]+\.[0-9]+' | vsort | tail -1
}

# Ultima version de una rama de MariaDB: "version|url del codigo fuente|sha256"
# (MariaDB no publica binarios para macOS, asi que se compila)
function mariadb_release() {
    fetch "https://downloads.mariadb.org/rest-api/mariadb/$1/latest/" | python3 -I -c 'import json, re, sys
for version, release in json.load(sys.stdin)["releases"].items():
    # Va en URLs, carpetas y ficheros de configuracion: solo una version normal
    if not re.fullmatch(r"[0-9]+\.[0-9]+\.[0-9]+", version):
        continue
    files = [f for f in release["files"] if f["file_name"] == "mariadb-%s.tar.gz" % version]
    if files:
        url = files[0]["file_download_url"].replace("http://", "https://", 1)
        sha = (files[0].get("checksum") or {}).get("sha256sum", "")
        if not url.startswith("https://") or "|" in url or not re.fullmatch(r"[0-9a-f]{64}", sha):
            continue
        print(version + "|" + url + "|" + sha)
        break' 2> /dev/null
}

function latest_perl() {
    fetch https://www.cpan.org/src/5.0/ | grep -oE "perl-$1\.[0-9]+\.tar\.xz\"" \
        | grep -oE '5\.[0-9]+\.[0-9]+' | vsort | tail -1
}

# ProFTPD publica parches con letra (1.3.9, 1.3.9a, 1.3.9b...). Se descartan las versiones rc.
function latest_proftpd() {
    local tags

    tags=$(fetch "https://api.github.com/repos/proftpd/proftpd/releases?per_page=50" | python3 -I -c 'import json, sys
for release in json.load(sys.stdin):
    # Solo las que publican el .sha256 del tar.gz: sin el no se puede comprobar la descarga
    assets = [a["name"] for a in release.get("assets", [])]
    if not release["prerelease"] and any(a.endswith(".tar.gz.sha256") for a in assets):
        print(release["tag_name"])' 2> /dev/null)

    # La API de GitHub limita las consultas: si falla, se leen las etiquetas con git
    if [ -z "$tags" ] && command -v git > /dev/null; then
        tags=$(/usr/bin/python3 -I -c "$NO_TTY_PY" git -c credential.helper= ls-remote --tags https://github.com/proftpd/proftpd 2> /dev/null < /dev/null | grep -oE 'v[0-9.]+[a-z]?$')
    fi

    grep -E "^v$(echo "$1" | sed 's/\./\\./g')[a-z]?$" <<< "$tags" | sed 's/^v//' | vsort | tail -1
}

# phpMyAdmin 6 necesita PHP 8.1 o posterior: las ramas anteriores se quedan con la 5.2
function latest_pma() {
    local branch=$1
    local version=$(fetch https://www.phpmyadmin.net/home_page/version.json \
        | python3 -I -c 'import json, sys; print(json.load(sys.stdin)["version"])' 2> /dev/null)
    # Va en URLs y en la configuracion de Apache: solo numeros y puntos
    [[ "$version" =~ ^[0-9]+(\.[0-9]+){1,3}$ ]] || version=""

    if [ -n "$version" ] && [ "${version%%.*}" -ge 6 ] && { [ "$branch" == "7.4" ] || [ "$branch" == "8.0" ]; }; then
        version=$PMA_VERSION
    fi

    echo "${version:-$PMA_VERSION}"
}

# Versiones de una pila: "php|apache|mariadb|proftpd|perl|phpmyadmin".
# Si no se puede consultar algun componente, se muestra su rama seguida de ".x".
function stack_versions() {
    local php=$1 branches
    read -r -a branches <<< "$(stack_branches "${php%.*}")"

    local apache=$(latest_apache "${branches[0]}")
    local mariadb=$(mariadb_release "${branches[1]}")
    mariadb=${mariadb%%|*}
    local ftp=$(latest_proftpd "${branches[2]}")
    local perl=$(latest_perl "${branches[3]}")

    echo "$php|${apache:-${branches[0]}.x}|${mariadb:-${branches[1]}.x}|${ftp:-${branches[2]}.x}|${perl:-${branches[3]}.x}|$(latest_pma "${php%.*}")"
}

# Comprueba una firma OpenPGP suelta del codigo fuente (en texto, .asc, o binaria) contra las claves
# de un proyecto, solo con Python del sistema: sin gnupg de Homebrew, que en las versiones de macOS
# sin paquetes ya hechos se compila entero (con python, meson, gnutls...). Firmas v4 de un fichero
# (tipo 0), RSA (PKCS#1 v1.5, de 2048 bits o mas) o EdDSA (Ed25519), con SHA-2 (sin SHA-1). Vale la
# firma de la clave principal o de una subclave de firmar con su firma de enlace de la principal y la
# de vuelta de la subclave (como gpg); nada revocado. Una clave caducada vale para lo que firmo (como
# gpgv). Uso: <fichero> <firma> <huellas que se aceptan>, con las claves (en base64) en la entrada.
# Solo es buena si escribe FIRMA-BUENA <huella de la clave principal> (no basta con que termine bien)
SIG_VERIFY_PY='
import base64, hashlib, sys, time
path, sig_path, want = sys.argv[1], sys.argv[2], sys.argv[3].upper().split()
def no(why):
    sys.stderr.write("Firma: %s\n" % why)
    sys.exit(1)
class Mal(Exception):
    pass
def packets(data):
    i, out = 0, []
    while i < len(data):
        b = data[i]
        if not b & 0x80:
            raise Mal("paquete OpenPGP no valido")
        if b & 0x40:
            tag, o = b & 0x3F, data[i + 1] if i + 1 < len(data) else 0
            if o < 192:
                n, h = o, 2
            elif o < 224:
                if i + 2 >= len(data):
                    raise Mal("paquete cortado")
                n, h = ((o - 192) << 8) + data[i + 2] + 192, 3
            elif o == 255:
                n, h = int.from_bytes(data[i + 2:i + 6], "big"), 6
            else:
                raise Mal("longitud parcial no admitida")
        else:
            tag, lt = (b >> 2) & 0x0F, b & 3
            if lt == 3:
                raise Mal("longitud indeterminada no admitida")
            size = (1, 2, 4)[lt]
            n, h = int.from_bytes(data[i + 1:i + 1 + size], "big"), 1 + size
        body = data[i + h:i + h + n]
        if len(body) != n or i + h > len(data):
            raise Mal("paquete cortado")
        out.append((tag, body))
        i += h + n
    return out
def mpi(b, i):
    if i + 2 > len(b):
        raise Mal("numero cortado")
    bits = int.from_bytes(b[i:i + 2], "big")
    n = (bits + 7) // 8
    if i + 2 + n > len(b):
        raise Mal("numero cortado")
    return b[i + 2:i + 2 + n], i + 2 + n
# Firma en texto (ASCII armor) o en binario
def dearmor(raw):
    if raw[:1] and raw[0] & 0x80:
        return raw
    try:
        lines = raw.decode("ascii").replace("\r", "").split("\n")
    except UnicodeDecodeError:
        raise Mal("la firma no es OpenPGP")
    try:
        a = lines.index("-----BEGIN PGP SIGNATURE-----")
        z = lines.index("-----END PGP SIGNATURE-----", a)
    except ValueError:
        raise Mal("la firma no es OpenPGP")
    body, i = lines[a + 1:z], 0
    while i < len(body) and body[i].strip():
        if ":" not in body[i]:
            break
        i += 1
    body = [l.strip() for l in body[i:] if l.strip()]
    crc = None
    if body and body[-1].startswith("=") and len(body[-1]) == 5:
        crc = body.pop()[1:]
    try:
        data = base64.b64decode("".join(body), validate=True)
    except ValueError:
        raise Mal("firma en texto no valida")
    if crc is not None:
        c = 0xB704CE
        for x in data:
            c ^= x << 16
            for _ in range(8):
                c <<= 1
                if c & 0x1000000:
                    c ^= 0x1864CFB
        if base64.b64decode(crc) != (c & 0xFFFFFF).to_bytes(3, "big"):
            raise Mal("la firma en texto esta estropeada (CRC)")
    return data
# Ed25519 (RFC 8032), solo para comprobar
P = 2 ** 255 - 19
Q = 2 ** 252 + 27742317777372353535851937790883648493
D = -121665 * pow(121666, P - 2, P) % P
SQRT_M1 = pow(2, (P - 1) // 4, P)
def recover_x(y, sign):
    xx = (y * y - 1) * pow(D * y * y + 1, P - 2, P) % P
    x = pow(xx, (P + 3) // 8, P)
    if (x * x - xx) % P:
        x = x * SQRT_M1 % P
    if (x * x - xx) % P:
        return None
    if x == 0 and sign:
        return None
    if x & 1 != sign:
        x = P - x
    return x
def add(a, b):
    x1, y1, z1, t1 = a
    x2, y2, z2, t2 = b
    A = (y1 - x1) * (y2 - x2) % P
    B = (y1 + x1) * (y2 + x2) % P
    C = 2 * t1 * t2 * D % P
    E = 2 * z1 * z2 % P
    e, f, g, h = B - A, E - C, E + C, B + A
    return (e * f % P, g * h % P, f * g % P, e * h % P)
def mul(s, a):
    r = (0, 1, 1, 0)
    while s:
        if s & 1:
            r = add(r, a)
        a = add(a, a)
        s >>= 1
    return r
def encode(a):
    zi = pow(a[2], P - 2, P)
    x, y = a[0] * zi % P, a[1] * zi % P
    return (y | ((x & 1) << 255)).to_bytes(32, "little")
def decode(s):
    if len(s) != 32:
        return None
    y = int.from_bytes(s, "little")
    sign, y = y >> 255, y & ((1 << 255) - 1)
    if y >= P:
        return None
    x = recover_x(y, sign)
    return None if x is None else (x, y, 1, x * y % P)
BY = 4 * pow(5, P - 2, P) % P
BASE = (recover_x(BY, 0), BY, 1, recover_x(BY, 0) * BY % P)
def ed25519_ok(pub, msg, sig):
    a, r = decode(pub), decode(sig[:32])
    s = int.from_bytes(sig[32:], "little")
    if a is None or r is None or s >= Q:
        return False
    h = int.from_bytes(hashlib.sha512(sig[:32] + pub + msg).digest(), "little") % Q
    return encode(mul(s, BASE)) == encode(add(r, mul(h, a)))
# Resumenes admitidos (sin SHA-1 ni MD5) y su DigestInfo para RSA (PKCS#1 v1.5)
HASHES = {8: hashlib.sha256, 9: hashlib.sha384, 10: hashlib.sha512, 11: hashlib.sha224}
DIGEST_INFO = {8: "3031300d060960864801650304020105000420", 9: "3041300d060960864801650304020205000430",
               10: "3051300d060960864801650304020305000440", 11: "302d300d06096086480165030402040500041c"}
ED_OID = bytes.fromhex("2B06010401DA470F01")
# Clave publica v4: (huella, creada, algoritmo, material) o None si no se puede usar
def pubkey(kb):
    if len(kb) < 6 or kb[0] != 4:
        return None
    fpr = hashlib.sha1(b"\x99" + len(kb).to_bytes(2, "big") + kb).hexdigest().upper()
    made, algo = int.from_bytes(kb[1:5], "big"), kb[5]
    try:
        if algo in (1, 3):
            n, i = mpi(kb, 6)
            e, i = mpi(kb, i)
            n, e = int.from_bytes(n, "big"), int.from_bytes(e, "big")
            if n.bit_length() < 2048 or e < 3 or not e & 1:
                return None
            return (fpr, made, "rsa", (n, e), kb)
        if algo == 22 and len(kb) > 7 and kb[6] == len(ED_OID) and kb[7:7 + len(ED_OID)] == ED_OID:
            q, _ = mpi(kb, 7 + len(ED_OID))
            if len(q) != 33 or q[0] != 0x40:
                return None
            return (fpr, made, "ed", q[1:], kb)
    except Mal:
        return None
    return None
def subpackets(b):
    i, out = 0, []
    while i < len(b):
        o = b[i]
        if o < 192:
            n, h = o, 1
        elif o < 255:
            if i + 1 >= len(b):
                raise Mal("subpaquete no valido")
            n, h = ((o - 192) << 8) + b[i + 1] + 192, 2
        else:
            n, h = int.from_bytes(b[i + 1:i + 5], "big"), 5
        if n < 1 or i + h + n > len(b):
            raise Mal("subpaquete no valido")
        out.append((b[i + h] & 0x7F, b[i + h] & 0x80, b[i + h + 1:i + h + n]))
        i += h + n
    return out
# Firma v4: dict con lo que hace falta, o Mal si no se entiende
KNOWN = (2, 3, 4, 5, 7, 9, 11, 12, 16, 21, 22, 23, 25, 27, 30, 31, 32, 33)
def parse_sig(sb):
    if len(sb) < 10 or sb[0] != 4:
        raise Mal("firma que no es v4")
    hl = int.from_bytes(sb[4:6], "big")
    if 6 + hl + 2 > len(sb):
        raise Mal("firma cortada")
    hashed = sb[6:6 + hl]
    ul = int.from_bytes(sb[6 + hl:8 + hl], "big")
    unhashed = sb[8 + hl:8 + hl + ul]
    rest = sb[8 + hl + ul:]
    hs, us = subpackets(hashed), subpackets(unhashed)
    for t, crit, v in hs:
        # Uno critico que no se conoce: no se puede dar por buena (como gpgv)
        if crit and t not in KNOWN:
            raise Mal("subpaquete critico desconocido (%d)" % t)
    s = {"type": sb[1], "algo": sb[2], "hash": sb[3], "trailer": sb[:6 + hl], "hs": hs, "us": us}
    s["made"] = next((int.from_bytes(v, "big") for t, c, v in hs if t == 2 and len(v) == 4), None)
    s["life"] = next((int.from_bytes(v, "big") for t, c, v in hs if t == 3 and len(v) == 4), 0)
    s["flags"] = next((v[0] for t, c, v in hs if t == 27 and v), None)
    s["fprs"] = [v[1:].hex().upper() for t, c, v in hs + us if t == 33 and len(v) == 21 and v[0] == 4]
    s["ids"] = [v.hex().upper() for t, c, v in hs + us if t == 16 and len(v) == 8]
    s["embedded"] = [v for t, c, v in hs + us if t == 32]
    if len(rest) < 2:
        raise Mal("firma cortada")
    s["prefix"] = rest[:2]
    if s["algo"] in (1, 3):
        m, i = mpi(rest, 2)
        s["mpis"] = (m,)
    elif s["algo"] == 22:
        r, i = mpi(rest, 2)
        q, i = mpi(rest, i)
        s["mpis"] = (r, q)
    else:
        raise Mal("algoritmo de firma no admitido (%d)" % s["algo"])
    if i != len(rest):
        raise Mal("firma con datos de mas")
    return s
def by(s, key):
    # (la firma dice de que clave es: con la huella, o con el ID largo si no la trae)
    return key[0] in s["fprs"] or (not s["fprs"] and key[0][-16:] in s["ids"])
def check(s, key, h):
    # h: el resumen ya con los datos firmados; se le añade la cola de la firma
    if s["hash"] not in HASHES or s["made"] is None or s["made"] < key[1]:
        return False
    h.update(s["trailer"])
    h.update(b"\x04\xff" + len(s["trailer"]).to_bytes(4, "big"))
    digest = h.digest()
    if s["prefix"] != digest[:2]:
        return False
    if key[2] == "rsa" and s["algo"] in (1, 3):
        n, e = key[3]
        k = (n.bit_length() + 7) // 8
        sig = int.from_bytes(s["mpis"][0], "big")
        if sig >= n:
            return False
        t = bytes.fromhex(DIGEST_INFO[s["hash"]]) + digest
        if k < len(t) + 11:
            return False
        return pow(sig, e, n).to_bytes(k, "big") == b"\x00\x01" + b"\xff" * (k - len(t) - 3) + b"\x00" + t
    if key[2] == "ed" and s["algo"] == 22:
        r, q = s["mpis"]
        if len(r) > 32 or len(q) > 32:
            return False
        return ed25519_ok(key[3], digest, r.rjust(32, b"\0") + q.rjust(32, b"\0"))
    return False
def key_hash(s, *keys):
    h = HASHES[s["hash"]]() if s["hash"] in HASHES else hashlib.sha256()
    for k in keys:
        h.update(b"\x99" + len(k[4]).to_bytes(2, "big") + k[4])
    return h
def good_sig(body, signer, want_type, *keys):
    try:
        s = parse_sig(body)
    except Mal:
        return None
    if s["type"] != want_type or not by(s, signer) or not check(s, signer, key_hash(s, *keys)):
        return None
    return s
# Las claves (de stdin, en base64): las principales, y las subclaves de firmar con su firma de enlace
# (de la principal) y la de vuelta (de la subclave), como gpg. Nada revocado
try:
    ring = packets(base64.b64decode("".join(sys.stdin.read().split()), validate=True))
except (ValueError, Mal):
    no("las claves no son validas")
signers, primary, sub, where, cur_sigs = {}, None, None, None, []
def close():
    if where == "key" and any(good_sig(b, primary, 0x20, primary) for b in cur_sigs):
        primary[5]["revoked"] = True
    if where != "sub" or any(good_sig(b, primary, 0x28, primary, sub) for b in cur_sigs):
        return
    for b in cur_sigs:
        s = good_sig(b, primary, 0x18, primary, sub)
        if not s or (s["flags"] is not None and not s["flags"] & 0x02):
            continue
        if any(good_sig(e, sub, 0x19, primary, sub) for e in s["embedded"]):
            signers[sub[0]] = (sub, primary)
            return
for tag, body in ring:
    if tag in (6, 13, 14, 17):
        close()
        where, cur_sigs = None, []
    if tag == 6:
        primary = pubkey(body)
        if primary is not None:
            primary += ({},)
            signers[primary[0]] = (primary, primary)
            where = "key"
    elif tag == 14 and primary is not None:
        sub = pubkey(body)
        if sub is not None:
            sub += ({},)
            where = "sub"
    elif tag == 2:
        cur_sigs.append(body)
close()
# Las de firmar: de las huellas que se aceptan para este proyecto y sin revocar
usable = [(k, p) for k, p in signers.values() if p[0] in want and not p[5].get("revoked")]
if not usable:
    no("no hay ninguna clave de las esperadas")
# La firma (en texto o binaria): de un fichero (tipo 0), de una de esas claves
with open(sig_path, "rb") as f:
    raw = f.read(65537)
if len(raw) > 65536:
    no("la firma es demasiado grande")
try:
    sp = packets(dearmor(raw))
except Mal as e:
    no(str(e))
if not sp or any(t != 2 for t, b in sp):
    no("no es una firma suelta")
cands = []
for t, b in sp:
    try:
        s = parse_sig(b)
    except Mal as e:
        no(str(e))
    if s["type"] != 0:
        no("tipo de firma no admitido")
    if s["hash"] not in HASHES:
        no("resumen no admitido (%d)" % s["hash"])
    if s["life"] and (s["made"] is None or time.time() > s["made"] + s["life"]):
        no("la firma ha caducado")
    for k, p in usable:
        if by(s, k):
            cands.append((s, k, p))
if not cands:
    no("la firma no es de ninguna de las claves esperadas")
hs = {}
with open(path, "rb") as f:
    for s, k, p in cands:
        hs.setdefault(s["hash"], HASHES[s["hash"]]())
    for chunk in iter(lambda: f.read(1 << 20), b""):
        for h in hs.values():
            h.update(chunk)
for s, k, p in cands:
    if check(s, k, hs[s["hash"]].copy()):
        print("FIRMA-BUENA %s" % p[0])
        sys.exit(0)
no("la firma no es buena o el fichero no es el firmado")
'

# gpg_verify <archivo> <firma> <PHP|APACHE|MARIADB|PMA>: ¿es buena la firma y de una de las claves de
# GPG_FPRS_<...>? Con SIG_VERIFY_PY, solo con esas claves (ni las tuyas ni un servidor de claves)
function gpg_verify() {
    local file=$1 sig=$2 keys=GPG_KEYS_$3 fprs=GPG_FPRS_$3 out="" fpr why
    [ -n "${!keys}" ] && [ -n "${!fprs}" ] && [ -n "$SIG_VERIFY_PY" ] \
        || { echo "  No hay claves para comprobar $(basename "$file")"; return 1; }
    out=$(/usr/bin/python3 -I -c "$SIG_VERIFY_PY" "$file" "$sig" "${!fprs}" <<< "${!keys}" 2>&1) || out="NO $out"
    # FIRMA-BUENA <huella de la clave principal> (y que sea una de las del proyecto)
    fpr=$(awk '$1 == "FIRMA-BUENA" && NF == 2 && NR == 1 { print $2 }' <<< "$out")
    if [[ "$fpr" =~ ^[0-9A-F]{40}$ ]] && [ "$(wc -l <<< "$out")" -eq 1 ] && [[ " ${!fprs} " == *" $fpr "* ]]; then
        echo "  Firma de $(basename "$file") comprobada (clave ${fpr: -16})"
        return 0
    fi
    why=$(sed -n 's/^\(NO \)\{0,1\}Firma: //p' <<< "$out" | head -1)
    echo "  La firma de $(basename "$file") no es buena o no es de quien lo publica${why:+ ($why)}. Se cancela."
    return 1
}

# download <url> <archivo> <sha256> [<url de la firma> <PHP|APACHE|MARIADB|PMA>]: descarga un archivo y
# comprueba su suma y, si se indica, su firma GPG (gpg_verify)
function download() {
    local url=$1 file=$2 sum=$3 sig_url=$4 keys=$5

    if [ -z "$sum" ]; then
        echo "  No se ha encontrado la suma sha256 de $(basename "$url")"

        return 1
    fi

    echo "  Descargando $(basename "$url")..."
    curl -q --proto =https --proto-redir =https -fsSL --retry 2 -o "$file" "$url" || { echo "  No se pudo descargar $url"; return 1; }

    if [ "$(sha256_of "$file")" != "$sum" ]; then
        echo "  $(basename "$url") no coincide con su suma sha256. Se cancela."

        return 1
    fi

    if [ -n "$sig_url" ]; then
        curl -q --proto =https --proto-redir =https -fsSL --retry 2 -o "$file.firma" "$sig_url" \
            || { echo "  No se pudo descargar la firma de $(basename "$url") ($sig_url). Se cancela."; return 1; }
        gpg_verify "$file" "$file.firma" "$keys" || return 1
    fi
}

# download_apache <ruta> <archivo>: dlcdn solo tiene la ultima version; si no esta, archive.apache.org
function download_apache() {
    local base sum

    for base in https://dlcdn.apache.org https://archive.apache.org/dist; do
        sum=$(curl -q --proto =https --proto-redir =https -fsSL "$base/$1.sha256" 2> /dev/null | grep -oE '^[0-9a-f]{64}')
        [ -n "$sum" ] && download "$base/$1" "$2" "$sum" "$base/$1.asc" APACHE && return 0
    done

    return 1
}

# step <componente> <desde> <hasta> <lineas> <descripcion> <log> <comando...>
# Un paso de la compilacion, con su salida en un log. <desde>-<hasta> es el tramo de la barra de
# progreso (en % de la version) y <lineas> las que suele tener el log al terminar (0 = el log
# escribe "[ NN%]", como CMake).
# Informe para buscar la solucion de un fallo al instalar: el sistema, lo que se instalaba, el paso
# que fallo con sus primeros errores y el final de su log y, si fallo un configure, la ultima prueba
# de su config.log (ahi esta la causa real). Se guarda con los logs; la ventana lo muestra para
# copiarlo de una vez.
# error_report <informe> <lo que se instalaba> <log del paso o ""> <paso> <config.log o "">
function error_report() {
    local out=$1 what=$2 log=$3 desc=$4 config=$5
    {
        echo "$APP_NAME $APP_VERSION - error al instalar"
        echo "Fecha: $(date '+%Y-%m-%d %H:%M')"
        echo "Sistema: macOS $(sw_vers -productVersion 2> /dev/null) ($(uname -m))"
        echo "Compilador: $(cc --version 2> /dev/null | head -1)"
        echo "Instalacion: $what"
        if [ -n "$log" ] && [ -f "$log" ]; then
            echo "Paso que fallo: $desc ($(basename "$log"))"
            local errors=$(grep -E -m 10 '(error:|Error:|ERROR|CMake Error|Undefined symbols|No such file)' "$log" | cut -c1-300)
            [ -n "$errors" ] && printf '\n== Primeros errores ==\n%s\n' "$errors"
            printf '\n== Ultimas 60 lineas de %s ==\n' "$(basename "$log")"
            tail -60 "$log"
        fi
        if [ -n "$config" ] && [ -f "$config" ]; then
            printf '\n== config.log: lo ultimo antes del error ==\n'
            awk '/^## Cache variables/ {exit} {print}' "$config" | grep -v '^## -* ##$' | tail -60
        fi
        printf '\nLogs completos: %s\n' "$(dirname "$out")"
    } > "$out" 2>&1
}

