# Ejecuta una orden en una sesion nueva, sin terminal de control: NO_TTY_PY <orden> [argumentos...]
NO_TTY_PY='
import os, signal, sys
# El hijo, en su sesion; este proceso se queda en el grupo de la tarea y le pasa las señales de
# Cancelar o Ctrl-C (si no, la compilacion seguiria despues de cancelar)
pid = os.fork()
if pid == 0:
    os.setsid()
    try:
        os.execvp(sys.argv[1], sys.argv[1:])
    except OSError as e:
        sys.stderr.write("%s: %s\n" % (sys.argv[1], e.strerror))
        os._exit(127)
def forward(sig, _):
    try:
        os.killpg(pid, sig)
    except OSError:
        pass
for s in (signal.SIGTERM, signal.SIGINT, signal.SIGHUP):
    signal.signal(s, forward)
while True:
    try:
        _, status = os.waitpid(pid, 0)
        break
    except InterruptedError:
        continue
sys.exit(os.WEXITSTATUS(status) if os.WIFEXITED(status) else 128 + os.WTERMSIG(status))
'

# no_tty <orden> [argumentos...]: para programas que leen tu configuracion (git, ssh, certutil). Sin
# terminal de control (no pueden usar el permiso de sudo recordado ni abrir /dev/tty) y sin la terminal
# en sus descriptores: la salida pasa por una tuberia, asi que nada que dejen en marcha puede quedarse
# leyendola hasta que sudo pida la contraseña
function no_tty() {
    ( set -o pipefail; /usr/bin/python3 -I -c "$NO_TTY_PY" "$@" < /dev/null 2>&1 | cat )
}

function step() {
    local part=$1 from=$2 to=$3 lines=$4 desc=$5 log=$6
    shift 6

    if [ "$lines" -eq 0 ]; then
        progress "$part" "$from" "$to" "${desc,,}" percent "$log" 100
    else
        progress "$part" "$from" "$to" "${desc,,}" lines "$log" "$lines"
    fi
    printf '  [%3d%%] %s...\n' "$from" "$desc"
    # Sin terminal (en su propia sesion): lo que se compila esta en una carpeta tuya y lo puede cambiar
    # cualquier programa tuyo; con la terminal de la tarea podria usar el permiso de sudo que ya se ha
    # dado (sudo -n). Sin ella, sudo le pediria la contraseña y falla
    if ! /usr/bin/python3 -I -c "$NO_TTY_PY" "$@" > "$log" 2>&1 < /dev/null; then
        echo "  ERROR: $desc. Ultimas lineas de $(basename "$log"):"
        tail -25 "$log" | sed 's/^/    /'
        STEP_LOG=$log STEP_DESC=$desc
        # Compilando en paralelo, el error real queda lejos del final (tapado por avisos de otros
        # procesos): se repiten al final los primeros errores, que salen tambien en el resumen
        local errors=$(grep -E -m 5 '(error:|Error:|CMake Error|Undefined symbols)' "$log" | cut -c1-200)
        [ -n "$errors" ] && echo "  Primeros errores:" && sed 's/^/    /' <<< "$errors"

        return 1
    fi
}

# Quita de los flags de un build de CMake la carpeta usr/include del SDK de macOS. La meten los
# .pc de Homebrew para librerias del sistema (zlib, libxml2...), que apuntan a un SDK concreto
# (MacOSX14.sdk) distinto del que usa el compilador (MacOSX.sdk), y CMake no la reconoce como del
# sistema: con -I queda por delante de las cabeceras de C++ (c++/v1) y no compila nada en C++
# ("<cstddef> tried including <stddef.h> but didn't find libc++'s <stddef.h>"). El compilador ya
# busca en el SDK por su cuenta, asi que quitarla no cambia nada mas.
# strip_sdk_includes <carpeta del build>
function strip_sdk_includes() {
    local files
    files=$(grep -rlE --include=flags.make -e '-(I|isystem ?)"?[^ "]*/SDKs/MacOSX[0-9.]*\.sdk/usr/include"?( |$)' "$1")
    [ -z "$files" ] && return 0
    echo "lvm-instalador: quitando la carpeta usr/include del SDK de los flags de:"
    while IFS= read -r file; do
        echo "  $file"
        sed -i '' -E 's#-(I|isystem ?)"?[^ "]*/SDKs/MacOSX[0-9.]*\.sdk/usr/include"?( |$)##g' "$file"
    done <<< "$files"
}

# Copia dentro de <carpeta>/lib las librerias de Homebrew que usan los binarios de la pila y cambia
# sus referencias a esa copia (con la ruta final <destino>/lib), para que la version siga
# funcionando aunque se actualice o desinstale Homebrew. Los archivos tocados se vuelven a firmar
# (en Apple Silicon un binario modificado sin firmar no arranca).
# bundle_libs <carpeta en el area temporal> <ruta final de esa carpeta>
function bundle_libs() {
    python3 -I - "$1" "$2" <<'EOF'
import os, shutil, subprocess, sys

stage, final = sys.argv[1], sys.argv[2]
stage_lib, final_lib = os.path.join(stage, "lib"), os.path.join(final, "lib")
MAGIC = {b"\xcf\xfa\xed\xfe", b"\xca\xfe\xba\xbe"}

def is_macho(path):
    try:
        with open(path, "rb") as f:
            return f.read(4) in MAGIC
    except OSError:
        return False

def deps(path):
    out = subprocess.run(["otool", "-L", path], capture_output=True, text=True).stdout.splitlines()[1:]
    return [line.strip().split(" (")[0] for line in out if line.strip()]

def rpaths(path):
    out = subprocess.run(["otool", "-l", path], capture_output=True, text=True).stdout.splitlines()
    found = []
    for i, line in enumerate(out):
        if "cmd LC_RPATH" in line:
            for extra in out[i + 1:i + 4]:
                extra = extra.strip()
                if extra.startswith("path "):
                    found.append(extra.split()[1])
    return found

def resolve(dep, origin):
    base = os.path.dirname(origin)
    if dep.startswith(("@loader_path/", "@executable_path/")):
        return os.path.realpath(os.path.join(base, dep.split("/", 1)[1]))
    if dep.startswith("@rpath/"):
        for rp in rpaths(origin):
            rp = rp.replace("@loader_path", base).replace("@executable_path", base)
            candidate = os.path.join(rp, dep[len("@rpath/"):])
            if os.path.exists(candidate):
                return os.path.realpath(candidate)
        return None
    return dep

def tool(*args):
    subprocess.run(list(args), check=True, capture_output=True)

os.makedirs(stage_lib, exist_ok=True)
queue = []
for dirpath, _, files in os.walk(stage):
    for name in files:
        path = os.path.join(dirpath, name)
        if not os.path.islink(path) and is_macho(path):
            queue.append((path, path))

copied, changed = {}, set()
while queue:
    path, origin = queue.pop()
    for dep in deps(path):
        real = resolve(dep, origin)
        if not real or not real.startswith("/opt/homebrew/"):
            continue
        name = os.path.basename(dep)
        new = os.path.join(final_lib, name)
        if name not in copied:
            dest = os.path.join(stage_lib, name)
            shutil.copy2(real, dest)
            os.chmod(dest, 0o755)
            tool("install_name_tool", "-id", new, dest)
            copied[name] = real
            changed.add(dest)
            queue.append((dest, real))
        tool("install_name_tool", "-change", dep, new, path)
        changed.add(path)

for path in changed:
    tool("codesign", "--force", "--sign", "-", path)

print("  %d librerias de Homebrew copiadas en %s" % (len(copied), final_lib))
EOF
}

# OpenSSL 1.1.1w estatico para PHP 7.4 y 8.0 (en <deps>, solo para compilar). Ocupa 5 puntos de
# la barra desde <inicio>.
function build_openssl11() {
    local deps=$1 p=$2

    tar -xzf openssl11.tar.gz && cd "openssl-$OPENSSL11_VERSION" || return 1
    step 3 $p $((p + 1)) 30 "OpenSSL $OPENSSL11_VERSION: configurando" "$build/openssl11-configure.log" \
        ./Configure darwin64-arm64-cc no-shared no-tests --prefix="$deps" --openssldir=/private/etc/ssl || return 1
    step 3 $((p + 1)) $((p + 4)) 1700 "OpenSSL $OPENSSL11_VERSION: compilando" "$build/openssl11-make.log" make -j"$jobs" || return 1
    step 3 $((p + 4)) $((p + 5)) 300 "OpenSSL $OPENSSL11_VERSION: instalando" "$build/openssl11-install.log" make install_sw || return 1
    cd "$build" || return 1
}

# ICU 72.1 estatico para PHP 7.4, 8.0 y 8.1 (en <deps>, solo para compilar). Ocupa 5 puntos de
# la barra desde <inicio>.
function build_icu72() {
    local deps=$1 p=$2

    tar -xzf icu72.tgz && cd icu/source || return 1
    step 3 $p $((p + 1)) 250 "ICU 72.1: configurando" "$build/icu72-configure.log" \
        ./runConfigureICU MacOSX --prefix="$deps" --enable-static --disable-shared --with-data-packaging=static \
        --disable-tests --disable-samples --disable-extras || return 1
    step 3 $((p + 1)) $((p + 4)) 900 "ICU 72.1: compilando" "$build/icu72-make.log" make -j"$jobs" || return 1
    step 3 $((p + 4)) $((p + 5)) 200 "ICU 72.1: instalando" "$build/icu72-install.log" make install || return 1
    cd "$build" || return 1
}

# Crea en xamppfiles/var/mysql unas bases de datos nuevas y vacias: solo las del sistema de
# MariaDB, root sin contraseña (como XAMPP) y la base 'phpmyadmin' con el usuario 'pma'.
function init_stack_databases() {
    local target=$1 user=$2
    local data=$target/var/mysql my=$target/mysql cnf=$target/etc/my.cnf

    if [ -e "$data" ]; then
        echo "Ya existe $data, no se crean bases de datos nuevas"

        return 1
    fi

    echo "  Creando bases de datos propias y vacias..."
    # (el ayudante de PAM no se copia a la version; si estuviera, fuera antes: mariadb-install-db le
    # daria la carpeta a tu usuario con un programa setuid de root dentro)
    $SUDO rm -rf "$my/lib/plugin/auth_pam_tool_dir" || return 1
    $SUDO "$my/scripts/mariadb-install-db" --defaults-file="$cnf" --basedir="$my" --datadir="$data" --user="$user" \
        --auth-root-authentication-method=normal --skip-test-db > "$LOG_DIR/install-db.log" 2>&1 \
        || { tail -20 "$LOG_DIR/install-db.log"; return 1; }
    # (y despues, por si acaso)
    $SUDO rm -rf "$my/lib/plugin/auth_pam_tool_dir"

    # Apache y PHP-FPM tienen que poder llegar a mysql.sock, que esta en esta carpeta
    $SUDO chown "$user" "$data"
    $SUDO chmod 775 "$data"

    # MariaDB temporal sin red y con su propio socket: no choca con la version en marcha. La
    # carpeta la crea root y solo es del usuario del servidor (no pide contraseña mientras se prepara)
    local tmp=$($SUDO mktemp -d /tmp/lvm-mysql-XXXX)
    local sock=$tmp/mysql.sock pid=$tmp/mysql.pid
    $SUDO chown "$user" "$tmp"
    $SUDO "$my/bin/mariadbd" --defaults-file="$cnf" --skip-networking --socket="$sock" --pid-file="$pid" \
        --log-error="$tmp/mysql.log" > /dev/null 2>&1 &
    local server_pid=$!

    local i
    for i in $(seq 150); do $SUDO test -S "$sock" && break; sleep 0.2; done

    local mysql=($SUDO "$my/bin/mariadb" --no-defaults -S "$sock" -uroot)
    $SUDO chmod 700 "$tmp"
    local ok=0
    if $SUDO test -S "$sock" \
        && "${mysql[@]}" < "$target/phpmyadmin/sql/create_tables.sql" \
        && "${mysql[@]}" -e "CREATE USER IF NOT EXISTS 'pma'@'localhost';
            GRANT SELECT, INSERT, UPDATE, DELETE ON phpmyadmin.* TO 'pma'@'localhost';
            FLUSH PRIVILEGES;"; then
        ok=1
    fi

    # (la carpeta es de tu usuario, con el que corre el servidor: el .pid solo vale si es de verdad
    # ese servidor; si no, se para el sudo que lo arranco)
    local spid
    if $SUDO test -f "$pid"; then
        spid=$(db_temp_pid "$pid" "$sock") && $SUDO kill "$spid" || db_temp_kill_launched "$server_pid" "$sock"
    fi
    for i in $(seq 150); do $SUDO test -f "$pid" || break; sleep 0.2; done
    $SUDO rm -rf "$tmp"

    if [ $ok -eq 0 ]; then
        echo "  Aviso: no se pudo crear la base 'phpmyadmin'; phpMyAdmin funcionara pero avisara de que falta su almacenamiento"
    fi

    return 0
}

# Escribe la configuracion de la pila en la carpeta temporal $S (que se copiara a $target).
# Usa las variables de install_stack.
function write_stack_files() {
    local test_mode=0
    [ -n "$TEST_DIR" ] && test_mode=1

    mkdir -p "$S"/{bin,etc/extra,etc/ssl.crt,etc/ssl.key,logs,tmp,cgi-bin,var/run,var/proftpd,php/etc/conf.d}

    # --- Apache ---
    local mods="mpm_event authn_file authn_core authz_host authz_groupfile authz_user authz_core access_compat
        auth_basic socache_shmcb reqtimeout include filter deflate brotli mime log_config env expires headers
        setenvif version proxy proxy_fcgi proxy_http ssl http2 unixd status autoindex cgid vhost_alias
        negotiation dir actions alias rewrite remoteip"
    local m load=""
    for m in $mods; do
        [ -f "$S/apache2/modules/mod_$m.so" ] && load+="LoadModule ${m}_module apache2/modules/mod_$m.so"$'\n'
    done

    cat > "$S/etc/httpd.conf" <<EOF
# Apache $apache de XAMPP-$vname (lvm-instalador)
ServerRoot "$target"
# Solo desde este Mac
Listen 127.0.0.1:$PORT_HTTP
Listen [::1]:$PORT_HTTP

$load
<IfModule unixd_module>
User $web_user
Group $web_group
</IfModule>

ServerAdmin you@example.com
ServerName localhost:$PORT_HTTP
PidFile "logs/httpd.pid"
Timeout 300
KeepAlive On

<Directory />
    AllowOverride None
    Require all denied
</Directory>

DocumentRoot "$docroot"
<Directory "$docroot">
    # (sin ExecCGI ni Includes: en htdocs solo hay proyectos PHP)
    Options Indexes FollowSymLinks
    AllowOverride All
    Require all granted
</Directory>

DirectoryIndex index.php index.html index.htm

<Files ".ht*">
    Require all denied
</Files>

ErrorLog "logs/error_log"
LogLevel warn
LogFormat "%h %l %u %t \"%r\" %>s %b \"%{Referer}i\" \"%{User-Agent}i\"" combined
LogFormat "%h %l %u %t \"%r\" %>s %b" common
CustomLog "logs/access_log" common

ScriptAlias /cgi-bin/ "$target/cgi-bin/"
<Directory "$target/cgi-bin">
    AllowOverride None
    Options None
    Require all granted
</Directory>

TypesConfig apache2/conf/mime.types
AddType application/x-compress .Z
AddType application/x-gzip .gz .tgz
# Scripts CGI, solo en cgi-bin (Perl de esta version: #!$link_files/bin/perl). En htdocs no: un .pl
# o un .cgi subido a un proyecto no se ejecuta

<IfModule http2_module>
    Protocols h2 h2c http/1.1
</IfModule>

# Antes de los vhosts: los dominios que no tienen ninguno solo pasan si son localhost
Include $UNKNOWN_HOST_CONF
Include etc/extra/httpd-vhosts.conf
Include etc/extra/httpd-ssl.conf
Include etc/extra/httpd-xampp.conf
EOF
    unknown_host_vhost > "$S/$UNKNOWN_HOST_CONF"
    # OpenSSL (copiado de Homebrew) con la configuracion de la version, no la de /opt/homebrew
    echo "# OpenSSL de esta version (lvm-instalador): sin configuracion ni modulos de fuera" > "$S/etc/openssl.cnf"

    cat > "$S/etc/extra/httpd-ssl.conf" <<EOF
# HTTPS con un certificado autofirmado para localhost (los vhosts usan los suyos)
Listen 127.0.0.1:$PORT_HTTPS
Listen [::1]:$PORT_HTTPS
SSLCipherSuite HIGH:MEDIUM:!aNULL:!MD5
SSLProtocol all -SSLv3
SSLPassPhraseDialog builtin
SSLSessionCache "shmcb:$target/logs/ssl_scache(512000)"
SSLSessionCacheTimeout 300

<VirtualHost _default_:$PORT_HTTPS>
    DocumentRoot "$docroot"
    ServerName localhost:$PORT_HTTPS
    ErrorLog "$target/logs/error_log"
    TransferLog "$target/logs/access_log"
    SSLEngine on
    SSLCertificateFile "$target/etc/ssl.crt/server.crt"
    SSLCertificateKeyFile "$target/etc/ssl.key/server.key"
</VirtualHost>
EOF

    cat > "$S/etc/extra/httpd-xampp.conf" <<EOF
# PHP $version via PHP-FPM
SetEnvIf Authorization "(.*)" HTTP_AUTHORIZATION=\$1
ProxyTimeout 300
<FilesMatch "\.php$">
    SetHandler "proxy:unix:$target/var/run/php-fpm.sock|fcgi://localhost"
</FilesMatch>

# phpMyAdmin $pma, solo desde este equipo
Alias /phpmyadmin "$target/phpmyadmin"
<Directory "$target/phpmyadmin">
    AllowOverride AuthConfig Limit
    Require local
</Directory>
EOF

    # El openssl de macOS es LibreSSL: se usa el de Homebrew
    "$(brew --prefix openssl@3)/bin/openssl" req -x509 -nodes -newkey rsa:2048 -days 3650 -subj "/CN=localhost" \
        -addext "basicConstraints=critical,CA:FALSE" -addext "subjectAltName=DNS:localhost,IP:127.0.0.1" \
        -keyout "$S/etc/ssl.key/server.key" -out "$S/etc/ssl.crt/server.crt" > /dev/null 2>&1

    # --- PHP ---
    cat > "$S/php/etc/conf.d/99-xampp.ini" <<EOF
; Mismos valores que el php.ini de XAMPP. Sin error_log: los errores van al log de Apache
memory_limit = 512M
upload_max_filesize = 64M
post_max_size = 64M
max_execution_time = 120
max_input_time = 60
max_input_vars = 3000
date.timezone = $PHP_TIMEZONE
error_reporting = E_ALL & ~E_DEPRECATED
display_errors = Off
log_errors = On
mysqli.default_socket = $target/var/mysql/mysql.sock
pdo_mysql.default_socket = $target/var/mysql/mysql.sock
; Certificados del sistema (macOS), para HTTPS desde PHP
openssl.cafile = /etc/ssl/cert.pem
curl.cainfo = /etc/ssl/cert.pem
opcache.enable = 1
opcache.revalidate_freq = 0
EOF

    # Contra PHP2Shell (va despues de 99-xampp.ini; SECURE_PY lo deja igual en las ya instaladas)
    { printf '%s' "$PHP_SECURITY_INI"
      if [ "${short%%.*}" -gt 8 ] || { [ "${short%%.*}" -eq 8 ] && [ "${short#*.}" -ge 5 ]; }; then
          printf '%s' "$PHP_SECURITY_INI_85"
      fi
    } > "$S/php/etc/conf.d/zz-lvm-seguridad.ini" || return 1

    # A partir de PHP 8.5 opcache va integrado y no se carga como extension
    if ls "$S"/php/lib/php/extensions/*/opcache.so > /dev/null 2>&1; then
        echo "zend_extension = opcache" > "$S/php/etc/conf.d/10-opcache.ini"
    fi

    cat > "$S/php/etc/php-fpm.conf" <<EOF
[global]
pid = $target/var/run/php-fpm.pid
error_log = $target/logs/php-fpm.log
daemonize = yes

[xampp]
user = $web_user
group = $web_group
listen = $target/var/run/php-fpm.sock
listen.owner = $web_user
listen.group = $web_group
listen.mode = 0660
pm = ondemand
pm.max_requests = 50
pm.max_children = 20
pm.process_idle_timeout = 60s
request_terminate_timeout = 300
catch_workers_output = yes
EOF

    # --- MariaDB: se ejecuta con el usuario del Mac ---
    mkdir -p "$S/etc/lvm-sin-ficheros"
    cat > "$S/etc/my.cnf" <<EOF
# MariaDB $mariadb de XAMPP-$vname (lvm-instalador)
[client]
port = $PORT_MYSQL
socket = $target/var/mysql/mysql.sock
default-character-set = utf8mb4

[mysqld]
user = $web_user
port = $PORT_MYSQL
# Solo desde este Mac
bind-address = 127.0.0.1
# Sin leer ni escribir ficheros del Mac desde SQL (la carpeta esta vacia y es de root)
secure-file-priv = "$target/etc/lvm-sin-ficheros"
local-infile = 0
socket = $target/var/mysql/mysql.sock
basedir = $target/mysql
datadir = $target/var/mysql
plugin_dir = $target/mysql/lib/plugin
pid-file = $target/var/mysql/mysqld.pid
log-error = $target/var/mysql/mysqld.err
max_allowed_packet = 512M
table_open_cache = 640
sort_buffer_size = 5120K
read_buffer_size = 2560K
read_rnd_buffer_size = 5120K
myisam_sort_buffer_size = 80M
innodb_lock_wait_timeout = 50
# Mismo cotejamiento que XAMPP, para que los volcados se puedan importar en versiones
# anteriores y en los servidores (desde MariaDB 11.2 el de por defecto es uca1400)
character-set-server = utf8mb4
collation-server = utf8mb4_general_ci
loose-character-set-collations = utf8mb4=utf8mb4_general_ci

[mysqldump]
max_allowed_packet = 512M
EOF

    # --- ProFTPD: acceso a htdocs con el usuario del Mac y su contraseña (PAM de macOS) ---
    local pam=ftpd
    [ -f /etc/pam.d/ftpd ] || pam=login
    cat > "$S/etc/proftpd.conf" <<EOF
# ProFTPD $ftp de XAMPP-$vname (lvm-instalador)
ServerName "ProFTPD XAMPP-$vname"
ServerType standalone
DefaultServer on
Port $PORT_FTP
# Solo desde este Mac
DefaultAddress 127.0.0.1
SocketBindTight on
Umask 022
MaxInstances 30
User $web_user
Group $web_group
PidFile $target/var/proftpd/proftpd.pid
ScoreboardFile $target/var/proftpd/proftpd.scoreboard
SystemLog $target/logs/proftpd.log
TransferLog $target/logs/xferlog
UseReverseDNS off
RequireValidShell off
<IfModule mod_ident.c>
    IdentLookups off
</IfModule>
<IfModule mod_delay.c>
    DelayTable $target/var/proftpd/proftpd.delay
</IfModule>
<IfModule mod_auth_pam.c>
    AuthPAM on
    AuthPAMConfig $pam
    AuthOrder mod_auth_pam.c* mod_auth_unix.c
</IfModule>

DefaultRoot $ftp_root
<Limit LOGIN>
    AllowUser $web_user
    DenyAll
</Limit>
<Directory $ftp_root/*>
    AllowOverwrite on
</Directory>
<Limit SITE_CHMOD>
    DenyAll
</Limit>
EOF

    # --- phpMyAdmin: como en XAMPP, entra como root sin contraseña ---
    local secret=$(head -c 16 /dev/urandom | od -An -tx1 | tr -d ' \n')
    cat > "$S/phpmyadmin/config.inc.php" <<EOF
<?php
declare(strict_types=1);

\$cfg['blowfish_secret'] = '$secret';

\$i = 1;
\$cfg['Servers'][\$i]['auth_type'] = 'config';
\$cfg['Servers'][\$i]['user'] = 'root';
\$cfg['Servers'][\$i]['password'] = '';
\$cfg['Servers'][\$i]['host'] = 'localhost';
\$cfg['Servers'][\$i]['socket'] = '$target/var/mysql/mysql.sock';
\$cfg['Servers'][\$i]['AllowNoPassword'] = true;
\$cfg['Servers'][\$i]['controluser'] = 'pma';
\$cfg['Servers'][\$i]['controlpass'] = '';
\$cfg['Servers'][\$i]['pmadb'] = 'phpmyadmin';
EOF
    for m in bookmark relation table_info table_coords pdf_pages column_info history table_uiprefs tracking \
        userconfig recent users usergroups navigationhiding savedsearches central_columns designer_settings \
        export_templates favorite; do
        local key=$m
        [ "$m" == "bookmark" ] && key=bookmarktable
        echo "\$cfg['Servers'][\$i]['$key'] = 'pma__$m';" >> "$S/phpmyadmin/config.inc.php"
    done
    cat >> "$S/phpmyadmin/config.inc.php" <<EOF

\$cfg['TempDir'] = '$target/phpmyadmin/tmp';
\$cfg['UploadDir'] = '';
\$cfg['SaveDir'] = '';
EOF
    mkdir -p "$S/phpmyadmin/tmp"

    # --- Script de arranque y parada, como el de XAMPP para Mac (lo usa "lvm-instalador use") ---
    sed -e "s|@ROOT@|$target|g" -e "s|@NAME@|$vname|g" -e "s|@NEED_ROOT@|$(( 1 - test_mode ))|g" \
        -e "s|@WEB_USER@|$web_user|g" > "$S/xampp" <<'EOF'
#!/bin/bash
# Arranque y parada de XAMPP-@NAME@ (pila propia creada por lvm-instalador):
# Apache con PHP-FPM, MariaDB y ProFTPD.
# Uso: xampp start|stop|restart|status|startapache|stopapache|reloadapache|startmysql|stopmysql|startftp|stopftp

ROOT=@ROOT@
# Como root, solo los programas del sistema (Homebrew es de tu usuario)
export PATH=/usr/bin:/bin:/usr/sbin:/sbin
# OpenSSL: solo su configuracion (no la de Homebrew, que es de tu usuario)
export OPENSSL_CONF=$ROOT/etc/openssl.cnf
export OPENSSL_MODULES=$ROOT/lib/ossl-modules
APACHE_PID=$ROOT/logs/httpd.pid
MYSQL_PID=$ROOT/var/mysql/mysqld.pid
MYSQL_SOCK=$ROOT/var/mysql/mysql.sock
FTP_PID=$ROOT/var/proftpd/proftpd.pid
# MariaDB con tu usuario, no como root: var/mysql (sus datos, su pid y su registro) es tuya, y
# como root mariadbd-safe escribiria donde apuntara un enlace puesto ahi, y kill mataria el
# proceso cuyo numero se hubiera escrito en el pid
WEB_USER=@WEB_USER@
as_web() {
    if [ "$(id -u)" -eq 0 ] && [ -n "$WEB_USER" ] && [ "$WEB_USER" != root ]; then
        /usr/bin/sudo -u "$WEB_USER" "$@"
    else
        "$@"
    fi
}

if [ @NEED_ROOT@ -eq 1 ] && [ "$(id -u)" -ne 0 ]; then
    echo "Hay que ejecutarlo como administrador: sudo $0 $*"
    exit 1
fi

function running() {
    [ -f "$1" ] && kill -0 "$(cat "$1" 2> /dev/null)" 2> /dev/null
}

# Espera hasta <segundos> a que se cumpla una condicion
function wait_until() {
    local seconds=$1 i
    shift

    for i in $(seq $(( seconds * 10 ))); do
        "$@" && return 0
        sleep 0.1
    done

    return 1
}

function stopped() {
    ! running "$1"
}

function mysql_ready() {
    running "$MYSQL_PID" && [ -S "$MYSQL_SOCK" ]
}

# Programa que ya escucha en un puerto (el Apache de macOS, otro XAMPP...)
function port_owner() {
    lsof -nP -iTCP:"$1" -sTCP:LISTEN 2> /dev/null | awk 'NR == 2 {print $1 " (PID " $2 ")"}'
}

function start_apache() {
    running "$APACHE_PID" && { echo "Apache ya estaba arrancado."; return 0; }

    # (< /dev/null en todo lo que se queda en marcha: si no, se queda con la terminal de la tarea
    # que lo arranca y la ventana no ve el final)
    "$ROOT/bin/pvm-php-fpm" start < /dev/null
    # Como XAMPP: los avisos del arranque (vhosts sin carpeta, certificados...) van al log
    if "$ROOT/apache2/bin/httpd" -f "$ROOT/etc/httpd.conf" -E "$ROOT/logs/error_log" -k start < /dev/null >> "$ROOT/logs/error_log" 2>&1 \
        && wait_until 10 running "$APACHE_PID"; then
        echo "Apache arrancado."
    else
        local port=$(sed -n 's/^Listen //p' "$ROOT/etc/httpd.conf" | head -1)
        local owner=$(port_owner "$port")
        echo "Apache no ha arrancado. Revisa $ROOT/logs/error_log"
        [ -n "$owner" ] && echo "El puerto $port ya lo usa $owner. Si es el Apache de macOS: sudo apachectl stop"
        return 1
    fi
}

function stop_apache() {
    if running "$APACHE_PID"; then
        "$ROOT/apache2/bin/httpd" -f "$ROOT/etc/httpd.conf" -k stop
        wait_until 15 stopped "$APACHE_PID"
        echo "Apache parado."
    fi
    "$ROOT/bin/pvm-php-fpm" stop
}

function reload_apache() {
    "$ROOT/bin/pvm-php-fpm" reload
    running "$APACHE_PID" && "$ROOT/apache2/bin/httpd" -f "$ROOT/etc/httpd.conf" -E "$ROOT/logs/error_log" -k graceful >> "$ROOT/logs/error_log" 2>&1 \
        && echo "Apache recargado."
}

function start_mysql() {
    running "$MYSQL_PID" && { echo "MariaDB ya estaba arrancado."; return 0; }

    # mariadbd-safe busca sus herramientas desde la carpeta de MariaDB
    (cd "$ROOT/mysql" && as_web /usr/bin/nohup ./bin/mariadbd-safe --defaults-file="$ROOT/etc/my.cnf" < /dev/null > /dev/null 2>&1 &)
    if wait_until 60 mysql_ready; then
        echo "MariaDB arrancado."
    else
        echo "MariaDB no ha arrancado. Revisa $ROOT/var/mysql/mysqld.err"
        return 1
    fi
}

function stop_mysql() {
    running "$MYSQL_PID" || return 0

    as_web kill "$(cat "$MYSQL_PID")"
    wait_until 60 stopped "$MYSQL_PID" && echo "MariaDB parado." || echo "MariaDB sigue parandose."
}

function start_ftp() {
    running "$FTP_PID" && { echo "ProFTPD ya estaba arrancado."; return 0; }

    if "$ROOT/proftpd/sbin/proftpd" -c "$ROOT/etc/proftpd.conf" < /dev/null 2> /dev/null && wait_until 5 running "$FTP_PID"; then
        echo "ProFTPD arrancado."
    else
        echo "ProFTPD no ha arrancado. Revisa $ROOT/logs/proftpd.log"
        return 1
    fi
}

function stop_ftp() {
    running "$FTP_PID" || return 0

    kill "$(cat "$FTP_PID")"
    wait_until 10 stopped "$FTP_PID"
    echo "ProFTPD parado."
}

function status() {
    local name pid

    echo "XAMPP-@NAME@ (pila propia)"
    for name in Apache MariaDB ProFTPD; do
        case $name in
            Apache) pid=$APACHE_PID ;;
            MariaDB) pid=$MYSQL_PID ;;
            ProFTPD) pid=$FTP_PID ;;
        esac
        running "$pid" && echo "$name esta arrancado." || echo "$name no esta arrancado."
    done
    "$ROOT/bin/pvm-php-fpm" status
}

case "$1" in
    # El FTP solo si se ha activado (xampp startftp; lo quita xampp stopftp)
    start) echo "Arrancando XAMPP-@NAME@..."; start_mysql; start_apache; if [ -f "$ROOT/etc/lvm-startftp" ]; then start_ftp; fi ;;
    stop) echo "Parando XAMPP-@NAME@..."; stop_apache; stop_mysql; stop_ftp ;;
    restart|reload) "$0" stop; "$0" start ;;
    status) status ;;
    startapache) start_apache ;;
    stopapache) stop_apache ;;
    reloadapache) reload_apache ;;
    restartapache) stop_apache; start_apache ;;
    startmysql) start_mysql ;;
    stopmysql) stop_mysql ;;
    restartmysql) stop_mysql; start_mysql ;;
    startftp) touch "$ROOT/etc/lvm-startftp"; start_ftp ;;
    stopftp) rm -f "$ROOT/etc/lvm-startftp"; stop_ftp ;;
    *) sed -n '4p' "$0" | sed 's/^# //'; exit 1 ;;
esac
EOF
    chmod 755 "$S/xampp"

    # PHP-FPM se arranca con el entorno limpio
    fpm_script_template | sed -e "s|@ROOT@|$target|g" -e "s|@VERSION@|$version|g" > "$S/bin/pvm-php-fpm"
    chmod 755 "$S/bin/pvm-php-fpm"

    # --- Comandos en bin/, como en XAMPP: /Applications/XAMPP/xamppfiles/bin/php, .../bin/mysql... ---
    for m in php php-config phpize; do ln -s "../php/bin/$m" "$S/bin/$m"; done
    for m in perl perldoc cpan; do ln -s "../perl/bin/$m" "$S/bin/$m"; done
    for m in httpd ab htpasswd; do [ -e "$S/apache2/bin/$m" ] && ln -s "../apache2/bin/$m" "$S/bin/$m"; done

    # Los clientes de MariaDB leen el my.cnf de esta version (socket y puerto). Los nombres
    # antiguos (mysql, mysqldump...) llaman a los nuevos, que no avisan de que estan obsoletos.
    local name real
    for name in mysql:mariadb mysqldump:mariadb-dump mysqladmin:mariadb-admin mysqlcheck:mariadb-check \
        mysqlimport:mariadb-import mysqlshow:mariadb-show mysql_upgrade:mariadb-upgrade; do
        real=${name#*:}
        [ -e "$S/mysql/bin/$real" ] || real=${name%%:*}
        [ -e "$S/mysql/bin/$real" ] || continue
        for m in ${name%%:*} ${name#*:}; do
            printf '#!/bin/sh\nexec %s/mysql/bin/%s --defaults-file=%s/etc/my.cnf "$@"\n' "$target" "$real" "$target" > "$S/bin/$m"
            chmod 755 "$S/bin/$m"
        done
    done

    # htdocs y vhosts compartidos con las demas versiones; /Applications/XAMPP-X.Y/htdocs como en XAMPP
    if [ $test_mode -eq 1 ]; then
        mkdir -p "$S/htdocs"
        echo '<?php phpinfo();' > "$S/htdocs/index.php"
        : > "$S/etc/extra/httpd-vhosts.conf"
    else
        ln -s "$COMMON/htdocs" "$S/htdocs"
        ln -s "$COMMON/httpd-vhosts.conf" "$S/etc/extra/httpd-vhosts.conf"
    fi
    ln -s xamppfiles/htdocs "$stage$root/htdocs"

    echo "$version" > "$S/etc/pvm-php"
    # (con el parche de seguridad contra PHP2Shell: PHP sigue llamandose igual, la marca lo dice)
    [ -n "$php_patch" ] && echo "CVE-2026-109618-109619|$php_patch|$PHP2SHELL_DATE" > "$S/etc/lvm-parche-php2shell"
    echo "$version|$apache|$mariadb|$ftp|$perl|$pma" > "$S/etc/pvm-stack"
    # Ya se instala solo para este Mac (secure_version no tiene nada que cambiar)
    echo "1" > "$S/etc/lvm-seguridad"
}

# Script pvm-php-fpm de una version, con @ROOT@ (su xamppfiles) y @VERSION@ (la de PHP): PHP-FPM con
# el entorno limpio y el php.ini y conf.d de su carpeta, no los que trae compilados (en las versiones
# de antes de la 1.39.3, que se compilaron en /Applications, serian los de alli). Tambien lo usa migrar
function fpm_script_template() {
    cat <<'EOF'
#!/bin/bash
# PHP-FPM @VERSION@ (lo arrancan y paran startapache/stopapache del script xampp)
FPM=@ROOT@/php/sbin/php-fpm
CONF=@ROOT@/php/etc/php-fpm.conf
INI=@ROOT@/php/etc/php.ini
PID=@ROOT@/var/run/php-fpm.pid

running() { [ -f "$PID" ] && kill -0 "$(cat "$PID")" 2> /dev/null; }

case "$1" in
    start)
        running || env -i PATH=/usr/sbin:/usr/bin:/sbin:/bin OPENSSL_CONF="${FPM%/php/sbin/php-fpm}/etc/openssl.cnf" \
            OPENSSL_MODULES="${FPM%/php/sbin/php-fpm}/lib/ossl-modules" PHP_INI_SCAN_DIR="${INI%/php.ini}/conf.d" \
            "$FPM" -c "$INI" --fpm-config "$CONF"
        ;;
    stop)
        running && kill -QUIT "$(cat "$PID")"
        for i in $(seq 50); do running || break; sleep 0.1; done
        ;;
    reload)
        running && kill -USR2 "$(cat "$PID")"
        ;;
    status)
        running && echo "PHP-FPM @VERSION@ esta arrancado." || echo "PHP-FPM @VERSION@ no esta arrancado."
        ;;
esac
EOF
}

# Enlaces de lo compilado que llevan fuera de la version (salvo htdocs y los vhosts compartidos):
# lo compilado es de tu usuario hasta que root lo copia, y un programa tuyo podria dejar un enlace
# a /etc para que root lo cambiara despues. Uso: <carpeta temporal> <carpeta definitiva> <compartida>
BUILD_LINKS_PY='
import os, posixpath, sys
root, target = sys.argv[1], sys.argv[2]
ok = {"htdocs": "xamppfiles/htdocs", "xamppfiles/htdocs": sys.argv[3] + "/htdocs",
      "xamppfiles/etc/extra/httpd-vhosts.conf": sys.argv[3] + "/httpd-vhosts.conf"}
# (los compartidos llevan a carpetas tuyas: nada puede apuntar a traves de ellos)
shared = [posixpath.join(target, k) for k in ok]
def under(path, top):
    return path == top or path.startswith(top + "/")
me = os.getuid()
for d, dirs, files in os.walk(root):
    for name in dirs + files:
        p = os.path.join(d, name)
        if not os.path.islink(p):
            # En la carpeta temporal todo lo ha creado tu usuario: un fichero de otro es un enlace duro
            # a un fichero suyo (macOS no los protege) que root copiaria
            if root != target and os.lstat(p).st_uid != me:
                print("%s (de otro usuario: enlace duro)" % os.path.relpath(p, root))
            continue
        rel, lt = os.path.relpath(p, root), os.readlink(p)
        if ok.get(rel) == lt:
            continue
        v = posixpath.join(target, rel)
        r = posixpath.normpath(lt if lt.startswith("/") else posixpath.join(posixpath.dirname(v), lt))
        bad = not under(r, target) or any(under(r, s) for s in shared)
        # La copia ya en su sitio (de root): tambien como lo resuelve el sistema, con los enlaces de en medio
        if root == target and not under(os.path.realpath(p), os.path.realpath(target)):
            bad = True
        if bad:
            print("%s -> %s" % (rel, lt))
'
function check_build_links() {
    local bad
    bad=$(/usr/bin/python3 -I -c "$BUILD_LINKS_PY" "$stage$root" "$root" "$COMMON") || bad="(no se han podido mirar)"
    bad=$(cut -c1-300 <<< "$bad")
    if [ -n "$bad" ]; then
        echo "  Lo compilado tiene enlaces que llevan fuera de $root (no se copia nada):"
        echo "$bad" | head -10 | sed 's/^/    /'

        return 1
    fi
}

# brew_quiet <argumentos>: brew sin pistas, sin limpiar y sin actualizar lo que ya esta instalado
# (ni lo que se pide ni lo que depende de ello). brew no se puede ejecutar como root: si el
# instalador va con sudo, se usa el usuario de la sesion
function brew_quiet() {
    local env=(HOMEBREW_NO_INSTALL_UPGRADE=1 HOMEBREW_NO_ENV_HINTS=1 HOMEBREW_NO_INSTALL_CLEANUP=1
        HOMEBREW_NO_INSTALLED_DEPENDENTS_CHECK=1)
    if [ "$(id -u)" -eq 0 ] && [ -n "$SUDO_USER" ]; then
        sudo -u "$SUDO_USER" env "${env[@]}" brew "$@"
    else
        env "${env[@]}" brew "$@"
    fi
}

# brew_filter: de lo que brew escribe en stderr, quita sus avisos (el de las herramientas de Xcode,
# que repite en cada formula; el de las versiones de macOS viejas; pistas; formulas nuevas o sin
# actualizar; lo que dice al actualizarse) y deja lo demas, siempre los errores
function brew_filter() {
    awk '
        /Error/ { skip = 0; print; fflush(); next }
        # (el de Xcode acaba en "You should download..."; los demas, en una linea en blanco)
        skip == 1 && /^You should download the Command Line Tools/ { skip = 0; next }
        skip == 2 && /^[[:space:]]*$/ { skip = 0; next }
        skip && /^(Warning|==>)/ { skip = 0 }
        skip { next }
        /^Warning: A newer Command Line Tools release is available/ { skip = 1; next }
        /^Warning: You are using macOS/ || /^==> (New|Outdated|Updated) (Formulae|Casks)/ { skip = 2; next }
        /HOMEBREW_NO_ENV_HINTS/ || /^You have [0-9]+ outdated (formula|formulae|cask|casks)/ { next }
        /^You can upgrade them with brew upgrade/ || /^or list them with brew outdated/ { next }
        /Cannot verify integrity/ || /^Running `brew update --auto-update`/ { next }
        /^==> Auto-updat/ || /^Auto-updated Homebrew/ || /^Updated [0-9]+ taps?/ || /^Updated Homebrew from/ { next }
        /^==> Homebrew was updated/ || /^==> Updated Homebrew/ || /^Already up-to-date/ { next }
        { print; fflush() }'
}

# Las librerias de Homebrew para compilar (STACK_BUILD_DEPS): solo instala las que faltan (con una
# sola consulta a brew; las que tienen otro nombre, como icu4c, una a una) y openssl@3 se pone al dia
# si brew dice que tiene una nueva. Si no falta nada, ni se llama a brew install (ni se actualiza
# Homebrew). En las versiones de macOS para las que Homebrew ya no tiene paquetes hechos, todo lo
# que se instala se compila
function brew_build_deps() {
    local have f missing=() upgrade=0
    have=$(brew_quiet list --formula -1 2> /dev/null)
    for f in $STACK_BUILD_DEPS; do
        grep -qxF -- "$f" <<< "$have" && continue
        brew_quiet list --versions "$f" > /dev/null 2>&1 || missing+=("$f")
    done
    [[ " ${missing[*]} " != *" openssl@3 "* ]] && [ -n "$(brew_quiet outdated --quiet openssl@3 2> /dev/null)" ] && upgrade=1
    if [ ${#missing[@]} -eq 0 ] && [ $upgrade -eq 0 ]; then
        echo "  Ya estan todas instaladas"
        return 0
    fi
    [ ${#missing[@]} -gt 0 ] && echo "  Se instalan con Homebrew: ${missing[*]}"
    [ $upgrade -eq 1 ] && echo "  Se actualiza openssl@3 (hay una version nueva)"
    echo "  En las versiones de macOS para las que Homebrew ya no tiene paquetes hechos, se compilan desde el codigo fuente: puede tardar un buen rato."
    if [ ${#missing[@]} -gt 0 ]; then
        { brew_quiet install --quiet "${missing[@]}" 2>&1 > /dev/null; } | brew_filter >&2
        [ "${PIPESTATUS[0]}" -eq 0 ] || { echo "  No se han podido instalar con Homebrew: ${missing[*]}"; return 1; }
    fi
    if [ $upgrade -eq 1 ]; then
        { brew_quiet upgrade --quiet openssl@3 2>&1 > /dev/null; } | brew_filter >&2
        [ "${PIPESTATUS[0]}" -eq 0 ] || { echo "  No se ha podido actualizar openssl@3 con Homebrew"; return 1; }
    fi
    return 0
}

# install_stack <version de PHP> [reemplazar]
# Compila Apache, PHP, Perl, ProFTPD y MariaDB y descarga phpMyAdmin, todo dentro de
# /Applications/XAMPP-X.Y/xamppfiles. Se instala primero en una carpeta temporal (DESTDIR) y solo
# al final se copia a /Applications, asi que si algo falla no queda nada a medias.
# Con reemplazar=1 sustituye la version que ya existe. Si su MariaDB es de la misma rama, conserva
# sus bases de datos; si no, guarda una copia y empieza con unas vacias.
function install_stack() {
    local version=$1 replace=${2:-0}
    local FETCH_FRESH=1

    if ! [[ "$version" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
        echo "Indica la version completa de PHP, por ejemplo: 8.4.26"

        exit 1
    fi

    # Carpeta con la version completa (XAMPP-8.4.27). Actualizar (reemplazar=1) rehace en la suya una
    # XAMPP-X.Y de antes de la 1.38, que se llamaba como la rama; reemplazar=2 rehace XAMPP-<version>
    # con la misma version (7.4.33, 8.0.30 y 8.1.34, para ponerles el parche de seguridad)
    local short=${version%.*}
    local vname=$version
    [ "$replace" -eq 1 ] && vname=$short
    local root=$BASE_DIR/XAMPP-$vname
    local target=$root/xamppfiles
    local link_files=$LINK/xamppfiles docroot=$LINK/xamppfiles/htdocs
    # (el FTP entra como root en su htdocs, por su ruta real y no por el enlace /Applications/XAMPP)
    local ftp_root=$target/htdocs
    [ -n "$TEST_DIR" ] && link_files=$target && docroot=$target/htdocs

    if ! grep -q "^$short|" <<< "$(printf '%s\n' "${STACK_MATRIX[@]}")"; then
        echo "PHP $short no esta entre las ramas que instala este gestor"

        exit 1
    fi

    if [ "$replace" -eq 0 ] && [ -e "$root" ]; then
        echo "Ya existe $root"

        exit 1
    fi

    if [ "$replace" -ge 1 ] && [ ! -f "$target/etc/pvm-stack" ]; then
        echo "No existe $root, no hay nada que actualizar"

        exit 1
    fi

    if [ "$replace" -ge 1 ] && [ -e "$target/htdocs" ] && [ ! -L "$target/htdocs" ] && [ -z "$TEST_DIR" ]; then
        echo "$target tiene una carpeta htdocs propia (no es un enlace a $COMMON/htdocs) y podria contener proyectos."
        echo "Revisala y muevela a mano antes de actualizar la version."

        exit 1
    fi

    if ! xcode-select -p > /dev/null 2>&1; then
        echo "Faltan las herramientas de linea de comandos de Xcode. Instalalas con: xcode-select --install"

        exit 1
    fi

    echo "Consultando las ultimas versiones de cada componente..."
    local branches
    read -r -a branches <<< "$(stack_branches "$short")"

    local apache=$(latest_apache "${branches[0]}")
    local apr=$(latest_apr apr) aprutil=$(latest_apr apr-util)
    local mariadb_info=$(mariadb_release "${branches[1]}")
    local mariadb=${mariadb_info%%|*}
    local ftp=$(latest_proftpd "${branches[2]}")
    local perl=$(latest_perl "${branches[3]}")
    local pma=$(latest_pma "$short")
    local php_sha=$(curl -q --proto =https --proto-redir =https -fsSL "https://www.php.net/releases/index.php?json&version=$version" \
        | python3 -I -c 'import json,sys; print([s["sha256"] for s in json.load(sys.stdin)["source"] if s["filename"].endswith(".tar.xz")][0])' 2> /dev/null)

    local missing=""
    [ -z "$php_sha" ] && missing+=" PHP-$version"
    [ -z "$apache" ] && missing+=" Apache-${branches[0]}"
    [ -z "$apr" ] || [ -z "$aprutil" ] && missing+=" APR"
    [ -z "$mariadb" ] && missing+=" MariaDB-${branches[1]}"
    [ -z "$ftp" ] && missing+=" ProFTPD-${branches[2]}"
    [ -z "$perl" ] && missing+=" Perl-${branches[3]}"

    if [ -n "$missing" ]; then
        echo "No se pudo consultar la ultima version de:$missing (¿hay conexion a internet?)"

        exit 1
    fi

    local web_user=$(web_user_name)
    local web_group=$(id -gn "$web_user")

    # Que hacer con las bases de datos de la version que se sustituye
    local keep_data=0 old_mariadb=""
    if [ "$replace" -ge 1 ]; then
        old_mariadb=$(stack_fields "$root" | cut -d'|' -f3)
        [ -d "$target/var/mysql" ] && [ ! -L "$target/var/mysql" ] \
            && [ "${old_mariadb%.*}" == "${mariadb%.*}" ] && keep_data=1
    fi

    local extras="" php_patch=""
    # 7.4.33, 8.0.30 y 8.1.34: con el parche de seguridad oficial contra PHP2Shell
    php2shell_backport "$version" > /dev/null && php_patch=$(php2shell_backport "$version" | cut -d'|' -f3)
    needs_openssl11 "$short" && extras+=", OpenSSL $OPENSSL11_VERSION"
    needs_icu72 "$short" && extras+=", ICU 72.1"

    echo ""
    local php_shown="PHP $version"
    [ -n "$php_patch" ] && php_shown+=" + parche de seguridad ($PHP2SHELL_DATE)"
    local stack_line="XAMPP-$vname: $php_shown, Apache $apache, MariaDB $mariadb, ProFTPD $ftp, Perl $perl, phpMyAdmin $pma$extras"
    echo "$stack_line"
    echo "Carpeta: $root   Usuario de Apache, PHP, MariaDB y FTP: $web_user:$web_group"

    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] librerias de Homebrew: $STACK_BUILD_DEPS"
        echo "  [simulacion] descarga con comprobacion sha256 y compilacion de Apache, APR $apr/$aprutil, PHP, Perl, ProFTPD y MariaDB$extras"
        echo "  [simulacion] copia de las librerias de Homebrew dentro de $target/lib"
        if [ "$replace" -ge 1 ] && [ $keep_data -eq 1 ]; then
            echo "  [simulacion] se sustituiria $root conservando sus bases de datos (MariaDB ${mariadb%.*})"
        elif [ "$replace" -ge 1 ]; then
            echo "  [simulacion] copia de las bases de datos de $root en ~/lvm-copias y bases nuevas y vacias"
        else
            echo "  [simulacion] bases de datos propias y vacias en $target/var/mysql (root sin contraseña)"
        fi
        echo "  [simulacion] puertos: web $PORT_HTTP/$PORT_HTTPS, MariaDB $PORT_MYSQL, FTP $PORT_FTP"

        exit 0
    fi

    echo "Instalando las librerias de Homebrew para compilar (solo librerias, no PHP)..."
    brew_build_deps || exit 1

    STEP_LOG="" STEP_DESC=""
    local build=$(mktemp -d /tmp/lvm-pila-$short-XXXX)
    local stage=$build/stage
    local S=$stage$target
    local deps=$build/deps
    local jobs=$(cpu_count)
    local sdk=$(xcrun --show-sdk-path)

    # Si algo falla se guardan los logs y se borra la carpeta temporal
    function stack_fail() {
        local logs=$LOG_DIR/pila-$short-$(date +%Y%m%d-%H%M%S)
        mkdir -p "$logs"
        cp "$build"/*.log "$logs/" 2> /dev/null
        # El config.log del componente que fallaba (stack_fail se llama desde su carpeta): ahi esta
        # el motivo real de los errores de configure ("GD build test failed...")
        local config=""
        if [ -f config.log ]; then
            config="$logs/$(basename "$PWD")-config.log"
            cp config.log "$config"
        fi
        cd / && rm -rf "$build"
        error_report "$logs/informe-error.txt" "$stack_line" "${STEP_LOG:+$logs/$(basename "$STEP_LOG")}" "$STEP_DESC" "$config"
        echo "No se ha instalado nada. Logs de la compilacion en $logs"
        echo "Informe del error: $logs/informe-error.txt"

        exit 1
    }

    cd "$build" || exit 1

    # Rutas de Homebrew. Las librerias "keg-only" no estan en /opt/homebrew/lib y hay que indicarlas.
    local b_ssl=$(brew --prefix openssl@3) b_icu=$(brew --prefix icu4c) b_pcre=$(brew --prefix pcre2)
    local pc="" f
    for f in zlib sqlite readline; do pc+="$(brew --prefix $f)/lib/pkgconfig:"; done
    pc+="$HOMEBREW_PREFIX/lib/pkgconfig"
    local headerpad="-Wl,-headerpad_max_install_names"

    local php_part=$php_shown
    [ -n "$extras" ] && php_part+=" (con ${extras#, })"
    local parts=("Descargas" "Apache $apache" "$php_part" "Perl $perl" "ProFTPD $ftp" "MariaDB $mariadb" \
        "phpMyAdmin $pma y configuracion")
    progress_parts "${parts[@]}"

    echo "Descargando el codigo fuente (con comprobacion sha256 y de las firmas GPG)..."
    progress 1 0 1 "codigo fuente"
    download_apache "httpd/httpd-$apache.tar.bz2" httpd.tar.bz2 || stack_fail
    download_apache "apr/apr-$apr.tar.bz2" apr.tar.bz2 || stack_fail
    download_apache "apr/apr-util-$aprutil.tar.bz2" apr-util.tar.bz2 || stack_fail
    download "https://www.php.net/distributions/php-$version.tar.xz" php.tar.xz "$php_sha" \
        "https://www.php.net/distributions/php-$version.tar.xz.asc" PHP || stack_fail
    download "https://www.cpan.org/src/5.0/perl-$perl.tar.xz" perl.tar.xz \
        "$(curl -q --proto =https --proto-redir =https -fsSL "https://www.cpan.org/src/5.0/perl-$perl.tar.xz.sha256.txt" | grep -oE '^[0-9a-f]{64}')" || stack_fail
    download "https://github.com/proftpd/proftpd/archive/refs/tags/v$ftp.tar.gz" proftpd.tar.gz \
        "$(curl -q --proto =https --proto-redir =https -fsSL "https://github.com/proftpd/proftpd/releases/download/v$ftp/proftpd-$ftp.tar.gz.sha256" | grep -oE '^[0-9a-f]{64}')" || stack_fail
    download "https://files.phpmyadmin.net/phpMyAdmin/$pma/phpMyAdmin-$pma-all-languages.tar.xz" pma.tar.xz \
        "$(pma_sum "$pma")" "https://files.phpmyadmin.net/phpMyAdmin/$pma/phpMyAdmin-$pma-all-languages.tar.xz.asc" PMA || stack_fail
    if needs_openssl11 "$short"; then
        download "https://www.openssl.org/source/openssl-$OPENSSL11_VERSION.tar.gz" openssl11.tar.gz "$OPENSSL11_SHA" || stack_fail
    fi
    if needs_icu72 "$short"; then
        download "https://github.com/unicode-org/icu/releases/download/release-72-1/icu4c-72_1-src.tgz" icu72.tgz "$ICU72_SHA" || stack_fail
    fi
    IFS='|' read -r _ mariadb_url mariadb_sha <<< "$mariadb_info"
    progress 1 1 4 "MariaDB (codigo fuente)" bytes "$build/mariadb.tar.gz" "$(remote_size "$mariadb_url")"
    # (la firma, en la misma direccion de su API: .../mariadb-X.Y.Z.tar.gz/signature/)
    download "$mariadb_url" mariadb.tar.gz "$mariadb_sha" "${mariadb_url%/}/signature/" MARIADB || stack_fail

    echo "Apache $apache (con APR $apr y APR-util $aprutil)"
    tar -xjf httpd.tar.bz2 && tar -xjf apr.tar.bz2 && tar -xjf apr-util.tar.bz2 || stack_fail
    mv "apr-$apr" "httpd-$apache/srclib/apr" && mv "apr-util-$aprutil" "httpd-$apache/srclib/apr-util" || stack_fail
    cd "httpd-$apache" || stack_fail
    step 2 4 6 1063 "Configurando" "$build/apache-configure.log" env LDFLAGS="$headerpad" ./configure \
        --prefix="$target/apache2" --with-included-apr --with-pcre="$b_pcre/bin/pcre2-config" \
        --with-ssl="$b_ssl" --with-nghttp2="$(brew --prefix nghttp2)" --with-brotli="$(brew --prefix brotli)" \
        --enable-mods-shared=most --enable-ssl --enable-http2 --enable-brotli --enable-proxy --enable-proxy-fcgi \
        --enable-mpms-shared="event prefork" || stack_fail
    step 2 6 9 712 "Compilando" "$build/apache-make.log" make -j"$jobs" || stack_fail
    step 2 9 10 583 "Instalando" "$build/apache-install.log" make install DESTDIR="$stage" || stack_fail
    cd "$build" || stack_fail

    echo "PHP $version"
    # Las ramas antiguas compilan con avisos que los compiladores actuales tratan como errores
    local php_cflags="-O2" php_cxxflags="-O2" php_cppflags="" php_pc=$pc
    local php_ssl_pc="$b_ssl/lib/pkgconfig" php_icu_pc="$b_icu/lib/pkgconfig" p=10
    # PHP 7.4 usa TRUE/FALSE, que ICU dejo de definir en la version 68
    [ "$short" == "7.4" ] && php_cppflags="-DU_DEFINE_FALSE_AND_TRUE=1"
    # El configure de PHP compila con -fvisibility=hidden, y con el enlazador actual de Apple un
    # programa con main oculto no tiene punto de entrada ("dyld: main executable has no entry
    # point"). PHP 7.4 es la unica rama que ejecuta un programa de prueba (el de GD: "GD build test
    # failed"); -fvisibility=default, que va despues en la linea del compilador, lo anula
    [ "$short" == "7.4" ] && php_cppflags+=" -fvisibility=default"
    if needs_icu72 "$short"; then
        php_cflags+=" -Wno-error=implicit-function-declaration -Wno-error=incompatible-function-pointer-types"
        php_cflags+=" -Wno-error=int-conversion -Wno-error=incompatible-pointer-types -Wno-error=implicit-int"
    else
        php_cxxflags+=" -std=c++17"
    fi
    if needs_openssl11 "$short"; then
        build_openssl11 "$deps" $p || stack_fail
        php_ssl_pc="$deps/lib/pkgconfig"
        p=$((p + 5))
    fi
    if needs_icu72 "$short"; then
        build_icu72 "$deps" $p || stack_fail
        php_icu_pc="$deps/lib/pkgconfig"
        p=$((p + 5))
    fi
    php_pc="$php_ssl_pc:$php_icu_pc:$pc"
    # 7.4 y 8.0 traen PCRE2 10.35, cuyo JIT no reserva memoria con MAP_JIT y falla en Apple Silicon
    # ("Allocation of JIT memory failed"): usan el pcre2 de Homebrew, que bundle_libs copia dentro
    local php_extra=()
    needs_openssl11 "$short" && php_extra+=(--with-external-pcre)

    # PHP 7.4 y 8.0 buscan argon2.h solo en la ruta indicada, /usr y /usr/local (no en /opt/homebrew);
    # desde la 8.1 se busca con pkg-config y la ruta se ignora
    tar -xJf php.tar.xz && cd "php-$version" || stack_fail
    if [ -n "$php_patch" ]; then
        echo "  Parche de seguridad contra PHP2Shell (CVE-2026-109618 y CVE-2026-109619, php-src ${php_patch:0:12})"
        php2shell_diff "$version" "$build/php2shell.diff" || stack_fail
        # (primero en seco: si no encaja entero, no se toca nada)
        /usr/bin/patch -p1 -s -f --dry-run < "$build/php2shell.diff" > "$build/php-parche.log" 2>&1 \
            && /usr/bin/patch -p1 -s -f < "$build/php2shell.diff" >> "$build/php-parche.log" 2>&1 \
            || { echo "  El parche de seguridad no se aplica a PHP $version (mira php-parche.log)"; stack_fail; }
    fi
    step 3 $p $((p + 3)) 701 "Configurando" "$build/php-configure.log" env PKG_CONFIG_PATH="$php_pc" \
        CFLAGS="$php_cflags" CXXFLAGS="$php_cxxflags" CPPFLAGS="$php_cppflags" LDFLAGS="$headerpad" \
        LIBXML_CFLAGS="-I$sdk/usr/include/libxml2" LIBXML_LIBS="-lxml2" \
        CURL_CFLAGS="-I$sdk/usr/include" CURL_LIBS="-lcurl" \
        ./configure --prefix="$target/php" \
        --with-config-file-path="$target/php/etc" \
        --with-config-file-scan-dir="$target/php/etc/conf.d" \
        --enable-fpm --with-fpm-user="$web_user" --with-fpm-group="$web_group" --disable-cgi \
        --with-openssl --with-zlib --with-curl --with-readline="$(brew --prefix readline)" \
        --with-gettext="$(brew --prefix gettext)" --with-iconv="$(brew --prefix libiconv)" \
        --enable-mbstring --enable-intl --enable-bcmath --enable-calendar --enable-exif --enable-ftp \
        --enable-gd --with-jpeg --with-freetype --with-webp \
        --with-zip --enable-soap --enable-sockets --with-sodium --with-password-argon2="$(brew --prefix argon2)" \
        --enable-mysqlnd --with-mysqli=mysqlnd --with-pdo-mysql=mysqlnd \
        --with-mysql-sock="$target/var/mysql/mysql.sock" \
        --with-sqlite3 --with-pdo-sqlite "${php_extra[@]}" || stack_fail
    step 3 $((p + 3)) 37 913 "Compilando (tarda unos minutos)" "$build/php-make.log" make -j"$jobs" || stack_fail
    step 3 37 38 17 "Instalando" "$build/php-install.log" make install INSTALL_ROOT="$stage" || stack_fail
    mkdir -p "$S/php/etc" && cp php.ini-production "$S/php/etc/php.ini" || stack_fail
    cd "$build" || stack_fail

    echo "Perl $perl"
    tar -xJf perl.tar.xz && cd "perl-$perl" || stack_fail
    step 4 38 41 948 "Configurando" "$build/perl-configure.log" sh Configure -des -Dprefix="$target/perl" \
        -Dman1dir=none -Dman3dir=none || stack_fail
    step 4 41 46 1798 "Compilando" "$build/perl-make.log" make -j"$jobs" || stack_fail
    step 4 46 48 3319 "Instalando" "$build/perl-install.log" make install DESTDIR="$stage" || stack_fail
    cd "$build" || stack_fail

    echo "ProFTPD $ftp"
    tar -xzf proftpd.tar.gz && cd "proftpd-$ftp" || stack_fail
    step 5 48 49 575 "Configurando" "$build/proftpd-configure.log" env install_user="$(id -un)" install_group="$(id -gn)" \
        LDFLAGS="$headerpad" ./configure --prefix="$target/proftpd" --sysconfdir="$target/etc" \
        --localstatedir="$target/var/proftpd" --enable-auth-pam || stack_fail
    # ProFTPD falla a veces al compilar en paralelo (Homebrew tambien lo compila sin -j)
    step 5 49 50 162 "Compilando" "$build/proftpd-make.log" make || stack_fail
    step 5 50 51 50 "Instalando" "$build/proftpd-install.log" make install DESTDIR="$stage" || stack_fail
    cd "$build" || stack_fail

    echo "MariaDB $mariadb (compilar MariaDB es lo que mas tarda)"
    tar -xzf mariadb.tar.gz && rm -f mariadb.tar.gz && cd "mariadb-$mariadb" || stack_fail
    step 6 51 53 0 "Configurando" "$build/mariadb-configure.log" cmake -S . -B build \
        -DCMAKE_BUILD_TYPE=Release -DCMAKE_INSTALL_PREFIX="$target/mysql" -DCMAKE_PREFIX_PATH="$HOMEBREW_PREFIX" \
        -DCMAKE_POLICY_VERSION_MINIMUM=3.5 \
        -DCMAKE_FIND_FRAMEWORK=LAST -DCMAKE_EXE_LINKER_FLAGS="$headerpad" -DCMAKE_SHARED_LINKER_FLAGS="$headerpad" \
        -DCMAKE_MODULE_LINKER_FLAGS="$headerpad" -DCMAKE_INSTALL_RPATH="$target/mysql/lib" \
        -DCMAKE_INSTALL_NAME_DIR="$target/mysql/lib" -DWITH_SSL="$b_ssl" -DWITH_PCRE=system -DWITH_LIBFMT=system \
        -DLIBFMT_INCLUDE_DIR="$(brew --prefix fmt)/include" \
        -DBISON_EXECUTABLE="$(brew --prefix bison)/bin/bison" -DWITH_UNIT_TESTS=OFF -DWITH_WSREP=OFF \
        -DWITH_EMBEDDED_SERVER=OFF -DINSTALL_MYSQLTESTDIR= -DINSTALL_SQLBENCHDIR= \
        -DPLUGIN_TOKUDB=NO -DPLUGIN_MROONGA=NO -DPLUGIN_SPIDER=NO -DPLUGIN_OQGRAPH=NO -DPLUGIN_ROCKSDB=NO \
        -DPLUGIN_CONNECT=NO -DPLUGIN_COLUMNSTORE=NO -DPLUGIN_S3=NO -DPLUGIN_AUTH_GSSAPI=NO \
        -DPLUGIN_AUTH_PAM=NO -DPLUGIN_AUTH_PAM_V1=NO \
        -DDEFAULT_CHARSET=utf8mb4 -DDEFAULT_COLLATION=utf8mb4_general_ci -DCOMPILATION_COMMENT="lvm-instalador" \
        || stack_fail
    strip_sdk_includes build >> "$build/mariadb-configure.log"
    step 6 53 94 0 "Compilando (tarda bastante)" "$build/mariadb-make.log" cmake --build build --parallel "$jobs" || stack_fail
    step 6 94 96 0 "Instalando" "$build/mariadb-install.log" env DESTDIR="$stage" cmake --install build || stack_fail
    # Sin el ayudante de PAM (aqui no se usa PAM): si llegara a la version, mariadb-install-db le daria
    # su carpeta al usuario del servidor (tu usuario) con un programa setuid de root dentro, hasta que
    # se borrara. Se quita antes de copiar nada como root (mariadb-install-db no tiene una opcion para
    # no hacerlo: solo lo hace si la carpeta existe)
    rm -rf "$S/mysql/lib/plugin/auth_pam_tool_dir" || stack_fail
    cd "$build" && rm -rf "mariadb-$mariadb" || stack_fail

    echo "phpMyAdmin $pma"
    progress 7 96 97 "configurando"
    tar -xJf pma.tar.xz && mv "phpMyAdmin-$pma-all-languages" "$S/phpmyadmin" || stack_fail

    echo "Configuracion"
    write_stack_files || stack_fail

    echo "Copiando dentro de la version las librerias de Homebrew que usa..."
    bundle_libs "$S" "$target" || stack_fail
    check_build_links || stack_fail

    # Copia a /Applications. Si se rehace una version, la anterior se aparta hasta que todo este copiado.
    local aside="" was_running=0 links
    if [ "$replace" -ge 1 ]; then
        # Si es la version activa, se para mientras tanto y se arranca la nueva al terminar
        if [ -n "$TEST_DIR" ]; then
            "$target/xampp" status 2> /dev/null | grep -q " esta arrancado" && was_running=1
            "$target/xampp" stop > /dev/null 2>&1
        elif [ "$(active_dir)" == "$root" ]; then
            lampp_running && was_running=1
            # Su script xampp lo ejecuta root solo si la version es de root (si no, podria ser de otro
            # programa): entonces se cierran sus procesos sin ejecutar nada de ella
            if trusted_version_dir "$root"; then
                sudo "$target/xampp" stop
            else
                close_processes --todos
            fi
        fi

        if [ $keep_data -eq 0 ] && [ -d "$target/var/mysql" ] && [ ! -L "$target/var/mysql" ]; then
            progress 7 97 98 "copia de las bases de datos"
            backup_databases "$vname" "$root" || { echo "No se pudo guardar la copia de las bases de datos."; stack_fail; }
        fi

        aside=$root.anterior-$(date +%Y%m%d%H%M%S)
        echo "Apartando la version anterior en $aside..."
        $SUDO mv "$root" "$aside" || stack_fail
    fi

    echo "Copiando a $root..."
    progress 7 98 99 "copiando a $root"
    # Lo compilado es de tu usuario: como root se copia sin -p (cada fichero nace de root, sin setuid
    # ni el dueño de antes) y sin escritura para otros
    # (los enlaces se vuelven a mirar en la copia, que ya es de root: entre la primera comprobacion y
    # la copia se podria haber puesto otro)
    # (mkdir sin -p: si ya hubiera una carpeta con ese nombre, puesta por otro programa mientras se
    # compilaba, falla y no se copia dentro)
    # (y, ya de root, root mira que sus programas solo carguen librerias suyas o del sistema: una de
    # /opt/homebrew, que es de tu usuario, la cargaria Apache como root. MACHO_AUDIT_PY)
    local audit=""
    if ! { $SUDO mkdir "$root" && $SUDO cp -R "$stage$root/." "$root/" && $SUDO chmod -R go-w,ug-s "$root" \
            && links=$($SUDO /usr/bin/python3 -I -c "$BUILD_LINKS_PY" "$root" "$root" "$COMMON") && [ -z "$links" ] \
            && { [ -n "$TEST_DIR" ] || audit=$($SUDO /usr/bin/python3 -I -c "$MACHO_AUDIT_PY" "$root"); }; }; then
        [ -n "$audit" ] && { echo "  Lo compilado carga librerias de fuera de la version (no se instala):"; head -5 <<< "$audit" | sed 's/^/    /'; }
        $SUDO rm -rf "$root"
        [ -n "$aside" ] && $SUDO mv "$aside" "$root" && echo "Se ha dejado la version anterior como estaba."
        stack_fail
    fi

    if [ -z "$TEST_DIR" ]; then
        sudo chown -R root:admin "$root"
        # Tu usuario esta en el grupo admin: sin escritura de grupo (ni de otros) en lo que lee
        # Apache al arrancar como root, por si la umask la dejo (menos las bases de datos y tmp)
        sudo find "$root" \( -path "$target/var" -o -path "$target/tmp" -o -path "$target/phpmyadmin/tmp" \) -prune -o \
            ! -type l \( -perm -020 -o -perm -002 \) -exec chmod go-w {} +
        # Las dos carpetas que se abren a otros las crea root vacias: las copiadas venian de tu
        # carpeta, y si fueran un enlace root cambiaria el dueño y los permisos de lo que apuntan
        sudo rm -rf "$target/phpmyadmin/tmp" "$target/tmp"
        sudo install -d -o 0 -g "$web_group" -m 775 "$target/phpmyadmin/tmp"
        sudo install -d -o 0 -g 0 -m 1777 "$target/tmp"

        # htdocs y vhosts compartidos: se crean si es la primera version del Mac (XAMPP-compartido, de
        # root: Apache lee como root sus vhosts, certificados y claves de Docker)
        if [ ! -d "$COMMON/htdocs" ]; then
            [ -d "$COMMON" ] || sudo install -d -o root -g wheel -m 755 "$COMMON"
            sudo mkdir -p "$COMMON/htdocs"
            sudo chown "$web_user:$web_group" "$COMMON/htdocs"
        fi
        if [ ! -f "$COMMON/httpd-vhosts.conf" ]; then
            echo "# Virtual hosts compartidos por todas las versiones de PHP" | sudo tee "$COMMON/httpd-vhosts.conf" > /dev/null
        fi
    fi

    if [ $keep_data -eq 1 ]; then
        echo "Conservando las bases de datos (MariaDB ${old_mariadb} -> $mariadb)..."
        $SUDO mv "$aside/xamppfiles/var/mysql" "$target/var/mysql" || stack_fail
    else
        progress 7 99 100 "creando las bases de datos"
        init_stack_databases "$target" "$web_user" || stack_fail
    fi

    # Apache lee al comprobar (y al arrancar) los vhosts compartidos y carga sus modulos: como root,
    # solo si la version y los vhosts son de root (vhosts_root los deja asi si pasan la comprobacion)
    local trusted=1
    if [ -z "$TEST_DIR" ]; then
        vhosts_root
        trusted_version_dir "$root" || trusted=0
    fi
    if [ $trusted -eq 1 ]; then
        echo "Comprobando la configuracion..."
        $SUDO "$target/apache2/bin/httpd" -t -f "$target/etc/httpd.conf" 2>&1 | sed 's/^/  Apache: /'
        $SUDO "$target/php/sbin/php-fpm" -t --fpm-config "$target/php/etc/php-fpm.conf" 2>&1 | sed 's/^.*NOTICE: /  PHP-FPM: /'
        $SUDO "$target/proftpd/sbin/proftpd" -t -c "$target/etc/proftpd.conf" 2>&1 | grep -iv '^checking' | sed 's/^/  ProFTPD: /'
    else
        echo "No se comprueba la configuracion como administrador: la version o los vhosts compartidos no"
        echo "son de root o el grupo puede cambiarlos. Dejalo bien con: lvm-instalador asegurar --todas"
    fi

    [ -n "$aside" ] && $SUDO rm -R "$aside"
    # (fuera de la carpeta antes de borrarla: si no, lo que se ejecuta despues avisa de que no
    # encuentra la carpeta actual, getcwd)
    cd / && rm -rf "$build"

    if [ $was_running -eq 1 ]; then
        if [ $trusted -eq 1 ]; then
            $SUDO "$target/xampp" start
        else
            echo "No se arranca: primero lvm-instalador asegurar --todas"
        fi
    fi

    echo ""
    echo "XAMPP-$vname instalada en $root"
    [ "$replace" -ge 1 ] && [ $keep_data -eq 0 ] && echo "Empieza con bases de datos vacias; la copia de las anteriores esta en ~/lvm-copias"
    [ "$replace" -ge 1 ] && [ $keep_data -eq 1 ] && echo "Conserva sus bases de datos"
    [ $was_running -eq 0 ] && echo "Para usarla: lvm-instalador use $vname"

    return 0
}

# ===========================================================================
# Ejecucion de un plan de instalacion
# ===========================================================================

# Nombre de un elemento del plan de instalacion
function plan_label() {
    local name=${1#*:}

    case "${1%%:*}" in
        php) echo "PHP $name" ;;
        rehacer) echo "PHP ${name%.*} (actualizar)" ;;
        parchear) echo "PHP $name (parche de seguridad)" ;;
    esac
}

# Instala un elemento del plan (en un subproceso: las funciones de instalacion usan exit)
function run_plan_item() {
    case "${1%%:*}" in
        php) ( install_stack "${1#*:}" ) ;;
        rehacer) ( install_stack "${1#*:}" 1 ) ;;
        parchear) ( install_stack "${1#*:}" 2 ) ;;
    esac
}

function fmt_minutes() {
    if [ "$1" -lt 60 ]; then
        echo "menos de 1 min"
    else
        echo "$(( ($1 + 30) / 60 )) min"
    fi
}

# Pantalla de la barra de progreso (protocolo de whiptail --gauge) a partir de $PROGRESS
function progress_screen() {
    local info=$(grep '^I|' "$PROGRESS" | tail -1)
    [ -z "$info" ] && return 0

    local k n label started
    IFS='|' read -r _ k n label started <<< "$info"

    # Solo cuentan las lineas escritas desde que empezo esta version
    local section=$(awk '/^I\|/ {buf = ""} {buf = buf $0 "\n"} END {printf "%s", buf}' "$PROGRESS")
    local parts=$(grep '^C|' <<< "$section" | tail -1 | cut -d'|' -f2)
    local step=$(grep '^S|' <<< "$section" | tail -1)
    local pct=0 cur=0 what="" from to mode file total t0 done=0 frac=0

    if [ -n "$step" ]; then
        IFS='|' read -r _ cur from to what mode file total t0 <<< "$step"
        case "$mode" in
            lines) done=$(wc -l < "$file" 2> /dev/null | tr -dc '0-9') ;;
            bytes) done=$(stat -f %z "$file" 2> /dev/null) ;;
            time) done=$(( $(date +%s) - t0 )) ;;
            percent) done=$(tail -n 40 "$file" 2> /dev/null | grep -oE '^\[ *[0-9]+%\]' | tail -1 | tr -dc '0-9') ;;
        esac
        if [ -n "$mode" ] && [ "${total:-0}" -gt 0 ]; then
            frac=$(( ${done:-0} * 1000 / total ))
            (( frac > 990 )) && frac=990
        fi
        pct=$(( from + (to - from) * frac / 1000 ))
    fi
    grep -q '^R|' <<< "$section" && pct=100 && cur=999

    local text="Instalando $k de $n: $label\n\n" i=1 part list
    IFS=';' read -r -a list <<< "$parts"
    for part in "${list[@]}"; do
        if (( i < cur )); then
            text+="  [x] $part\n"
        elif (( i == cur )); then
            text+="  [>] $part: $what\n"
        else
            text+="  [ ] $part\n"
        fi
        i=$(( i + 1 ))
    done

    local elapsed=$(( $(date +%s) - started ))
    text+="\nTiempo: $(fmt_minutes $elapsed)"
    if (( pct >= 5 && pct < 100 )); then
        local left=$(( elapsed * (100 - pct) / pct ))
        if (( left < 60 )); then text+="   Queda menos de 1 min"; else text+="   Quedan unos $(fmt_minutes $left)"; fi
    fi
    (( n > 1 )) && text+="\nTotal de la instalacion: $(( ((k - 1) * 100 + pct) / n ))%"

    printf 'XXX\n%d\n%s\nXXX\n' "$pct" "$text"
}

# Barra de progreso mientras se instala en segundo plano (proceso <pid>)
function progress_gauge() {
    local job=$1
    local rows=$(tput lines 2> /dev/null || echo 24)
    local text_lines=12
    (( text_lines + 6 > rows - 1 )) && text_lines=$(( rows - 7 ))

    # whiptail fija el alto del texto con el texto inicial: se abre con lineas vacias
    local init=$(printf '%.0s \\n' $(seq $text_lines))

    while true; do
        local finished=0
        kill -0 "$job" 2> /dev/null || finished=1
        progress_screen
        [ $finished -eq 1 ] && break
        sleep 1
    done | wt --title "$TITLE" --gauge "$init" $(( text_lines + 6 )) 74 0
}

# Solo una instalacion a la vez
LOCK_DIR="$LOG_DIR/instalando.lock"

function lock_install() {
    mkdir -p -m 700 "$LOG_DIR"
    if ! mkdir "$LOCK_DIR" 2> /dev/null; then
        local pid=$(cat "$LOCK_DIR/pid" 2> /dev/null)
        [ -n "$pid" ] && kill -0 "$pid" 2> /dev/null && return 1
        rm -rf "$LOCK_DIR"
        mkdir "$LOCK_DIR" 2> /dev/null || return 1
    fi
    echo $$ > "$LOCK_DIR/pid"
}

function unlock_install() {
    rm -rf "$LOCK_DIR"
}

function other_install_running() {
    local pid=$(cat "$LOCK_DIR/pid" 2> /dev/null)
    [ -n "$pid" ] && [ "$pid" != "$$" ] && kill -0 "$pid" 2> /dev/null
}

# install_plan "php:8.4.26 rehacer:8.3.35 ..."
function install_plan() {
    local items=($1) item ok=() failed=() errors=""

    mkdir -p -m 700 "$LOG_DIR"

    if [ "$DRY" -eq 0 ]; then
        if ! lock_install; then
            ui_msg "Hay otra instalacion en marcha. Espera a que termine."

            return 1
        fi

        if [ -z "$TEST_DIR" ]; then
            # Pide la contraseña una sola vez y la mantiene activa durante toda la instalacion
            echo "Se necesita la contraseña de administrador (sudo):"
            sudo -v || { unlock_install; return 1; }
            while true; do sudo -n true; sleep 50; kill -0 "$$" 2> /dev/null || exit; done 2> /dev/null &
            local keepalive=$!
            trap "kill $keepalive 2> /dev/null; unlock_install" EXIT
        else
            trap "unlock_install" EXIT
        fi
    fi

    if [ "$UI" == "whiptail" ] && [ "$DRY" -eq 0 ]; then
        # Con ventanas: la instalacion va en segundo plano (salida al log) y se muestra la barra
        PROGRESS=$(mktemp /tmp/lvm-progreso-XXXX)
        (
            local k=0
            for item in "${items[@]}"; do
                k=$(( k + 1 ))
                echo "I|$k|${#items[@]}|$(plan_label "$item")|$(date +%s)" >> "$PROGRESS"
                echo -e "\n================ ${item/:/ } ================" >> "$LOG"
                run_plan_item "$item" < /dev/null > "$PROGRESS.$k" 2>&1
                echo "R|$item|$?" >> "$PROGRESS"
                cat "$PROGRESS.$k" >> "$LOG"
            done
        ) &
        local job=$!
        progress_gauge "$job"
        wait "$job"

        local k=0 rc
        for item in "${items[@]}"; do
            k=$(( k + 1 ))
            rc=$(grep "^R|$item|" "$PROGRESS" | cut -d'|' -f3)
            if [ "$rc" == "0" ]; then
                ok+=("$item")
            else
                failed+=("$item")
                errors+="\nUltimas lineas de ${item/:/ }:\n$(tail -8 "$PROGRESS.$k" 2> /dev/null | fold -w 90)\n"
            fi
        done
        rm -f "$PROGRESS" "$PROGRESS".*
        PROGRESS=""
    else
        # La ventana pasa LVM_PROGRESO: se escribe el mismo archivo de progreso que lee la barra
        [ -n "$LVM_PROGRESO" ] && [ "$DRY" -eq 0 ] && PROGRESS=$LVM_PROGRESO
        local k=0 rc
        for item in "${items[@]}"; do
            k=$(( k + 1 ))
            [ -n "$PROGRESS" ] && echo "I|$k|${#items[@]}|$(plan_label "$item")|$(date +%s)" >> "$PROGRESS"
            echo ""
            echo "================ ${item/:/ } ================" | tee -a "$LOG"

            run_plan_item "$item" 2>&1 | tee -a "$LOG"
            rc=${PIPESTATUS[0]}

            [ -n "$PROGRESS" ] && echo "R|$item|$rc" >> "$PROGRESS"
            if [ "$rc" -eq 0 ]; then ok+=("$item"); else failed+=("$item"); fi
        done
        PROGRESS=""
    fi

    [ "$DRY" -eq 0 ] && unlock_install

    local summary="Resultado de la instalacion:\n\n"
    for item in "${ok[@]}"; do
        local name=${item#*:}
        summary+="  OK     PHP ${name}  ->  activar con: lvm-instalador use ${name%.*}\n"
    done
    for item in "${failed[@]}"; do
        local name=${item#*:}
        summary+="  ERROR  PHP ${name}  (no se ha instalado nada; revisa el log)\n"
    done
    summary+="$errors\nLog completo: $LOG"
    [ "$DRY" -eq 1 ] && summary+="\n\nSIMULACION: no se ha hecho ningun cambio."

    echo -e "\n$summary" >> "$LOG"
    ui_msg "$summary"

    [ ${#failed[@]} -eq 0 ]
}

function check_space() {
    local needed=$1
    # En modo prueba la carpeta puede no existir todavia: se mira la mas cercana que exista
    local dir=$BASE_DIR
    while [ ! -d "$dir" ] && [ "$dir" != "/" ]; do dir=$(dirname "$dir"); done
    local free=$(df -g "$dir" | awk 'NR == 2 {print $4}')

    if [ "${free:-0}" -lt "$(( needed + 2 ))" ]; then
        ui_msg "Espacio insuficiente: hay ${free}G libres y se necesitan unos ${needed}G (+2G de margen)."

        return 1
    fi
}

# ===========================================================================
# Panel
# ===========================================================================

function panel_install() {
    local releases=$(php_releases) supported=$(php_supported) states=$(php_branch_states)
    local items=() branch full sha f note
    local widths="13 8 8 9 9 8 11 14"
    local header=$(fmt_row "$widths" "Instalar" "PHP" "Apache" "MariaDB" "ProFTPD" "Perl" "phpMyAdmin" "PHP (php.net)")

    if [ -z "$releases" ]; then
        ui_msg "No se pudo consultar php.net. Comprueba la conexion a internet."

        return 0
    fi

    [ "$UI" == "whiptail" ] && clear && echo "Consultando las ultimas versiones de cada componente..."
    while read -r branch full sha _; do
        [ -z "$branch" ] && continue
        # (cada version en su carpeta, XAMPP-X.Y.Z: al lado de las que ya haya de la rama)
        { [ -e "$BASE_DIR/XAMPP-$full" ] || php_installed_in "$full" > /dev/null; } && continue
        note=$(branch_state_text "$branch" "$states" "$supported")
        IFS='|' read -r -a f <<< "$(stack_versions "$full")"
        items+=("php:$full" "$(fmt_row "$widths" "PHP $full" "${f[@]}" "$note")")
    done <<< "$releases"

    if [ ${#items[@]} -eq 0 ]; then
        ui_msg "Ya tienes instaladas todas las versiones disponibles."

        return 0
    fi

    local text="Marca las versiones que quieres instalar (las que ya tienes no aparecen).\n"
    text+="Cada fila indica la version de cada componente que se instalara.\n\n"
    text+="Cada version tiene su pila propia, sin XAMPP: Apache, PHP, Perl, ProFTPD y MariaDB\n"
    text+="se compilan en tu Mac (unos 20-40 min por version) y tienen sus propias bases de datos.\n"
    text+="Segun php.net: 'estable' recibe correcciones de errores y de seguridad (la mejor para\n"
    text+="proyectos nuevos), 'solo seguridad' solo parches de seguridad y 'sin soporte' ya no\n"
    text+="recibe parches (proyectos antiguos)."

    local selected
    while true; do
        selected=$(ui_table_checklist "$text" "$header" "${items[@]}") || return 0
        selected=$(echo $selected)
        [ -n "$selected" ] && break

        # Aceptar sin marcar nada: la fila resaltada no cuenta, hay que marcarla con Espacio
        ui_msg "No has marcado ninguna version.\n\nMuevete con las flechas hasta la version y pulsa Espacio para marcarla\n(aparece [*] a su izquierda). Despues pulsa Intro para aceptar."
    done

    # Resumen
    local n=$(printf '%s\n' $selected | grep -c .)
    local needed=$(( n * SPACE_STACK_GB ))
    local summary="Se va a instalar:\n\n" item
    summary+="$header\n$(printf '%*s' ${#header} "" | tr ' ' '-')\n"

    for item in $selected; do
        full=${item#php:}
        note=$(branch_state_text "${full%.*}" "$states" "$supported")
        IFS='|' read -r -a f <<< "$(stack_versions "$full")"
        summary+="$(fmt_row "$widths" "PHP $full" "${f[@]}" "$note")\n"
    done

    summary+="\nCarpetas:"
    for item in $selected; do full=${item#php:}; summary+=" $BASE_DIR/XAMPP-$full"; done
    summary+="\n"
    summary+="Se compilan en tu Mac y tienen bases de datos propias y vacias.\n"
    summary+="Homebrew instala las librerias necesarias (no PHP), y se copian dentro de cada version.\n"
    summary+="\nEspacio aproximado: ${needed}G\n"
    summary+="\nLa version activa no cambia. Las nuevas se activan con\n'Cambiar la version activa'."
    [ "$DRY" -eq 1 ] && summary+="\n\nSIMULACION: no se hara ningun cambio."
    summary+="\n\n¿Instalar?"

    check_space "$needed" || return 0

    if other_install_running; then
        ui_msg "Hay otra instalacion en marcha. Espera a que termine."

        return 0
    fi

    ui_yesno "$summary" || return 0

    [ "$UI" == "whiptail" ] && clear
    install_plan "$selected"

    [ "$DRY" -eq 1 ] && return 0
    ui_yesno "¿Quieres activar ahora alguna de las versiones?" && panel_use
    return 0
}

function panel_use() {
    local items=() dir active=$(active_dir)

    if official_xampp; then
        ui_msg "$LINK es un XAMPP oficial. Apartalo primero (opcion del panel principal)."

        return 0
    fi

    for dir in $(version_dirs); do
        local mark=""
        [ "$dir" == "$active" ] && mark="activa"
        items+=("$(version_name "$dir")" "$(stack_row "$dir" "$mark")")
    done

    if [ ${#items[@]} -eq 0 ]; then
        ui_msg "No hay versiones instaladas."

        return 0
    fi

    local version
    version=$(ui_table_menu "Elige la version que quieres activar.\nSe parara la version activa y se arrancara la elegida." \
        "$(version_name "$active")" "$(stack_header "Estado")" "${items[@]}") || return 0

    if [ "$BASE_DIR/XAMPP-$version" == "$active" ]; then
        ui_yesno "XAMPP-$version ya es la version activa. ¿Reiniciarla?" || return 0
        [ "$UI" == "whiptail" ] && clear
        control_lampp restart
    else
        [ "$UI" == "whiptail" ] && clear
        use_version "$version"
    fi

    [ -t 0 ] && [ "$NO_ASK" != "1" ] && read -p "Pulsa Intro para volver al panel... " _
}

function panel_set_aside() {
    local text="Hay un XAMPP oficial en $LINK.\n\n"
    text+="Este gestor necesita que $LINK sea un enlace a la version activa. Sin borrar nada:\n"
    text+="  1. Se para (si algo sigue en marcha, no se mueve nada).\n"
    text+="  2. Se copian todas sus bases de datos (.zip) en ~/lvm-copias/XAMPP-oficial-<fecha>.\n"
    text+="  3. Se copian sus proyectos a $COMMON/htdocs y sus vhosts al fichero compartido.\n"
    text+="  4. Se mueve a $APPS_DIR/XAMPP-oficial-<fecha>.\n\n"
    text+="Despues, activa una version y carga sus bases (en la ventana, en Configuración).\n"
    text+="Se puede deshacer con Volver al XAMPP oficial.\n\n¿Apartarlo?"

    ui_yesno "$text" || return 0
    [ "$UI" == "whiptail" ] && clear
    set_aside_official
    [ -t 0 ] && [ "$NO_ASK" != "1" ] && read -p "Pulsa Intro para volver al panel... " _
}

function panel_restore_official() {
    local aside=$(ls -d "$APPS_DIR"/XAMPP-oficial-* 2> /dev/null | sort | tail -1)
    ui_yesno "Se para y desactiva la version activa del gestor y $aside\nvuelve a $LINK, y se arranca.\n\nLas versiones del gestor, sus bases de datos y las copias no se tocan.\n\n¿Volver al XAMPP oficial?" || return 0
    [ "$UI" == "whiptail" ] && clear
    restore_official "$aside"
    [ -t 0 ] && [ "$NO_ASK" != "1" ] && read -p "Pulsa Intro para volver al panel... " _
}

function panel_databases() {
    local choice active
    while true; do
        active=$(active_dir)
        local where="ninguna version activa"
        [ -n "$active" ] && where="XAMPP-$(version_name "$active")"
        choice=$(ui_menu "Bases de datos. Cargar, crear y borrar se hace en la version activa ($where)." "${choice:-ver}" \
            "ver" "Ver las bases de datos de cada version" \
            "cargar" "Subir o actualizar una base de datos (fichero .sql, .sql.gz o .zip)" \
            "crear" "Crear una base de datos" \
            "borrar" "Borrar una base de datos") || return 0
        case "$choice" in
            ver) panel_db_list ;;
            cargar) panel_db_import ;;
            crear) panel_db_create ;;
            borrar) panel_db_drop ;;
        esac
    done
}

function panel_db_list() {
    local items=() dir version count active=$(active_dir)
    local widths="10 12 30"

    for dir in $(version_dirs); do
        version=$(version_name "$dir")
        count=$(db_names "$dir" | grep -c .)
        local data="propias"
        [ "$dir" == "$active" ] && data+=" (activa)"
        items+=("$version" "$(fmt_row "$widths" "$version" "$count" "$data")")
    done
    version=""

    if [ ${#items[@]} -eq 0 ]; then
        ui_msg "No hay versiones instaladas."

        return 0
    fi

    while true; do
        version=$(ui_table_menu "Elige una version para ver sus bases de datos." "${version:-$(version_name "$active")}" \
            "$(fmt_row "$widths" "Version" "BBDD" "De quien son")" "${items[@]}") || return 0

        local cols=$(tput cols 2> /dev/null || echo 80)
        ui_msg "$(databases_text "$version" $(( (cols > 110 ? 110 : cols) - 8 )))"
    done
}

# ===========================================================================
# Bases de datos de la version activa: cargar, crear y borrar
# ===========================================================================

# El cliente $LINK/xamppfiles/bin/mysql lee el my.cnf de la version activa (socket y puerto). Si root
# tiene contraseña, se pasa en la variable MYSQL_PWD
DB_SYSTEM="information_schema|mysql|performance_schema|phpmyadmin|sys|test"
# Para pruebas se puede usar otro cliente (por ejemplo uno contra un MariaDB temporal)
DB_CLIENT=${LVM_BD_CLIENTE:-$LINK/xamppfiles/bin/mysql}
# El cliente y mysqldump de XAMPP leen tambien ~/.my.cnf y $MYSQL_HOME/my.cnf, que cualquier programa
# tuyo puede preparar (plugin-dir/default-auth les hacen cargar una biblioteca) y se ejecutan en la
# terminal de la tarea, con el permiso de sudo recordado: siempre sin esos ficheros
DB_SAFE=(/usr/bin/env -u MYSQL_HOME -u MARIADB_HOME HOME=/var/empty)

# Tamaño legible: 1,5 GB
function human_size() {
    awk -v n="${1:-0}" 'BEGIN {
        split("B KB MB GB TB", u); i = 1
        while (n >= 1024 && i < 5) { n /= 1024; i++ }
        s = (i == 1) ? sprintf("%d %s", n, u[i]) : sprintf("%.1f %s", n, u[i])
        gsub(/\./, ",", s); print s
    }'
}

# Lo que ocupa en el disco cada proyecto de htdocs (du), para la lista de Proyectos:
# T|carpeta|bytes|cuando se midio. Se guarda y se vuelven a medir los que tienen la medida de hace mas
# de 6 horas, de 10 en 10 (du tarda con miles de ficheros), los mas antiguos antes. Si quedan mas por
# medir, lo dice al final (F|cuantos) y la ventana pide la siguiente tanda. Con "ya", sin esperar.
# (bash 3.2 de macOS: sin arrays asociativos ni mapfile; du de BSD, en KB)
function gui_project_sizes() {
    local cache=$LOG_DIR/cache/proyectos-tamanos now dir name t k left=0 list batch
    local -a dirs=()
    now=$(date +%s)
    mkdir -p -m 700 "$LOG_DIR/cache" || return 0
    [ -f "$cache" ] || : > "$cache"
    # Los que hay que medir, los mas antiguos antes («cuando|carpeta»)
    list=$(for dir in "$HTDOCS_DIR"/*; do
               name=${dir##*/}
               [ -d "$dir" ] && [ ! -L "$dir" ] && [[ "$name" != *'|'* ]] || continue
               t=$(awk -F'|' -v n="$name" '$1 == n { print $3; exit }' "$cache")
               [[ "$t" =~ ^[0-9]+$ ]] || t=0
               if [ "$1" == ya ] || [ $((now - t)) -ge 21600 ]; then echo "$t|$name"; fi
           done | sort -t'|' -k1,1n)
    if [ -n "$list" ]; then
        left=$(( $(wc -l <<< "$list") - 10 ))
        [ $left -lt 0 ] && left=0
        batch=$(head -10 <<< "$list" | cut -d'|' -f2-)
        while IFS= read -r name; do dirs+=("$HTDOCS_DIR/$name"); done <<< "$batch"
        # (sin salir del disco ni seguir enlaces; lo que no se puede leer no cuenta)
        { REDO=$batch awk -F'|' 'BEGIN { n = split(ENVIRON["REDO"], r, "\n"); for (i = 1; i <= n; i++) skip[r[i]] = 1 }
                                 !($1 in skip)' "$cache" | while IFS='|' read -r name k t; do
              [ -d "$HTDOCS_DIR/$name" ] && [ ! -L "$HTDOCS_DIR/$name" ] && echo "$name|$k|$t"
          done
          du -skx "${dirs[@]}" 2> /dev/null | while IFS=$'\t' read -r k dir; do
              [[ "$k" =~ ^[0-9]+$ ]] && echo "${dir##*/}|$((k * 1024))|$now"
          done
        } > "$cache.nuevo" && mv -f "$cache.nuevo" "$cache"
    fi
    grep -E '^[^|]+\|[0-9]+\|[0-9]+$' "$cache" | sed 's/^/T|/'
    [ "$left" -gt 0 ] && echo "F|$left"
    return 0
}

# ¿Se puede entrar en el MariaDB de la version activa? ok|version|mariadb / clave|version / no|motivo
function gui_db_check() {
    local active=$(active_dir)
    if [ -z "$active" ]; then
        echo "no|No hay ninguna versión activa."

        return 0
    fi

    local version=$(version_name "$active") out
    if [ ! -x "$DB_CLIENT" ]; then
        echo "no|XAMPP-$version no tiene el cliente de MariaDB (bin/mysql)."

        return 0
    fi

    if out=$("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N -e 'SELECT VERSION()' < /dev/null 2>&1); then
        echo "ok|$version|${out%%-*}"
    elif [[ "$out" == *1045* ]] || [[ "$out" == *"Access denied"* ]]; then
        echo "clave|$version"
    else
        echo "no|El MariaDB de XAMPP-$version no está en marcha. Arráncalo antes."
    fi
}

# Tamaño de cada BBDD (datos e indices, de information_schema) de la version activa en marcha. Se
# guarda para enseñar tambien el de las demas versiones (sus carpetas de datos no se pueden leer sin
# sudo): Z|version de las BBDD|base|bytes|cuando se midio (segundos desde 1970). La cache se
# rehace en un fichero nuevo que sustituye al anterior (sin sed -i)
function gui_db_sizes() {
    local cache=$LOG_DIR/cache/bbdd-tamanos active owner out check now
    now=$(date +%s)
    mkdir -p -m 700 "$LOG_DIR/cache" || return 0
    active=$(active_dir)
    if [ -n "$active" ] && check=$(gui_db_check) && [[ "$check" == ok\|* ]]; then
        owner=$(version_name "$active")
        out=$("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N -B -e "SELECT table_schema, SUM(data_length + index_length) FROM information_schema.tables GROUP BY table_schema" < /dev/null 2> /dev/null)
        if [ -n "$out" ] && valid_version_name "$owner"; then
            { [ -f "$cache" ] && awk -F'|' -v v="$owner" '$1 != v' "$cache"
              awk -F'\t' -v v="$owner" -v t="$now" '$1 ~ /^[A-Za-z0-9_-]+$/ && $2 ~ /^[0-9]+$/ { print v "|" $1 "|" $2 "|" t }' <<< "$out"
            } > "$cache.nuevo" && mv -f "$cache.nuevo" "$cache"
        fi
    fi
    [ -f "$cache" ] && grep -E '^[A-Za-z0-9._-]+\|[A-Za-z0-9_-]+\|[0-9]+\|[0-9]+$' "$cache" | sed 's/^/Z|/'
    return 0
}

# Conexion con el MariaDB activo: deja en DB_FOLDER la version activa y en DB_VERSION la de MariaDB.
# Si no se puede, explica por que (sale con 3 si hace falta la contraseña de root)
function db_connect() {
    local check=$(gui_db_check)
    case "$check" in
        ok\|*)
            DB_FOLDER=$(cut -d'|' -f2 <<< "$check")
            DB_VERSION=$(cut -d'|' -f3 <<< "$check")
            ;;
        clave\|*)
            echo "MariaDB pide la contraseña de root: ponla en la variable MYSQL_PWD"

            return 3
            ;;
        *)
            echo "${check#no|}"

            return 1
            ;;
    esac
}

# Nombre de base valido y que no sea del sistema
function db_valid_name() {
    # Sin - delante: mysql y mysqldump lo tomarian como una opcion (-h otroequipo...)
    if ! [[ "$1" =~ ^[A-Za-z0-9_][A-Za-z0-9_-]{0,63}$ ]]; then
        echo "Nombre de base de datos no valido: $1 (solo letras sin acentos, numeros, _ y -, sin - delante)"

        return 1
    fi
    # (sin distinguir mayusculas: en el Mac el disco no las distingue y MySQL seria la base mysql)
    if [[ "${1,,}" =~ ^($DB_SYSTEM)$ ]]; then
        echo "$1 es una base de datos del sistema: no se toca"

        return 1
    fi
}

# Importaciones hechas con lvm-instalador: carpeta real de datos de MariaDB|base|fecha (segundos)
IMPORTS_FILE="$HOME/.lvm-instalador/importaciones"

# Bases de una carpeta de datos de MariaDB con su fecha: base|fecha|tipo. Tipo i: la de su ultima
# importacion con lvm-instalador. Tipo c: la de su carpeta, que cambia al crear o borrar tablas (al
# importar desde phpMyAdmin, por ejemplo); se lee sin MariaDB en marcha aunque la carpeta sea suya
function db_dates() {
    python3 -I - "$1" "$IMPORTS_FILE" <<'EOF'
import os, re, sys
data, imports = os.path.realpath(sys.argv[1]), sys.argv[2]
done = {}
try:
    with open(imports, encoding="utf-8") as f:
        for line in f:
            parts = line.rstrip("\n").split("|")
            if len(parts) == 3 and parts[0] == data and parts[2].isdigit():
                done[parts[1]] = int(parts[2])
except OSError:
    pass
try:
    names = os.listdir(data)
except OSError:
    names = []
rows = []
for raw in names:
    path = os.path.join(data, raw)
    if raw in ("mysql", "performance_schema", "phpmyadmin", "test", "sys") or raw.startswith("#") \
            or os.path.islink(path) or not os.path.isdir(path):
        continue
    # MariaDB guarda los caracteres especiales del nombre como @XXXX (wp_mi@002dweb es wp_mi-web)
    name = re.sub(r"@([0-9a-f]{4})", lambda m: chr(int(m.group(1), 16)), raw)
    # Solo nombres que se pueden usar: uno con | o un salto de linea (@007c, @000a) meteria lineas
    # falsas en lo que lee la ventana
    if not re.fullmatch(r"[A-Za-z0-9_][A-Za-z0-9_-]{0,63}", name):
        continue
    if name in done:
        rows.append((name, done[name], "i"))
    else:
        try:
            rows.append((name, int(os.stat(path).st_mtime), "c"))
        except OSError:
            rows.append((name, 0, "c"))
for name, when, kind in sorted(rows, key=lambda r: r[0].lower()):
    print("%s|%d|%s" % (name, when, kind))
EOF
}

# Apunta la fecha de la importacion de una base (sin fecha: la olvida, al borrarla o crearla vacia)
function db_note_import() {
    local data=$1 db=$2 when=$3
    [ "$DRY" -eq 1 ] && return 0
    data=$(python3 -I -c 'import os, sys; print(os.path.realpath(sys.argv[1]))' "$data") || return 0
    mkdir -p "$(dirname "$IMPORTS_FILE")" || return 0
    { [ -f "$IMPORTS_FILE" ] && awk -F'|' -v a="$data" -v d="$db" '!($1 == a && $2 == d)' "$IMPORTS_FILE"
      [ -n "$when" ] && echo "$data|$db|$when"; } > "$IMPORTS_FILE.nuevo"
    mv "$IMPORTS_FILE.nuevo" "$IMPORTS_FILE"
}

function db_exists() {
    # Va dentro de la consulta: solo nombres validos
    [[ "$1" =~ ^[A-Za-z0-9_-]+$ ]] || return 1
    [ "$("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N -e "SELECT COUNT(*) FROM information_schema.SCHEMATA WHERE SCHEMA_NAME='$1'" < /dev/null)" != "0" ]
}

# Bases de la version activa vistas por el servidor (sin las del sistema)
function db_list_active() {
    "${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N -e "SELECT SCHEMA_NAME FROM information_schema.SCHEMATA" < /dev/null 2> /dev/null \
        | grep -vxE "$DB_SYSTEM" | sort -f
}

# crear-bd <base>: base vacia en utf8mb4_general_ci (como las de XAMPP)
function create_database() {
    local db=$1 rc
    db_valid_name "$db" || return 1
    db_connect
    rc=$?
    [ $rc -ne 0 ] && return $rc

    if db_exists "$db"; then
        echo "Ya hay una base de datos $db en XAMPP-$DB_FOLDER"

        return 1
    fi

    run "${DB_SAFE[@]}" "$DB_CLIENT" -uroot -e "CREATE DATABASE \`$db\` CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci" < /dev/null || return 1
    db_note_import "$LINK/xamppfiles/var/mysql" "$db"
    echo "Base de datos $db creada en XAMPP-$DB_FOLDER"
}

# Tablas y tamaño (bytes) de una base: I|tablas|bytes
function gui_db_info() {
    local db=$1 rc
    db_valid_name "$db" || return 1
    db_connect
    rc=$?
    [ $rc -ne 0 ] && return $rc

    if ! db_exists "$db"; then
        echo "No hay ninguna base de datos $db en XAMPP-$DB_FOLDER"

        return 1
    fi

    "${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N -e "SELECT CONCAT('I|', COUNT(*), '|', COALESCE(SUM(DATA_LENGTH + INDEX_LENGTH), 0))
        FROM information_schema.TABLES WHERE TABLE_SCHEMA='$db'" < /dev/null
}

# borrar-bd <base> [--copia]: elimina la base y todo su contenido. Con --copia guarda antes un
# volcado en ~/lvm-copias (se puede volver a cargar con importar-bd); si la copia falla, no se borra
function drop_database() {
    local db=$1 backup=0 rc
    [ "$2" == "--copia" ] && backup=1
    db_valid_name "$db" || return 1
    db_connect
    rc=$?
    [ $rc -ne 0 ] && return $rc

    if ! db_exists "$db"; then
        echo "No hay ninguna base de datos $db en XAMPP-$DB_FOLDER"

        return 1
    fi

    if [ $backup -eq 1 ]; then
        local dump=${LVM_BD_VOLCADO:-$(dirname "$DB_CLIENT")/mysqldump}
        local dest="$HOME/lvm-copias/XAMPP-$DB_FOLDER-$db-$(date +%Y%m%d-%H%M%S).sql.gz"
        echo "Guardando copia de $db en $dest..."
        if [ "$DRY" -eq 1 ]; then
            echo "  [simulacion] mysqldump $db | gzip > $dest"
        else
            mkdir -p -m 700 "$HOME/lvm-copias"
            if ! ( set -o pipefail; "${DB_SAFE[@]}" "$dump" -uroot --default-character-set=utf8mb4 --single-transaction \
                --routines --triggers --events "$db" < /dev/null | gzip > "$dest" ); then
                rm -f "$dest"
                echo "No se ha podido guardar la copia, asi que NO se borra nada."

                return 1
            fi
            echo "Copia guardada: $dest ($(du -h "$dest" | cut -f1))"
        fi
    fi

    echo "Borrando la base de datos $db de XAMPP-$DB_FOLDER..."
    run "${DB_SAFE[@]}" "$DB_CLIENT" -uroot -e "DROP DATABASE \`$db\`" < /dev/null || return 1
    db_note_import "$LINK/xamppfiles/var/mysql" "$db"
    echo "Base de datos $db borrada"
}

# Posicion de lectura del descriptor <fd> del proceso <pid> ("pid:fd"). macOS no tiene /proc: se
# consulta con lsof, que da la posicion como 0t<decimal> o, si es grande, como 0x<hexadecimal>
function fd_offset() {
    local off=$(lsof -a -p "${1%%:*}" -d "${1##*:}" -o -Fo 2> /dev/null | sed -n 's/^o//p' | head -1)
    case "$off" in
        0t*) echo "${off#0t}" ;;
        0x*) echo $(( 16#${off#0x} )) ;;
        *) echo 0 ;;
    esac
}

# Mientras se carga un volcado, sus funciones y procedimientos ya existen: si fueran SQL SECURITY
# INVOKER y la web (que entra como root) o phpMyAdmin los usaran a mitad de carga, se ejecutarian como
# root y podrian cambiar otras bases o darle permisos a su usuario. Este filtro cambia al vuelo la
# palabra INVOKER suelta por DEFINER (se ejecutan con el usuario de la base, que solo puede tocarla),
# este donde este: asi da igual como se escriba (comentarios en medio, /*!...*/, trozos). No toca los
# nombres que la llevan dentro (invoker_id, php-di/invoker...) y conserva el largo y las mayusculas
# (no rompe los datos serializados de PHP); un texto con la palabra suelta cambia (documentado).
# Por SQL dinamico (PREPARE) no se pueden crear rutinas, y una vista solo puede tocar lo que su
# creador puede (su base); lo que quede lo neutraliza la limpieza
INVOKER_PY='
import re, sys
# La palabra INVOKER suelta (no dentro de un nombre: invoker_id, $invoker, php-di/invoker,
# Vendor\Invoker, x.invoker), en mayusculas o minusculas, pasa a DEFINER con las mismas mayusculas
RX = re.compile(rb"(?<![A-Za-z0-9_$@.\\])(?<![^*]/)INVOKER(?![A-Za-z0-9_$.\\])", re.I)
NEW = b"DEFINER"
def swap(w):
    return bytes(d if 65 <= c <= 90 else d + 32 for c, d in zip(w, NEW))
CHUNK = int(sys.argv[1]) if len(sys.argv) > 1 else 1 << 20
inp, out = sys.stdin.buffer, sys.stdout.buffer
# buf[:skip] ya se ha escrito: solo sirve para mirar los dos caracteres de antes de una palabra
buf, skip = b"", 0
while True:
    data = inp.read(CHUNK)
    eof = not data
    buf += data
    # Las palabras que empiezan en los ultimos 8 bytes esperan al trozo siguiente
    cut = len(buf) if eof else max(skip, len(buf) - 8)
    parts, pos = [], skip
    for m in RX.finditer(buf, skip):
        if m.start() >= cut:
            break
        parts.append(buf[pos:m.start()])
        parts.append(swap(m.group()))
        pos = m.end()
    cut = max(cut, pos)
    parts.append(buf[pos:cut])
    out.write(b"".join(parts))
    if eof:
        break
    keep = max(0, cut - 2)
    buf, skip = buf[keep:], cut - keep
'

# Copias en .zip (como las que se descargan del servidor): el .sql de dentro se lee sin
# descomprimirlo a disco. "info <zip>" -> nombre|tamaño|empieza por la linea del modo sandbox (1/0);
# "extraer <zip o ->" lo escribe en la salida ("-": el zip es la entrada estandar, para que el
# avance se vea en la posicion del descriptor)
ZIP_SQL_PY='
import re, shutil, sys, zipfile
# Los nombres de dentro del .zip salen en la terminal: sin caracteres de control
def clean(name):
    return re.sub(r"[\x00-\x1f\x7f-\x9f]", "?", name)
mode, src = sys.argv[1], sys.argv[2]
f = open(0, "rb", closefd=False) if src == "-" else open(src, "rb")
try:
    z = zipfile.ZipFile(f)
except Exception as exc:
    print("ERROR|El fichero .zip no es valido: %s" % clean(str(exc)))
    sys.exit(1)
sqls = [i for i in z.infolist() if not i.is_dir() and not i.filename.startswith("__MACOSX/")
        and i.filename.lower().endswith(".sql")]
if not sqls:
    print("ERROR|El .zip no tiene ningun fichero .sql dentro")
    sys.exit(1)
if len(sqls) > 1:
    print("ERROR|El .zip tiene varios .sql (%s): deja solo el que quieras cargar"
          % ", ".join(clean(i.filename) for i in sqls))
    sys.exit(1)
if mode == "info":
    with z.open(sqls[0]) as m:
        first = m.readline(200)
    print("%s|%d|%d" % (clean(sqls[0].filename).replace("|", " "), sqls[0].file_size,
                        1 if first.startswith(b"/*M!999999\\-") else 0))
    sys.exit(0)
try:
    with z.open(sqls[0]) as m:
        shutil.copyfileobj(m, sys.stdout.buffer, 1 << 20)
except BrokenPipeError:
    sys.exit(1)
'

# Escribe en un .zip (en la salida) lo que llega por la entrada, como un unico <nombre>.sql
ZIP_WRITE_PY='
import shutil, sys, time, zipfile
info = zipfile.ZipInfo(sys.argv[1], time.localtime()[:6])
info.compress_type = zipfile.ZIP_DEFLATED
info.external_attr = 0o644 << 16
with zipfile.ZipFile(sys.stdout.buffer, "w", zipfile.ZIP_DEFLATED) as z:
    with z.open(info, "w", force_zip64=True) as m:
        shutil.copyfileobj(sys.stdin.buffer, m, 1 << 20)
'

# MariaDB temporal de una version que no esta en marcha: sin red, sin comprobar usuarios
# (--skip-grant-tables: solo se llega por un socket en una carpeta temporal). Deja el socket en
# DB_TMP_SOCK; db_temp_stop lo para.
DB_TMP=""
function db_temp_start() {
    local root=$1/xamppfiles data=$1/xamppfiles/var/mysql user grants=(--skip-grant-tables)
    # (con --con-permisos, con sus usuarios: para cargar una base con su usuario lvm_bd_<base>)
    [ "$2" == "--con-permisos" ] && grants=()
    # Root ejecuta su mariadbd: solo de una version de root (como xampp_ctl)
    if [ -z "$TEST_DIR" ] && ! trusted_version_dir "$1"; then
        echo "No se arranca el MariaDB de $1 como administrador: no es de root, tiene enlaces o el grupo"
        echo "puede cambiarlo (lvm-instalador asegurar --todas)"

        return 1
    fi
    # El dueño de los datos de verdad (-L: si var/mysql es un enlace, el de su destino). Nunca root:
    # un MariaDB de root escribiria como root donde le pidiera una base (DATA DIRECTORY, registros)
    user=$($SUDO stat -L -f %Su "$data") || return 1
    [ -n "$TEST_DIR" ] && user=$(id -un)
    if [ "$user" == "root" ] || ! [[ "$user" =~ ^[A-Za-z_][A-Za-z0-9_.-]*$ ]]; then
        echo "Las BBDD de XAMPP-$(version_name "$1") son de $user: no se arranca su MariaDB con ese usuario"
        return 1
    fi
    if [ ! -x "$root/mysql/bin/mariadbd" ]; then
        echo "XAMPP-$(version_name "$1") no tiene el servidor de MariaDB"

        return 1
    fi

    # La carpeta la crea root y solo es del usuario del servidor (en el Mac, el tuyo): no pide
    # contraseña mientras dura la copia y otros usuarios del Mac no pueden llegar a su socket
    DB_TMP=$($SUDO mktemp -d /tmp/lvm-mysql-XXXX) || { DB_TMP=""; return 1; }
    DB_TMP_SOCK=$DB_TMP/mysql.sock
    $SUDO chown "$user" "$DB_TMP" && $SUDO chmod 700 "$DB_TMP" || { $SUDO rm -rf "$DB_TMP"; DB_TMP=""; return 1; }

    echo "Arrancando un MariaDB temporal de XAMPP-$(version_name "$1") (sin red, solo para esta copia)..."
    $SUDO "$root/mysql/bin/mariadbd" --defaults-file="$root/etc/my.cnf" --user="$user" --skip-networking \
        "${grants[@]}" --socket="$DB_TMP_SOCK" --pid-file="$DB_TMP/mysql.pid" --log-error="$DB_TMP/mysql.log" \
        < /dev/null > /dev/null 2>&1 &
    local server_pid=$!
    DB_TMP_PID=$server_pid DB_TMP_USER=$user

    local i
    for i in $(seq 300); do
        [ -S "$DB_TMP_SOCK" ] && return 0
        kill -0 $server_pid 2> /dev/null || break
        sleep 0.2
    done
    echo "No ha arrancado. Ultimas lineas de su registro:"
    # (lo lee el dueño de los datos, no root: si el registro fuera un enlace a un fichero de root,
    # root lo mostraria)
    $SUDO ${SUDO:+-u "$user"} /usr/bin/tail -15 "$DB_TMP/mysql.log" 2> /dev/null | sed 's/^/  /'

    return 1
}

# Para lo que se lanzo en segundo plano con $SUDO (su $!): sus hijos y el. Con sudo es el sudo (que
# pasa la señal al servidor); si sudo es una funcion (Mac), una subshell cuyo hijo es el sudo
# Solo si lleva el socket de esa carpeta (al azar) en su orden: si ya habia terminado, su PID podria
# ser de otro proceso. db_temp_kill_launched <pid lanzado> <socket>
function db_temp_kill_launched() {
    local p
    [[ "$1" =~ ^[0-9]+$ ]] && [ "$1" -gt 1 ] && [ -n "$2" ] || return 0
    for p in "$1" $($SUDO pgrep -P "$1" 2> /dev/null); do
        [[ "$($SUDO ps -ww -o args= -p "$p" 2> /dev/null)" == *"--socket=$2"* ]] && $SUDO kill "$p" 2> /dev/null
    done
    return 0
}

# PID de un MariaDB temporal: el de su .pid, solo si es de verdad ese servidor (su orden lleva el
# socket de esa carpeta, que es al azar). Si el MariaDB corre con tu usuario, otro programa tuyo
# podria poner en el .pid el de otro proceso para que root lo parase. db_temp_pid <.pid> <socket>
function db_temp_pid() {
    local pid
    $SUDO test -f "$1" && ! $SUDO test -L "$1" || return 1
    pid=$($SUDO head -c 20 "$1" 2> /dev/null | tr -d ' \n')
    [[ "$pid" =~ ^[0-9]+$ ]] && [ "$pid" -gt 1 ] || return 1
    # (con sudo: macOS no enseña la orden de los procesos de otros usuarios)
    [[ "$($SUDO ps -ww -o args= -p "$pid" 2> /dev/null)" == *"--socket=$2"* ]] || return 1
    echo "$pid"
}

# Al salir (tambien si se cancela): sin copia a medias y sin MariaDB temporal en marcha
DB_PART="" DB_COPY_TMP=""
function db_cleanup() {
    [ -n "$DB_PART" ] && rm -f "$DB_PART"
    # (copiar-bd: su copia temporal y el envoltorio del cliente, tambien si se cancela)
    [ -n "$DB_COPY_TMP" ] && rm -f "$DB_COPY_TMP"
    db_client_wrapper_remove
    db_temp_stop
}

# Envoltorio del cliente de MariaDB para un MariaDB temporal: en una carpeta de root que nadie mas
# puede cambiar. Se ejecuta muchas veces en la terminal de la tarea, que ya tiene el permiso de sudo:
# si fuera un fichero tuyo, otro programa tuyo podria cambiarlo por «sudo -n ...» y ser root.
# db_client_wrapper <cliente> <carpeta de librerias o ""> <socket>: deja la ruta en DB_CLI
DB_CLI_DIR="" DB_CLI=""
function db_client_wrapper() {
    local client=$1 libs=$2 sock=$3 body
    if [ -n "$libs" ]; then
        body=$(printf '#!/bin/bash\nexec /usr/bin/env LD_LIBRARY_PATH=%q %q --no-defaults -S %q "$@"\n' "$libs" "$client" "$sock")
    else
        body=$(printf '#!/bin/bash\nexec %q --no-defaults -S %q "$@"\n' "$client" "$sock")
    fi
    DB_CLI_DIR=$($SUDO mktemp -d /tmp/lvm-cliente-XXXXXX) || { DB_CLI_DIR=""; return 1; }
    DB_CLI=$DB_CLI_DIR/mysql
    if ! printf '%s\n' "$body" | $SUDO sh -c 'umask 022; cat > "$1"' sh "$DB_CLI" \
        || ! $SUDO chmod 755 "$DB_CLI_DIR" "$DB_CLI"; then
        db_client_wrapper_remove
        return 1
    fi
}

function db_client_wrapper_remove() {
    [ -n "$DB_CLI_DIR" ] && [[ "$DB_CLI_DIR" == /tmp/lvm-cliente-* ]] && $SUDO rm -rf "$DB_CLI_DIR"
    DB_CLI_DIR="" DB_CLI=""
}

function db_temp_stop() {
    [ -z "$DB_TMP" ] && return 0
    if $SUDO test -f "$DB_TMP/mysql.pid"; then
        echo "Parando el MariaDB temporal..."
        # El de su .pid si es el servidor (en el Mac corre con tu usuario: el .pid lo podria cambiar
        # otro programa tuyo); si no, el sudo que lo arranco (que le pasa la señal)
        local pid
        pid=$(db_temp_pid "$DB_TMP/mysql.pid" "$DB_TMP_SOCK") && $SUDO kill "$pid" 2> /dev/null \
            || db_temp_kill_launched "$DB_TMP_PID" "$DB_TMP_SOCK"
        local i
        for i in $(seq 300); do $SUDO test -f "$DB_TMP/mysql.pid" || break; sleep 0.2; done
    fi
    $SUDO rm -rf "$DB_TMP"
    DB_TMP="" DB_TMP_PID=""
}

# copiar-bd <base> <version de origen> <version de destino> [--como <nombre>] [--carpeta <carpeta|->]
# [--sustituir]: --como le da otro nombre en la de destino (base_8_4 -> base_8_5) y --carpeta la
# vincula alli a esa carpeta de proyecto (- = a ninguna; sin --carpeta, el vinculo no se toca).
# Copia una base a otra version que no
# la tiene, para probar el proyecto con otro PHP. Se descarga de la de origen (como exportar-bd) a un
# fichero solo tuyo y se carga en la de destino con la carga protegida de importar-bd (usuario de la
# base, sin DEFINER, lo INVOKER y los eventos neutralizados). Si la de destino no es la activa en
# marcha, se arranca su MariaDB solo para la copia (sin red y con su propio socket). La de origen no
# se toca
function copy_database() {
    local db=$1 src=$2 dst=$3 sdir ddir tmp rc active
    local replace=0 load=(--crear) new="" link="" usage=0
    shift 3 2> /dev/null
    # --sustituir: si la de destino ya la tiene, antes se guarda una copia suya en ~/lvm-copias y se
    # carga la de origen encima (la de destino se vacia antes de cargar)
    while [ $# -gt 0 ]; do
        case $1 in
            --sustituir) replace=1; shift ;;
            --como|--carpeta)
                [ -n "$2" ] || { usage=1; break; }
                [ "$1" == --como ] && new=$2 || link=$2
                shift 2 ;;
            *) usage=1; break ;;
        esac
    done
    if [ -z "$db" ] || [ -z "$src" ] || [ -z "$dst" ] || [ $usage -eq 1 ]; then
        echo "Uso: lvm-instalador copiar-bd <base de datos> <version de origen> <version de destino> [--como <nombre>] [--carpeta <carpeta|->] [--sustituir]"
        return 1
    fi
    new=${new:-$db}
    db_valid_name "$db" || return 1
    db_valid_name "$new" || return 1
    link=${link%/}
    if [ -n "$link" ] && [ "$link" != "-" ]; then
        valid_project "$link" || return 1
    fi
    valid_version_name "$src" && valid_version_name "$dst" || { echo "Version no valida"; return 1; }
    if [ "$src" == "$dst" ]; then
        echo "La version de origen y la de destino son la misma"
        return 1
    fi
    sdir="$BASE_DIR/XAMPP-$src" ddir="$BASE_DIR/XAMPP-$dst"
    [ -d "$sdir" ] && [ ! -L "$sdir" ] || { echo "No existe la version XAMPP-$src"; return 1; }
    [ -d "$ddir" ] && [ ! -L "$ddir" ] || { echo "No existe la version XAMPP-$dst"; return 1; }
    if ! db_names "$sdir" | grep -qxF "$db"; then
        echo "No hay ninguna BBDD $db en XAMPP-$src"
        return 1
    fi
    if db_names "$ddir" | grep -qxF "$new"; then
        if [ $replace -eq 0 ]; then
            echo "XAMPP-$dst ya tiene una BBDD $new: no se toca (con --sustituir se guarda una copia suya en"
            echo "~/lvm-copias y se pone la de XAMPP-$src en su lugar; o copiala con otro nombre: --como)"
            return 1
        fi
        load=(--crear --sin-copia)
    else
        replace=0
    fi
    active=$(active_dir)
    local shown=$db
    [ "$new" != "$db" ] && shown="$db (como $new)"
    echo "Copia de la BBDD $shown: de XAMPP-$src a XAMPP-$dst (XAMPP-$src no se toca)"
    if [ "$DRY" -eq 1 ]; then
        [ $replace -eq 1 ] && echo "  [simulacion] copia de $new de XAMPP-$dst en ~/lvm-copias (la sustituida)"
        echo "  [simulacion] descarga de $db de XAMPP-$src a un fichero temporal en ~/.lvm-instalador"
        if [ "$active" == "$(realpath_f "$ddir")" ] && lampp_running; then
            echo "  [simulacion] carga en el MariaDB en marcha de XAMPP-$dst (importar-bd ${load[*]})"
        else
            echo "  [simulacion] MariaDB temporal de XAMPP-$dst (sin red) y carga de $new"
        fi
        if [ "$link" == "-" ]; then
            echo "  [simulacion] $new sin vincular a ningun proyecto en XAMPP-$dst"
        elif [ -n "$link" ]; then
            echo "  [simulacion] $new vinculada a $link en XAMPP-$dst"
        fi
        return 0
    fi
    if [ $replace -eq 1 ]; then
        local backup="$HOME/lvm-copias/XAMPP-$dst-$new-antes-de-copiar-$(date +%Y%m%d-%H%M%S).sql.gz"
        echo "XAMPP-$dst ya tiene $new: antes se guarda una copia suya en $backup"
        mkdir -p -m 700 "$HOME/lvm-copias" || return 1
        if ! export_database "$new" "$backup" "$dst"; then
            echo "No se ha podido guardar la copia de $new de XAMPP-$dst, asi que no se ha cambiado nada."
            return 1
        fi
        db_temp_stop
    fi
    mkdir -p -m 700 "$LOG_DIR" || return 1
    tmp=$(mktemp "$LOG_DIR/copia-$db-XXXXXX") || return 1
    mv -f "$tmp" "$tmp.sql.gz" && tmp=$tmp.sql.gz || { rm -f "$tmp"; return 1; }
    # (si se cancela, db_cleanup la borra)
    DB_COPY_TMP=$tmp
    if ! export_database "$db" "$tmp" "$src"; then
        rm -f "$tmp"
        echo "No se ha podido descargar $db de XAMPP-$src: no se ha copiado nada."
        return 1
    fi
    db_temp_stop
    if [ "$active" == "$(realpath_f "$ddir")" ] && lampp_running; then
        import_database "$tmp" "$new" "${load[@]}"
        rc=$?
    else
        # MariaDB de la de destino solo para la copia, con sus usuarios (la carga va con el usuario de
        # la base). Su cliente, sin ficheros de opciones (llevarian al socket de la activa), por un
        # envoltorio en una carpeta de root (db_client_wrapper)
        local client=$ddir/xamppfiles/mysql/bin/mariadb
        if [ ! -x "$client" ] || ! db_temp_start "$ddir" --con-permisos; then
            rm -f "$tmp"
            db_temp_stop
            return 1
        fi
        if ! db_client_wrapper "$client" "" "$DB_TMP_SOCK"; then
            rm -f "$tmp"
            db_temp_stop
            return 1
        fi
        DB_CLIENT=$DB_CLI DB_TARGET_FOLDER=$dst DB_TARGET_DATA="$ddir/xamppfiles/var/mysql" import_database "$tmp" "$new" "${load[@]}"
        rc=$?
        db_client_wrapper_remove
        db_temp_stop
    fi
    rm -f "$tmp"
    DB_COPY_TMP=""
    if [ $rc -eq 0 ]; then
        if [ "$link" == "-" ]; then
            remember_project "$new" "" "$dst"
            echo "$new no queda vinculada a ningun proyecto en XAMPP-$dst (vinculala en Cargar proyecto)."
        elif [ -n "$link" ]; then
            remember_project "$new" "$link" "$dst"
            echo "$new queda vinculada al proyecto $link en XAMPP-$dst."
        fi
        echo "$new esta ahora en XAMPP-$dst. Para probar el proyecto con PHP $(php_version "$ddir" 2> /dev/null),"
        echo "cargalo en Versiones y elige XAMPP-$dst."
    fi
    return $rc
}

# pasar-version <origen> <destino>: despues de instalar el parche nuevo de PHP a su lado (XAMPP-8.4.26
# -> XAMPP-8.4.27), copia a la nueva todas las BBDD de la anterior con copiar-bd, cada una vinculada
# a su carpeta como estaba, y la activa si la anterior era la activa. La anterior no se toca (se
# desinstala despues a mano). Las que la nueva ya tiene no se tocan
function move_to_version() {
    local src=$1 dst=$2 sdir ddir db folder rc=0 was_active=0 n=0
    valid_version_name "$src" && valid_version_name "$dst" && [ -n "$src" ] && [ -n "$dst" ] && [ "$src" != "$dst" ] \
        || { echo "Uso: lvm-instalador pasar-version <origen> <destino>"; return 1; }
    sdir=$BASE_DIR/XAMPP-$src ddir=$BASE_DIR/XAMPP-$dst
    [ -f "$sdir/xamppfiles/etc/pvm-stack" ] && [ ! -L "$sdir" ] || { echo "No existe la version XAMPP-$src"; return 1; }
    [ -f "$ddir/xamppfiles/etc/pvm-stack" ] && [ ! -L "$ddir" ] || { echo "No existe la version XAMPP-$dst"; return 1; }
    [ "$(active_dir)" == "$(realpath_f "$sdir")" ] && was_active=1
    echo "BBDD de XAMPP-$src a XAMPP-$dst, con sus vinculos (XAMPP-$src no se toca)"
    for db in $(db_names "$sdir"); do
        if db_names "$ddir" | grep -qxF "$db"; then
            echo "  $db ya esta en XAMPP-$dst: no se toca"
            continue
        fi
        folder=$(linked_folder "$db" "$src")
        copy_database "$db" "$src" "$dst" ${folder:+--carpeta "$folder"} || { rc=1; echo "  No se ha podido copiar $db"; }
        n=$((n + 1))
    done
    [ $n -eq 0 ] && echo "  No hay BBDD que copiar"
    if [ $rc -ne 0 ]; then
        echo "Alguna BBDD no se ha copiado: XAMPP-$dst no se activa. Revisa el registro."
        return 1
    fi
    if [ $was_active -eq 1 ]; then
        echo "XAMPP-$src era la activa: se activa XAMPP-$dst"
        use_version "$dst" || return 1
    fi
    echo "Listo. Cuando compruebes que todo va bien, desinstala XAMPP-$src."
}

# Correo de pruebas en las BBDD: WordPress (sus plugins de correo) y PrestaShop (su configuracion de
# correo, por SMTP a Mailpit). Lo que cambia se apunta, con lo de antes, en MAIL_TABLE de la propia
# base; MAIL_DB_PY lo deshace al cambiar de modo o apagarlo y para las copias (ver mail_export_filter)
MAIL_DB_PY='
import re, sys
# Correo de pruebas en una BBDD (mail_db y exportar-bd). Ordenes:
#   consulta                      (entrada: tabla<TAB>columna de la base) -> SQL que saca las filas
#   cambios <modo> <puerto> <sql> (entrada: esas filas) -> en <sql>, lo que deshace lo de antes y aplica
#                                 el modo (mailpit, desactivar, nada o apagado); en la salida, que cambia
#   copia                         (entrada: esas filas) -> SQL que deja los valores de antes (para el
#                                 final de un volcado)
# Las filas llegan con los valores en hexadecimal (- = NULL): O (opciones de WordPress), M (sitemeta de
# un multisitio), C (configuracion de PrestaShop), T (tabla y su tipo) y R (lo apuntado en MAIL_TABLE:
# tabla, fila, clave, tipo, ruta, valor de antes y valor puesto). Los nombres de tablas y claves se
# comprueban: la tabla apuntada puede venir de un volcado
Q = chr(39)
NAME = re.compile(r"^[A-Za-z0-9_]+$")
REC = "lvm_correo_original"
WP_OPTS = ("active_plugins", "wp_mail_smtp", "easy_wp_smtp", "solid_smtp_providers")
PS_MAIL = (("PS_MAIL_METHOD", "2"), ("PS_MAIL_SERVER", "127.0.0.1"), ("PS_MAIL_SMTP_PORT", None),
           ("PS_MAIL_SMTP_ENCRYPTION", "off"), ("PS_MAIL_USER", ""), ("PS_MAIL_PASSWD", ""))
# Plugins de correo de WordPress, por su carpeta: nombre y si su correo se lleva a Mailpit con
# phpmailer_init (los demas sustituyen wp_mail o mandan por una API: se desactivan). WP SMTP (Solid
# Mail) tambien se desactiva si tiene una conexion de Postmark, que va por API
PLUGINS = {
    "wp-mail-smtp": ("WP Mail SMTP", True), "wp-mail-smtp-pro": ("WP Mail SMTP Pro", True),
    "easy-wp-smtp": ("Easy WP SMTP", True), "smtp-mailer": ("SMTP Mailer", True),
    "wp-smtp": ("WP SMTP (Solid Mail)", True),
    "mailin": ("Brevo", False), "woocommerce-sendinblue-newsletter-subscription": ("Brevo para WooCommerce", False),
    "post-smtp": ("Post SMTP", False), "fluent-smtp": ("FluentSMTP", False), "gmail-smtp": ("Gmail SMTP", False),
    "wp-ses": ("WP Offload SES", False), "wp-offload-ses": ("WP Offload SES", False),
    "sendgrid-email-delivery-simplified": ("SendGrid", False), "mailgun": ("Mailgun", False),
    "postmark-approved-wordpress-plugin": ("Postmark", False), "sparkpost": ("SparkPost", False),
    "wp-mail-bank": ("Mail Bank", False), "mailjet-for-wordpress": ("Mailjet", False),
    "mailpoet": ("MailPoet", False), "suremails": ("SureMail", False),
}
# Opciones de WP Mail SMTP y Easy WP SMTP: con un servicio por API (brevo, sendgrid...), a mail()
MAILER_OPTS = {"wp_mail_smtp": ("wp-mail-smtp", "wp-mail-smtp-pro"), "easy_wp_smtp": ("easy-wp-smtp",)}
SMTP_MAILERS = (b"mail", b"smtp", b"pepipost")


def plugin_info(path):
    folder = path.split(b"/")[0].decode("utf-8", "replace").lower()
    if folder in PLUGINS:
        return PLUGINS[folder]
    if folder.startswith(("sendinblue", "brevo")):
        return ("Brevo", False)
    return None


# Datos serializados de PHP (los de las opciones): N, b, i, d, s y a (las claves, en orden). Los
# objetos no: esa opcion no se toca
def unser(b, i=0):
    t = b[i:i + 1]
    if t == b"N" and b[i + 1:i + 2] == b";":
        return ("N", b""), i + 2
    if t in (b"b", b"i", b"d") and b[i + 1:i + 2] == b":":
        j = b.index(b";", i)
        return (t.decode(), b[i + 2:j]), j + 1
    if t == b"s" and b[i + 1:i + 2] == b":":
        j = b.index(b":", i + 2)
        n = int(b[i + 2:j])
        if b[j + 1:j + 2] != b"\x22" or b[j + 2 + n:j + 4 + n] != b"\x22;":
            raise ValueError("cadena")
        return ("s", b[j + 2:j + 2 + n]), j + 4 + n
    if t == b"a" and b[i + 1:i + 2] == b":":
        j = b.index(b":", i + 2)
        n = int(b[i + 2:j])
        if b[j + 1:j + 2] != b"{":
            raise ValueError("lista")
        k, items = j + 2, []
        for _ in range(n):
            key, k = unser(b, k)
            if key[0] not in ("i", "s"):
                raise ValueError("clave")
            val, k = unser(b, k)
            items.append([key, val])
        if b[k:k + 1] != b"}":
            raise ValueError("fin de lista")
        return ("a", items), k + 1
    raise ValueError("tipo")


def parse(b):
    if b is None:
        return None
    try:
        v, i = unser(b)
    except (ValueError, IndexError):
        return None
    return v if i == len(b) else None


def ser(v):
    t, x = v
    if t == "N":
        return b"N;"
    if t in ("b", "i", "d"):
        return t.encode() + b":" + x + b";"
    if t == "s":
        return b"s:%d:\x22" % len(x) + x + b"\x22;"
    return b"a:%d:{" % len(x) + b"".join(ser(k) + ser(val) for k, val in x) + b"}"


def get_path(v, path):
    for part in path:
        if not v or v[0] != "a":
            return None
        v = next((val for k, val in v[1] if k == ("s", part)), None)
    return v


def set_path(v, path, new):
    for part in path[:-1]:
        v = next((val for k, val in v[1] if k == ("s", part)), None)
    for item in v[1]:
        if item[0] == ("s", path[-1]):
            item[1] = new


def sql(b):
    if b is None:
        return "NULL"
    return "0x" + b.hex().upper() if b else Q + Q


def unhex(x):
    if x == "-":
        return None
    if not re.fullmatch(r"(?:[0-9A-Fa-f]{2})*", x):
        raise ValueError("hex")
    return bytes.fromhex(x)


def read_rows():
    tables, rows, recs = {}, {}, []
    for line in sys.stdin.read().splitlines():
        f = line.split("\t")
        try:
            if f[0] == "T" and len(f) >= 3 and NAME.match(f[1]):
                tables[f[1]] = f[2]
            elif f[0] in ("O", "M", "C") and len(f) >= 5 and NAME.match(f[1]) and f[2].isdigit():
                rows[(f[1], f[2])] = {"kind": f[0], "name": f[3], "value": unhex(f[4]), "table": f[1], "id": f[2]}
            elif f[0] == "R" and len(f) >= 8:
                recs.append({"tabla": f[1], "fila": f[2], "clave": f[3], "tipo": f[4], "ruta": f[5],
                             "original": unhex(f[6]), "puesto": unhex(f[7])})
        except ValueError:
            continue
    # (solo lo apuntado sobre tablas de esta base que se han leido, con claves y tipos conocidos)
    known = set(WP_OPTS) | {"active_sitewide_plugins"} | {n for n, _ in PS_MAIL}
    recs = [r for r in recs if r["tabla"] in tables and tables[r["tabla"]] in ("wp", "ms", "ps")
            and r["fila"].isdigit() and r["clave"] in known
            and r["tipo"] in ("quitados", "ruta", "valor", "nuevo") and r["ruta"] in ("", "mail/mailer")]
    return tables, rows, recs


def restore(rows, recs, notes):
    """Deja en rows lo de antes (lo apuntado, del ultimo al primero). Lo que se ha cambiado despues en
    local (otro plugin activado, otro servidor de correo) se respeta."""
    back = {}
    for r in reversed(recs):
        row = rows.get((r["tabla"], r["fila"]))
        if not row or row.get("gone") or row["name"] != r["clave"]:
            continue
        if r["tipo"] == "nuevo":
            if row["value"] == r["puesto"]:
                row["gone"] = True
        elif r["tipo"] == "valor":
            if row["value"] == r["puesto"]:
                row["value"] = r["original"]
                back.setdefault(r["tabla"], set()).add("correo de PrestaShop")
        elif r["tipo"] == "ruta":
            cur = parse(row["value"])
            path = [p.encode() for p in r["ruta"].split("/")]
            got = get_path(cur, path)
            if got and got[0] == "s" and got[1] == r["puesto"] and r["original"] is not None:
                set_path(cur, path, ("s", r["original"]))
                row["value"] = ser(cur)
                back.setdefault(r["tabla"], set()).add("su servicio de correo")
        elif r["tipo"] == "quitados":
            cur, old = parse(row["value"]), parse(r["original"])
            if not cur or not old or cur[0] != "a" or old[0] != "a":
                continue
            names = []
            if r["clave"] == "active_plugins":
                have = {ser(v) for _k, v in cur[1]}
                last = max([int(k[1]) for k, _v in cur[1] if k[0] == "i"] + [-1])
                for _k, v in old[1]:
                    if ser(v) not in have and v[0] == "s":
                        last += 1
                        cur[1].append([("i", str(last).encode()), v])
                        names.append(v[1])
            else:
                have = {k for k, _v in cur[1]}
                for k, v in old[1]:
                    if k not in have:
                        cur[1].append([k, v])
                        names.append(k[1])
            if names:
                row["value"] = ser(cur)
                back.setdefault(r["tabla"], set()).update(
                    (plugin_info(n) or (n.decode("utf-8", "replace"),))[0] for n in names)
    for t in sorted(back):
        notes.append("Correo de pruebas deshecho en %s: vuelve %s" % (t, ", ".join(sorted(back[t]))))


def apply(tables, rows, mode, port, recs, inserts, notes):
    """Aplica el modo sobre rows (ya con lo de antes) y apunta en recs lo que cambia."""
    if mode not in ("mailpit", "desactivar"):
        return
    for t, kind in sorted(tables.items()):
        mine = [r for r in rows.values() if r["table"] == t and not r.get("gone")]
        if kind in ("wp", "ms"):
            key = "active_plugins" if kind == "wp" else "active_sitewide_plugins"
            providers = next((r["value"] or b"" for r in mine if r["name"] == "solid_smtp_providers"), b"")
            row = next((r for r in mine if r["name"] == key), None)
            cur = parse(row["value"]) if row else None
            active = set()
            if row and not (cur and cur[0] == "a"):
                notes.append("Aviso: WordPress (%s): no se pueden leer sus plugins activos; revisa sus plugins de correo" % t)
            if cur and cur[0] == "a":
                keep, gone = [], []
                for k, v in cur[1]:
                    path = (v if kind == "wp" else k)
                    path = path[1] if path[0] == "s" else b""
                    info = plugin_info(path) if path else None
                    off = info is not None and (mode == "desactivar" or not info[1]
                                                or (path.startswith(b"wp-smtp/") and b"postmark" in providers.lower()))
                    (gone if off else keep).append([k, v])
                    if not off and path:
                        active.add(path.split(b"/")[0].decode("utf-8", "replace").lower())
                if gone:
                    if kind == "wp":
                        keep = [[("i", str(n).encode()), v] for n, (_k, v) in enumerate(keep)]
                    row["value"] = ser(("a", keep))
                    recs.append((t, row["id"], key, "quitados", "", ser(("a", gone)), None))
                    names = sorted({(plugin_info((v if kind == "wp" else k)[1]) or ("?",))[0] for k, v in gone})
                    notes.append("WordPress (%s): desactivados en la copia local: %s" % (t, ", ".join(names)))
            if mode == "mailpit" and kind == "wp":
                for opt, folders in MAILER_OPTS.items():
                    r = next((x for x in mine if x["name"] == opt), None)
                    if not r or not active & set(folders):
                        continue
                    cur = parse(r["value"])
                    got = get_path(cur, [b"mail", b"mailer"])
                    if cur is None:
                        notes.append("Aviso: WordPress (%s): no se puede leer la configuracion de %s; revisa por donde manda"
                                     % (t, PLUGINS[folders[0]][0]))
                    if got and got[0] == "s" and got[1] not in SMTP_MAILERS:
                        set_path(cur, [b"mail", b"mailer"], ("s", b"mail"))
                        r["value"] = ser(cur)
                        recs.append((t, r["id"], opt, "ruta", "mail/mailer", got[1], b"mail"))
                        notes.append("WordPress (%s): %s mandaba por %s (API): ahora por PHP, a Mailpit"
                                     % (t, PLUGINS[folders[0]][0], got[1].decode("utf-8", "replace")))
        elif kind == "ps":
            changed = False
            for name, want in PS_MAIL:
                want = (want if want is not None else port).encode()
                same = [r for r in mine if r["name"] == name]
                if not same:
                    # (una que se borro al deshacer, con su numero, o una nueva para todas las tiendas)
                    old = next((r for r in rows.values() if r["table"] == t and r.get("gone") and r["name"] == name), None)
                    if old:
                        old["gone"], old["value"] = False, want
                        recs.append((t, old["id"], name, "nuevo", "", None, want))
                    else:
                        inserts.append((t, name, want))
                    changed = True
                for r in same:
                    if r["value"] != want:
                        recs.append((t, r["id"], name, "valor", "", r["value"], want))
                        r["value"] = want
                        changed = True
            if changed or any(x[0] == t for x in recs):
                notes.append("PrestaShop (%s): correo por SMTP a Mailpit (127.0.0.1:%s)" % (t, port))


COLS = {"O": ("option_value", "option_id"), "M": ("meta_value", "meta_id"), "C": ("value", "id_configuration")}


def statements(rows, before):
    out = []
    for key, r in sorted(rows.items()):
        val, idc = COLS[r["kind"]]
        if r.get("gone"):
            out.append("DELETE FROM `%s` WHERE %s = %s;" % (r["table"], idc, r["id"]))
        elif r["value"] != before[key]:
            out.append("UPDATE `%s` SET %s = %s WHERE %s = %s;" % (r["table"], val, sql(r["value"]), idc, r["id"]))
    return out


cmd = sys.argv[1] if len(sys.argv) > 1 else ""
if cmd == "consulta":
    cols = {}
    for line in sys.stdin.read().splitlines():
        f = line.split("\t")
        if len(f) >= 2 and NAME.match(f[0]):
            cols.setdefault(f[0], set()).add(f[1])
    out = []
    lit = lambda s: Q + s + Q
    for t, c in sorted(cols.items()):
        if t == REC and {"tabla", "fila", "clave", "tipo", "ruta", "original", "puesto"} <= c:
            out.append("SELECT %s, %s, %s;" % (lit("T"), lit(t), lit("rec")))
            out.append("SELECT %s, tabla, fila, clave, tipo, ruta, IFNULL(HEX(original), %s), IFNULL(HEX(puesto), %s) FROM `%s` ORDER BY id;"
                       % (lit("R"), lit("-"), lit("-"), t))
        elif {"option_id", "option_name", "option_value"} <= c:
            out.append("SELECT %s, %s, %s;" % (lit("T"), lit(t), lit("wp")))
            out.append("SELECT %s, %s, option_id, option_name, IFNULL(HEX(option_value), %s) FROM `%s` WHERE option_name IN (%s);"
                       % (lit("O"), lit(t), lit("-"), t, ", ".join(lit(n) for n in WP_OPTS)))
        elif {"meta_id", "meta_key", "meta_value", "site_id"} <= c:
            out.append("SELECT %s, %s, %s;" % (lit("T"), lit(t), lit("ms")))
            out.append("SELECT %s, %s, meta_id, meta_key, IFNULL(HEX(meta_value), %s) FROM `%s` WHERE meta_key = %s;"
                       % (lit("M"), lit(t), lit("-"), t, lit("active_sitewide_plugins")))
        elif {"id_configuration", "name", "value", "id_shop", "id_shop_group"} <= c:
            out.append("SELECT %s, %s, %s;" % (lit("T"), lit(t), lit("ps")))
            out.append("SELECT %s, %s, id_configuration, name, IFNULL(HEX(value), %s) FROM `%s` WHERE name IN (%s);"
                       % (lit("C"), lit(t), lit("-"), t, ", ".join(lit(n) for n, _v in PS_MAIL)))
    print("\n".join(out))
elif cmd in ("cambios", "copia"):
    tables, rows, recs = read_rows()
    before = {k: r["value"] for k, r in rows.items()}
    notes, new_recs, inserts = [], [], []
    restore(rows, recs, notes)
    if cmd == "copia":
        st = statements(rows, before)
        if st:
            print("\n-- lvm-instalador: el correo de pruebas cambio esto en la copia local; aqui vuelve lo de antes")
            print("\n".join(st))
        sys.exit(0)
    mode, port, dst = sys.argv[2], sys.argv[3], sys.argv[4]
    if not port.isdigit():
        sys.exit("puerto no valido")
    apply(tables, rows, mode, port, new_recs, inserts, notes)
    st = statements(rows, before)
    has_rec = "rec" in tables.values()
    out = []
    if st or inserts or new_recs or has_rec:
        if new_recs or inserts:
            out.append("CREATE TABLE IF NOT EXISTS `%s` (id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, "
                       "tabla VARCHAR(64) NOT NULL, fila VARCHAR(20) NOT NULL, clave VARCHAR(191) NOT NULL, "
                       "tipo VARCHAR(16) NOT NULL, ruta VARCHAR(64) NOT NULL DEFAULT %s, original LONGTEXT NULL, "
                       "puesto LONGTEXT NULL, cuando DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 "
                       "COMMENT=%s;" % (REC, Q + Q, Q + "lvm-instalador: correo de pruebas, valores de antes (no va en las copias)" + Q))
        out.append("START TRANSACTION;")
        if has_rec and (new_recs or inserts):
            out.append("DELETE FROM `%s`;" % REC)
        out += st
        cols = "(tabla, fila, clave, tipo, ruta, original, puesto, cuando)"
        for t, fila, clave, tipo, ruta, orig, put in new_recs:
            out.append("INSERT INTO `%s` %s VALUES (%s, %s, %s, %s, %s, %s, %s, NOW());"
                       % (REC, cols, Q + t + Q, Q + fila + Q, Q + clave + Q, Q + tipo + Q, Q + ruta + Q, sql(orig), sql(put)))
        for t, name, val in inserts:
            out.append("INSERT INTO `%s` (id_shop_group, id_shop, name, value, date_add, date_upd) VALUES (NULL, NULL, %s, %s, NOW(), NOW());"
                       % (t, Q + name + Q, sql(val)))
            out.append("INSERT INTO `%s` %s VALUES (%s, LAST_INSERT_ID(), %s, %s, %s, NULL, %s, NOW());"
                       % (REC, cols, Q + t + Q, Q + name + Q, Q + "nuevo" + Q, Q + Q, sql(val)))
        out.append("COMMIT;")
        if has_rec and not (new_recs or inserts):
            out.append("DROP TABLE IF EXISTS `%s`;" % REC)
    with open(dst, "w", encoding="utf-8") as f:
        f.write("\n".join(out) + ("\n" if out else ""))
    for n in notes:
        print(n)
else:
    sys.exit("uso: consulta | cambios <modo> <puerto> <sql> | copia")
'

# Filas de una base que mira MAIL_DB_PY (con su orden «consulta»). mail_db_rows <base> <cliente...>
function mail_db_rows() {
    local db=$1 cols sql
    shift
    [[ "$db" =~ ^[A-Za-z0-9_-]+$ ]] || return 1
    cols=$("$@" -B -e "SELECT c.TABLE_NAME, c.COLUMN_NAME FROM information_schema.COLUMNS c
        JOIN information_schema.TABLES t ON t.TABLE_SCHEMA = c.TABLE_SCHEMA AND t.TABLE_NAME = c.TABLE_NAME
        WHERE c.TABLE_SCHEMA = '$db' AND t.TABLE_TYPE = 'BASE TABLE' AND c.COLUMN_NAME IN ('option_id', 'option_name',
        'option_value', 'meta_id', 'meta_key', 'meta_value', 'site_id', 'id_configuration', 'name', 'value', 'id_shop',
        'id_shop_group', 'tabla', 'fila', 'clave', 'tipo', 'ruta', 'original', 'puesto')" < /dev/null 2> /dev/null) || return 1
    [ -n "$cols" ] || return 0
    sql=$(python3 -I -c "$MAIL_DB_PY" consulta <<< "$cols") || return 1
    [ -n "$sql" ] || return 0
    "$@" -B "$db" -e "$sql" < /dev/null 2> /dev/null
}

# correo bd <base>: el correo de pruebas en esa base (de la version activa en marcha), segun como este:
# encendido, lleva a Mailpit (o desactiva) lo de WordPress y PrestaShop; apagado o con WordPress en
# «nada», deshace lo que se hizo. Se hace solo al cargar un proyecto o una BBDD
function mail_db() {
    local db=$1 mode=apagado rows out sqlf
    if ! [[ "$db" =~ ^[A-Za-z0-9_][A-Za-z0-9_-]{0,63}$ ]]; then
        echo "Base no valida: $db"
        return 1
    fi
    mail_on && mode=$(mail_wp_mode)
    local mysql=("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N --default-character-set=utf8mb4)
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] correo de pruebas en $db ($mode)"
        return 0
    fi
    rows=$(mail_db_rows "$db" "${mysql[@]}") || { echo "Aviso: no se ha podido leer $db para el correo de pruebas"; return 1; }
    [ -n "$rows" ] || return 0
    mkdir -p -m 700 "$LOG_DIR" || return 1
    sqlf=$(mktemp "$LOG_DIR/correo-XXXXXX") || return 1
    if ! out=$(python3 -I -c "$MAIL_DB_PY" cambios "$mode" "$MAIL_SMTP_PORT" "$sqlf" <<< "$rows"); then
        rm -f "$sqlf"
        echo "Aviso: no se ha podido preparar el correo de pruebas en $db"
        return 1
    fi
    if [ -s "$sqlf" ] && ! "${mysql[@]}" "$db" < "$sqlf" > /dev/null 2>&1; then
        rm -f "$sqlf"
        echo "Aviso: no se ha podido cambiar el correo de pruebas en $db: lo que mande la web puede salir de verdad"
        return 1
    fi
    rm -f "$sqlf"
    [ -n "$out" ] && echo "$out"
    return 0
}

# Base de un proyecto para el correo de pruebas: la indicada, la de su configuracion (PrestaShop o
# wp-config.php) o la vinculada a la carpeta
function mail_project_db() {
    local folder=$1 db=$2 conf
    if [ -z "$db" ]; then
        conf=$(ps_config "$folder")
        db=${conf%%|*}
    fi
    [ -z "$db" ] && [ -f "$HTDOCS_DIR/$folder/wp-config.php" ] && db=$(wp_config_read "$HTDOCS_DIR/$folder/wp-config.php" | head -1)
    [ -z "$db" ] && db=$(saved_project_db "$folder")
    [[ "$db" =~ ^[A-Za-z0-9_-]+$ ]] && echo "$db"
}

# Al cambiar el correo de pruebas: la BBDD del proyecto cargado (si MariaDB esta en marcha)
function mail_loaded_project() {
    local link folder db check
    link=$(project_link)
    [ -n "$link" ] && [ -L "$HTDOCS_DIR/$link" ] || return 0
    folder=$(readlink "$HTDOCS_DIR/$link")
    folder=${folder%/}
    valid_project "$folder" > /dev/null 2>&1 || return 0
    check=$(gui_db_check)
    [[ "$check" == ok\|* ]] || return 0
    db=$(mail_project_db "$folder") || return 0
    db_names "$(active_dir)" | grep -qxF "$db" || return 0
    mail_db "$db"
}

# Copias de una base (exportar-bd, copiar-bd, Docker): sin MAIL_TABLE (va a skip) y con lo que habia
# antes del correo de pruebas al final (mail_sql, que se añade al volcado). Usa query (el cliente)
function mail_export_filter() {
    local db=$1 rows
    rows=$(mail_db_rows "$db" "${query[@]}") || return 0
    grep -q "^T"$'\t'"$MAIL_TABLE"$'\t' <<< "$rows" || return 0
    skip+=(--ignore-table="$db.$MAIL_TABLE")
    mail_sql=$(python3 -I -c "$MAIL_DB_PY" copia <<< "$rows")
    return 0
}


# exportar-bd <base> <fichero .zip, .sql o .sql.gz> [version]: descarga una copia de la base
# (estructura, datos, rutinas, disparadores y eventos) que se puede volver a cargar con importar-bd.
# Sin version, de la activa. Si es la activa y esta en marcha se usa su MariaDB; si no, uno
# temporal (pide la contraseña de administrador).
# Tablas del administrador de pruebas en una base (para exportar-bd): deja en skip los --ignore-table
# del volcado de siempre y en only/wheres cada tabla con su condicion (sin las filas de
# local@local.test). Solo las tablas de verdad que lo tienen. Usa query (el cliente de la base)
function test_admin_filter() {
    local db=$1 t c p n
    local -A cols=()
    while IFS=$'\t' read -r t c; do
        [[ "$t" =~ ^[A-Za-z0-9_]+$ ]] && cols[$t]=$c
    done < <("${query[@]}" -e "SELECT c.TABLE_NAME, c.COLUMN_NAME FROM information_schema.COLUMNS c
        JOIN information_schema.TABLES t ON t.TABLE_SCHEMA = c.TABLE_SCHEMA AND t.TABLE_NAME = c.TABLE_NAME
        WHERE c.TABLE_SCHEMA = '$db' AND t.TABLE_TYPE = 'BASE TABLE' AND (
            (c.TABLE_NAME LIKE '%users' AND c.COLUMN_NAME = 'user_login')
            OR (c.TABLE_NAME LIKE '%employee' AND c.COLUMN_NAME = 'email'))" < /dev/null 2> /dev/null)
    for t in "${!cols[@]}"; do
        if [ "${cols[$t]}" == user_login ]; then
            p=${t%users}
            n=$("${query[@]}" "$db" -e "SELECT COUNT(*) FROM \`$t\` WHERE user_login = '$TEST_ADMIN_USER'" < /dev/null 2> /dev/null)
            [ "${n:-0}" -gt 0 ] 2> /dev/null || continue
            skip+=(--ignore-table="$db.$t") only+=("$t") wheres+=("NOT (user_login <=> '$TEST_ADMIN_USER')")
            if [ "$("${query[@]}" -e "SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA = '$db' AND TABLE_NAME = '${p}usermeta' AND TABLE_TYPE = 'BASE TABLE'" < /dev/null 2> /dev/null)" == 1 ]; then
                skip+=(--ignore-table="$db.${p}usermeta") only+=("${p}usermeta")
                wheres+=("user_id IS NULL OR user_id NOT IN (SELECT ID FROM \`$t\` WHERE user_login = '$TEST_ADMIN_USER')")
            fi
        else
            p=${t%employee}
            n=$("${query[@]}" "$db" -e "SELECT COUNT(*) FROM \`$t\` WHERE email = '$TEST_ADMIN_USER'" < /dev/null 2> /dev/null)
            [ "${n:-0}" -gt 0 ] 2> /dev/null || continue
            skip+=(--ignore-table="$db.$t") only+=("$t") wheres+=("NOT (email <=> '$TEST_ADMIN_USER')")
            if [ "$("${query[@]}" -e "SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA = '$db' AND TABLE_NAME = '${p}employee_shop' AND TABLE_TYPE = 'BASE TABLE'" < /dev/null 2> /dev/null)" == 1 ]; then
                skip+=(--ignore-table="$db.${p}employee_shop") only+=("${p}employee_shop")
                wheres+=("id_employee IS NULL OR id_employee NOT IN (SELECT id_employee FROM \`$t\` WHERE email = '$TEST_ADMIN_USER')")
            fi
        fi
    done
    return 0
}

function export_database() {
    local db=$1 dest=$2 folder=$3
    if [ -z "$db" ] || [ -z "$dest" ]; then
        echo "Uso: lvm-instalador exportar-bd <base de datos> <fichero.zip|.sql|.sql.gz> [version]"

        return 1
    fi
    db_valid_name "$db" || return 1
    local active=$(active_dir)
    folder=${folder:-$([ -n "$active" ] && version_name "$active")}
    local dir="$BASE_DIR/XAMPP-$folder"
    if [ -z "$folder" ] || [ ! -d "$dir" ]; then
        echo "No existe la version XAMPP-$folder"

        return 1
    fi
    if ! db_names "$dir" | grep -qxF "$db"; then
        echo "No hay ninguna base de datos $db en XAMPP-$folder"

        return 1
    fi
    local parent
    parent=$(cd "$(dirname "$dest")" 2> /dev/null && pwd -P)
    if [ -z "$parent" ] || [ ! -w "$parent" ]; then
        echo "No se puede escribir en $(dirname "$dest")"

        return 1
    fi
    dest=$parent/$(basename "$dest")

    echo "Base de datos: $db (XAMPP-$folder)"
    echo "Destino: $dest"
    local dump=() query=() check
    trap db_cleanup EXIT
    trap 'exit 130' INT TERM HUP
    if [ "$dir" == "$active" ] && check=$(gui_db_check) && [[ "$check" != no\|* ]]; then
        db_connect || return $?
        echo "Se usa el MariaDB en marcha de XAMPP-$DB_FOLDER (MariaDB $DB_VERSION)"
        dump=("${DB_SAFE[@]}" "${LVM_BD_VOLCADO:-$(dirname "$DB_CLIENT")/mysqldump}" -uroot)
        query=("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N)
    elif [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] MariaDB temporal de XAMPP-$folder y mysqldump $db > $dest"

        return 0
    else
        db_temp_start "$dir" || return 1
        dump=("$dir/xamppfiles/mysql/bin/mariadb-dump" --no-defaults -S "$DB_TMP_SOCK" -uroot)
        query=("$dir/xamppfiles/mysql/bin/mariadb" --no-defaults -S "$DB_TMP_SOCK" -uroot -N)
    fi
    # El administrador de pruebas (test_admin) no sale en la copia: sus filas de los usuarios de
    # WordPress y de los empleados de PrestaShop se quedan fuera del volcado (la BBDD de trabajo no
    # se toca). Esas tablas van aparte, con --where
    local skip=() only=() wheres=() mail_sql=""
    test_admin_filter "$db"
    [ ${#only[@]} -gt 0 ] && echo "El administrador de pruebas ($TEST_ADMIN_USER) no va en la copia"
    # Lo que cambio el correo de pruebas (plugins de WordPress, correo de PrestaShop) tampoco: la copia
    # lleva lo que habia antes (al final del volcado) y sin la tabla donde se apunto
    mail_export_filter "$db"
    [ -n "$mail_sql" ] && echo "Los cambios del correo de pruebas no van en la copia: lleva el correo como estaba"

    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] mysqldump $db > $dest"

        return 0
    fi

    local out=(cat) inner
    [[ "${dest,,}" == *.gz ]] && out=(gzip -6)
    if [[ "${dest,,}" == *.zip ]]; then
        inner=$(basename "$dest")
        inner=${inner%.*}
        out=(python3 -I -c "$ZIP_WRITE_PY" "${inner%.sql}.sql")
    fi
    local part="$dest.parte" errors=$(mktemp) pid
    DB_PART=$part
    echo "Descargando..."
    # (solo para ti: lleva la base entera, aunque la carpeta de destino sea de todos)
    ( umask 077; set -o pipefail
      { "${dump[@]}" --default-character-set=utf8mb4 --single-transaction --quick \
            --routines --triggers --events --max-allowed-packet=1G "${skip[@]}" "$db" || exit 1
        # (las tablas del administrador de pruebas, aparte y sin sus filas; sin la linea del modo
        # sandbox de cada volcado: solo la del primero, que la carga sabe quitar)
        for i in "${!only[@]}"; do
            "${dump[@]}" --default-character-set=utf8mb4 --single-transaction --quick --triggers \
                --max-allowed-packet=1G --where="${wheres[$i]}" "$db" "${only[$i]}" | LC_ALL=C sed '/^\/\*M!999999\\-/d' || exit 1
        done
        [ -z "$mail_sql" ] || printf '%s\n' "$mail_sql"; } < /dev/null 2> "$errors" | "${out[@]}" > "$part" ) &
    pid=$!
    while kill -0 $pid 2> /dev/null; do
        sleep 2
        kill -0 $pid 2> /dev/null && echo "  $(human_size "$(stat -f %z "$part" 2> /dev/null || echo 0)") escritos"
    done
    if ! wait $pid; then
        cat "$errors"
        rm -f "$errors"
        echo "No se ha podido descargar la base de datos."

        return 1
    fi
    rm -f "$errors"
    mv -f "$part" "$dest"
    DB_PART=""
    echo "Copia guardada: $dest ($(du -h "$dest" | cut -f1))"
}

# importar-bd <fichero .sql, .sql.gz o .zip> <base> [--crear] [--sin-copia]: carga el fichero en el
# MariaDB de la version activa. --crear crea la base si no existe. Si ya existe, siempre se vacia
# antes (se borra y se crea de nuevo con su juego de caracteres): asi no quedan tablas que el volcado
# ya no trae ni filas de una carga anterior que fallo a medias (los volcados de phpMyAdmin no llevan
# DROP TABLE y sus INSERT se suman a lo que haya). Si tiene tablas, antes se guarda una copia suya en
# ~/lvm-copias; --sin-copia no la guarda (copiar-bd, que ya la ha guardado). --vaciar se admite, pero
# ya no hace falta.
# Las copias hechas con mariadb-dump moderno empiezan por "/*M!999999\- enable the sandbox mode */",
# que los clientes de MariaDB anteriores a 10.5.25 no entienden: esa primera linea se quita al
# vuelo, sin tocar el fichero.
# Avance: el fichero se abre como descriptor 3 del script y los programas que lo leen comparten su
# posicion, que se lee con lsof (fd_offset). Con LVM_PROGRESO (o $PROGRESS, en el panel) se escribe
# una linea S con modo lsof; en una terminal con pv se muestra la barra de pv.
function import_database() {
    local file=$1 db=$2 create=0 backup=1 saved="" project="" rc
    shift 2
    while [ $# -gt 0 ]; do
        case "$1" in
            --crear) create=1 ;;
            --vaciar) ;;
            --sin-copia) backup=0 ;;
            --proyecto) project=${2%/}; shift ;;
        esac
        shift
    done

    if [ -z "$file" ] || [ -z "$db" ]; then
        echo "Uso: lvm-instalador importar-bd <fichero.sql|.sql.gz|.zip> <base de datos> [--crear] [--sin-copia] [--proyecto <carpeta>]"

        return 1
    fi
    if [ ! -f "$file" ] || [ ! -r "$file" ]; then
        echo "No se puede leer el fichero $file"

        return 1
    fi
    db_valid_name "$db" || return 1
    # (como en el resto: sin ., .. ni saltos de linea, que meterian lineas en ~/.lvm-instalador/proyectos)
    if [ -n "$project" ] && ! valid_project "$project"; then
        return 1
    fi

    # Tipo de fichero (por su contenido) y si empieza por la linea del modo sandbox. Se mira antes
    # de crear o vaciar la base, para no vaciarla si el fichero no sirve
    local kind=sql first="" sandbox=0 inner="" inner_size=0
    case "$(head -c 4 "$file" | od -An -tx1 | tr -d ' \n')" in
        1f8b*) kind=gz ;;
        504b0304) kind=zip ;;
    esac
    case "${file,,}" in
        *.zip) [ $kind == zip ] || { echo "$(basename "$file") no es un .zip valido"; return 1; } ;;
        *.gz) [ $kind == gz ] || { echo "$(basename "$file") no es un .gz valido"; return 1; } ;;
    esac
    case $kind in
        sql) first=$(head -c 200 "$file" | head -1) ;;
        gz) first=$(gzip -dc "$file" 2> /dev/null | head -c 200 | head -1) ;;
        zip)
            local info
            info=$(python3 -I -c "$ZIP_SQL_PY" info "$file")
            if [ $? -ne 0 ]; then
                echo "${info#ERROR|}"

                return 1
            fi
            IFS='|' read -r inner inner_size sandbox <<< "$info"
            ;;
    esac
    [[ "$first" == '/*M!999999\-'* ]] && sandbox=1

    # (copiar-bd a una version que no es la activa: DB_CLIENT ya va a su MariaDB temporal)
    if [ -n "$DB_TARGET_FOLDER" ]; then
        DB_FOLDER=$DB_TARGET_FOLDER
        DB_VERSION=$("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N -e "SELECT VERSION()" < /dev/null 2> /dev/null | cut -d- -f1)
        [ -n "$DB_VERSION" ] || { echo "No se puede entrar en el MariaDB de XAMPP-$DB_FOLDER"; return 1; }
    else
        db_connect
        rc=$?
        [ $rc -ne 0 ] && return $rc
    fi

    # --binary-mode: el cliente no ejecuta sus propios comandos que traiga el volcado (\! orden,
    # system, source, tee: con ellos un .sql manipulado ejecutaria programas en este Mac), solo SQL.
    # --local-infile=0: el volcado no puede leer ficheros del Mac (LOAD DATA LOCAL INFILE)
    local mysql=("${DB_SAFE[@]}" "$DB_CLIENT" -uroot --default-character-set=utf8mb4 --binary-mode --local-infile=0)
    local size=$(stat -f %z "$file") name=$(basename "$file")
    # (el nombre va en el fichero de progreso, separado por |)
    name=${name//[|$'\n'$'\r']/_}
    local progress=${LVM_PROGRESO:-$PROGRESS}

    echo "Fichero: $file ($(human_size "$size"))"
    [ $kind == zip ] && echo "Dentro del zip: $inner ($(human_size "$inner_size"), se descomprime al vuelo)"
    echo "Destino: base $db en XAMPP-$DB_FOLDER (MariaDB $DB_VERSION)"
    [ $sandbox -eq 1 ] && echo "Se quita la primera linea (/*M!999999\- enable the sandbox mode */), que los MariaDB antiguos no entienden"
    # (antes de crear o vaciar la base: si no se puede cargar, no se toca nada)
    # Con FEDERATED, CONNECT o SPIDER activos, una tabla del volcado podria conectarse a este mismo
    # MariaDB como root (sin contraseña) y leer o cambiar cualquier base: no se carga (vienen
    # desactivados; se activan a mano con INSTALL SONAME)
    local engines
    engines=$("${mysql[@]}" -N -e "SELECT GROUP_CONCAT(ENGINE) FROM information_schema.ENGINES
        WHERE ENGINE IN ('FEDERATED', 'CONNECT', 'SPIDER', 'OQGRAPH') AND SUPPORT IN ('YES', 'DEFAULT')" < /dev/null 2> /dev/null)
    if [ -n "$engines" ] && [ "$engines" != NULL ]; then
        echo "No se carga: MariaDB tiene activos los motores $engines, con los que una tabla del volcado"
        echo "podria entrar como root en este MariaDB. Desactivalos (UNINSTALL SONAME) y vuelve a cargarlo."
        return 1
    fi
    if ! db_exists "$db"; then
        if [ $create -eq 0 ]; then
            echo "La base $db no existe en XAMPP-$DB_FOLDER (con --crear se crea)"

            return 1
        fi
        echo "Creando la base de datos $db..."
        run "${mysql[@]}" -e "CREATE DATABASE \`$db\` CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci" < /dev/null || return 1
    else
        # (ya existe: se vacia siempre, con copia antes si tiene tablas)
        local tables
        tables=$("${mysql[@]}" -N -e "SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA='$db'" < /dev/null)
        if ! [[ "$tables" =~ ^[0-9]+$ ]]; then
            echo "No se pueden ver las tablas de $db: no se ha cambiado nada."
            return 1
        fi
        if [ "$tables" -gt 0 ] && [ $backup -eq 1 ]; then
            saved="$HOME/lvm-copias/XAMPP-$DB_FOLDER-$db-antes-de-cargar-$(date +%Y%m%d-%H%M%S).sql.gz"
            echo "$db ya tiene $tables $([ "$tables" == 1 ] && echo tabla || echo tablas): se borran todas antes de cargar."
            echo "Antes se guarda una copia suya en $saved"
            local dump=${LVM_BD_VOLCADO:-$(dirname "$DB_CLIENT")/mysqldump}
            if [ "$DRY" -eq 1 ]; then
                echo "  [simulacion] mysqldump $db | gzip > $saved"
            else
                mkdir -p -m 700 "$HOME/lvm-copias"
                if ! ( set -o pipefail; "${DB_SAFE[@]}" "$dump" -uroot --default-character-set=utf8mb4 --single-transaction \
                    --routines --triggers --events "$db" < /dev/null | gzip > "$saved" ); then
                    rm -f "$saved"
                    echo "No se ha podido guardar la copia de $db, asi que no se ha cambiado nada."
                    return 1
                fi
                echo "Copia guardada: $saved ($(du -h "$saved" | cut -f1))"
            fi
        fi
        echo "Vaciando la base de datos $db..."
        local charset=$("${mysql[@]}" -N -e "SELECT CONCAT(DEFAULT_CHARACTER_SET_NAME, ' COLLATE ', DEFAULT_COLLATION_NAME)
            FROM information_schema.SCHEMATA WHERE SCHEMA_NAME='$db'" < /dev/null)
        run "${mysql[@]}" -e "DROP DATABASE \`$db\`; CREATE DATABASE \`$db\` CHARACTER SET $charset" < /dev/null || return 1
    fi

    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] mysql $db < $file"
        [ -n "$project" ] && import_project "$db" "$project"

        return 0
    fi

    # Las copias de WordPress o PrestaShop pueden traer filas grandes: el servidor admite paquetes
    # de hasta 1 GB (hasta que se reinicie) y el cliente tambien
    "${mysql[@]}" -e "SET GLOBAL max_allowed_packet = GREATEST(@@GLOBAL.max_allowed_packet, 1073741824)" < /dev/null 2> /dev/null

    # El volcado se carga con el usuario de esa base (lvm_bd_<base>), que solo puede tocarla (no
    # root): un .sql de una web comprometida no puede cambiar otras bases, crear usuarios ni leer o
    # escribir ficheros desde el servidor (sin el permiso FILE). En el permiso, el _ va escapado
    # (si no, wp_x valdria tambien para wpYx). Al terminar se bloquea: no puede entrar, pero las
    # vistas y disparadores del volcado (que son suyos) siguen funcionando.
    local imp_user="lvm_bd_$db" imp_pass grant_db=${db//_/\\_}
    imp_pass=$(head -c 18 /dev/urandom | base64 | tr -d '/+=\n')
    db_drop_import_users "${mysql[@]}"
    # (con su huella, no con la contraseña: la orden se ve en ps; la contraseña va en MYSQL_PWD)
    local imp_hash
    imp_hash=$(printf '%s' "$imp_pass" | db_pass_hash) || return 1
    if ! "${mysql[@]}" -e "CREATE USER IF NOT EXISTS '$imp_user'@'localhost' IDENTIFIED BY PASSWORD '$imp_hash';
            ALTER USER '$imp_user'@'localhost' IDENTIFIED BY PASSWORD '$imp_hash' ACCOUNT UNLOCK;
            GRANT ALL PRIVILEGES ON \`$grant_db\`.* TO '$imp_user'@'localhost'" < /dev/null; then
        echo "No se ha podido preparar el usuario de la base para cargar el volcado"
        return 1
    fi
    # Si la carga se interrumpe, solo se marca: despues se limpia lo que haya cargado (con su
    # usuario, que aun puede entrar) y se bloquea igual
    local imp_stop=0
    trap 'imp_stop=1' INT TERM HUP PIPE
    local imp=(env MYSQL_PWD="$imp_pass" "${DB_SAFE[@]}" "$DB_CLIENT" -u"$imp_user" --default-character-set=utf8mb4
               --binary-mode --local-infile=0)

    # Lectura: descomprimir (gzip o zip), quitar la linea del modo sandbox (sed de macOS: el ;
    # antes de } es obligatorio) y los DEFINER de vistas, disparadores y rutinas (son de otro
    # usuario: con el temporal no se podrian crear)
    local source=(cat) filter=(env LC_ALL=C sed -E -e 's/DEFINER=`[^`]*`@`[^`]*`//g')
    case $kind in
        gz) source=(gzip -dc) ;;
        zip) source=(python3 -I -c "$ZIP_SQL_PY" extraer -) ;;
    esac
    [ $sandbox -eq 1 ] && filter=(env LC_ALL=C sed -E -e '/^\/\*M!999999\\-/d' -e 's/DEFINER=`[^`]*`@`[^`]*`//g')
    local definer=(python3 -I -c "$INVOKER_PY")
    local start=$(date +%s)

    exec 3< "$file"
    if [ -n "$progress" ]; then
        { echo "I|1|1|Cargando $name en $db|$start"
          echo "S|1|0|100|cargando|lsof|$BASHPID:3|$size|$start"; } >> "$progress"
    fi
    echo "Cargando..."
    if [ -z "$progress" ] && [ -t 2 ] && command -v pv > /dev/null; then
        # En una terminal, la barra de pv (el zip necesita poder saltar dentro del fichero: pv va
        # sobre el .sql ya descomprimido)
        if [ $kind == zip ]; then
            ( set -o pipefail; python3 -I -c "$ZIP_SQL_PY" extraer "$file" | pv -s "$inner_size" \
                | "${filter[@]}" | "${definer[@]}" | "${imp[@]}" --max-allowed-packet=1G "$db" )
        else
            ( set -o pipefail; pv -s "$size" <&3 | "${source[@]}" | "${filter[@]}" \
                | "${definer[@]}" | "${imp[@]}" --max-allowed-packet=1G "$db" )
        fi
    else
        ( set -o pipefail; "${source[@]}" <&3 | "${filter[@]}" | "${definer[@]}" | "${imp[@]}" --max-allowed-packet=1G "$db" )
    fi
    rc=$?
    exec 3<&-
    # Primero se cortan sus conexiones (un evento del volcado que ya estuviera corriendo), despues
    # eventos y tablas con DIRECTORY, luego lo INVOKER; se bloquea y root repasa que no quede nada
    db_kill_user "$imp_user" "${mysql[@]}"
    db_neutralize_extras "$db" "${imp[@]}"
    db_neutralize_invoker "$db" "${imp[@]}"
    db_lock_import_user "$imp_user" "${mysql[@]}"
    db_root_cleanup "$db" "${mysql[@]}"
    trap - INT TERM HUP PIPE
    if [ $imp_stop -eq 1 ]; then
        echo "Carga interrumpida. Lo anterior ya esta en $db."
        [ -n "$saved" ] && echo "Lo que tenia antes esta en $saved (se vuelve a cargar con importar-bd)."
        return 130
    fi
    [ -n "$progress" ] && echo "R|bd:$db|$rc" >> "$progress"

    local secs=$(( $(date +%s) - start ))
    if [ $rc -ne 0 ]; then
        echo "Error al cargar $name. Lo anterior al error ya esta en $db."
        echo "Si el error es «Access denied», el volcado intenta tocar otra base o crear usuarios:"
        echo "solo se carga lo que va en $db (un volcado de una sola base, como los de phpMyAdmin)."
        [ -n "$saved" ] && echo "Lo que tenia antes esta en $saved (se vuelve a cargar con importar-bd)."

        return 1
    fi

    local tables=$("${mysql[@]}" -N -e "SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA='$db'" < /dev/null)
    echo "Cargado en $((secs / 60)) min $((secs % 60)) s. La base $db tiene ahora $tables $([ "$tables" == 1 ] && echo tabla || echo tablas)."
    db_note_import "${DB_TARGET_DATA:-$LINK/xamppfiles/var/mysql}" "$db" "$(date +%s)"
    # Administrador de pruebas para el boton del panel de Cargar proyecto (WordPress o PrestaShop)
    local admin
    admin=$(test_admin "$db" "$project")
    grep -v '^A|' <<< "$admin" | grep .
    grep -q '^A|' <<< "$admin" && echo "Administrador de pruebas del panel: $TEST_ADMIN_USER, contraseña $TEST_ADMIN_PASS"
    # Correo de pruebas: lo que mande la web (sus plugins de correo, la configuracion de la tienda) va a
    # Mailpit (o, apagado, se deshace lo que traiga hecho)
    mail_db "$db"
    [ -n "$project" ] && { import_project "$db" "$project" || return 1; }
    return 0
}

# Vistas y rutinas SQL SECURITY INVOKER de un volcado: se ejecutarian con los permisos de quien las
# use (root en phpMyAdmin, o en la web si su wp-config.php usa root). Pasan a DEFINER, de
# lvm_bd_<base> (lo hace ese mismo usuario). Con --force: una vista rota del volcado no para las
# demas. Las que no se dejen cambiar se borran, y se avisa. db_neutralize_invoker <base> <cliente...>
function db_neutralize_invoker() {
    local db=$1 left
    shift
    local list="FROM information_schema.VIEWS WHERE TABLE_SCHEMA = DATABASE() AND SECURITY_TYPE = 'INVOKER'"
    local rlist="FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA = DATABASE() AND SECURITY_TYPE = 'INVOKER'"
    "$@" --raw -N "$db" -e "SELECT CONCAT('ALTER SQL SECURITY DEFINER VIEW \`', REPLACE(TABLE_NAME, '\`', '\`\`'), '\` AS ', VIEW_DEFINITION, ';') $list;
        SELECT CONCAT('ALTER ', ROUTINE_TYPE, ' \`', REPLACE(ROUTINE_NAME, '\`', '\`\`'), '\` SQL SECURITY DEFINER;') $rlist" \
        < /dev/null 2> /dev/null | "$@" --force "$db" > /dev/null 2>&1
    left=$("$@" --raw -N "$db" -e "SELECT CONCAT('vista ', TABLE_NAME) $list; SELECT CONCAT(LOWER(ROUTINE_TYPE), ' ', ROUTINE_NAME) $rlist" < /dev/null 2> /dev/null)
    [ -z "$left" ] && return 0
    "$@" --raw -N "$db" -e "SELECT CONCAT('DROP VIEW IF EXISTS \`', REPLACE(TABLE_NAME, '\`', '\`\`'), '\`;') $list;
        SELECT CONCAT('DROP ', ROUTINE_TYPE, ' IF EXISTS \`', REPLACE(ROUTINE_NAME, '\`', '\`\`'), '\`;') $rlist" \
        < /dev/null 2> /dev/null | "$@" --force "$db" > /dev/null 2>&1
    echo "Aviso: el volcado traia vistas o rutinas SQL SECURITY INVOKER que no se han podido pasar a"
    echo "DEFINER (rotas o mal hechas). Se han borrado, porque se ejecutarian con los permisos de quien"
    echo "las usara: $(printf '%s' "$left" | tr -c '[:alnum:]_ \n-' '?' | head -20 | paste -sd ',' - | sed 's/,/, /g')"
    # (lo que no haya podido borrar este usuario, como los paquetes de MariaDB 10.4, lo borra root
    # en db_root_cleanup)
    return 0
}

# Eventos y tablas con DATA DIRECTORY o INDEX DIRECTORY de un volcado. Los eventos se ejecutan solos
# (si el planificador de MariaDB esta encendido) aunque el usuario de la base este bloqueado, y
# podrian volver a crear vistas INVOKER. Las tablas con esas opciones guardan sus ficheros fuera de
# la carpeta de MariaDB (en las de otras versiones, en /tmp...). Se borran, y se avisa (lo hace el
# usuario de la base). db_neutralize_extras <base> <cliente...>
DB_DIRECTORY_PY='
import re, sys
# Salida de SHOW CREATE TABLE con -N --batch: nombre<TAB>sentencia, con \n \t \\ escapados
def unesc(s):
    return re.sub(r"\\(.)", lambda m: {"n": "\n", "t": "\t", "0": "\0"}.get(m.group(1), m.group(1)), s)
# La opcion de verdad es DATA DIRECTORY = <cadena>: las cadenas (un COMMENT o un DEFAULT que digan
# data directory), los nombres entre comillas y los comentarios no cuentan
def options(sql):
    sql = re.sub(r"\x27(?:[^\x27\\]|\\.|\x27\x27)*\x27", " Q ", sql)
    sql = re.sub(r"`(?:[^`]|``)*`", " I ", sql)
    return re.sub(r"/\*.*?\*/", " ", sql, flags=re.S)
for line in sys.stdin:
    name, _, create = line.rstrip("\n").partition("\t")
    if re.search(r"(?i)\b(DATA|INDEX)\s+DIRECTORY\s*=?\s*Q", options(unesc(create))):
        print("DROP TABLE IF EXISTS `%s`;" % unesc(name).replace("`", "``"))
'
function db_neutralize_extras() {
    local db=$1 events tables drop
    shift
    local elist="FROM information_schema.EVENTS WHERE EVENT_SCHEMA = DATABASE()"
    events=$("$@" --raw -N "$db" -e "SELECT EVENT_NAME $elist" < /dev/null 2> /dev/null)
    if [ -n "$events" ]; then
        "$@" --raw -N "$db" -e "SELECT CONCAT('DROP EVENT IF EXISTS \`', REPLACE(EVENT_NAME, '\`', '\`\`'), '\`;') $elist" \
            < /dev/null 2> /dev/null | "$@" --force "$db" > /dev/null 2>&1
        echo "Aviso: el volcado traia eventos programados (se ejecutan solos en el servidor). Se han"
        echo "borrado: $(printf '%s' "$events" | tr -c '[:alnum:]_ \n-' '?' | head -20 | paste -sd ',' - | sed 's/,/, /g')"
    fi
    # Las particionadas no lo dicen en CREATE_OPTIONS: se mira su SHOW CREATE TABLE
    local tlist="FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_TYPE = 'BASE TABLE'"
    drop=$( { "$@" --raw -N "$db" -e "SELECT CONCAT('DROP TABLE IF EXISTS \`', REPLACE(TABLE_NAME, '\`', '\`\`'), '\`;')
                $tlist AND CREATE_OPTIONS LIKE '%DIRECTORY%'" < /dev/null 2> /dev/null
              "$@" --raw -N "$db" -e "SELECT CONCAT('SHOW CREATE TABLE \`', REPLACE(TABLE_NAME, '\`', '\`\`'), '\`;')
                $tlist AND CREATE_OPTIONS LIKE '%partitioned%'" < /dev/null 2> /dev/null \
                  | "$@" -N --batch --force "$db" 2> /dev/null | /usr/bin/python3 -I -c "$DB_DIRECTORY_PY"; } | sort -u)
    [ -z "$drop" ] && return 0
    tables=$(printf '%s\n' "$drop" | sed -e 's/^DROP TABLE IF EXISTS `//' -e 's/`;$//')
    printf '%s\n' "$drop" | "$@" --force "$db" > /dev/null 2>&1
    echo "Aviso: el volcado traia tablas con DATA DIRECTORY o INDEX DIRECTORY, que guardan sus ficheros"
    echo "fuera de la carpeta de MariaDB. Se han borrado (con sus ficheros): $(printf '%s' "$tables" \
        | tr -c '[:alnum:]_ \n-' '?' | head -20 | paste -sd ',' - | sed 's/,/, /g')"
    if [ -n "$("$@" --raw -N "$db" -e "SELECT 1 $tlist AND CREATE_OPTIONS LIKE '%DIRECTORY%' LIMIT 1" < /dev/null 2> /dev/null)" ]; then
        echo "ATENCION: siguen quedando tablas con DATA DIRECTORY en $db."
    fi
    return 0
}

# Huella mysql_native_password de una contraseña leida de la entrada (asi no va en ninguna linea de
# ordenes, que cualquier usuario del equipo ve con ps)
function db_pass_hash() {
    python3 -I -c 'import hashlib, sys; p = sys.stdin.buffer.read(); print("*" + hashlib.sha1(hashlib.sha1(p).digest()).hexdigest().upper())'
}

# Bloquea el usuario de una base (con otra contraseña al azar): ya no puede entrar, pero lo suyo
# (vistas, disparadores) sigue funcionando. Se borra y se vuelve a crear con solo los permisos de su
# base: si durante la carga hubiera conseguido otros (globales, de otras bases, roles), no le quedan.
# db_lock_import_user <usuario> <cliente como root...>
function db_lock_import_user() {
    local user=$1 pass extra
    shift
    [[ "$user" =~ ^lvm_bd_[A-Za-z0-9_-]+$ ]] || return 0
    pass=$(head -c 18 /dev/urandom | base64 | tr -d '/+=\n')
    # Sin permiso para crear vistas, rutinas ni eventos: una rutina suya (DEFINER) no podria crear
    # despues otra INVOKER. Lo que ya tiene sigue funcionando (la proxima carga le vuelve a dar todo)
    local gdb=${user#lvm_bd_}
    gdb=${gdb//_/\\_}
    db_kill_user "$user" "$@"
    if ! "$@" -e "DROP USER IF EXISTS '$user'@'localhost';
            CREATE USER '$user'@'localhost' IDENTIFIED BY '$pass' ACCOUNT LOCK;
            GRANT ALL PRIVILEGES ON \`$gdb\`.* TO '$user'@'localhost';
            REVOKE CREATE VIEW, CREATE ROUTINE, ALTER ROUTINE, EVENT ON \`$gdb\`.* FROM '$user'@'localhost'" < /dev/null 2> /dev/null; then
        # (MariaDB sin DROP USER IF EXISTS o sin ACCOUNT LOCK: como antes, y sin lo de fuera de su base)
        "$@" -e "ALTER USER '$user'@'localhost' IDENTIFIED BY '$pass' ACCOUNT LOCK" < /dev/null 2> /dev/null
        "$@" -e "REVOKE ALL PRIVILEGES, GRANT OPTION FROM '$user'@'localhost'" < /dev/null 2> /dev/null
        "$@" -e "GRANT ALL PRIVILEGES ON \`$gdb\`.* TO '$user'@'localhost'" < /dev/null 2> /dev/null
        "$@" -e "REVOKE CREATE VIEW, CREATE ROUTINE, ALTER ROUTINE, EVENT ON \`$gdb\`.* FROM '$user'@'localhost'" < /dev/null 2> /dev/null
    fi
    # Lo que le quede fuera de su base (no deberia haber nada) se avisa
    extra=$("$@" -N --raw -e "SHOW GRANTS FOR '$user'@'localhost'" < /dev/null 2> /dev/null \
        | LVM_ON="ON \`$gdb\`.* TO " awk 'index($0, "GRANT USAGE ON *.* TO ") != 1 && !index($0, ENVIRON["LVM_ON"])' | wc -l)
    [ "${extra:-0}" -gt 0 ] && echo "Aviso: el usuario $user conserva permisos fuera de su base. Revisalo en phpMyAdmin (Cuentas de usuario)."
    db_kill_user "$user" "$@"
    return 0
}

# Corta las conexiones de un usuario de base (tambien un evento suyo en marcha). Como root.
# db_kill_user <usuario> <cliente como root...>
function db_kill_user() {
    local user=$1
    shift
    [[ "$user" =~ ^lvm_bd_[A-Za-z0-9_-]+$ ]] || return 0
    "$@" -e "KILL USER '$user'@'localhost'" < /dev/null 2> /dev/null
    return 0
}

# Repaso como root, al final de una carga (o de una que se corto): si en la base quedan vistas,
# rutinas o paquetes INVOKER, eventos o tablas con DATA DIRECTORY, root los borra (solo DROP: nunca
# se ejecutan ni se pasan a DEFINER de root) y avisa. db_root_cleanup <base> <cliente como root...>
function db_root_cleanup() {
    local db=$1 drop left
    shift
    [[ "$db" =~ ^[A-Za-z0-9_-]+$ ]] || return 0
    local w="TABLE_SCHEMA = '$db'" rw="ROUTINE_SCHEMA = '$db'" ew="EVENT_SCHEMA = '$db'"
    # (--force: en una MariaDB con las tablas del sistema antiguas, EVENTS o ROUTINES dan error y lo
    # demas tiene que seguir)
    drop=$( { "$@" --raw -N --force -e "SELECT CONCAT('DROP VIEW IF EXISTS \`$db\`.\`', REPLACE(TABLE_NAME, '\`', '\`\`'), '\`;')
                FROM information_schema.VIEWS WHERE $w AND SECURITY_TYPE = 'INVOKER';
            SELECT CONCAT(IF(ROUTINE_TYPE LIKE 'PACKAGE%', 'SET sql_mode = ORACLE; ', ''), 'DROP ', ROUTINE_TYPE,
                ' IF EXISTS \`$db\`.\`', REPLACE(ROUTINE_NAME, '\`', '\`\`'), '\`; SET sql_mode = DEFAULT;')
                FROM information_schema.ROUTINES WHERE $rw AND SECURITY_TYPE = 'INVOKER'
                ORDER BY ROUTINE_TYPE = 'PACKAGE';
            SELECT CONCAT('DROP EVENT IF EXISTS \`$db\`.\`', REPLACE(EVENT_NAME, '\`', '\`\`'), '\`;')
                FROM information_schema.EVENTS WHERE $ew;
            SELECT CONCAT('DROP TABLE IF EXISTS \`$db\`.\`', REPLACE(TABLE_NAME, '\`', '\`\`'), '\`;')
                FROM information_schema.TABLES WHERE $w AND TABLE_TYPE = 'BASE TABLE' AND CREATE_OPTIONS LIKE '%DIRECTORY%'" \
                < /dev/null 2> /dev/null
          "$@" --raw -N -e "SELECT CONCAT('SHOW CREATE TABLE \`$db\`.\`', REPLACE(TABLE_NAME, '\`', '\`\`'), '\`;')
                FROM information_schema.TABLES WHERE $w AND TABLE_TYPE = 'BASE TABLE' AND CREATE_OPTIONS LIKE '%partitioned%'" \
                < /dev/null 2> /dev/null | "$@" -N --batch --force 2> /dev/null | /usr/bin/python3 -I -c "$DB_DIRECTORY_PY" \
                | sed "s/^DROP TABLE IF EXISTS /DROP TABLE IF EXISTS \`$db\`./"; } )
    [ -z "$drop" ] && return 0
    printf '%s\n' "$drop" | "$@" --force > /dev/null 2>&1
    left=$("$@" --raw -N --force -e "SELECT CONCAT('vista ', TABLE_NAME) FROM information_schema.VIEWS WHERE $w AND SECURITY_TYPE = 'INVOKER';
        SELECT CONCAT(LOWER(ROUTINE_TYPE), ' ', ROUTINE_NAME) FROM information_schema.ROUTINES WHERE $rw AND SECURITY_TYPE = 'INVOKER';
        SELECT CONCAT('evento ', EVENT_NAME) FROM information_schema.EVENTS WHERE $ew" < /dev/null 2> /dev/null)
    echo "Aviso: en $db quedaban $(printf '%s\n' "$drop" | grep -c 'DROP ') cosas del volcado que no deben estar (vistas o"
    echo "rutinas INVOKER, eventos o tablas con DATA DIRECTORY): las ha borrado root."
    if [ -n "$left" ]; then
        echo "ATENCION: siguen en $db: $(printf '%s' "$left" | tr -c '[:alnum:]_ \n-' '?' | head -10 | paste -sd ',' - | sed 's/,/, /g')."
        echo "No abras esa base como root en phpMyAdmin hasta quitarlas."
    fi
    return 0
}

# Borra los usuarios temporales de la 1.37 (lvm_imp_*) y bloquea los de las bases (lvm_bd_*) que
# hayan quedado abiertos (una carga que no termino). Recibe el cliente de MariaDB como root.
function db_drop_import_users() {
    local u
    for u in $("$@" -N -e "SELECT User FROM mysql.user WHERE User LIKE 'lvm\\_imp\\_%' AND Host='localhost'" < /dev/null 2> /dev/null); do
        [[ "$u" =~ ^lvm_imp_[0-9a-f]+$ ]] && "$@" -e "DROP USER IF EXISTS '$u'@'localhost'" < /dev/null 2> /dev/null
    done
    local open_users old_tables=0
    open_users=$("$@" -N -e "SELECT User FROM mysql.global_priv WHERE User LIKE 'lvm\\_bd\\_%' AND Host='localhost'
            AND IFNULL(JSON_VALUE(Priv, '$.account_locked'), 'false') <> 'true'" < /dev/null 2> /dev/null) \
        || { old_tables=1; open_users=$("$@" -N -e "SELECT User FROM mysql.user WHERE User LIKE 'lvm\\_bd\\_%' AND Host='localhost'" \
            < /dev/null 2> /dev/null); }
    # (con las tablas del sistema antiguas no hay global_priv ni se sabe si estan bloqueados: todos)
    for u in $open_users; do
        # (una carga que se corto: lo que dejara en su base lo repasa root)
        db_kill_user "$u" "$@"
        db_lock_import_user "$u" "$@"
        # (con las tablas antiguas no se sabe cuales se cortaron: se bloquean todos, pero su base no se
        # repasa, que borraria lo que hayas creado despues a proposito)
        [ $old_tables -eq 0 ] && db_root_cleanup "${u#lvm_bd_}" "$@"
    done
    return 0
}

# Tablas del sistema de MariaDB (mysql.*) de una version anterior a la del servidor: los datos de
# XAMPP vienen de una MariaDB antigua sin poner al dia, y el servidor escribe un error en su registro
# cada vez que usa las estadisticas de una tabla (en una 8.2.4 llego a 28 GB). 0 si la version
# montada, en marcha, las tiene asi (en las de 10.4 en adelante: varbinary(255) y varchar(199))
function db_system_outdated() {
    [ -x "$DB_CLIENT" ] && lampp_running || return 1
    local t
    t=$("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N -e "SELECT CONCAT(TABLE_NAME, '.', COLUMN_NAME, '=', COLUMN_TYPE) FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = 'mysql' AND ((TABLE_NAME = 'column_stats' AND COLUMN_NAME = 'min_value')
        OR (TABLE_NAME = 'innodb_table_stats' AND COLUMN_NAME = 'table_name'))" < /dev/null 2> /dev/null) || return 1
    [ -n "$t" ] || return 1
    grep -q "^column_stats.min_value=varbinary" <<< "$t" && grep -q "^innodb_table_stats.table_name=varchar(199)" <<< "$t" && return 1
    return 0
}

# Registro de errores de MariaDB de una version: el .err mas grande de var/mysql (solo su ruta)
function db_error_log() {
    local f
    for f in "$1"/xamppfiles/var/mysql/*.err; do
        [ -f "$f" ] && [ ! -L "$f" ] && echo "$(stat -f %z "$f") $f"
    done | sort -rn | head -1 | cut -d' ' -f2-
}

# reparar-bd-sistema: pone al dia las tablas del sistema de MariaDB de la version montada (con su
# propio mysql_upgrade, solo las del sistema: las bases de los proyectos no se tocan), despues de
# guardar una copia de la base mysql en ~/lvm-copias, y vacia su registro de errores si es grande
function repair_db_system() {
    local dir name upgrade dump log size backup out
    dir=$(active_dir)
    if [ -z "$dir" ] || ! lampp_running; then
        echo "La version activa tiene que estar en marcha: arrancala y vuelve a intentarlo."
        return 1
    fi
    if ! wait_mariadb; then
        echo "MariaDB no responde o root tiene contraseña (ponla en MYSQL_PWD y vuelve a intentarlo)."
        return 1
    fi
    name=$(basename "$dir")
    if [ -x "$dir/xamppfiles/mysql/bin/mariadb-upgrade" ] && [ -x "$dir/xamppfiles/mysql/bin/mariadb-dump" ]; then
        upgrade=("$dir/xamppfiles/mysql/bin/mariadb-upgrade") dump=("$dir/xamppfiles/mysql/bin/mariadb-dump")
    else
        echo "$name no tiene mariadb-upgrade"
        return 1
    fi
    upgrade+=(--no-defaults -S "$dir/xamppfiles/var/mysql/mysql.sock" -uroot)
    dump+=(--no-defaults -S "$dir/xamppfiles/var/mysql/mysql.sock" -uroot)
    log=$(db_error_log "$dir")
    # mysql_upgrade escribe en la carpeta de datos (mysql_upgrade_info): se ejecuta con su dueño
    # (mysql, o tu usuario en el Mac), nunca como root. Con sudo -u, MYSQL_PWD no pasaria
    local owner as_owner=()
    owner=$(stat -f %Su "$dir/xamppfiles/var/mysql" 2> /dev/null)
    if [ -n "$owner" ] && [ "$owner" != "$(id -un)" ]; then
        [[ "$owner" =~ ^[A-Za-z0-9_][A-Za-z0-9_.-]{0,31}$ ]] && [ "$owner" != root ] || {
            echo "La carpeta de datos de $name es de $owner: no se ejecuta mysql_upgrade con ese usuario."
            return 1
        }
        as_owner=(sudo -u "$owner")
        if [ -n "$MYSQL_PWD" ]; then
            echo "root de MariaDB tiene contraseña y con sudo -u no se le pasa: hazlo a mano en la terminal:"
            echo "  sudo -u $owner ${upgrade[0]} --no-defaults -S <socket> -uroot -p --upgrade-system-tables --force"
            return 1
        fi
    fi
    if db_system_outdated; then
        echo "Las tablas del sistema de MariaDB de $name son de una version anterior: se ponen al dia"
        echo "(las bases de los proyectos no se tocan)."
        backup="$HOME/lvm-copias/$name-mysql-sistema-$(date +%Y%m%d-%H%M%S).sql.gz"
        if [ "$DRY" -eq 1 ]; then
            echo "  [simulacion] copia de la base mysql en $backup"
            echo "  [simulacion] ${upgrade[0]##*/} --upgrade-system-tables --force"
        else
            mkdir -p -m 700 "$HOME/lvm-copias" || return 1
            if ! ( set -o pipefail; umask 077; "${dump[@]}" --databases mysql < /dev/null | gzip > "$backup" ); then
                rm -f "$backup"
                echo "No se ha podido guardar la copia de la base mysql: no se cambia nada."
                return 1
            fi
            echo "Copia de las tablas del sistema: $backup"
            if ! out=$("${as_owner[@]}" "${upgrade[@]}" --upgrade-system-tables --force < /dev/null 2>&1); then
                echo "$out" | tail -8 | sed 's/^/  /'
                echo "No se han podido poner al dia (la copia esta en $backup)."
                return 1
            fi
            echo "$out" | grep -E '^(Phase|OK)' | sed 's/^/  /'
            if db_system_outdated; then
                echo "Siguen sin estar al dia: revisa la salida de arriba."
                return 1
            fi
            echo "Tablas del sistema al dia."
            # Con las tablas antiguas, MariaDB no leia mysql.proc: rutinas INVOKER de volcados de
            # antes de la 1.42 (que nunca se neutralizaron) vuelven a funcionar. Se avisa de cuales
            local inv
            inv=$("${DB_SAFE[@]}" "$DB_CLIENT" -uroot --raw -N --force -e "SELECT CONCAT(ROUTINE_SCHEMA, '.', ROUTINE_NAME) FROM information_schema.ROUTINES
                    WHERE SECURITY_TYPE = 'INVOKER' AND ROUTINE_SCHEMA NOT IN ('mysql', 'sys');
                SELECT CONCAT(TABLE_SCHEMA, '.', TABLE_NAME) FROM information_schema.VIEWS
                    WHERE SECURITY_TYPE = 'INVOKER' AND TABLE_SCHEMA NOT IN ('mysql', 'sys');
                SELECT CONCAT(EVENT_SCHEMA, '.', EVENT_NAME, ' (evento)') FROM information_schema.EVENTS" < /dev/null 2> /dev/null)
            if [ -n "$inv" ]; then
                echo "Aviso: estas rutinas, vistas o eventos se ejecutan con los permisos de quien las use (root en"
                echo "phpMyAdmin). Si no las reconoces, vuelve a cargar esa BBDD con el gestor, que las neutraliza:"
                printf '%s\n' "$inv" | tr -c '[:alnum:]_ .()\n-' '?' | head -30 | sed 's/^/  /'
            fi
        fi
    else
        echo "Las tablas del sistema de MariaDB de $name ya estan al dia."
    fi
    # El registro: si pasa de 100 MB se vacia (solo son errores, ya corregidos; MariaDB sigue
    # escribiendo en el mismo fichero)
    if [ -n "$log" ] && [ -f "$log" ] && [ ! -L "$log" ] && [[ "$log" == "$dir"/xamppfiles/var/mysql/*.err ]]; then
        size=$(stat -f %z "$log")
        if [ "$size" -gt 104857600 ]; then
            echo "El registro de errores de MariaDB ($log) ocupa $((size / 1048576)) MB: se vacia."
            # (en el Mac el registro es tuyo: MariaDB corre con tu usuario; sin sudo, que vaciaria lo
            # que apuntara un enlace puesto ahi)
            if [ "$DRY" -eq 1 ]; then
                echo "  [simulacion] vaciar $log"
            elif ! : > "$log"; then
                echo "No se ha podido vaciar (no es tuyo): vacialo a mano con: sudo sh -c ': > \"$log\"'"
            fi
        fi
    fi
    return 0
}

# Espera (hasta 8 s) a que MariaDB de la version montada acepte a root. 1 si no arranca o pide
# contraseña (y no esta en MYSQL_PWD)
function wait_mariadb() {
    local i out
    [ -x "$DB_CLIENT" ] || return 1
    for i in 1 2 3 4 5 6 7 8; do
        out=$("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N -e "SELECT 1" < /dev/null 2>&1) && return 0
        [[ "$out" == *"Access denied"* ]] && return 1
        sleep 1
    done
    return 1
}

# Sin usuarios anonimos (sin nombre ni contraseña) ni permisos de cualquiera sobre las bases test y
# test_* (las versiones nuevas ya se crean asi)
function secure_mariadb() {
    [ -x "$DB_CLIENT" ] || return 0
    local mysql=("${DB_SAFE[@]}" "$DB_CLIENT" -uroot -N) hosts h
    hosts=$("${mysql[@]}" -e "SELECT Host FROM mysql.user WHERE User=''" < /dev/null 2> /dev/null) || return 0
    for h in $hosts; do
        [[ "$h" =~ ^[A-Za-z0-9._%-]+$ ]] || continue
        echo "MariaDB: se quita el usuario anonimo (''@$h)"
        [ "$DRY" -eq 1 ] || "${mysql[@]}" -e "DROP USER IF EXISTS ''@'$h'" < /dev/null 2> /dev/null
    done
    if [ -n "$("${mysql[@]}" -e "SELECT 1 FROM mysql.db WHERE Db IN ('test', 'test\\_%') LIMIT 1" < /dev/null 2> /dev/null)" ]; then
        echo "MariaDB: se quitan los permisos de cualquiera sobre las bases test"
        [ "$DRY" -eq 1 ] || "${mysql[@]}" -e "DELETE FROM mysql.db WHERE Db IN ('test', 'test\\_%'); FLUSH PRIVILEGES" < /dev/null 2> /dev/null
    fi
    # Usuarios de las bases que hayan quedado sin bloquear (una carga interrumpida)
    [ "$DRY" -eq 1 ] || db_drop_import_users "${DB_SAFE[@]}" "$DB_CLIENT" -uroot
    return 0
}

# Base subida para un proyecto: pasa a ser su base (sustituye a la anterior). Si es un WordPress, su
# wp-config.php se rehace con la plantilla para que la use; si es una tienda PrestaShop, su
# parameters.php (o settings.inc.php) pasa a usarla y se vacia su cache
function import_project() {
    local db=$1 folder=$2
    remember_project "$db" "$folder" "${DB_TARGET_FOLDER:-}" --unica
    echo "La base $db queda asociada al proyecto $folder"
    if is_prestashop "$folder"; then
        PS_NEW_PARAMS=0
        ps_parameters "$folder" "$db" || return 1
        ps_set_db "$folder" "$db" || return 1
        ps_first_load "$folder"
    elif is_wordpress "$folder"; then
        wp_config "$folder" "$db" || return 1
    fi
    return 0
}

# ---------------------------------------------------------------- panel de bases de datos

function ui_password() {
    if [ "$UI" == "whiptail" ]; then
        ui_size "$1"
        wt --title "$TITLE" --ok-button "Aceptar" --cancel-button "Volver" \
            --passwordbox "$1" $((H + 2)) $W 3>&1 1>&2 2>&3
    else
        local answer
        echo -e "\n$1" >&2
        read -r -s -p "> " answer >&2
        echo "" >&2
        echo "$answer"
    fi
}

# Comprueba que se puede entrar en el MariaDB activo; si root tiene contraseña la pide (MYSQL_PWD)
function panel_db_connect() {
    local check=$(gui_db_check) pwd retry=""

    while [[ "$check" == clave\|* ]]; do
        pwd=$(ui_password "${retry}El usuario root del MariaDB de XAMPP-${check#clave|} tiene contraseña.\nEscribela para continuar:") || return 1
        export MYSQL_PWD=$pwd
        check=$(gui_db_check)
        retry="Contraseña incorrecta. "
    done

    if [[ "$check" != ok\|* ]]; then
        ui_msg "${check#no|}"

        return 1
    fi
}

# Elige una base de la version activa: ui_pick_db "texto" [con_nueva]
function ui_pick_db() {
    local text=$1 with_new=$2 items=() db
    while IFS= read -r db; do
        [ -n "$db" ] && items+=("$db" "")
    done < <(db_list_active)
    [ -n "$with_new" ] && items+=("@nueva" "(crear una base nueva)")

    if [ ${#items[@]} -eq 0 ]; then
        ui_msg "La version activa no tiene bases de datos (aparte de las del sistema)."

        return 1
    fi

    ui_menu "$text" "" "${items[@]}"
}

# Fichero SQL: ventana de Finder para elegirlo (osascript) o, si no se puede, la ruta escrita
function ui_pick_sql() {
    local path
    path=$(osascript -e 'try' \
        -e 'POSIX path of (choose file with prompt "Elige la copia SQL (.sql, .sql.gz o .zip)" of type {"sql", "gz", "zip", "public.data"})' \
        -e 'end try' 2> /dev/null)
    if [ -z "$path" ]; then
        path=$(ui_input "Escribe la ruta del fichero .sql, .sql.gz o .zip (puedes arrastrarlo aqui desde Finder):" "") || return 1
        # Arrastrado desde Finder llega con comillas o con los espacios escapados (\ )
        path=${path% }; path=${path%\'}; path=${path#\'}; path=${path//\\ / }
    fi
    [ -n "$path" ] && echo "$path"
}

function ui_new_db_name() {
    local name err=""
    while true; do
        name=$(ui_input "${err}Nombre de la base de datos nueva (letras sin acentos, numeros, _ y -).\nSe crea vacia en utf8mb4 (utf8mb4_general_ci)." "") || return 1
        err=$(db_valid_name "$name")
        [ -z "$err" ] && db_exists "$name" && err="Ya hay una base de datos $name."
        [ -z "$err" ] && echo "$name" && return 0
        err="$err\n\n"
    done
}

# Pantalla de la barra al cargar una base (protocolo de whiptail --gauge) a partir de $PROGRESS
function db_progress_screen() {
    local info=$(grep '^I|' "$PROGRESS" | tail -1) step=$(grep '^S|' "$PROGRESS" | tail -1)
    [ -z "$step" ] && return 0
    local label started cur from to what mode file total t0
    IFS='|' read -r _ _ _ label started <<< "$info"
    IFS='|' read -r _ cur from to what mode file total t0 <<< "$step"

    local done=$(fd_offset "$file") pct=0
    (( total > 0 )) && pct=$(( done * 100 / total ))
    (( pct > 99 )) && pct=99
    grep -q '^R|' "$PROGRESS" && pct=100 && done=$total

    local elapsed=$(( $(date +%s) - started ))
    local text="$label\n\n$(human_size "$done") de $(human_size "$total")\n\nTiempo: $(fmt_minutes $elapsed)"
    if (( pct >= 5 && pct < 100 )); then
        local left=$(( elapsed * (100 - pct) / pct ))
        if (( left < 60 )); then text+="   Queda menos de 1 min"; else text+="   Quedan unos $(fmt_minutes $left)"; fi
    fi

    printf 'XXX\n%d\n%s\nXXX\n' "$pct" "$text"
}

function panel_db_import() {
    panel_db_connect || return 0

    local file db args=()
    file=$(ui_pick_sql) || return 0
    if [ ! -r "$file" ]; then
        ui_msg "No se puede leer el fichero:\n$file"

        return 0
    fi
    db=$(ui_pick_db "Elige la base de datos de XAMPP-$(version_name "$(active_dir)") donde cargar\n$(basename "$file") ($(human_size "$(stat -f %z "$file")"))" 1) || return 0
    if [ "$db" == "@nueva" ]; then
        db=$(ui_new_db_name) || return 0
        args+=(--crear)
    fi

    local text="Se va a cargar $(basename "$file") en la base $db de XAMPP-$(version_name "$(active_dir)").\n\n"
    if [ ${#args[@]} -gt 0 ]; then
        text+="Primero se crea la base $db (vacia)."
    else
        text+="Antes se BORRAN todas las tablas de $db, para que no quede nada de lo anterior. Si tiene alguna, primero se guarda una copia en ~/lvm-copias."
    fi
    ui_yesno "$text\n\n¿Cargar?" || return 0

    if [ "$UI" == "whiptail" ] && [ "$DRY" -eq 0 ]; then
        PROGRESS=$(mktemp /tmp/lvm-progreso-XXXX)
        local out=$PROGRESS.salida
        ( import_database "$file" "$db" "${args[@]}" > "$out" 2>&1 ) &
        local job=$!
        local rows=$(tput lines 2> /dev/null || echo 24)
        while true; do
            local finished=0
            kill -0 "$job" 2> /dev/null || finished=1
            db_progress_screen
            [ $finished -eq 1 ] && break
            sleep 1
        done | wt --title "$TITLE" --gauge "$(printf '%.0s \\n' 1 2 3 4 5 6)" 12 74 0
        wait "$job"
        local rc=$?
        ui_msg "$( [ $rc -eq 0 ] && echo "Base de datos $db cargada." || echo "No se ha podido cargar la base de datos.")\n\n$(tail -12 "$out" | fold -w 90)"
        rm -f "$PROGRESS" "$out"
        PROGRESS=""
    else
        [ "$UI" == "whiptail" ] && clear
        import_database "$file" "$db" "${args[@]}"
        [ -t 0 ] && [ "$NO_ASK" != "1" ] && read -p "Pulsa Intro para volver al panel... " _
    fi
}

function panel_db_create() {
    panel_db_connect || return 0
    local name
    name=$(ui_new_db_name) || return 0
    ui_msg "$(create_database "$name" 2>&1)"
}

function panel_db_drop() {
    panel_db_connect || return 0
    local db info tables bytes
    db=$(ui_pick_db "Elige la base de datos de XAMPP-$(version_name "$(active_dir)") que quieres BORRAR.") || return 0
    info=$(gui_db_info "$db" | grep '^I|')
    IFS='|' read -r _ tables bytes <<< "$info"

    local backup=0
    if [ "${tables:-0}" -gt 0 ]; then
        local text="¿Borrar la base de datos $db de XAMPP-$(version_name "$(active_dir)")?\n\n"
        text+="Tiene $tables $([ "$tables" == 1 ] && echo tabla || echo tablas) ($(human_size "$bytes")).\n\n"
        text+="ATENCION: se eliminara todo su contenido. Esta accion es IRREVERSIBLE: no se puede deshacer."
        ui_yesno "$text" || return 0

        local choice
        choice=$(ui_menu "Antes de borrar $db puedes guardar una copia en ~/lvm-copias (un .sql.gz que se puede volver a cargar)." \
            "copia" "copia" "Guardar una copia y despues borrar" "sin" "Borrar SIN copia") || return 0
        if [ "$choice" == "copia" ]; then
            backup=1
        else
            local typed
            typed=$(ui_input "Sin copia, el contenido de $db no se podra recuperar.\n\nEscribe $db para confirmar:" "") || return 0
            if [ "$typed" != "$db" ]; then
                ui_msg "No coincide. No se ha borrado nada."

                return 0
            fi
        fi
    else
        ui_yesno "¿Borrar la base de datos $db?\n\nEsta vacia (no tiene tablas). Esta accion no se puede deshacer." || return 0
    fi

    [ "$UI" == "whiptail" ] && clear
    if [ $backup -eq 1 ]; then
        drop_database "$db" --copia
    else
        drop_database "$db"
    fi
    [ -t 0 ] && [ "$NO_ASK" != "1" ] && read -p "Pulsa Intro para volver al panel... " _
}

# Version instalada que ya tiene una version exacta de PHP (vacio y 1 si ninguna)
function php_installed_in() {
    local dir
    for dir in $(version_dirs); do
        [ "$(stack_fields "$dir" | cut -d'|' -f1)" == "$1" ] && echo "$dir" && return 0
    done
    return 1
}

# Ultima version de PHP de la rama de una instalacion
function rebuild_version() {
    local dir=$1 releases=$2
    local php=$(stack_fields "$dir" | cut -d'|' -f1)

    awk -v b="${php%.*}" '$1 == b {print $2}' <<< "$releases"
}

# Vuelve a compilar una version con la ultima pila de su rama (parches nuevos)
function panel_rebuild() {
    local releases=$(php_releases) items=() dir version full f state

    if [ -z "$releases" ]; then
        ui_msg "No se pudo consultar php.net. Comprueba la conexion a internet."

        return 0
    fi

    [ "$UI" == "whiptail" ] && clear && echo "Consultando las ultimas versiones de cada componente..."
    for dir in $(version_dirs); do
        # (solo las XAMPP-X.Y de antes: las XAMPP-X.Y.Z llevan su version en el nombre)
        [[ "$(version_name "$dir")" =~ ^[0-9]+\.[0-9]+$ ]] || continue
        full=$(rebuild_version "$dir" "$releases")
        [ -z "$full" ] && continue

        local new=$(stack_versions "$full")
        if [ "$(stack_fields "$dir")" == "$new" ] && ! php2shell_missing "$dir" "$full"; then
            state="al dia"
        else
            state="actualizable"
        fi

        IFS='|' read -r -a f <<< "$new"
        items+=("$(version_name "$dir")" "$(fmt_row "$STACK_WIDTHS" "$(version_name "$dir")" "${f[@]}" "$state")")
    done

    if [ ${#items[@]} -eq 0 ]; then
        ui_msg "No hay versiones instaladas que se puedan actualizar."

        return 0
    fi

    local text="Elige la version que quieres actualizar. Se muestra la pila con la que quedara:\n"
    text+="la ultima de su rama de PHP. 'actualizable' = hay parches nuevos;\n"
    text+="'al dia' = ya tiene todos los paquetes en su ultima version."
    local new
    while true; do
        version=$(ui_table_menu "$text" "$version" "$(stack_header "Estado")" "${items[@]}") || return 0
        dir=$BASE_DIR/XAMPP-$version
        full=$(rebuild_version "$dir" "$releases")
        new=$(stack_versions "$full")

        # Con todos los paquetes al dia no hay nada que actualizar: se avisa y se vuelve a la lista
        if [ "$(stack_fields "$dir")" == "$new" ] && ! php2shell_missing "$dir" "$full"; then
            ui_up_to_date "XAMPP-$version"
            continue
        fi
        break
    done

    local old_mariadb=$(stack_fields "$dir" | cut -d'|' -f3) new_mariadb=$(cut -d'|' -f3 <<< "$new")
    IFS='|' read -r -a f <<< "$new"

    local header=$(stack_header "")
    local summary="XAMPP-$version se volvera a compilar con la ultima pila de PHP ${full%.*}:\n\n"
    summary+="$header\n$(printf '%*s' ${#header} "" | tr ' ' '-')\n"
    summary+="$(stack_row "$dir" "" "Ahora")\n"
    summary+="$(fmt_row "$STACK_WIDTHS" "Despues" "${f[@]}" "")\n\n"

    if [ "${old_mariadb%.*}" == "${new_mariadb%.*}" ]; then
        summary+="Conserva sus bases de datos (misma rama de MariaDB, ${new_mariadb%.*}).\n"
    else
        local count=$(db_names "$dir" | grep -c .)
        summary+="MariaDB $new_mariadb no usa directamente los datos de MariaDB $old_mariadb, asi que\n"
        summary+="la nueva version empezara con bases de datos vacias. Antes se guarda una\n"
        summary+="copia de las actuales ($count) en ~/lvm-copias/. Para llevarte alguna, exportala\n"
        summary+="antes desde phpMyAdmin e importala despues.\n"
    fi

    summary+="\nLa compilacion tarda 20-40 minutos y mientras tanto la version actual sigue\n"
    summary+="como esta. Solo al final se sustituye"
    if [ "$(active_dir)" == "$dir" ]; then
        summary+=": como es la version activa, se parara\nunos segundos y se arrancara la nueva.\n"
    else
        summary+=".\n"
    fi
    summary+="Los proyectos y los vhosts de $COMMON no se tocan."
    [ "$DRY" -eq 1 ] && summary+="\n\nSIMULACION: no se hara ningun cambio."
    summary+="\n\n¿Actualizar XAMPP-$version?"

    check_space "$SPACE_STACK_GB" || return 0

    if other_install_running; then
        ui_msg "Hay otra instalacion en marcha. Espera a que termine."

        return 0
    fi

    ui_yesno "$summary" || return 0

    [ "$UI" == "whiptail" ] && clear
    install_plan "rehacer:$full"
}

# ui_up_to_date XAMPP-X.Y: aviso en verde de que la version ya tiene todos los paquetes al dia
function ui_up_to_date() {
    local message="El paquete $1 se encuentra actualizado."

    if [ "$UI" == "whiptail" ]; then
        WT_GREEN=$message ui_msg "$message\n\nTodos sus paquetes (PHP, Apache, MariaDB, ProFTPD, Perl y phpMyAdmin)\nestan en la ultima version de su rama: no hay nada que actualizar."
    elif [ -t 2 ]; then
        ui_msg "\033[1;32m$message\033[0m\n\nNo hay nada que actualizar."
    else
        ui_msg "$message\n\nNo hay nada que actualizar."
    fi
}

function panel_remove() {
    local items=() dir version active=$(active_dir)

    for dir in $(version_dirs); do
        local mark=""
        [ "$dir" == "$active" ] && mark="activa"
        items+=("$(version_name "$dir")" "$(stack_row "$dir" "$mark")")
    done

    if [ ${#items[@]} -eq 0 ]; then
        ui_msg "No hay versiones instaladas."

        return 0
    fi

    local text="Elige la version que quieres desinstalar.\n"
    text+="No se puede desinstalar la version activa."
    version=$(ui_table_menu "$text" "" "$(stack_header "Estado")" "${items[@]}") || return 0
    dir=$BASE_DIR/XAMPP-$version

    local blocker=$(remove_blocker "$version")
    if [ -n "$blocker" ]; then
        ui_msg "$blocker"

        return 0
    fi

    local fields
    IFS='|' read -r -a fields <<< "$(stack_fields "$dir")"

    local summary="Se va a desinstalar XAMPP-$version (PHP ${fields[0]}) y se borrara la carpeta $dir.\n\n"
    local names=$(db_names "$dir")
    local own_dbs=$(grep -c . <<< "$names")

    if [ "$own_dbs" -gt 0 ]; then
        summary+="ATENCION: sus bases de datos ($own_dbs) se BORRARAN con ella:\n\n"
        summary+="$(columns 66 <<< "$names")\n\n"
        summary+="Antes de borrar podras guardar una copia de todas ellas.\n"
    else
        summary+="No tiene bases de datos propias (aparte de las del sistema).\n"
    fi

    summary+="\nLos proyectos y los vhosts de $COMMON no se tocan."
    [ "$DRY" -eq 1 ] && summary+="\n\nSIMULACION: no se hara ningun cambio."
    summary+="\n\n¿Desinstalar XAMPP-$version?"

    ui_yesno "$summary" || return 0

    local backup=0
    if [ "$own_dbs" -gt 0 ]; then
        ui_yesno "¿Guardar antes una copia comprimida de las bases de datos de XAMPP-$version?\n\nSe guardara en ~/lvm-copias/ (se necesita espacio libre en tu carpeta personal)." && backup=1

        # Sin copia, se pide escribir el nombre de la version para confirmar
        if [ $backup -eq 0 ]; then
            local typed
            typed=$(ui_input "Se borraran sus bases de datos ($own_dbs) SIN copia y no se podran recuperar.\n\nEscribe $version para confirmar:" "") || return 0
            if [ "$typed" != "$version" ]; then
                ui_msg "No coincide. No se ha desinstalado nada."

                return 0
            fi
        fi
    fi

    [ "$UI" == "whiptail" ] && clear

    if [ "$DRY" -eq 0 ] && [ -n "$SUDO" ]; then
        echo "Se necesita la contraseña de administrador (sudo):"
        sudo -v || return 0
    fi

    local ok=1
    if [ $backup -eq 1 ]; then
        local home_dir=$(eval echo "~${SUDO_USER:-$USER}")
        local size_kb=0
        [ "$DRY" -eq 0 ] && size_kb=$($SUDO du -sk "$dir/xamppfiles/var/mysql" 2> /dev/null | cut -f1)
        local free_kb=$(df -k "$home_dir" | awk 'NR == 2 {print $4}')

        if [ -n "$size_kb" ] && [ "$free_kb" -lt "$size_kb" ]; then
            echo "No hay espacio para la copia: ocupan $((size_kb / 1024)) MB y hay $((free_kb / 1024)) MB libres en $home_dir."
            ok=0
        else
            backup_databases "$version" || ok=0
        fi

        [ $ok -eq 0 ] && echo "No se ha podido guardar la copia, asi que NO se desinstala nada."
    fi

    [ $ok -eq 1 ] && remove_version "$version"

    [ -t 0 ] && [ "$NO_ASK" != "1" ] && read -p "Pulsa Intro para volver al panel... " _
}

