        .split(separator: "\n").map { String($0).trimmingCharacters(in: .whitespaces) }.filter { !$0.isEmpty })
    @Published var task: TaskRunner? = nil
    @Published var toastText: String? = nil
    // Formulario «Subir o actualizar una base de datos»
