    @Published var npOpen = false
    @Published var npStep = 1
    @Published var npUrl = ""
    @Published var npFolder = ""
    @Published var npFolderAuto = true
    @Published var npVersion = ""
    @Published var npDb = ""
    @Published var npFile: String? = nil
